let currentAktionId = localStorage.getItem('currentAktionId') || '';
let currentAktionInfo = null; // {id, name, typ, status, ...} der gewählten Aktion
// dashDokumenteAktionId/-Loading: Cache-Steuerung für die Dokumente-Liste
// im Start-Dashboard (Migration 67) — verhindert, dass renderDashboard()
