// ---------- Generisches Benachrichtigungssystem (Migration 36) ----------
// Kartei-weit, NICHT pro Aktion — die Glocke muss auch dann Bescheid geben
// können, wenn eine komplett neue Aktion angelegt wurde, für die noch keine
// Freischaltung besteht. Läuft deshalb über epCallOhneAktion.
// Gelesen-Tracking: bei Team (teamPersonId vorhanden, PIN-verifiziert)
// serverseitig über benachrichtigung_gelesen; bei Admin (kein teamPersonId)
// als lokaler Fallback über localStorage, da Admin keine Kartei-Person ist.
let benachrichtigungen = [];
function benachrichtigungGelesenLokalKey(){ return 'benachrichtigungGelesenLokal'; }
function benachrichtigungGelesenLokalSet(){
  try{ return new Set(JSON.parse(localStorage.getItem(benachrichtigungGelesenLokalKey())||'[]')); }
  catch(e){ return new Set(); }
}
function benachrichtigungLokalAlsGelesenMarkieren(id){
  const s = benachrichtigungGelesenLokalSet();
  s.add(id);
  localStorage.setItem(benachrichtigungGelesenLokalKey(), JSON.stringify([...s]));
}
async function ladeBenachrichtigungen(){
  try{
    const json = await epCallOhneAktion({action:'team_benachrichtigungen_list', pass: currentAuthPass, personId: teamPersonId || undefined});
    let liste = json.benachrichtigungen || [];
    if(!teamPersonId){
      // Admin-Fallback: server kennt kein "gelesen" ohne personId, also lokal ergänzen
      const gelesenLokal = benachrichtigungGelesenLokalSet();
      liste = liste.map(b=>({...b, gelesen: gelesenLokal.has(b.id)}));
    }
    benachrichtigungen = liste;
    renderBenachrichtigungGlocke();
  }catch(e){
    // Benachrichtigungen sind ein Zusatzfeature — ein Fehler hier soll die
    // restliche App nicht blockieren, deshalb bewusst nur in der Konsole.
    console.error('Benachrichtigungen konnten nicht geladen werden:', e);
  }
}
// Periodisches Nachladen — anders als der 12-Sekunden-Datenabgleich
// (POLL_INTERVAL_MS, siehe startRealtime) bewusst seltener, da neue
// Benachrichtigungen (z.B. "neue Aktion") deutlich seltener vorkommen als
// laufende Programmänderungen innerhalb einer Aktion.
const BENACHRICHTIGUNG_POLL_INTERVAL_MS = 45000; // alle 45 Sekunden
let benachrichtigungPollingStarted = false;
function starteBenachrichtigungPolling(){
  if(benachrichtigungPollingStarted) return;
  benachrichtigungPollingStarted = true;
  setInterval(()=>{ if(document.hidden || navigator.onLine === false) return; ladeBenachrichtigungen(); }, BENACHRICHTIGUNG_POLL_INTERVAL_MS);
}
function renderBenachrichtigungGlocke(){
  const badge = document.getElementById('benachrichtigungBadge');
  const ungelesen = benachrichtigungen.filter(b=>!b.gelesen);
  if(!badge) return;
  if(ungelesen.length > 0){
    badge.style.display = 'inline-block';
    badge.textContent = ungelesen.length > 9 ? '9+' : String(ungelesen.length);
  } else {
    badge.style.display = 'none';
    badge.textContent = '';
  }
  renderBenachrichtigungDropdown();
}
function renderBenachrichtigungDropdown(){
  const dd = document.getElementById('benachrichtigungDropdown');
  if(!dd || dd.style.display === 'none') return;
  if(benachrichtigungen.length === 0){
    dd.innerHTML = '<div class="dp-hint" style="margin:0;">Keine Benachrichtigungen.</div>';
    return;
  }
  const ungelesen = benachrichtigungen.filter(b=>!b.gelesen);
  const kopf = ungelesen.length > 0
    ? `<div style="display:flex; justify-content:flex-end; margin-bottom:6px;"><button class="btn ghost" id="benachrichtigungAlleGelesenBtn" style="font-size:0.78rem; padding:4px 8px;">Alle als gelesen markieren</button></div>`
    : '';
  const items = benachrichtigungen.map(b=>{
    const when = new Date(b.erstellt_am).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
    return `
      <div class="benachrichtigung-item" data-id="${escapeHtml(b.id)}" style="padding:8px 6px; border-bottom:1px solid #eee; ${b.gelesen?'opacity:0.6;':''} cursor:pointer;">
        <div style="font-weight:600; font-size:0.88rem;">${b.gelesen?'':'🔵 '}${escapeHtml(b.titel)}</div>
        ${b.text ? `<div style="font-size:0.82rem; color:#555; margin-top:2px;">${escapeHtml(b.text)}</div>` : ''}
        <div style="font-size:0.72rem; color:#999; margin-top:2px;">${when}${b.erstellt_von?' — '+escapeHtml(b.erstellt_von):''}</div>
      </div>`;
  }).join('');
  dd.innerHTML = kopf + items;
  const alleBtn = document.getElementById('benachrichtigungAlleGelesenBtn');
  if(alleBtn){
    alleBtn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      const ids = benachrichtigungen.filter(b=>!b.gelesen).map(b=>b.id);
      if(ids.length === 0) return;
      benachrichtigungen.forEach(b=>{ b.gelesen = true; });
      renderBenachrichtigungGlocke();
      if(teamPersonId){
        try{ await epCallOhneAktion({action:'team_benachrichtigungen_alle_gelesen_setzen', pass: currentAuthPass, personId: teamPersonId, ids}); }
        catch(err){ console.error('Konnte Benachrichtigungen nicht als gelesen markieren:', err); }
      } else {
        ids.forEach(id=>benachrichtigungLokalAlsGelesenMarkieren(id));
      }
    });
  }
  dd.querySelectorAll('.benachrichtigung-item').forEach(el=>{
    el.addEventListener('click', async ()=>{
      const id = el.getAttribute('data-id');
      const eintrag = benachrichtigungen.find(b=>b.id===id);
      if(!eintrag || eintrag.gelesen) return;
      eintrag.gelesen = true;
      renderBenachrichtigungGlocke();
      if(teamPersonId){
        try{ await epCallOhneAktion({action:'team_benachrichtigung_gelesen_setzen', pass: currentAuthPass, personId: teamPersonId, id}); }
        catch(e){ console.error('Konnte Benachrichtigung nicht als gelesen markieren:', e); }
      } else {
        benachrichtigungLokalAlsGelesenMarkieren(id);
      }
    });
  });
}
document.getElementById('benachrichtigungGlocke').addEventListener('click', ()=>{
  const dd = document.getElementById('benachrichtigungDropdown');
  const sichtbar = dd.style.display !== 'none';
  dd.style.display = sichtbar ? 'none' : 'block';
  if(!sichtbar) renderBenachrichtigungDropdown();
});
document.addEventListener('click', (e)=>{
  const dd = document.getElementById('benachrichtigungDropdown');
  const glocke = document.getElementById('benachrichtigungGlocke');
  if(!dd || dd.style.display==='none') return;
  if(!dd.contains(e.target) && !glocke.contains(e.target)) dd.style.display = 'none';
});

// changelogVisibleToRole: Team-Zugang bekommt in Banner/Benachrichtigungen
// keine Details zu Admin-Bereichen (Gruppen, Personal inkl. Krankmeldungen)
// und keine Hinweise auf "Nur Admin"-To-Dos zu sehen — nur was alle angeht.
function changelogVisibleToRole(c){
  if(isAdmin()) return true;
  if(c.area==='Gruppen' || c.area==='Personal') return false;
  if(c.area==='System' && c.refId){
    const todo = (state.todos||[]).find(t=>t.id===c.refId);
    if(todo && todo.visibility==='admin') return false;
  }
  return true;
}

// --- LOCK SCREEN ---
// Achtung: Diese Rollentrennung ist eine reine Oberflächen-Beschränkung,
// kein echter Datenbankschutz — für den Team-Alltag aber ausreichend.
function unlockApp(){
  document.getElementById('lockscreen').style.display = 'none';
  appEntsperrt = true;
  // Admin behält den bisherigen, uneingeschränkten Weg (jede Aktion sofort
  // wählbar). Team durchläuft den zweistufigen Zugang (erst identifizieren).
  // Mitglied (Migration 55, Sitzungsplanung) hat gar keine Aktionen — geht
  // direkt in die eigene Identifikation und danach in die Sitzungen-Ansicht.
  aktualisiereAdminKontoZeilen();
  if(userRole === 'admin'){
    zeigeStartMenu(); pruefeAdminKontoEinrichtung();
    if(adminKontoModus && adminKontoInfo && adminKontoInfo.mussPasswortAendern){
      // Einmalpasswort: erst eigenes Passwort festlegen, dann geht es weiter
      zeigePasswortWechselDialog(true).then(function(ok){ if(ok) datenschutzPruefen(); });
    }else{
      datenschutzPruefen();
    }
  }
  else if(userRole === 'mitglied') zeigeMitgliedEinstieg();
  else zeigeTeamEinstieg();
  if(pushZielOffen) setTimeout(pushZielAnwenden, 0);
}
// zeigeStartMenu: reiner Anzeige-Wechsel (kein Laden) — Startpunkt für
// Admin nach dem Login und Rücksprungziel von Allgemein/Verwaltung.
function zeigeStartMenu(){
  document.getElementById('appShell').style.display = 'none';
  alleAuswahlScreensAusblenden();
  document.getElementById('startMenuScreen').style.display = 'grid';
  if(isAdmin()) aktualisiereSicherheitsUebersicht();
}
// alleAuswahlScreensAusblenden: räumt alle möglichen Vorbildschirme weg,
// unabhängig davon, über welchen der beiden Wege (Admin-Auswahl oder
// Team-Übersicht) eine Aktion betreten wurde.
function alleAuswahlScreensAusblenden(){
  ['startMenuScreen','startAnleitungScreen','aktionAuswahlScreen','teamIdentifikationScreen','teamAktionsScreen','aktionVerwaltenScreen','allgemeinScreen','verwaltungScreen','mitgliedIdentifikationScreen','sitzungenScreen','infothekScreen','meldungScreen'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.style.display = 'none';
  });
}
// Nach Auswahl/Anlegen einer Aktion geht es hier weiter.
async function betreteAktion(aktionId, aktionInfo){
  currentAktionId = aktionId;
  currentAktionInfo = aktionInfo || null;
  localStorage.setItem('currentAktionId', aktionId);
  // Aktionsbezogene Dashboard-Caches zurücksetzen — sonst würde nach einem
  // Aktionswechsel ohne vollen Seiten-Reload (siehe "Aktion wechseln"-Button)
  // kurzzeitig der Stand der VORHERIGEN Aktion angezeigt. Bewusst NICHT
  // zurückgesetzt: nachweiseCacheLoaded/globaleEinstellungenGeladen — diese
  // Daten sind aktionsübergreifend (Kartei-weit), bleiben also gültig.
  kinderGruppenBedarfCache = null;
  teamendeFreigeschaltetCache = null;
  alleAuswahlScreensAusblenden();
  document.getElementById('appShell').style.display = 'flex';
  // Sidebar zeigt jetzt den Namen der aktuellen Aktion statt eines starren
  // App-Namens — AWO Jugendwerk Erftstadt bleibt als kleiner Zusatz sichtbar,
  // damit die Zuordnung zum Träger erhalten bleibt.
  const brandEl = document.getElementById('sidebarBrand');
  if(brandEl){
    const aktionName = (aktionInfo && aktionInfo.name) ? escapeHtml(aktionInfo.name) : 'Aktion';
    brandEl.innerHTML = `${aktionName}<small>AWO Jugendwerk Erftstadt</small>`;
  }
  const btn = document.getElementById('aktionWechselnBtn');
  if(btn) btn.textContent = 'Aktion wechseln ▾';
  applyModulFilter(aktionInfo);
  applyRoleRestrictions();
  // await, damit Aufrufer (z.B. der Nachweise-Schnellzugriff in der
  // Verwaltung) nach dem Betreten gezielt auf einen bestimmten Reiter
  // wechseln können, ohne dass renderAll() das wieder auf "Start" zurücksetzt.
  await loadState();
  // Benachrichtigungen sind kartei-weit (nicht an diese Aktion gebunden),
  // aber die Sidebar mit der Glocke existiert erst, sobald appShell sichtbar
  // ist — deshalb hier laden, bewusst nicht awaited (Zusatzfeature, soll
  // den Start nicht verzögern). Danach periodisches Nachladen starten,
  // damit eine neue Aktion auch sichtbar wird, ohne dass man die App
  // verlässt und neu betritt.
  ladeBenachrichtigungen();
  starteBenachrichtigungPolling();
}
// applyModulFilter: blendet Nav-Reiter aus, die für diese Aktion nicht
// aktiviert sind (aktionen.aktive_module). Reiter ohne data-modul-Attribut
// (Start, Kinder, Verlauf, To-Do, Wünsche, Anleitung) sind immer sichtbar —
// bewusste Entscheidung, das sind aktionstyp-übergreifend relevante Reiter.
// Fehlt aktive_module komplett oder ein einzelner Schlüssel, wird der Reiter
// aus Kompatibilitätsgründen sicherheitshalber angezeigt (nicht versehentlich
// etwas verstecken, das der Admin nie bewusst deaktiviert hat).
// WICHTIG: läuft bewusst VOR applyRoleRestrictions() (siehe betreteAktion) —
// die dortige feste Admin-only-Sperre für "Nachweise" muss als letztes
// gewinnen, sonst würde ein aktiviertes Nachweise-Modul den Reiter für
// Teamende wieder sichtbar machen (genau das war der gemeldete Fehler).
function applyModulFilter(aktionInfo){
  const module = (aktionInfo && aktionInfo.aktive_module) || {};
  document.querySelectorAll('.nav button[data-modul]').forEach(btn=>{
    const key = btn.dataset.modul;
    const sichtbar = !(key in module) || !!module[key];
    btn.style.display = sichtbar ? '' : 'none';
  });
}
// modulAktiv: gleiche Logik wie applyModulFilter, aber als einzelne Abfrage
// nutzbar (z.B. für die Dashboard-Kacheln, die pro Reiter ein- oder
// ausgeblendet werden sollen — siehe renderDashboard).
function modulAktiv(key){
  const module = (currentAktionInfo && currentAktionInfo.aktive_module) || {};
  return !(key in module) || !!module[key];
}
// dashboardKachelAktiv: unabhängig von modulAktiv() — steuert, ob eine
// einzelne Start-Kachel gezeigt wird, auch wenn der zugehörige Reiter selbst
// weiter aktiv bleibt (z.B. Reiter "Personal" aktiv, aber die Kachel
// "Kranke Teamende heute" auf der Startseite ausgeblendet). Fehlt der
// Schlüssel (auch bei allen bereits bestehenden Aktionen ohne diese
// Einstellung), ist die Kachel sichtbar — gleiche "sicherheitshalber
// anzeigen"-Logik wie bei modulAktiv.
function dashboardKachelAktiv(key){
  const kacheln = (currentAktionInfo && currentAktionInfo.aktive_dashboard_kacheln) || {};
  return !(key in kacheln) || !!kacheln[key];
}
// Label-Map fürs Auswahl-Menü in "Aktion verwalten". Reihenfolge hier =
// Reihenfolge im Auswahl-Menü (nicht zwingend identisch mit der
// Darstellungsreihenfolge im Dashboard selbst).
const DASHBOARD_KACHEL_LABEL = {
  wetter: 'Wetter',
  krankmeldungen: 'Kranke Teamende heute',
  kinder_pro_gruppe: 'Kinderanzahl pro Gruppe',
  team_pro_gruppe: 'Teamendenanzahl pro Gruppe',
  teamende_freigeschaltet: 'Teamende (freigeschaltet)',
  foto_einwilligung: 'Foto-/Video-Einwilligung ungeklärt',
  nachweise: 'Nachweise fehlen/laufen ab',
  einkauf: 'Offene Einkäufe',
  material: 'Offene Materialpunkte',
  todo: 'To-Dos heute',
  verlauf: 'Letzte Änderungen',
};
// ===========================================================================
// ADMIN-KONTEN (Schritt B, 11/2026): persoenliche Anmeldung statt gemeinsamem
// Passwort. Der Browser merkt sich nur ein GERAETETOKEN (kein Passwort).
// Daraus holt er sich im Hintergrund alle ~60 Minuten ein Zugriffstoken
// ("adm1."), das wie bisher im Feld "pass" an die Edge Function geht —
// deshalb brauchen die vielen bestehenden Aufrufstellen keine Aenderung
// (epCallRoh tauscht das Token zentral aus und erneuert es bei Bedarf).
//   "Angemeldet bleiben" an  -> localStorage  (30 Tage nach letzter Nutzung)
//   "Angemeldet bleiben" aus -> sessionStorage (bis zum Schliessen, max. 8 h)
// ===========================================================================
const ADMIN_SITZUNG_KEY = 'adminSitzung';
let adminKontoModus = false;      // true, solange ein persoenliches Konto angemeldet ist
let adminZugriff = null;          // {token, bis} nur im Arbeitsspeicher
let adminKontoInfo = null;        // {name, kontenVerwalter, ...}
let adminErneuerungLaeuft = null;
let adminSitzungBeendetFlag = false;

class AdminSitzungEnde extends Error {}

function adminSitzungLesen(){
  const speicher = [sessionStorage, localStorage];
  for(let i = 0; i < speicher.length; i++){
    try{
      const roh = speicher[i].getItem(ADMIN_SITZUNG_KEY);
      if(roh){
        const o = JSON.parse(roh);
        if(o && typeof o.geraetToken === 'string' && o.geraetToken.indexOf('gt1_') === 0) return {o: o, speicher: speicher[i]};
      }
    }catch(e){}
  }
  return null;
}
function adminSitzungLoeschen(){
  [sessionStorage, localStorage].forEach(function(s){ try{ s.removeItem(ADMIN_SITZUNG_KEY); }catch(e){} });
  adminZugriff = null; adminKontoInfo = null; adminKontoModus = false; adminStepup = null;
}
function adminSitzungUebernehmen(a, merken){
  const o = {geraetToken: a.geraetToken, geraetBis: a.geraetGueltigBis, konto: a.konto};
  const ziel = merken ? localStorage : sessionStorage;
  const anderes = merken ? sessionStorage : localStorage;
  try{ anderes.removeItem(ADMIN_SITZUNG_KEY); }catch(e){}
  try{ ziel.setItem(ADMIN_SITZUNG_KEY, JSON.stringify(o)); }catch(e){}
  // Das alte gemeinsame Passwort liegt nach dem Wechsel nicht mehr im Browser.
  ['unlocked','appRole','appPass'].forEach(function(k){ try{ localStorage.removeItem(k); }catch(e){} });
  adminZugriff = {token: a.accessToken, bis: a.accessGueltigBis};
  adminKontoInfo = a.konto;
  adminKontoModus = true;
  adminSitzungBeendetFlag = false;
  adminStepup = null;
  userRole = 'admin';
  currentAuthPass = a.accessToken;
}
function adminGeraeteName(){
  const ua = navigator.userAgent || '';
  const os = /Android/i.test(ua) ? 'Android' : /iPhone|iPad|iPod/i.test(ua) ? 'iPhone/iPad' : /Windows/i.test(ua) ? 'Windows' : /Mac OS/i.test(ua) ? 'Mac' : /Linux/i.test(ua) ? 'Linux' : 'Gerät';
  const br = /Edg\//.test(ua) ? 'Edge' : /OPR\/|Opera/.test(ua) ? 'Opera' : /Firefox|FxiOS/.test(ua) ? 'Firefox' : /Chrome|CriOS/.test(ua) ? 'Chrome' : /Safari/.test(ua) ? 'Safari' : 'Browser';
  const app = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) ? ' (App)' : '';
  return os + ' · ' + br + app;
}
function adminWarte(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }

// Zugriffstoken per Geraetetoken erneuern. Ueber mehrere Tabs hinweg mit
// Web-Locks abgesichert (das Geraetetoken wird bei jeder Erneuerung ausgetauscht;
// jeder Tab liest daher immer das AKTUELLE aus dem Speicher).
function adminTokenErneuern(){
  if(adminErneuerungLaeuft) return adminErneuerungLaeuft;
  const arbeit = async function(){
    for(let versuch = 0; versuch < 3; versuch++){
      const s = adminSitzungLesen();
      if(!s) throw new AdminSitzungEnde('keine Sitzung');
      const res = await fetch(ELTERN_FUNCTION_URL, {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({action: 'admin_token_erneuern', geraetToken: s.o.geraetToken})
      });
      const data = await res.json().catch(function(){ return {}; });
      if(res.ok && data.ok){
        const neu = {geraetToken: data.geraetToken, geraetBis: data.geraetGueltigBis, konto: data.konto};
        try{ s.speicher.setItem(ADMIN_SITZUNG_KEY, JSON.stringify(neu)); }catch(e){}
        adminZugriff = {token: data.accessToken, bis: data.accessGueltigBis};
        adminKontoInfo = data.konto;
        return;
      }
      if(res.status === 409 && data.code === 'erneut_versuchen'){ await adminWarte(400); continue; }
      if(res.status === 401 || data.code === 'geraet_ungueltig') throw new AdminSitzungEnde(data.error || 'Sitzung ungültig');
      throw new Error(data.error || ('Fehler (' + res.status + ')'));
    }
    throw new Error('Die Anmeldung konnte gerade nicht erneuert werden. Bitte noch einmal versuchen.');
  };
  const lauf = (navigator.locks && navigator.locks.request)
    ? navigator.locks.request('adminTokenErneuern', arbeit)
    : arbeit();
  adminErneuerungLaeuft = Promise.resolve(lauf).finally(function(){ adminErneuerungLaeuft = null; });
  return adminErneuerungLaeuft;
}
async function holeAdminZugriff(){
  if(adminZugriff && adminZugriff.bis - Date.now() > 120000) return adminZugriff.token;
  try{
    await adminTokenErneuern();
  }catch(e){
    if(e instanceof AdminSitzungEnde) throw e;
    // Kurz ohne Netz: das bisherige Token gilt eventuell noch.
    if(adminZugriff && adminZugriff.bis - Date.now() > 5000) return adminZugriff.token;
    throw e;
  }
  return adminZugriff.token;
}
function adminSitzungBeendet(){
  if(adminSitzungBeendetFlag) return;
  adminSitzungBeendetFlag = true;
  adminSitzungLoeschen();
  try{ sessionStorage.setItem('lockHinweis', 'Deine Admin-Anmeldung ist nicht mehr gültig (abgelaufen, abgemeldet oder Konto gesperrt). Bitte neu anmelden.'); }catch(e){}
  location.reload();
}

// Start mit gespeicherter Sitzung: Zugriffstoken holen, dann normal weiter.
async function adminSitzungStart(){
  const lock = document.getElementById('lockscreen');
  lock.classList.add('lock-wartet');
  userRole = 'admin';
  adminKontoModus = true;
  try{
    await adminTokenErneuern();
    currentAuthPass = adminZugriff.token;
    lock.classList.remove('lock-wartet');
    unlockApp();
  }catch(e){
    lock.classList.remove('lock-wartet');
    let hinweis;
    if(e instanceof AdminSitzungEnde){
      adminSitzungLoeschen();
      hinweis = 'Deine Admin-Anmeldung ist nicht mehr gültig (abgelaufen, abgemeldet oder Konto gesperrt). Bitte neu anmelden.';
    }else{
      adminKontoModus = false;
      hinweis = 'Keine Verbindung zum Server – deine Anmeldung bleibt gespeichert. Bitte Internetverbindung prüfen und die Seite neu laden.';
    }
    try{ sessionStorage.setItem('lockHinweis', hinweis); }catch(err){}
    verdrahteLockscreen();
  }
}

// Anmeldeformular (Name + Passwort)
async function adminKontoLogin(){
  const fehlerEl = document.getElementById('adminLoginError');
  const name = document.getElementById('adminName').value.trim();
  const pw = document.getElementById('adminPw').value;
  const merken = document.getElementById('adminMerken').checked;
  fehlerEl.textContent = '';
  if(!name || !pw){ fehlerEl.textContent = 'Bitte Anmeldename und Passwort eingeben.'; return; }
  const btn = document.getElementById('adminLoginBtn');
  btn.disabled = true;
  try{
    const a = await epCallOhneAktion({action: 'admin_login', anmeldename: name, passwort: pw, merken: merken, geraetName: adminGeraeteName()});
    try{ localStorage.setItem('adminMerkenWahl', merken ? '1' : '0'); }catch(e){}
    adminSitzungUebernehmen(a, merken);
    document.getElementById('adminPw').value = '';
    unlockApp();
  }catch(e){
    const msg = String(e && e.message || '');
    fehlerEl.textContent =
      /zu viele/i.test(msg) ? msg :
      (navigator.onLine === false || /failed to fetch|networkerror|load failed/i.test(msg))
        ? 'Keine Verbindung zum Server. Bitte Internetverbindung prüfen und noch einmal versuchen.'
        : msg;
  }finally{
    btn.disabled = false;
  }
}

// Abmelden: Geraet auch auf dem Server abmelden (best effort), dann Seite neu laden.
async function adminAbmeldenServer(){
  const s = adminSitzungLesen();
  if(!s) return;
  try{
    await Promise.race([
      fetch(ELTERN_FUNCTION_URL, {
        method: 'POST', headers: {'Content-Type': 'application/json'}, keepalive: true,
        body: JSON.stringify({action: 'admin_abmelden', pass: adminZugriff ? adminZugriff.token : undefined, geraetToken: s.o.geraetToken})
      }),
      adminWarte(2500)
    ]);
  }catch(e){}
}

function aktualisiereAdminKontoZeilen(){
  const text = (adminKontoModus && adminKontoInfo)
    ? 'Angemeldet als ' + adminKontoInfo.name + (adminKontoInfo.kontenVerwalter ? ' (Konten-Verwalter)' : '')
    : '';
  ['adminKontoZeileStart', 'adminKontoZeileSeite'].forEach(function(id){
    const el = document.getElementById(id);
    if(el){ el.textContent = text; el.style.display = text ? 'block' : 'none'; }
  });
}

// Ersteinrichtung: nur mit dem alten gemeinsamen Passwort und nur solange es noch
// keinen Konten-Verwalter gibt. Hinweis im Startmenue, bis das erste Konto steht.
async function pruefeAdminKontoEinrichtung(){
  if(adminKontoModus || userRole !== 'admin') return;
  const banner = document.getElementById('adminKontoBanner');
  if(!banner) return;
  try{
    if(sessionStorage.getItem('adminKontoBannerAus') === '1') return;
    const st = await epCallOhneAktion({action: 'admin_konten_status', pass: currentAuthPass});
    banner.style.display = st && st.verwalterVorhanden === false ? 'block' : 'none';
  }catch(e){ /* Hinweis ist nur ein Angebot — Fehler still ignorieren */ }
}

async function zeigeKontoEinrichtenDialog(){
  let personen = [];
  try{
    const j = await epCallOhneAktion({action: 'admin_personen_list', pass: currentAuthPass});
    personen = (j.personen || []).slice().sort(function(a, b){ return (a.vorname + ' ' + a.nachname).localeCompare(b.vorname + ' ' + b.nachname, 'de'); });
  }catch(e){ alert('Die Personenliste konnte nicht geladen werden: ' + e.message); return; }
  const ov = document.createElement('div');
  ov.id = 'dlgOverlay';
  ov.innerHTML =
    '<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="kontoDlgTitel">' +
    '<h3 id="kontoDlgTitel" style="margin:0 0 8px 0;">🔐 Persönliches Admin-Konto einrichten</h3>' +
    '<p class="dlg-text">Dieses erste Konto wird automatisch <strong>Konten-Verwalter</strong>. Die Konten der anderen Admins legst du danach an.</p>' +
    '<label class="dlg-label" for="kontoPerson">Wer bist du?</label>' +
    '<select id="kontoPerson"><option value="">– bitte auswählen –</option>' +
    personen.map(function(p){ return '<option value="' + escapeHtml(p.id) + '" data-vorname="' + escapeHtml(p.vorname || '') + '">' + escapeHtml((p.vorname || '') + ' ' + (p.nachname || '')) + '</option>'; }).join('') +
    '</select>' +
    '<label class="dlg-label" for="kontoName">Anmeldename (klein, ohne Leerzeichen)</label>' +
    '<input type="text" id="kontoName" autocomplete="username" autocapitalize="none" spellcheck="false">' +
    '<label class="dlg-label" for="kontoPw">Passwort (mindestens 12 Zeichen – am besten drei, vier Wörter)</label>' +
    '<input type="password" id="kontoPw" autocomplete="new-password">' +
    '<label class="dlg-label" for="kontoPw2">Passwort wiederholen</label>' +
    '<input type="password" id="kontoPw2" autocomplete="new-password">' +
    '<label class="dlg-check"><input type="checkbox" id="kontoMerken"> Auf diesem Gerät angemeldet bleiben (nur auf eigenen Geräten)</label>' +
    '<div class="err" id="kontoFehler" role="alert"></div>' +
    '<div class="dlg-knoepfe"><button type="button" class="btn ghost" id="kontoAbbr">Abbrechen</button><button type="button" class="btn" id="kontoOk">Konto anlegen</button></div>' +
    '</div>';
  document.body.appendChild(ov);
  const el = function(id){ return document.getElementById(id); };
  let nameVonHand = false;
  el('kontoName').addEventListener('input', function(){ nameVonHand = true; });
  el('kontoPerson').addEventListener('change', function(){
    if(nameVonHand && el('kontoName').value) return;
    const o = el('kontoPerson').selectedOptions[0];
    el('kontoName').value = o && o.dataset.vorname ? o.dataset.vorname.toLowerCase().replace(/[^a-z0-9äöüß._-]/g, '') : '';
  });
  const zu = function(){ if(ov.parentNode) ov.parentNode.removeChild(ov); };
  el('kontoAbbr').addEventListener('click', zu);
  el('kontoOk').addEventListener('click', async function(){
    const fehler = el('kontoFehler');
    fehler.textContent = '';
    const personId = el('kontoPerson').value;
    const name = el('kontoName').value.trim().toLowerCase();
    const pw = el('kontoPw').value;
    const merken = el('kontoMerken').checked;
    if(!personId){ fehler.textContent = 'Bitte wähle aus, wer du bist.'; return; }
    if(!/^[a-z0-9äöüß._-]{2,40}$/.test(name)){ fehler.textContent = 'Der Anmeldename darf nur Kleinbuchstaben, Ziffern sowie . _ - enthalten (2–40 Zeichen).'; return; }
    if(pw.length < 12){ fehler.textContent = 'Das Passwort muss mindestens 12 Zeichen lang sein.'; return; }
    if(pw !== el('kontoPw2').value){ fehler.textContent = 'Die beiden Passwörter sind nicht gleich.'; return; }
    el('kontoOk').disabled = true;
    try{
      await epCallOhneAktion({action: 'admin_konto_bootstrap', pass: currentAuthPass, personId: personId, anmeldename: name, passwort: pw});
      const a = await epCallOhneAktion({action: 'admin_login', anmeldename: name, passwort: pw, merken: merken, geraetName: adminGeraeteName()});
      adminSitzungUebernehmen(a, merken);
      zu();
      location.reload(); // frisch mit dem neuen Konto starten
    }catch(e){
      fehler.textContent = e.message;
      el('kontoOk').disabled = false;
    }
  });
  el('kontoPerson').focus();
}

