let dsPruefLaeuft = false;

function dsTextRolle(){
  if(userRole === 'eltern') return 'eltern';
  if(userRole === 'admin') return 'admin';
  return 'team';
}
function dsSubjekt(){
  if(adminKontoModus && adminKontoInfo && adminKontoInfo.id) return {typ: 'konto', id: adminKontoInfo.id};
  if(userRole === 'team' && teamPersonId) return {typ: 'team', id: teamPersonId};
  if(userRole === 'mitglied' && mitgliedId) return {typ: 'mitglied', id: mitgliedId};
  return null;
}
function dsTitelHtml(t){ return escapeHtml(t) + (DS_ENTWURF ? ' <span style="font-weight:normal; font-size:0.8rem; color:#b45309;">(Entwurf – wird mit dem Datenschutzbeauftragten abgestimmt)</span>' : ''); }

// modus 'pflicht': kein Schliessen ohne "Zur Kenntnis genommen" (oder Abmelden).
// modus 'lesen' : nur lesen, Schliessen moeglich. rolle 'alle' zeigt alle drei Texte.
function dsDialog(rolle, modus, speichern){
  return new Promise(function(fertig){
    const vorher = document.activeElement;
    let inhalt, titel;
    if(rolle === 'alle'){
      titel = 'Datenschutzhinweis';
      inhalt = ['eltern', 'team', 'admin'].map(function(r, i){
        return '<details' + (i === 0 ? ' open' : '') + ' style="margin:0 0 8px 0;"><summary style="cursor:pointer; font-weight:600;">' + escapeHtml(DS_TEXTE[r].titel) + '</summary>' + DS_TEXTE[r].html + '</details>';
      }).join('');
    }else{
      titel = DS_TEXTE[rolle].titel;
      inhalt = DS_TEXTE[rolle].html;
    }
    const ov = document.createElement('div');
    ov.id = 'dsOverlay';
    ov.innerHTML = '<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dsTitel">' +
      '<h3 id="dsTitel" style="margin:0 0 10px 0;">📄 ' + dsTitelHtml(titel) + '</h3>' +
      '<div class="ds-text" tabindex="0">' + inhalt + '</div>' +
      '<div class="err" id="dsFehler" role="alert"></div>' +
      '<div class="dlg-knoepfe">' +
      (modus === 'pflicht'
        ? '<button type="button" class="btn ghost" id="dsAbmelden">Abmelden</button><button type="button" class="btn" id="dsOk">Zur Kenntnis genommen</button>'
        : '<button type="button" class="btn" id="dsZu">Schließen</button>') +
      '</div></div>';
    document.body.appendChild(ov);
    const el = function(id){ return document.getElementById(id); };
    function weg(wert){
      document.removeEventListener('keydown', taste, true);
      if(ov.parentNode) ov.parentNode.removeChild(ov);
      try{ if(vorher && vorher.focus) vorher.focus(); }catch(e){}
      fertig(wert);
    }
    function taste(e){
      if(e.key === 'Escape' && modus === 'lesen'){ e.preventDefault(); e.stopPropagation(); weg('zu'); }
      else if(e.key === 'Tab'){
        const f = Array.prototype.slice.call(ov.querySelectorAll('button, [tabindex="0"], summary'));
        const i = f.indexOf(document.activeElement);
        if(e.shiftKey && i <= 0){ e.preventDefault(); f[f.length - 1].focus(); }
        else if(!e.shiftKey && i === f.length - 1){ e.preventDefault(); f[0].focus(); }
      }
    }
    document.addEventListener('keydown', taste, true);
    if(modus === 'pflicht'){
      el('dsAbmelden').addEventListener('click', function(){ weg('abmelden'); });
      el('dsOk').addEventListener('click', async function(){
        el('dsOk').disabled = true; el('dsFehler').textContent = '';
        try{ if(speichern) await speichern(); weg('ok'); }
        catch(e){
          el('dsFehler').textContent = 'Das hat gerade nicht geklappt: ' + (e && e.message || e) + ' Bitte noch einmal versuchen.';
          el('dsOk').disabled = false;
        }
      });
      el('dsOk').focus();
    }else{
      el('dsZu').addEventListener('click', function(){ weg('zu'); });
      ov.addEventListener('mousedown', function(e){ if(e.target === ov) weg('zu'); });
      el('dsZu').focus();
    }
  });
}

async function datenschutzPruefen(){
  if(dsPruefLaeuft || document.getElementById('dsOverlay')) return;
  dsPruefLaeuft = true;
  try{
    const subj = dsSubjekt();
    const key = subj ? 'dsOk:' + subj.typ + ':' + subj.id + ':' + DS_VERSION : 'dsOk:geraet:' + userRole + ':' + DS_VERSION;
    try{ if(localStorage.getItem(key) === '1') return; }catch(e){}
    let personenbezogen = false;
    if(subj){
      try{
        const st = await epCallOhneAktion({action: 'datenschutz_status', pass: currentAuthPass, version: DS_VERSION});
        personenbezogen = st.personenbezogen === true;
        if(st.bestaetigt){ try{ localStorage.setItem(key, '1'); }catch(e){} return; }
      }catch(e){ return; } // ohne Verbindung nicht blockieren — beim naechsten Start erneut
    }
    const ergebnis = await dsDialog(dsTextRolle(), 'pflicht', async function(){
      if(personenbezogen) await epCallOhneAktion({action: 'datenschutz_bestaetigen', pass: currentAuthPass, version: DS_VERSION});
      try{ localStorage.setItem(key, '1'); }catch(e){}
    });
    if(ergebnis === 'abmelden'){
      if(userRole === 'eltern') document.getElementById('elternLogoutBtn').click();
      else logoutApp();
    }
  }finally{
    dsPruefLaeuft = false;
  }
}
function zeigeDatenschutzLesen(rolle){ return dsDialog(rolle || dsTextRolle(), 'lesen'); }

// ===========================================================================
// ADMIN-KONTEN, Schritt C: Mein Konto, Konten-Verwaltung, Passwort, Zusatzpasswort
// ===========================================================================
let adminStepup = null;          // {token, bis} — "Passwort fuer heikle Aktionen", 10 Minuten
let adminStepupLaeuft = null;

function kdDatum(iso){
  if(!iso) return '–';
  const d = new Date(iso);
  return isNaN(d) ? '–' : d.toLocaleString('de-DE', {dateStyle: 'short', timeStyle: 'short'});
}
// Einfacher Dialog-Rahmen (eigene ID, damit er neben bestaetigen()/eingabe() bestehen kann).
function kdDialog(innerHtml, init){
  const ov = document.createElement('div');
  ov.id = 'kdOverlay';
  ov.innerHTML = '<div class="dlg" role="dialog" aria-modal="true">' + innerHtml + '</div>';
  document.body.appendChild(ov);
  const zu = function(){ if(ov.parentNode) ov.parentNode.removeChild(ov); };
  if(init) init(ov, zu);
  return zu;
}

// "Passwort fuer heikle Aktionen": liefert true, wenn ein Zusatz-Token geholt wurde.
function adminStepupHolen(){
  if(adminStepupLaeuft) return adminStepupLaeuft;
  adminStepupLaeuft = new Promise(function(fertig){
    kdDialog(
      '<h3 style="margin:0 0 8px 0;">🔒 Zur Sicherheit: Passwort bestätigen</h3>' +
      '<p class="dlg-text">Das ist eine heikle Aktion. Bitte gib dein Passwort noch einmal ein. Danach gilt es 10 Minuten für weitere heikle Aktionen.</p>' +
      '<input type="password" id="kdStepupPw" autocomplete="current-password" aria-label="Passwort" style="width:100%; box-sizing:border-box; margin:0 0 10px 0;">' +
      '<div class="err" id="kdStepupFehler" role="alert"></div>' +
      '<div class="dlg-knoepfe"><button type="button" class="btn ghost" id="kdStepupAbbr">Abbrechen</button><button type="button" class="btn" id="kdStepupOk">Bestätigen</button></div>',
      function(ov, zu){
        const pw = document.getElementById('kdStepupPw');
        const ende = function(wert){ zu(); fertig(wert); };
        const senden = async function(){
          const fehler = document.getElementById('kdStepupFehler');
          fehler.textContent = '';
          if(!pw.value){ fehler.textContent = 'Bitte Passwort eingeben.'; return; }
          document.getElementById('kdStepupOk').disabled = true;
          try{
            const r = await epCallOhneAktion({action: 'admin_stepup', pass: currentAuthPass, passwort: pw.value});
            adminStepup = {token: r.stepup, bis: r.stepupGueltigBis};
            ende(true);
          }catch(e){
            fehler.textContent = e.message;
            document.getElementById('kdStepupOk').disabled = false;
            pw.select();
          }
        };
        document.getElementById('kdStepupOk').addEventListener('click', senden);
        document.getElementById('kdStepupAbbr').addEventListener('click', function(){ ende(false); });
        pw.addEventListener('keydown', function(e){ if(e.key === 'Enter') senden(); else if(e.key === 'Escape') ende(false); });
        pw.focus();
      }
    );
  }).finally(function(){ adminStepupLaeuft = null; });
  return adminStepupLaeuft;
}

// Passwort aendern. pflicht = true: Einmalpasswort muss ersetzt werden (nicht schliessbar).
function zeigePasswortWechselDialog(pflicht){
  return new Promise(function(fertig){
    kdDialog(
      '<h3 style="margin:0 0 8px 0;">🔑 ' + (pflicht ? 'Eigenes Passwort festlegen' : 'Passwort ändern') + '</h3>' +
      '<p class="dlg-text">' + (pflicht ? 'Du hast ein Einmalpasswort bekommen. Lege jetzt dein eigenes fest.' : 'Beim Ändern werden deine anderen Geräte abgemeldet.') +
      ' Mindestens 12 Zeichen – am besten drei oder vier Wörter hintereinander.</p>' +
      '<label class="dlg-label" for="kdPwAlt">' + (pflicht ? 'Einmalpasswort' : 'Bisheriges Passwort') + '</label>' +
      '<input type="password" id="kdPwAlt" autocomplete="current-password">' +
      '<label class="dlg-label" for="kdPwNeu">Neues Passwort</label>' +
      '<input type="password" id="kdPwNeu" autocomplete="new-password">' +
      '<label class="dlg-label" for="kdPwNeu2">Neues Passwort wiederholen</label>' +
      '<input type="password" id="kdPwNeu2" autocomplete="new-password">' +
      '<div class="err" id="kdPwFehler" role="alert"></div>' +
      '<div class="dlg-knoepfe">' + (pflicht ? '<button type="button" class="btn ghost" id="kdPwAbmelden">Abmelden</button>' : '<button type="button" class="btn ghost" id="kdPwAbbr">Abbrechen</button>') +
      '<button type="button" class="btn" id="kdPwOk">Passwort speichern</button></div>',
      function(ov, zu){
        const el = function(id){ return document.getElementById(id); };
        el('kdPwOk').addEventListener('click', async function(){
          const fehler = el('kdPwFehler'); fehler.textContent = '';
          if(!el('kdPwAlt').value || !el('kdPwNeu').value){ fehler.textContent = 'Bitte alle Felder ausfüllen.'; return; }
          if(el('kdPwNeu').value.length < 12){ fehler.textContent = 'Das neue Passwort muss mindestens 12 Zeichen lang sein.'; return; }
          if(el('kdPwNeu').value !== el('kdPwNeu2').value){ fehler.textContent = 'Die beiden neuen Passwörter sind nicht gleich.'; return; }
          el('kdPwOk').disabled = true;
          try{
            const r = await epCallOhneAktion({action: 'admin_passwort_aendern', pass: currentAuthPass, altesPasswort: el('kdPwAlt').value, neuesPasswort: el('kdPwNeu').value});
            adminZugriff = {token: r.accessToken, bis: r.accessGueltigBis};
            currentAuthPass = r.accessToken;
            adminKontoInfo = r.konto;
            adminStepup = null;
            zu();
            alert('Passwort gespeichert.' + (r.andereGeraeteAbgemeldet ? ' ' + r.andereGeraeteAbgemeldet + ' andere(s) Gerät(e) abgemeldet.' : ''));
            fertig(true);
          }catch(e){
            fehler.textContent = e.message;
            el('kdPwOk').disabled = false;
          }
        });
        if(pflicht){
          el('kdPwAbmelden').addEventListener('click', function(){ zu(); logoutApp(); fertig(false); });
        }else{
          el('kdPwAbbr').addEventListener('click', function(){ zu(); fertig(false); });
        }
        el('kdPwAlt').focus();
      }
    );
  });
}

// Einmalpasswort einmalig anzeigen
function zeigeEinmalPasswort(titel, name, pw){
  return new Promise(function(fertig){
    kdDialog(
      '<h3 style="margin:0 0 8px 0;">' + escapeHtml(titel) + '</h3>' +
      '<p class="dlg-text">Einmalpasswort für <strong>' + escapeHtml(name) + '</strong>. Es wird nur jetzt angezeigt. Gib es persönlich weiter, nicht in einer Gruppe oder per E-Mail. Beim ersten Anmelden muss ' + escapeHtml(name) + ' ein eigenes Passwort festlegen.</p>' +
      '<div style="font-family:monospace; font-size:1.25rem; text-align:center; background:#FAF7F0; border:1px solid var(--line,#e5dfd3); border-radius:8px; padding:12px; margin:0 0 12px 0; user-select:all;" id="kdEinmal">' + escapeHtml(pw) + '</div>' +
      '<div class="err" id="kdEinmalHinweis" style="color:#1a7f37;"></div>' +
      '<div class="dlg-knoepfe"><button type="button" class="btn ghost" id="kdKopieren">Kopieren</button><button type="button" class="btn" id="kdEinmalOk">Habe ich notiert</button></div>',
      function(ov, zu){
        document.getElementById('kdKopieren').addEventListener('click', async function(){
          try{ await navigator.clipboard.writeText(pw); document.getElementById('kdEinmalHinweis').textContent = 'Kopiert.'; }
          catch(e){ document.getElementById('kdEinmalHinweis').textContent = 'Kopieren nicht möglich – bitte markieren und abschreiben.'; }
        });
        document.getElementById('kdEinmalOk').addEventListener('click', function(){ zu(); fertig(); });
        document.getElementById('kdEinmalOk').focus();
      }
    );
  });
}

// ---------- Kachel "Mein Konto & Geraete" ----------
async function renderVwMeinKonto(){
  const el = document.getElementById('vwMeinKontoInhalt');
  el.innerHTML = 'Lädt…';
  pushKarteRendern('pushKarteAdmin');
  try{
    const r = await epCallOhneAktion({action: 'admin_meine_geraete', pass: currentAuthPass});
    const k = adminKontoInfo || {};
    el.innerHTML =
      '<div class="card" style="text-align:left;"><strong>' + escapeHtml(k.name || '') + '</strong>' + (k.kontenVerwalter ? ' <span class="kd-badge">Konten-Verwalter</span>' : '') +
      '<div class="dp-hint" style="margin-top:4px;">Anmeldename: ' + escapeHtml(k.anmeldename || '') + '</div>' +
      '<button class="btn ghost" id="kdPwAendernBtn" style="margin-top:10px;">🔑 Passwort ändern</button></div>' +
      '<h3 style="margin:16px 0 6px; text-align:left;">Meine Geräte</h3>' +
      '<div class="dp-hint" style="text-align:left; margin:0 0 8px 0;">Auf diesen Geräten bist du angemeldet. Ein Gerät, das du nicht kennst oder verloren hast, meldest du hier ab.</div>' +
      (r.geraete.length ? r.geraete.map(function(g){
        return '<div class="card kd-zeile"><div style="text-align:left; flex:1;"><strong>' + escapeHtml(g.name) + '</strong>' + (g.aktuell ? ' <span class="kd-badge">dieses Gerät</span>' : '') +
          '<div class="dp-hint" style="margin:2px 0 0 0;">zuletzt benutzt ' + escapeHtml(kdDatum(g.zuletztBenutzt)) + ' · angemeldet bis ' + escapeHtml(kdDatum(g.gueltigBis)) + (g.gemerkt ? ' · bleibt angemeldet' : '') + '</div></div>' +
          '<button class="btn ghost" data-kd-geraet="' + escapeHtml(g.id) + '" data-kd-aktuell="' + (g.aktuell ? '1' : '') + '">Abmelden</button></div>';
      }).join('') : '<p style="color:#7a7266;">Keine Geräte.</p>') +
      (r.geraete.length > 1 ? '<button class="btn ghost" id="kdAndereAbBtn" style="margin-top:8px; width:100%;">Alle anderen Geräte abmelden</button>' : '');
    document.getElementById('kdPwAendernBtn').addEventListener('click', async function(){
      if(await zeigePasswortWechselDialog(false)) renderVwMeinKonto();
    });
    el.querySelectorAll('[data-kd-geraet]').forEach(function(b){
      b.addEventListener('click', async function(){
        const dieses = b.dataset.kdAktuell === '1';
        if(!(await bestaetigen(dieses ? 'Dieses Gerät abmelden? Du musst dich danach neu anmelden.' : 'Dieses Gerät abmelden?', {ok: 'Abmelden', gefahr: false}))) return;
        try{
          await epCallOhneAktion({action: 'admin_geraet_abmelden', pass: currentAuthPass, geraetId: b.dataset.kdGeraet});
          if(dieses){ adminSitzungLoeschen(); location.reload(); return; }
          renderVwMeinKonto();
        }catch(e){ alert(e.message); }
      });
    });
    const alle = document.getElementById('kdAndereAbBtn');
    if(alle) alle.addEventListener('click', async function(){
      if(!(await bestaetigen('Alle anderen Geräte abmelden? Dieses Gerät bleibt angemeldet.', {ok: 'Abmelden', gefahr: false}))) return;
      try{
        const r2 = await epCallOhneAktion({action: 'admin_alle_geraete_abmelden', pass: currentAuthPass});
        alert(r2.anzahl + ' Gerät(e) abgemeldet.');
        renderVwMeinKonto();
      }catch(e){ alert(e.message); }
    });
  }catch(e){
    el.innerHTML = '<div class="err">Konnte nicht geladen werden: ' + escapeHtml(e.message) + '</div>';
  }
}

// ---------- Kachel "Admin-Konten" (nur Konten-Verwalter) ----------
async function renderVwKonten(){
  const el = document.getElementById('vwKontenInhalt');
  el.innerHTML = 'Lädt…';
  try{
    const [kj, pj] = await Promise.all([
      epCallOhneAktion({action: 'admin_konten_liste', pass: currentAuthPass}),
      epCallOhneAktion({action: 'admin_personen_list', pass: currentAuthPass}),
    ]);
    const mitKonto = {};
    kj.konten.forEach(function(k){ mitKonto[k.personId] = true; });
    const frei = (pj.personen || []).filter(function(p){ return !mitKonto[p.id]; })
      .sort(function(a, b){ return (a.vorname + ' ' + a.nachname).localeCompare(b.vorname + ' ' + b.nachname, 'de'); });
    el.innerHTML =
      '<div class="card" style="text-align:left;"><strong>Neues Konto anlegen</strong>' +
      '<div class="dp-hint" style="margin:4px 0 8px 0;">Die Person muss in der Kartei stehen. Du bekommst ein Einmalpasswort, das du persönlich weitergibst.</div>' +
      '<select id="kdNeuPerson" style="width:100%; box-sizing:border-box; margin-bottom:8px;"><option value="">– Person wählen –</option>' +
      frei.map(function(p){ return '<option value="' + escapeHtml(p.id) + '" data-vorname="' + escapeHtml(p.vorname || '') + '">' + escapeHtml((p.vorname || '') + ' ' + (p.nachname || '')) + '</option>'; }).join('') + '</select>' +
      '<input type="text" id="kdNeuName" placeholder="Anmeldename (klein, z. B. nick)" autocapitalize="none" spellcheck="false" style="width:100%; box-sizing:border-box; margin-bottom:8px;">' +
      '<div class="err" id="kdNeuFehler" role="alert"></div>' +
      '<button class="btn" id="kdNeuBtn">Konto anlegen</button></div>' +
      '<h3 style="margin:16px 0 6px; text-align:left;">Konten (' + kj.konten.length + ')</h3>' +
      kj.konten.map(function(k){
        return '<div class="card" style="text-align:left;" data-kd-konto="' + escapeHtml(k.id) + '">' +
          '<strong>' + escapeHtml(k.name) + '</strong> <span class="dp-hint" style="display:inline;">(' + escapeHtml(k.anmeldename) + ')</span>' +
          (k.kontenVerwalter ? ' <span class="kd-badge">Konten-Verwalter</span>' : '') +
          (!k.aktiv ? ' <span class="kd-badge kd-rot">gesperrt</span>' : '') +
          (k.mussPasswortAendern ? ' <span class="kd-badge kd-gelb">Einmalpasswort offen</span>' : '') +
          '<div class="dp-hint" style="margin:2px 0 8px 0;">letzter Login ' + escapeHtml(kdDatum(k.letzterLogin)) + ' · ' + k.geraete + ' Gerät(e)</div>' +
          '<div class="kd-knoepfe">' +
          '<button class="btn ghost" data-kd-aktion="geraete">Geräte</button>' +
          '<button class="btn ghost" data-kd-aktion="reset">Passwort zurücksetzen</button>' +
          '<button class="btn ghost" data-kd-aktion="' + (k.aktiv ? 'sperren' : 'entsperren') + '">' + (k.aktiv ? 'Sperren' : 'Entsperren') + '</button>' +
          '<button class="btn ghost" data-kd-aktion="' + (k.kontenVerwalter ? 'verwalter_weg' : 'verwalter_ja') + '">' + (k.kontenVerwalter ? 'Verwalter-Rolle entziehen' : 'Zum Verwalter machen') + '</button>' +
          '<button class="btn ghost" data-kd-aktion="loeschen" style="color:var(--awo-red,#E2001A);">Löschen</button>' +
          '</div><div class="kd-geraeteliste"></div></div>';
      }).join('');
    const person = document.getElementById('kdNeuPerson');
    person.addEventListener('change', function(){
      const o = person.selectedOptions[0];
      document.getElementById('kdNeuName').value = o && o.dataset.vorname ? o.dataset.vorname.toLowerCase().replace(/[^a-z0-9äöüß._-]/g, '') : '';
    });
    document.getElementById('kdNeuBtn').addEventListener('click', async function(){
      const f = document.getElementById('kdNeuFehler'); f.textContent = '';
      if(!person.value){ f.textContent = 'Bitte eine Person wählen.'; return; }
      const name = document.getElementById('kdNeuName').value.trim().toLowerCase();
      if(!/^[a-z0-9äöüß._-]{2,40}$/.test(name)){ f.textContent = 'Der Anmeldename darf nur Kleinbuchstaben, Ziffern sowie . _ - enthalten (2–40 Zeichen).'; return; }
      try{
        const r = await epCallOhneAktion({action: 'admin_konto_erstellen', pass: currentAuthPass, personId: person.value, anmeldename: name});
        await zeigeEinmalPasswort('Konto angelegt', r.konto.name, r.einmalPasswort);
        renderVwKonten();
      }catch(e){ f.textContent = e.message; }
    });
    el.querySelectorAll('[data-kd-aktion]').forEach(function(b){
      b.addEventListener('click', async function(){
        const karte = b.closest('[data-kd-konto]');
        const id = karte.dataset.kdKonto;
        const k = kj.konten.find(function(x){ return x.id === id; });
        const aktion = b.dataset.kdAktion;
        try{
          if(aktion === 'geraete'){
            const box = karte.querySelector('.kd-geraeteliste');
            if(box.innerHTML){ box.innerHTML = ''; return; }
            const r = await epCallOhneAktion({action: 'admin_meine_geraete', pass: currentAuthPass, kontoId: id});
            box.innerHTML = r.geraete.length ? r.geraete.map(function(g){
              return '<div class="kd-zeile" style="margin-top:6px;"><div style="flex:1;">' + escapeHtml(g.name) + '<div class="dp-hint" style="margin:0;">zuletzt ' + escapeHtml(kdDatum(g.zuletztBenutzt)) + '</div></div><button class="btn ghost" data-kd-ab="' + escapeHtml(g.id) + '">Abmelden</button></div>';
            }).join('') : '<div class="dp-hint">Keine angemeldeten Geräte.</div>';
            box.querySelectorAll('[data-kd-ab]').forEach(function(ab){
              ab.addEventListener('click', async function(){
                if(!(await bestaetigen('Dieses Gerät von ' + k.name + ' abmelden?', {ok: 'Abmelden', gefahr: false}))) return;
                try{ await epCallOhneAktion({action: 'admin_geraet_abmelden', pass: currentAuthPass, geraetId: ab.dataset.kdAb}); renderVwKonten(); }catch(e){ alert(e.message); }
              });
            });
            return;
          }
          if(aktion === 'reset'){
            if(!(await bestaetigen('Passwort von ' + k.name + ' zurücksetzen? ' + k.name + ' wird überall abgemeldet und bekommt ein neues Einmalpasswort.', {ok: 'Zurücksetzen', gefahr: false}))) return;
            const r = await epCallOhneAktion({action: 'admin_konto_passwort_zuruecksetzen', pass: currentAuthPass, kontoId: id});
            await zeigeEinmalPasswort('Passwort zurückgesetzt', k.name, r.einmalPasswort);
          }else if(aktion === 'sperren'){
            if(!(await bestaetigen(k.name + ' sperren? ' + k.name + ' wird sofort überall abgemeldet und kann sich nicht mehr anmelden.', {ok: 'Sperren', gefahr: true}))) return;
            await epCallOhneAktion({action: 'admin_konto_sperren', pass: currentAuthPass, kontoId: id});
          }else if(aktion === 'entsperren'){
            await epCallOhneAktion({action: 'admin_konto_entsperren', pass: currentAuthPass, kontoId: id});
          }else if(aktion === 'verwalter_ja' || aktion === 'verwalter_weg'){
            const ja = aktion === 'verwalter_ja';
            if(!(await bestaetigen(ja ? k.name + ' zum Konten-Verwalter machen? ' + k.name + ' darf dann Konten anlegen, sperren und zurücksetzen.' : k.name + ' die Verwalter-Rolle entziehen?', {ok: ja ? 'Zum Verwalter machen' : 'Entziehen', gefahr: false}))) return;
            await epCallOhneAktion({action: 'admin_konto_verwalter_setzen', pass: currentAuthPass, kontoId: id, verwalter: ja});
          }else if(aktion === 'loeschen'){
            if(!(await bestaetigen('Konto von ' + k.name + ' endgültig löschen? Das Protokoll bleibt erhalten.', {ok: 'Löschen', gefahr: true}))) return;
            await epCallOhneAktion({action: 'admin_konto_loeschen', pass: currentAuthPass, kontoId: id});
          }
          renderVwKonten();
        }catch(e){ if(e && e.message && e.message !== 'Abgebrochen.') alert(e.message); }
      });
    });
  }catch(e){
    el.innerHTML = '<div class="err">Konnte nicht geladen werden: ' + escapeHtml(e.message) + '</div>';
  }
}
function aktualisiereVwKontenKacheln(){
  const mein = document.getElementById('vwKachelMeinKontoWrap');
  const konten = document.getElementById('vwKachelKontenWrap');
  if(mein) mein.style.display = adminKontoModus ? '' : 'none';
  if(konten) konten.style.display = adminKontoModus && adminKontoInfo && adminKontoInfo.kontenVerwalter ? '' : 'none';
  const versionen = document.getElementById('vwKachelVersionenWrap');
  if(versionen) versionen.style.display = adminKontoModus && adminKontoInfo && adminKontoInfo.kontenVerwalter ? '' : 'none';
}

// ===========================================================================
// PROTOKOLL, Schritt D: Wer hat was wann getan (nur lesen, alle Admins)
// ===========================================================================
const PROT_LABELS = {
  admin_login: 'Anmeldung', admin_logout: 'Abmeldung', stepup: 'Passwort-Rückfrage', passwort_geaendert: 'Passwort geändert',
  geraet_abgemeldet: 'Gerät abgemeldet', alle_geraete_abgemeldet: 'Alle Geräte abgemeldet', geraet_gesperrt: 'Gerät gesperrt',
  konto_bootstrap: 'Erstes Konto angelegt', konto_erstellt: 'Konto angelegt', konto_passwort_zurueckgesetzt: 'Konto-Passwort zurückgesetzt',
  konto_gesperrt: 'Konto gesperrt', konto_entsperrt: 'Konto entsperrt', verwalter_ernannt: 'Zum Verwalter gemacht',
  verwalter_entzogen: 'Verwalter-Rolle entzogen', konto_geloescht: 'Konto gelöscht',
  state_set: 'Programm/Daten gespeichert', admin_backup_export: 'Sicherung exportiert',
  kind_angelegt_oder_geaendert: 'Kind angelegt/geändert', kind_geaendert: 'Kind geändert', kind_geloescht: 'Kind gelöscht',
  team_hinweis_hinzugefuegt: 'Team-Hinweis hinzugefügt', team_hinweis_geloescht: 'Team-Hinweis gelöscht',
  alle_team_hinweise_geloescht: 'Alle Team-Hinweise gelöscht', laeusebefall_gemeldet: 'Läusebefall gemeldet', laeusebefall_beendet: 'Läusebefall beendet',
  tagessatz_geaendert: 'Tagessatz geändert', tagessatz_geloescht: 'Tagessatz gelöscht', auszahlung_geaendert: 'Auszahlung geändert',
  quittung_unterschrift_erfasst: 'Quittung unterschrieben', quittung_per_email_versendet: 'Quittung per E-Mail',
  vertrag_vorbereitet: 'Vertrag vorbereitet', vertrag_unterschrift_erfasst: 'Vertrag unterschrieben', vertrag_unterschrift_team_erfasst: 'Vertrag (Team) unterschrieben',
  vertrag_per_email_versendet: 'Vertrag per E-Mail', vertrag_unterschrift_zurueckgesetzt: 'Vertrags-Unterschrift zurückgesetzt',
  person_geburtsdatum_geaendert: 'Geburtsdatum geändert', globale_einstellungen_geaendert: 'Einstellungen geändert',
  frist_angelegt: 'Frist angelegt', frist_bearbeitet: 'Frist bearbeitet', frist_erledigt: 'Frist abgehakt', frist_wieder_geoeffnet: 'Frist wieder geöffnet', frist_geloescht: 'Frist gelöscht', aktion_typ_geaendert: 'Aktionstyp einer Aktion geändert', aktion_sichtbarkeit_geaendert: 'Sichtbarkeit einer Aktion geändert', aktionstyp_angelegt: 'Aktionstyp angelegt', aktionstyp_geloescht: 'Aktionstyp gelöscht', nachweis_geaendert: 'Nachweis geändert', nachweis_geloescht: 'Nachweis gelöscht',
  admin_person_loeschen: 'Person gelöscht', admin_aktionen_loeschen: 'Aktion gelöscht', admin_aktionen_erstellen: 'Aktion angelegt',
  admin_verleih_ausleihe_speichern: 'Verleih gespeichert', admin_verleih_ausleihe_status_setzen: 'Verleih-Status geändert',
  admin_verleih_ausleihe_loeschen: 'Verleih gelöscht', admin_verleih_ausleihe_unterschrift_speichern: 'Verleih unterschrieben',
  admin_dokument_speichern: 'Dokument gespeichert', admin_dokument_loeschen: 'Dokument gelöscht',
  admin_spiel_speichern: 'Spiel gespeichert', admin_spiel_loeschen: 'Spiel gelöscht'
};
function protLabel(a){
  if(PROT_LABELS[a]) return PROT_LABELS[a];
  const t = String(a || '').replace(/^admin_/, '').replace(/_/g, ' ').trim();
  return t ? t.charAt(0).toUpperCase() + t.slice(1) : '–';
}
let protFilter = {};
let protOffset = 0;

function protZeile(e){
  const bad = e.ergebnis && e.ergebnis !== 'ok';
  return '<div class="card" style="text-align:left; padding:10px 12px; margin:6px 0;">' +
    '<div style="display:flex; justify-content:space-between; gap:8px; flex-wrap:wrap;">' +
    '<strong>' + escapeHtml(protLabel(e.aktion)) + '</strong>' +
    '<span class="dp-hint" style="margin:0;">' + escapeHtml(kdDatum(e.zeitpunkt)) + '</span></div>' +
    '<div class="dp-hint" style="margin:2px 0 0 0;">' + escapeHtml(e.akteur) +
    (e.rolle === 'team' ? ' <span class="kd-badge">Team</span>' : '') +
    (bad ? ' <span class="kd-badge kd-rot">' + escapeHtml(e.ergebnis) + '</span>' : '') + '</div>' +
    (e.objekt ? '<div style="margin-top:4px; font-size:0.9rem;">' + escapeHtml(e.objekt) + '</div>' : '') +
    '</div>';
}

async function protLaden(mehr){
  const liste = document.getElementById('protListe');
  const wb = document.getElementById('protMehrBtn');
  if(!mehr){ protOffset = 0; liste.innerHTML = 'Lädt…'; }
  try{
    const r = await epCallOhneAktion({action: 'admin_protokoll_lesen', pass: currentAuthPass, filter: protFilter, limit: 50, offset: protOffset});
    if(!mehr){
      const sel = function(id, werte, leer, aktuell, beschr){
        const el = document.getElementById(id); if(!el || el.dataset.gefuellt) return;
        el.innerHTML = '<option value="">' + leer + '</option>' + werte.map(function(w){ return '<option value="' + escapeHtml(w) + '">' + escapeHtml(beschr ? beschr(w) : w) + '</option>'; }).join('');
        el.dataset.gefuellt = '1';
      };
      sel('protAkteur', r.akteure || [], 'Alle Personen');
      sel('protAktion', r.aktionen || [], 'Alle Arten', null, protLabel);
    }
    const html = (r.eintraege || []).map(protZeile).join('');
    if(!mehr) liste.innerHTML = html || '<p class="dp-hint">Keine Einträge für diese Auswahl.</p>';
    else liste.insertAdjacentHTML('beforeend', html);
    protOffset += (r.eintraege || []).length;
    wb.style.display = r.weitere ? '' : 'none';
  }catch(e){
    liste.innerHTML = '<div class="err" role="alert">' + escapeHtml(e.message || 'Protokoll konnte nicht geladen werden.') + '</div>';
    wb.style.display = 'none';
  }
}

async function renderVwProtokoll(){
  protFilter = {};
  const el = document.getElementById('vwProtokollInhalt');
  el.innerHTML =
    '<div class="card" style="text-align:left;">' +
    '<div style="display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:8px;">' +
    '<label class="dlg-label" style="min-width:0;">Von<input type="date" id="protVon" style="width:100%; box-sizing:border-box; min-width:0;"></label>' +
    '<label class="dlg-label" style="min-width:0;">Bis<input type="date" id="protBis" style="width:100%; box-sizing:border-box; min-width:0;"></label>' +
    '<label class="dlg-label" style="min-width:0;">Person<select id="protAkteur" style="width:100%; box-sizing:border-box; min-width:0;"><option value="">Alle Personen</option></select></label>' +
    '<label class="dlg-label" style="min-width:0;">Art<select id="protAktion" style="width:100%; box-sizing:border-box; min-width:0;"><option value="">Alle Arten</option></select></label>' +
    '</div>' +
    '<label class="dlg-label" style="margin-top:8px; display:flex; align-items:center; gap:8px;"><input type="checkbox" id="protNurProbleme" style="width:auto; flex:none; margin:0;"> nur abgelehnte Versuche</label>' +
    '<div class="kd-knoepfe" style="margin-top:8px;"><button class="btn" id="protFilterBtn">Anzeigen</button>' +
    '<button class="btn ghost" id="protResetBtn">Zurücksetzen</button>' +
    '<button class="btn ghost" id="protPruefenBtn">🔎 Unverändert?</button></div>' +
    '<div id="protPruefErgebnis" class="dp-hint" role="status" style="margin-top:6px;"></div></div>' +
    '<div id="protListe">Lädt…</div>' +
    '<button class="btn ghost" id="protMehrBtn" style="width:100%; display:none;">Weitere laden</button>' +
    '<p class="dp-hint" style="text-align:left;">Gespeichert werden Zeitpunkt, Person, Art und Ziel – keine Passwörter und keine Inhalte. Einträge werden nach 12 Monaten automatisch gelöscht.</p>';
  const anwenden = function(){
    protFilter = {};
    const v = document.getElementById('protVon').value, b = document.getElementById('protBis').value;
    if(v) protFilter.von = v; if(b) protFilter.bis = b;
    const p = document.getElementById('protAkteur').value; if(p) protFilter.akteur = p;
    const a = document.getElementById('protAktion').value; if(a) protFilter.aktion = a;
    if(document.getElementById('protNurProbleme').checked) protFilter.ergebnis = 'abgelehnt';
    protLaden(false);
  };
  document.getElementById('protFilterBtn').addEventListener('click', anwenden);
  document.getElementById('protResetBtn').addEventListener('click', function(){
    ['protVon', 'protBis', 'protAkteur', 'protAktion'].forEach(function(id){ document.getElementById(id).value = ''; });
    document.getElementById('protNurProbleme').checked = false; anwenden();
  });
  document.getElementById('protMehrBtn').addEventListener('click', function(){ protLaden(true); });
  document.getElementById('protPruefenBtn').addEventListener('click', async function(){
    const ziel = document.getElementById('protPruefErgebnis'); ziel.textContent = 'Prüft…';
    try{
      const r = await epCallOhneAktion({action: 'admin_protokoll_pruefen', pass: currentAuthPass});
      ziel.textContent = r.intakt ? '✓ Die Prüfsummen-Kette ist lückenlos: keine nachträgliche Änderung erkennbar.'
        : '⚠ Die Kette ist an Eintrag Nr. ' + r.ersteAbweichung + ' unterbrochen. Bitte Datenschutzbeauftragten/Verwalter informieren.';
    }catch(e){ ziel.textContent = e.message || 'Prüfung nicht möglich.'; }
  });
  await protLaden(false);
}
// Nur weiterlassen, wenn sowohl "unlocked" als auch eine gültige Rolle
// gespeichert sind — nach diesem Update müssen sich alle einmal neu
// einloggen, damit die richtige Rolle zugewiesen wird.
const storedRole = localStorage.getItem('appRole');
// Eltern-Zugang ist pro Aktion (eigener Link, siehe Konzept-Addendum
// Verfügbarkeit/Aktionen-Umbau): aktionId kommt aus dem URL-Parameter
// "?aktion=...", NICHT aus dem localStorage-basierten Aktion-Umschalter
// des Team/Admin-Bereichs.
const urlAktionId = new URLSearchParams(window.location.search).get('aktion');
if(urlAktionId) currentAktionId = urlAktionId;
// Newsletter-Links (Anmeldeformular, Bestätigung, Abmeldung) sind komplett
// unabhängig vom normalen Login — kein Passwort, keine Aktion, keine Rolle
// nötig. Wird der URL-Parameter "?newsletter=..." erkannt, ersetzt dieser
// Zweig den kompletten normalen Boot-Ablauf (Passwort-Bildschirm bleibt
// verborgen) und wird danach sofort beendet (return in einer IIFE), damit
// der restliche Boot-Code darunter gar nicht erst läuft.
const urlNewsletter = new URLSearchParams(window.location.search).get('newsletter');
const urlNewsletterToken = new URLSearchParams(window.location.search).get('token');
const urlPinReset = new URLSearchParams(window.location.search).get('pinreset');
if(urlNewsletter){
  document.getElementById('lockscreen').style.display = 'none';
  document.getElementById('newsletterScreen').style.display = 'grid';
  if(urlNewsletter === 'bestaetigen' && urlNewsletterToken){
    document.getElementById('nlBestaetigenView').style.display = 'block';
    document.getElementById('nlBestaetigenBtn').addEventListener('click', async ()=>{
      const btn = document.getElementById('nlBestaetigenBtn');
      const errEl = document.getElementById('nlBestaetigenError');
      btn.disabled = true;
      errEl.textContent = '';
      try{
        await epCallOhneAktion({action:'newsletter_bestaetigen', token: urlNewsletterToken});
        document.getElementById('nlBestaetigenView').innerHTML = '<h2>📰 Bestätigt ✓</h2><p style="color:#7a7266;">Danke! Deine Newsletter-Anmeldung ist jetzt bestätigt.</p>';
      }catch(e){
        errEl.textContent = 'Fehler: '+e.message;
        btn.disabled = false;
      }
    });
  } else if(urlNewsletter === 'abmelden' && urlNewsletterToken){
    document.getElementById('nlAbmeldenView').style.display = 'block';
    document.getElementById('nlAbmeldenBtn').addEventListener('click', async ()=>{
      const btn = document.getElementById('nlAbmeldenBtn');
      const errEl = document.getElementById('nlAbmeldenError');
      btn.disabled = true;
      errEl.textContent = '';
      try{
        await epCallOhneAktion({action:'newsletter_abmelden', token: urlNewsletterToken});
        document.getElementById('nlAbmeldenView').innerHTML = '<h2>📰 Abgemeldet</h2><p style="color:#7a7266;">Du bekommst keine weiteren Newsletter-Mails mehr. Du kannst dich jederzeit über das Anmeldeformular wieder eintragen.</p>';
      }catch(e){
        errEl.textContent = 'Fehler: '+e.message;
        btn.disabled = false;
      }
    });
  } else if(urlNewsletter === 'bestaetigen' || urlNewsletter === 'abmelden'){
    // Parameter erkannt, aber kein Token dabei — unvollständiger Link.
    document.getElementById('nlUngueltigView').style.display = 'block';
  } else {
    document.getElementById('nlFormularView').style.display = 'block';
    document.getElementById('nlAnmeldenBtn').addEventListener('click', async ()=>{
      const btn = document.getElementById('nlAnmeldenBtn');
      const errEl = document.getElementById('nlFormularError');
      const email = document.getElementById('nl_email').value.trim();
      const vorname = document.getElementById('nl_vorname').value.trim();
      errEl.textContent = '';
      if(!email){ errEl.textContent = 'Bitte E-Mail-Adresse angeben.'; return; }
      btn.disabled = true;
      try{
        const res = await epCallOhneAktion({action:'newsletter_anmelden', email, vorname});
        document.getElementById('nlFormularView').innerHTML = '<h2>📰 Fast geschafft</h2><p style="color:#7a7266;">'+escapeHtml(res.message || 'Bitte prüfe dein Postfach und bestätige die Anmeldung über den Link in der E-Mail.')+'</p>';
      }catch(e){
        errEl.textContent = 'Fehler: '+e.message;
        btn.disabled = false;
      }
    });
  }
} else if(urlPinReset){
  // PIN-Reset-Link aus der E-Mail: komplett ohne Login, nur der Token zaehlt.
  document.getElementById('lockscreen').style.display = 'none';
  document.getElementById('pinResetScreen').style.display = 'grid';
  document.getElementById('prSpeichernBtn').addEventListener('click', async ()=>{
    const btn = document.getElementById('prSpeichernBtn');
    const errEl = document.getElementById('prError');
    const pin = document.getElementById('prPinNeu').value.trim();
    const pinWdh = document.getElementById('prPinNeuWdh').value.trim();
    errEl.textContent = '';
    if(!/^[0-9]{4,6}$/.test(pin)){ errEl.textContent = 'Bitte eine PIN aus 4 bis 6 Ziffern vergeben.'; return; }
    if(pin !== pinWdh){ errEl.textContent = 'Die beiden PINs stimmen nicht überein.'; return; }
    btn.disabled = true;
    try{
      await epCallOhneAktion({action:'pin_reset_einloesen', token: urlPinReset, pin});
      document.getElementById('prFormView').style.display = 'none';
      document.getElementById('prFertigView').style.display = 'block';
      try{ history.replaceState(null, '', window.location.pathname); }catch(_e){}
    }catch(e){
      errEl.textContent = 'Fehler: '+e.message;
      btn.disabled = false;
    }
  });
} else if(adminSitzungLesen()){
  adminSitzungStart();
} else if(localStorage.getItem('unlocked') === 'yes' && (storedRole==='admin' || storedRole==='team' || storedRole==='mitglied')){
  userRole = storedRole;
  currentAuthPass = localStorage.getItem('appPass') || '';
  unlockApp();
} else if(localStorage.getItem('unlocked') === 'yes' && storedRole==='eltern'){
  userRole = 'eltern';
  // SICHERHEITS-FIX (Audit 08/2026): Backend prüft "lookup"/"update" jetzt
  // ebenfalls serverseitig gegen ELTERN_PASSWORD (vorher nur login_check).
  // Das Passwort muss daher wie bei Admin/Team lokal gemerkt und bei jedem
  // Aufruf mitgeschickt werden (siehe epCall).
  currentAuthPass = localStorage.getItem('appPass') || '';
  if(!currentAktionId){
    document.getElementById('lockscreen').innerHTML = '<div class="lockbox"><p>Dieser Link ist unvollständig — bitte den vollständigen Eltern-Link vom Team verwenden.</p></div>';
  } else {
    unlockElternApp();
  }
} else {
  verdrahteLockscreen();
}
function verdrahteLockscreen(){
  document.getElementById('lockSubmit').addEventListener('click', tryUnlock);
  document.getElementById('lockPassword').addEventListener('keydown', (e)=>{
    if(e.key==='Enter') tryUnlock();
  });
  document.getElementById('lockToggle').addEventListener('click', ()=>{
    const feld = document.getElementById('lockPassword');
    const zeigen = feld.type === 'password';
    feld.type = zeigen ? 'text' : 'password';
    const knopf = document.getElementById('lockToggle');
    knopf.textContent = zeigen ? 'verbergen' : 'anzeigen';
    knopf.setAttribute('aria-pressed', zeigen ? 'true' : 'false');
    feld.focus();
  });
  // Admin-Anmeldung mit persoenlichem Konto (Schritt B)
  const wechsel = document.getElementById('adminLoginOeffnenBtn');
  const box = document.getElementById('adminLoginBox');
  const pwBereich = ['lockIntro','lockPwWrap','lockSubmit','lockHinweisText'].map(id=>document.getElementById(id));
  function zeigeAdminForm(an){
    box.style.display = an ? 'block' : 'none';
    pwBereich.forEach(el=>{ if(el) el.style.display = an ? 'none' : ''; });
    wechsel.textContent = an ? '← Zurück zur Passwort-Eingabe' : '🔑 Admin-Anmeldung mit persönlichem Konto';
    document.getElementById('lockError').textContent = '';
    if(an) document.getElementById('adminName').focus(); else document.getElementById('lockPassword').focus();
  }
  wechsel.addEventListener('click', ()=>zeigeAdminForm(box.style.display === 'none'));
  document.getElementById('adminLoginBtn').addEventListener('click', adminKontoLogin);
  ['adminName','adminPw'].forEach(id=>document.getElementById(id).addEventListener('keydown', (e)=>{ if(e.key==='Enter') adminKontoLogin(); }));
  document.getElementById('adminPwToggle').addEventListener('click', ()=>{
    const feld = document.getElementById('adminPw');
    const zeigen = feld.type === 'password';
    feld.type = zeigen ? 'text' : 'password';
    const knopf = document.getElementById('adminPwToggle');
    knopf.textContent = zeigen ? 'verbergen' : 'anzeigen';
    knopf.setAttribute('aria-pressed', zeigen ? 'true' : 'false');
  });
  try{ document.getElementById('adminMerken').checked = localStorage.getItem('adminMerkenWahl') === '1'; }catch(e){}
  // Hinweis von frueher (z.B. Sitzung abgelaufen) anzeigen und gleich das Konto-Formular oeffnen
  let hinweis = '';
  try{ hinweis = sessionStorage.getItem('lockHinweis') || ''; sessionStorage.removeItem('lockHinweis'); }catch(e){}
  if(hinweis){
    zeigeAdminForm(true);
    document.getElementById('adminLoginError').textContent = hinweis;
  }
}
async function tryUnlock(){
  // trim: beim Kopieren/Einfügen rutschen gern Leerzeichen am Rand mit — die waren nie Teil des Passworts.
  const val = document.getElementById('lockPassword').value.trim();
  if(!val){
    document.getElementById('lockError').textContent = 'Bitte zuerst das Passwort eingeben.';
    document.getElementById('lockPassword').focus();
    return;
  }
  document.getElementById('lockError').textContent = '';
  const submitBtn = document.getElementById('lockSubmit');
  if(submitBtn) submitBtn.disabled = true;
  try{
    // Admin/Team/Eltern: serverseitige Prüfung über die Edge Function
    // (login_check) — kein Passwort-Fingerabdruck mehr im Quelltext, der
    // offline durchprobiert werden könnte. Nutzt dieselbe Fehlversuch-
    // Bremse wie alle anderen passwortgeschützten Aktionen.
    const json = await epCallOhneAktion({action:'login_check', pass: val});
    if(json.role === 'admin' || json.role === 'team' || json.role === 'eltern' || json.role === 'mitglied'){
      userRole = json.role;
    } else {
      document.getElementById('lockError').textContent = 'Das Passwort stimmt nicht. Bitte auf Groß-/Kleinschreibung achten (mit dem Knopf „anzeigen“ siehst du, was du getippt hast).';
      return;
    }
  }catch(e){
    // Verständliche Meldungen: Sperre (zu viele Versuche) und fehlende Verbindung getrennt behandeln.
    const msg = String(e && e.message || '');
    document.getElementById('lockError').textContent =
      /zu viele/i.test(msg) ? msg :
      (navigator.onLine === false || /failed to fetch|networkerror|load failed/i.test(msg))
        ? 'Keine Verbindung zum Server. Bitte Internetverbindung prüfen und noch einmal versuchen.'
        : 'Anmeldung nicht möglich: '+msg;
    return;
  }finally{
    if(submitBtn) submitBtn.disabled = false;
  }
  if(userRole === 'eltern' && !currentAktionId){
    document.getElementById('lockError').textContent = 'Dieser Link ist unvollständig — bitte den vollständigen Eltern-Link vom Team verwenden.';
    return;
  }
  localStorage.setItem('unlocked','yes');
  localStorage.setItem('appRole', userRole);
  if(userRole === 'admin' || userRole === 'team' || userRole === 'eltern' || userRole === 'mitglied'){
    // Das Klartext-Passwort wird weiterhin lokal gemerkt (nur im eigenen Browser),
    // weil die Edge Function es serverseitig noch braucht, um Admin/Team-Aktionen zu prüfen.
    // Aus dem Quelltext der Seite selbst ist es damit trotzdem nicht mehr ablesbar.
    // (Seit dem Sicherheits-Fix 08/2026 gilt das auch für "eltern" — lookup/update
    // prüfen das Passwort jetzt ebenfalls serverseitig, nicht mehr nur login_check.)
    currentAuthPass = val;
    localStorage.setItem('appPass', val);
  }
  if(userRole === 'eltern') unlockElternApp();
  else unlockApp();
}

// applyRoleRestrictions: blendet die Bearbeiten-Werkzeuge bei Gruppen und
// Personal aus, wenn die Person sich mit dem Team-Passwort angemeldet hat.
function applyRoleRestrictions(){
  const visSel = document.getElementById('todo_visibility');
  if(visSel) visSel.style.display = isAdmin() ? 'inline-block' : 'none';
  if(isAdmin()) return;
  ['gnManageCard','gAddCard','peAddCard','ztManageCard','krankManageCard','bedarfManageCard'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.style.display = 'none';
  });
  const hint = document.getElementById('roleHint');
  if(hint) hint.style.display = 'block';
  // Verlauf: war bisher fest für Team ausgeblendet, ist jetzt wie die
  // anderen Reiter über den Modul-Schalter der Aktion steuerbar
  // (aktive_module.verlauf, siehe applyModulFilter) — Admin entscheidet
  // pro Aktion, ob Team den Verlauf sehen darf.
  // Nachweise (Führungszeugnis, Ehrenamtsvertrag etc.) sind seit dem Umbau
  // auf aktionsübergreifende Nachweise-Verwaltung kein eigener Reiter mehr,
  // sondern nur noch über den (ebenfalls admin-only) Verwaltungsbereich
  // erreichbar — daher hier kein eigenes Ausblenden mehr nötig.

  // Alle Import-/Export-Funktionen (Massendaten-Zugriff) nur für Admin —
  // Teamende sollen weder Backups/Excel-Dateien herunterladen noch Daten
  // einspielen können. Betrifft: globales Excel/JSON-Backup (Kopfleiste),
  // Personal-Einsatztage-Export, Läusekontroll-Export, Umfragen-Auswertung-
  // Export, Kinder-Tagesübersicht-Export. Nachweise-Export ist ohnehin
  // bereits über den ganzen (admin-only) Verwaltungsbereich unerreichbar.
  // Kinder-Import/-Gruppenlisten-/Protokoll-/Gruppenzuordnung-Export sind
  // bereits an anderer Stelle eigenständig admin-gated (isAdmin()-Check in
  // ihren jeweiligen render*-Funktionen).
  ['exportExcelBtn','importExcelBtn','exportBtn','importBtn','importFile','importExcelFile','importConfirm',
   'pe_export_btn','laeuse_export_btn','ufAuswertungExport','k_tag_export','k_tag_pdf_export'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.style.display = 'none';
  });
}

// logoutApp: entfernt die gespeicherte Freischaltung und lädt die Seite neu.
// Der Reload ist wichtig: ohne ihn blieben zwischengespeicherte Daten der
// vorherigen Anmeldung (z.B. Personal, Tagessätze, Kinderzahlen) im
// Arbeitsspeicher des Browsers hängen, bis man die Seite manuell neu
// geladen hat — genau das Problem, das hier behoben wird.
async function logoutApp(){
  await adminAbmeldenServer();
  adminSitzungLoeschen();
  localStorage.removeItem('unlocked');
  localStorage.removeItem('appRole');
  localStorage.removeItem('appPass');
  location.reload();
}
document.getElementById('logoutBtn').addEventListener('click', logoutApp);
document.getElementById('lockDatenschutzLink').addEventListener('click', ()=>zeigeDatenschutzLesen('alle'));
document.getElementById('dsLesenBtn').addEventListener('click', ()=>zeigeDatenschutzLesen());
document.getElementById('adminKontoEinrichtenBtn').addEventListener('click', zeigeKontoEinrichtenDialog);
document.getElementById('adminKontoSpaeterBtn').addEventListener('click', ()=>{
  document.getElementById('adminKontoBanner').style.display = 'none';
  try{ sessionStorage.setItem('adminKontoBannerAus', '1'); }catch(e){}
});

// --- AKTION-AUSWAHL ---
// Zeigt die Liste vorhandener Aktionen (Ferienfreizeit, Wochenendfahrt,
// Tagesausflug, Gruppenstunde, oder ein vom Admin frei angelegter Typ) —
// jede hat ihren eigenen Datenstand.
// TYP_LABEL nur noch als Anzeige-Fallback für die vier ursprünglichen,
// intern klein geschriebenen Typ-Werte aus der Zeit vor der freien
// Typen-Verwaltung — neue, frei angelegte Typen zeigen direkt ihren Text.
const TYP_LABEL_FALLBACK = {ferienfreizeit:'Ferienfreizeit', tagesausflug:'Tagesausflug', wochenendfahrt:'Wochenendfahrt', gruppenstunde:'Gruppenstunde'};
// aktionAuswahlAktiveCache/-ArchivCache: zuletzt geladene Aktionsliste,
// getrennt nach aktiv/archiviert. Wird von renderAktionAuswahlAktive()
// bei jeder Sucheingabe neu gefiltert gerendert, ohne erneut vom Server
// zu laden.
let aktionAuswahlAktiveCache = [];
let aktionAuswahlArchivCache = [];
let aktionAuswahlOberCache = [];

// baueAktionZeile: einzelne Aktions-Zeile (Name-Button + ggf. Verwalten-
// Button). Gemeinsam für aktive Liste und Archiv-Gruppen genutzt.
function baueAktionZeile(a){
  const zeile = document.createElement('div');
  zeile.style.display = 'flex';
  zeile.style.gap = '6px';
  zeile.style.marginBottom = '6px';
  const btn = document.createElement('button');
  btn.className = 'btn ghost';
  btn.style.flex = '1';
  btn.style.textAlign = 'left';
  const statusHinweis = a.status === 'abgeschlossen' ? ' — archiviert (schreibgeschützt)' : '';
  const sichtbarHinweis = a.sichtbar_fuer_interesse ? (a.sichtbar_beschraenkt ? ' 🔒' : ' 👁') : '';
  btn.textContent = `${a.name} (${TYP_LABEL_FALLBACK[a.typ]||a.typ})${a.ort ? ' · 📍 ' + a.ort : ''}${statusHinweis}${sichtbarHinweis}`;
  btn.addEventListener('click', ()=>betreteAktion(a.id, a));
  zeile.appendChild(btn);
  // "Verwalten" nur für Admin — Modul-Auswahl, Sichtbarkeit,
  // Team-Freischaltungen (siehe Aktion-Verwalten-Screen).
  if(isAdmin()){
    const verwaltenBtn = document.createElement('button');
    verwaltenBtn.className = 'btn ghost';
    verwaltenBtn.textContent = '⚙';
    verwaltenBtn.title = 'Aktion verwalten';
    verwaltenBtn.addEventListener('click', ()=>zeigeAktionVerwalten(a));
    zeile.appendChild(verwaltenBtn);
  }
  return zeile;
}

// renderAktionAuswahlAktive: rendert die aktiven Aktionen, optional
// gefiltert durch den Suchtext. Nach Typ gruppiert (alphabetisch), aber
// NICHT eingeklappt wie das Archiv — aktive Aktionen sollen weiter auf
// einen Blick da sein, nur die Gruppierung schafft Übersicht bei vielen
// Einträgen. Bei nur einer vorkommenden Gruppe wird kein Gruppenkopf
// gezeigt (unnötiger Ballast bei kleinen Vereinen mit nur einem Typ).
function renderAktionAuswahlAktive(suchtext){
  const listeEl = document.getElementById('aktionAuswahlListe');
  listeEl.innerHTML = '';
  if(aktionAuswahlAktiveCache.length === 0){
    listeEl.innerHTML = '<p style="color:#7a7266;">Keine aktiven Aktionen.</p>';
    return;
  }
  const suche = (suchtext||'').trim().toLowerCase();
  const treffer = suche
    ? aktionAuswahlAktiveCache.filter(a=>(a.name||'').toLowerCase().includes(suche))
    : aktionAuswahlAktiveCache;
  if(treffer.length === 0){
    listeEl.innerHTML = '<p style="color:#7a7266;">Keine Aktion gefunden.</p>';
    return;
  }
  // Zugeordnete Aktionen gebündelt unter ihrer Oberaktion (aufklappbar), der Rest wie bisher nach Typ.
  const oberIds = new Set(aktionAuswahlOberCache.map(o=>o.id));
  aktionAuswahlOberCache.slice().sort((x,y)=>(x.name||'').localeCompare(y.name||'','de')).forEach(o=>{
    const kinder = treffer.filter(a=>a.oberaktion_id===o.id)
      .sort((x,y)=>(x.start_datum||'').localeCompare(y.start_datum||'') || (x.name||'').localeCompare(y.name||'','de'));
    if(!kinder.length) return;
    const det = document.createElement('details');
    det.className = 'ober-gruppe';
    det.open = !!suche || kinder.length <= 6;
    const sum = document.createElement('summary');
    const t = document.createElement('span'); t.textContent = `🗂 ${o.name}`;
    const nb = document.createElement('span'); nb.className = 'ober-anzahl'; nb.textContent = kinder.length + (kinder.length === 1 ? ' Aktion' : ' Aktionen');
    sum.appendChild(t); sum.appendChild(nb);
    det.appendChild(sum);
    kinder.forEach(a=>det.appendChild(baueAktionZeile(a)));
    listeEl.appendChild(det);
  });
  const restListe = treffer.filter(a=>!a.oberaktion_id || !oberIds.has(a.oberaktion_id));
  if(restListe.length === 0) return;
  const gruppen = {};
  restListe.forEach(a=>{
    const label = TYP_LABEL_FALLBACK[a.typ] || a.typ || 'Ohne Typ';
    if(!gruppen[label]) gruppen[label] = [];
    gruppen[label].push(a);
  });
  const typSchluessel = Object.keys(gruppen).sort((x,y)=>x.localeCompare(y,'de'));
  const nurEineGruppe = typSchluessel.length <= 1;
  typSchluessel.forEach(label=>{
    const gruppe = gruppen[label].slice().sort((x,y)=>(x.name||'').localeCompare(y.name||'','de'));
    if(!nurEineGruppe){
      const kopf = document.createElement('div');
      kopf.className = 'dp-hint';
      kopf.style.margin = '10px 0 4px 0';
      kopf.textContent = `${label} (${gruppe.length})`;
      listeEl.appendChild(kopf);
    }
    gruppe.forEach(a=>listeEl.appendChild(baueAktionZeile(a)));
  });
}

// renderAktionAuswahlArchiv: eigener Container, damit ein aufgeklapptes
// Archiv beim Tippen ins Suchfeld nicht bei jedem Tastendruck neu gebaut
// wird und dabei wieder zuklappt (Suche wirkt nur auf die aktive Liste).
function renderAktionAuswahlArchiv(){
  const archivEl = document.getElementById('aktionAuswahlArchivListe');
  archivEl.innerHTML = '';
  if(aktionAuswahlArchivCache.length === 0) return;
  // Nach Jahr des Start-Datums gruppiert (neueste zuerst), damit die
  // Liste durch alte Aktionen nicht endlos wächst. Aktionen ohne
  // Start-Datum landen in einer eigenen Gruppe "Ohne Datum" am Ende.
  const jahresGruppen = {};
  aktionAuswahlArchivCache.forEach(a=>{
    const jahr = a.start_datum ? String(a.start_datum).slice(0,4) : 'Ohne Datum';
    if(!jahresGruppen[jahr]) jahresGruppen[jahr] = [];
    jahresGruppen[jahr].push(a);
  });
  const jahresSchluessel = Object.keys(jahresGruppen).filter(j=>j!=='Ohne Datum').sort((a,b)=>b.localeCompare(a));
  if(jahresGruppen['Ohne Datum']) jahresSchluessel.push('Ohne Datum');

  const archivDetails = document.createElement('details');
  archivDetails.className = 'erledigt-fach';
  archivDetails.style.marginTop = '4px';
  const archivSummary = document.createElement('summary');
  archivSummary.textContent = `📦 Archiv (${aktionAuswahlArchivCache.length} abgeschlossene Aktion${aktionAuswahlArchivCache.length===1?'':'en'})`;
  archivDetails.appendChild(archivSummary);

  jahresSchluessel.forEach(jahr=>{
    const gruppe = jahresGruppen[jahr];
    const jahrDetails = document.createElement('details');
    jahrDetails.className = 'erledigt-fach';
    jahrDetails.style.margin = '6px 0 0 10px';
    const jahrSummary = document.createElement('summary');
    jahrSummary.textContent = `${jahr} (${gruppe.length})`;
    jahrDetails.appendChild(jahrSummary);
    gruppe.forEach(a=>jahrDetails.appendChild(baueAktionZeile(a)));
    archivDetails.appendChild(jahrDetails);
  });

  archivEl.appendChild(archivDetails);
}

document.getElementById('aktionAuswahlSuche').addEventListener('input', (e)=>{
  renderAktionAuswahlAktive(e.target.value);
});

// Maske „Neue Aktion anlegen“ schließen und leeren (bei jedem Öffnen der Aktionsauswahl, auch nach dem Anlegen).
function aktionNeuSchliessen(){
  document.getElementById('aktionNeuBereich').style.display = 'none';
  document.getElementById('aktionNeuAnzeigenBtn').style.display = isAdmin() ? 'block' : 'none';
  ['aktionNeuName','aktionNeuTypNeuer','aktionNeuOrt','aktionNeuBenoetigtePersonal','aktionNeuStart','aktionNeuEnde'].forEach(id=>{ const el = document.getElementById(id); if(el) el.value = ''; });
  ['aktionNeuWiederkehrend','aktionNeuSichtbar'].forEach(id=>{ const el = document.getElementById(id); if(el) el.checked = false; });
  const ob = document.getElementById('aktionNeuOberaktion'); if(ob) ob.value = '';
  neuSichtZuruecksetzen();
}
async function zeigeAktionAuswahl(){
  aktionNeuSchliessen();
  document.getElementById('appShell').style.display = 'none';
  document.getElementById('aktionAuswahlScreen').style.display = 'grid';
  document.getElementById('aktionAuswahlError').textContent = '';
  document.getElementById('aktionAuswahlSuche').value = '';
  document.getElementById('aktionAuswahlSucheWrap').style.display = 'none';
  const listeEl = document.getElementById('aktionAuswahlListe');
  listeEl.textContent = 'Lädt…';
  document.getElementById('aktionAuswahlArchivListe').innerHTML = '';
  try{
    const json = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass});
    const aktionen = json.aktionen || [];
    aktionAuswahlOberCache = json.oberaktionen || [];
    aktionAuswahlAktiveCache = aktionen.filter(a=>a.status !== 'abgeschlossen');
    aktionAuswahlArchivCache = aktionen.filter(a=>a.status === 'abgeschlossen');
    // Suchfeld nur einblenden, wenn genug aktive Aktionen da sind, dass
    // Suchen wirklich hilft — bei kleinen Vereinen mit wenigen Aktionen
    // bleibt die Ansicht wie bisher ohne zusätzliches Feld.
    document.getElementById('aktionAuswahlSucheWrap').style.display = aktionAuswahlAktiveCache.length > 6 ? 'block' : 'none';
    renderAktionAuswahlAktive('');
    renderAktionAuswahlArchiv();
  }catch(e){
    listeEl.innerHTML = '';
    document.getElementById('aktionAuswahlError').textContent = 'Fehler beim Laden: '+e.message;
  }
  // Neue Aktion anlegen nur für Admin sichtbar
  document.getElementById('aktionNeuAnzeigenBtn').style.display = isAdmin() ? 'block' : 'none';
}
// ladeAktionsTypen: befüllt die Typ-Auswahl beim Anlegen einer neuen Aktion
// aus der vom Admin frei verwaltbaren Liste (aktions_typen). Wird sowohl
// beim Öffnen des "Neue Aktion"-Bereichs als auch nach dem Hinzufügen
// eines neuen Typs erneut aufgerufen.
// Oberaktionen für die Auswahl beim Anlegen (nur noch offene).
async function ladeNeuOberaktionen(){
  const sel = document.getElementById('aktionNeuOberaktion');
  try{
    const oj = await epCallOhneAktion({action:'admin_oberaktionen_liste', pass: currentAuthPass});
    sel.innerHTML = '<option value="">– keine –</option>' + (oj.oberaktionen||[]).filter(o=>!o.abgeschlossen_am)
      .map(o=>'<option value="' + escapeHtml(o.id) + '">' + escapeHtml(o.name) + '</option>').join('');
  }catch(e){ /* Oberaktionen nicht ladbar: Feld bleibt bei „keine“ */ }
}
async function ladeAktionsTypen(vorauswahl){
  const sel = document.getElementById('aktionNeuTyp');
  try{
    const json = await epCallOhneAktion({action:'admin_aktionstypen_list', pass: currentAuthPass});
    const typen = json.typen || [];
    sel.innerHTML = typen.map(t=>`<option value="${escapeHtml(t.name)}">${escapeHtml(t.name)}</option>`).join('');
    if(vorauswahl) sel.value = vorauswahl;
  }catch(e){
    document.getElementById('aktionAuswahlError').textContent = 'Fehler beim Laden der Aktions-Typen: '+e.message;
  }
}
