// ================================================================
// TEAM-EINSTIEG (zweistufiger Zugang: identifizieren -> Interesse
// anmelden -> von Admin freigeschaltet werden -> Aktion betreten)
// ================================================================
// Nur Module mit eigenem Nav-Reiter (data-modul-Attribut) — "gehalt" ist
// Teil des Personal-Reiters ohne eigene Sichtbarkeits-Steuerung, taucht
// deshalb hier bewusst nicht auf (eine Checkbox ohne sichtbare Wirkung
// wäre nur verwirrend).
// "nachweise" ist seit dem Umbau auf aktionsübergreifende Nachweise-Verwaltung
// (Verwaltungsbereich) kein pro-Aktion-Modul mehr — daher hier bewusst entfernt.
const MODUL_LABEL = {
  programm:'Programm', gruppen:'Gruppen', personal:'Personal',
  umfragen:'Umfragen', material:'Material', einkauf:'Einkaufsliste', dienste:'Dienste',
  verfuegbarkeit:'Verfügbarkeit', aufgaben:'Aufgabenliste', kinder:'Kinder', verlauf:'Verlauf', todo:'To-Do',
  wuensche:'Wünsche', anleitung:'Anleitung', feedback:'Feedback',
};

// zeigeTeamEinstieg: wenn schon eine Person aus einer früheren Sitzung im
// Browser gemerkt ist, direkt zur Aktionsübersicht — sonst erst identifizieren.
function zeigeTeamEinstieg(){
  if(teamPersonId) zeigeTeamAktionsUebersicht();
  else zeigeTeamIdentifikation();
}

async function zeigeTeamIdentifikation(){
  alleAuswahlScreensAusblenden();
  document.getElementById('teamIdentifikationScreen').style.display = 'grid';
  document.getElementById('teamIdError').textContent = '';
  // Immer bei der Personenauswahl starten, nicht mitten im PIN-Schritt
  // (z.B. nach "Andere Identität" oder erneutem Aufruf) — siehe auch
  // teamIdPinZurueckBtn, der denselben Reset auslöst.
  document.getElementById('teamIdPinBereich').style.display = 'none';
  document.getElementById('teamIdPersonWahl').style.display = 'block';
  document.getElementById('teamIdPinError').textContent = '';
  teamIdPendingPersonId = '';
  // Keine Namensliste mehr: jede Person tippt ihren eigenen Namen.
  document.getElementById('teamIdVorname').value = '';
  document.getElementById('teamIdNachname').value = '';
}

// ---------------------------------------------------------------
// PIN-Schritt (schließt die Lücke: bisher konnte sich jeder mit dem
// Team-Passwort als jede beliebige Kartei-Person ausgeben und den
// Namen jederzeit wechseln). Ablauf: Person wählen/anlegen -> Server
// fragen, ob für diesen Namen schon eine PIN existiert -> je nachdem
// neue PIN festlegen (Selbstbedienung, "wer zuerst kommt") oder
// bestehende PIN abfragen. Auf einem einmal verifizierten Gerät bleibt
// die Identität wie bisher über localStorage gemerkt — die PIN wird
// nur bei einer neuen Geräte-/Browser-Zuordnung erneut verlangt.
// ---------------------------------------------------------------
let teamIdPendingPersonId = '';

document.getElementById('teamIdWeiterBtn').addEventListener('click', async ()=>{
  const errEl = document.getElementById('teamIdError');
  errEl.textContent = '';
  const vorname = document.getElementById('teamIdVorname').value.trim();
  const nachname = document.getElementById('teamIdNachname').value.trim();
  try{
    if(!vorname || !nachname){ errEl.textContent = 'Bitte Vor- und Nachname eingeben.'; return; }
    const json = await epCallOhneAktion({action:'team_identifizieren', pass: currentAuthPass, vorname, nachname});
    await zeigeTeamPinSchritt(json.personId, true, !!json.pinGesetzt);
  }catch(e){
    errEl.textContent = 'Fehler: '+e.message;
  }
});

async function zeigeTeamPinSchritt(personId, statusSchonBekannt, pinSchonGesetzt){
  teamIdPendingPersonId = personId;
  const pinErrEl = document.getElementById('teamIdPinError');
  pinErrEl.textContent = '';
  document.getElementById('teamIdPinNeu').value = '';
  document.getElementById('teamIdPinNeuWdh').value = '';
  document.getElementById('teamIdPinEingabe').value = '';
  let pinGesetzt = !!pinSchonGesetzt;
  if(!statusSchonBekannt){
    try{
      const statusJson = await epCallOhneAktion({action:'person_pin_status', pass: currentAuthPass, personId});
      pinGesetzt = !!statusJson.pinGesetzt;
    }catch(e){
      document.getElementById('teamIdError').textContent = 'Fehler: '+e.message;
      return;
    }
  }
  document.getElementById('teamIdPersonWahl').style.display = 'none';
  document.getElementById('teamIdPinBereich').style.display = 'block';
  document.getElementById('teamIdPinNeuBereich').style.display = pinGesetzt ? 'none' : 'block';
  document.getElementById('teamIdPinEingabeBereich').style.display = pinGesetzt ? 'block' : 'none';
  document.getElementById('teamIdPinWer').textContent = pinGesetzt
    ? 'Bitte deine PIN eingeben, um zu bestätigen, dass du das wirklich bist.'
    : 'Diesen Namen gibt es noch ohne PIN — leg jetzt eine fest, damit ihn ab sofort nur noch du verwenden kannst.';
  (pinGesetzt ? document.getElementById('teamIdPinEingabe') : document.getElementById('teamIdPinNeu')).focus();
}

document.getElementById('teamIdPinZurueckBtn').addEventListener('click', ()=>{
  document.getElementById('teamIdPinBereich').style.display = 'none';
  document.getElementById('teamIdPersonWahl').style.display = 'block';
  document.getElementById('teamIdPinError').textContent = '';
  teamIdPendingPersonId = '';
});

document.getElementById('teamIdPinBestaetigenBtn').addEventListener('click', async ()=>{
  const pinErrEl = document.getElementById('teamIdPinError');
  pinErrEl.textContent = '';
  if(!teamIdPendingPersonId){ pinErrEl.textContent = 'Bitte zuerst eine Person auswählen.'; return; }
  const neuBereichSichtbar = document.getElementById('teamIdPinNeuBereich').style.display !== 'none';
  try{
    let pinErgebnis;
    if(neuBereichSichtbar){
      const pin = document.getElementById('teamIdPinNeu').value.trim();
      const pinWdh = document.getElementById('teamIdPinNeuWdh').value.trim();
      if(!/^[0-9]{4,6}$/.test(pin)){ pinErrEl.textContent = 'Bitte eine PIN aus 4 bis 6 Ziffern vergeben.'; return; }
      if(pin !== pinWdh){ pinErrEl.textContent = 'Die beiden PINs stimmen nicht überein.'; return; }
      pinErgebnis = await epCallOhneAktion({action:'person_pin_setzen', pass: currentAuthPass, personId: teamIdPendingPersonId, pin});
    } else {
      const pin = document.getElementById('teamIdPinEingabe').value.trim();
      if(!pin){ pinErrEl.textContent = 'Bitte PIN eingeben.'; return; }
      pinErgebnis = await epCallOhneAktion({action:'person_pin_pruefen', pass: currentAuthPass, personId: teamIdPendingPersonId, pin});
    }
    teamPersonId = teamIdPendingPersonId;
    localStorage.setItem('teamPersonId', teamPersonId);
    // SICHERHEITS-FIX (Audit 08/2026): das vom Server nach erfolgreicher
    // PIN-Prüfung ausgestellte Token merken — wird ab jetzt bei allen
    // Team-Aktionen automatisch mitgeschickt (siehe epCall/epCallOhneAktion).
    personToken = pinErgebnis && pinErgebnis.personToken ? pinErgebnis.personToken : '';
    localStorage.setItem('personToken', personToken);
    zeigeTeamAktionsUebersicht();
  }catch(e){
    pinErrEl.textContent = 'Fehler: '+e.message;
  }
});

// "PIN vergessen?": fordert einen Reset-Link per E-Mail an (Team + Mitglieder).
// Der Server antwortet immer gleich, damit nichts ueber hinterlegte Adressen verraten wird.
async function pinVergessenAnfordern(art, id, btnId, infoId){
  const btn = document.getElementById(btnId);
  const info = document.getElementById(infoId);
  info.textContent = '';
  if(!id){ info.textContent = 'Bitte zuerst eine Person auswählen.'; return; }
  btn.disabled = true;
  try{
    const res = await epCallOhneAktion({action:'pin_reset_anfordern', pass: currentAuthPass, art, id});
    info.textContent = (res && res.hinweis) || 'Falls für dich eine E-Mail-Adresse hinterlegt ist, ist ein Link unterwegs.';
    setTimeout(()=>{ btn.disabled = false; }, 30000);
  }catch(e){
    info.textContent = 'Fehler: '+e.message;
    btn.disabled = false;
  }
}
document.getElementById('teamIdPinVergessenBtn').addEventListener('click', ()=> pinVergessenAnfordern('person', teamIdPendingPersonId, 'teamIdPinVergessenBtn', 'teamIdPinVergessenInfo'));
document.getElementById('mgIdPinVergessenBtn').addEventListener('click', ()=> pinVergessenAnfordern('mitglied', mitgliedIdPending, 'mgIdPinVergessenBtn', 'mgIdPinVergessenInfo'));

