async function zeigeMitgliedIdentifikation(){
  alleAuswahlScreensAusblenden();
  document.getElementById('mitgliedIdentifikationScreen').style.display = 'grid';
  document.getElementById('mgIdError').textContent = '';
  document.getElementById('mgIdPinBereich').style.display = 'none';
  document.getElementById('mgIdPersonWahl').style.display = 'block';
  document.getElementById('mgIdPinError').textContent = '';
  mitgliedIdPending = '';
  // Keine Namensliste mehr: jede Person tippt ihren eigenen Namen.
  document.getElementById('mgIdName').value = '';
}

document.getElementById('mgIdWeiterBtn').addEventListener('click', async ()=>{
  const errEl = document.getElementById('mgIdError');
  errEl.textContent = '';
  const name = document.getElementById('mgIdName').value.trim();
  if(!name){ errEl.textContent = 'Bitte deinen Namen eingeben.'; return; }
  let gefunden;
  try{
    gefunden = await epCallOhneAktion({action:'mitglied_identifizieren', pass: currentAuthPass, name});
  }catch(e){ errEl.textContent = 'Fehler: '+e.message; return; }
  const pinGesetzt = !!gefunden.pinGesetzt;
  mitgliedIdPending = gefunden.mitgliedId;
  document.getElementById('mgIdPinError').textContent = '';
  document.getElementById('mgIdPinNeu').value = '';
  document.getElementById('mgIdPinNeuWdh').value = '';
  document.getElementById('mgIdPinEingabe').value = '';
  document.getElementById('mgIdPersonWahl').style.display = 'none';
  document.getElementById('mgIdPinBereich').style.display = 'block';
  document.getElementById('mgIdPinNeuBereich').style.display = pinGesetzt ? 'none' : 'block';
  document.getElementById('mgIdPinEingabeBereich').style.display = pinGesetzt ? 'block' : 'none';
  document.getElementById('mgIdPinWer').textContent = pinGesetzt
    ? 'Bitte deine PIN eingeben, um zu bestätigen, dass du das wirklich bist.'
    : 'Für diesen Namen gibt es noch keine PIN — leg jetzt eine fest, damit ihn ab sofort nur noch du verwenden kannst.';
  (pinGesetzt ? document.getElementById('mgIdPinEingabe') : document.getElementById('mgIdPinNeu')).focus();
});

document.getElementById('mgIdPinZurueckBtn').addEventListener('click', ()=>{
  document.getElementById('mgIdPinBereich').style.display = 'none';
  document.getElementById('mgIdPersonWahl').style.display = 'block';
  document.getElementById('mgIdPinError').textContent = '';
  mitgliedIdPending = '';
});

document.getElementById('mgIdPinBestaetigenBtn').addEventListener('click', async ()=>{
  const pinErrEl = document.getElementById('mgIdPinError');
  pinErrEl.textContent = '';
  if(!mitgliedIdPending){ pinErrEl.textContent = 'Bitte zuerst eine Person auswählen.'; return; }
  const neuBereichSichtbar = document.getElementById('mgIdPinNeuBereich').style.display !== 'none';
  try{
    let pinErgebnis;
    if(neuBereichSichtbar){
      const pin = document.getElementById('mgIdPinNeu').value.trim();
      const pinWdh = document.getElementById('mgIdPinNeuWdh').value.trim();
      if(!/^[0-9]{4,6}$/.test(pin)){ pinErrEl.textContent = 'Bitte eine PIN aus 4 bis 6 Ziffern vergeben.'; return; }
      if(pin !== pinWdh){ pinErrEl.textContent = 'Die beiden PINs stimmen nicht überein.'; return; }
      pinErgebnis = await epCallOhneAktion({action:'mitglied_pin_setzen', pass: currentAuthPass, mitgliedId: mitgliedIdPending, pin});
    } else {
      const pin = document.getElementById('mgIdPinEingabe').value.trim();
      if(!pin){ pinErrEl.textContent = 'Bitte PIN eingeben.'; return; }
      pinErgebnis = await epCallOhneAktion({action:'mitglied_pin_pruefen', pass: currentAuthPass, mitgliedId: mitgliedIdPending, pin});
    }
    mitgliedId = mitgliedIdPending;
    localStorage.setItem('mitgliedId', mitgliedId);
    mitgliedToken = (pinErgebnis && pinErgebnis.personToken) ? pinErgebnis.personToken : '';
    localStorage.setItem('mitgliedToken', mitgliedToken);
    zeigeSitzungenBereich('mitglied');
  }catch(e){
    pinErrEl.textContent = 'Fehler: '+e.message;
  }
});

document.getElementById('mgIdAbmeldenBtn').addEventListener('click', logoutApp);

// ================================================================
// SITZUNGEN — gemeinsam von Team UND Mitglied genutzte Ansicht der
// eigenen Einladungen mit Zu-/Absage. Welche Rolle gerade aktiv ist,
// steuert aktiverSitzungenTeilnehmerTyp/-Id.
// ================================================================
async function zeigeSitzungenBereich(vonWo){
  if(vonWo === 'mitglied') datenschutzPruefen();
  sitzungenVorherigerScreen = vonWo;
  aktiverSitzungenTeilnehmerTyp = vonWo === 'mitglied' ? 'mitglied' : 'team';
  aktiverSitzungenTeilnehmerId = vonWo === 'mitglied' ? mitgliedId : teamPersonId;
  // Mitglieder: eigener Abmelden-Knopf (Identität bleibt gemerkt, wie beim Team); "Zurück" heißt hier "Andere Person wählen".
  document.getElementById('sitzMeineAbmeldenBtn').style.display = vonWo === 'mitglied' ? 'block' : 'none';
  document.getElementById('sitzMeineZurueckBtn').textContent = vonWo === 'mitglied' ? 'Andere Person wählen' : 'Zurück';
  alleAuswahlScreensAusblenden();
  document.getElementById('sitzungenScreen').style.display = 'grid';
  document.getElementById('sitzMeineError').textContent = '';
  document.getElementById('sitzMeineWer').textContent = '';
  const listeEl = document.getElementById('sitzMeineListe');
  listeEl.textContent = 'Lädt…';
  if(!aktiverSitzungenTeilnehmerId){
    listeEl.innerHTML = '';
    document.getElementById('sitzMeineError').textContent = 'Keine Identität ausgewählt.';
    return;
  }
  try{
    const json = await epCallOhneAktion({action:'sitzungen_meine_liste', pass: currentAuthPass, teilnehmerTyp: aktiverSitzungenTeilnehmerTyp, teilnehmerId: aktiverSitzungenTeilnehmerId});
    renderSitzMeineListe(json.einladungen || []);
  }catch(e){
    listeEl.innerHTML = '';
    document.getElementById('sitzMeineError').textContent = 'Fehler: '+e.message;
  }

  // Dokumente (Migration 67): nur für Mitglieder hier zusätzlich anzeigen —
  // Team sieht dieselben globalen Dokumente bereits im "Allgemein"-Bereich.
  const dokBereichEl = document.getElementById('sitzDokumenteBereich');
  if(aktiverSitzungenTeilnehmerTyp === 'mitglied'){
    dokBereichEl.style.display = 'block';
    await dokListeRenderFuerRolle('sitzDokumenteListe', 'mitglied', null, null);
  } else {
    dokBereichEl.style.display = 'none';
  }
}

function renderSitzMeineListe(einladungen){
  const listeEl = document.getElementById('sitzMeineListe');
  if(einladungen.length === 0){
    listeEl.innerHTML = '<p style="color:#7a7266; margin:0;">Aktuell keine Einladungen.</p>';
    return;
  }
  const fmt = iso=>new Date(iso).toLocaleString('de-DE', {weekday:'short', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'});
  const ANTWORT_LABEL = {offen:'Noch offen', zusage:'✅ Zugesagt', absage:'❌ Abgesagt'};
  listeEl.innerHTML = einladungen.map(e=>{
    const s = e.sitzung;
    const tops = Array.isArray(s.tagesordnungspunkte) ? s.tagesordnungspunkte.filter(t=>t && t.text && t.text.trim()) : [];
    const topListe = tops.length>0 ? `<div style="font-size:0.85rem; margin:6px 0;"><strong>Themen:</strong> ${tops.map(t=>escapeHtml(t.text)).join(', ')}</div>` : '';
    // Protokoll-Notizen nur zeigen, wenn tatsächlich mindestens eine
    // eingetragen wurde (sonst wirkt das Formular vor der Sitzung leer/
    // verwirrend) — Ergebnisse pro TOP, sobald Protokoll erfasst ist.
    const topsMitNotiz = tops.filter(t=>t.notiz && t.notiz.trim());
    const protokollNotizListe = topsMitNotiz.length>0
      ? `<div style="font-size:0.85rem; margin:6px 0;"><strong>Protokoll:</strong><br>${topsMitNotiz.map(t=>`${escapeHtml(t.text)}: ${escapeHtml(t.notiz)}`).join('<br>')}</div>`
      : '';
    const pdfBtn = s.tagesordnung_pdf_dateiname ? `<button type="button" class="btn ghost sitzPdfMeinBtn" data-id="${escapeHtml(s.id)}" style="margin-top:6px; margin-right:6px; font-size:0.8rem; padding:4px 8px;">📎 Tagesordnung: ${escapeHtml(s.tagesordnung_pdf_dateiname)}</button>` : '';
    const protokollPdfBtn = s.protokoll_pdf_dateiname ? `<button type="button" class="btn ghost sitzProtokollPdfMeinBtn" data-id="${escapeHtml(s.id)}" style="margin-top:6px; font-size:0.8rem; padding:4px 8px;">📎 Protokoll: ${escapeHtml(s.protokoll_pdf_dateiname)}</button>` : '';
    return `
    <div class="card" style="margin-bottom:8px; ${s.status==='abgesagt'?'opacity:0.6;':''}" data-id="${escapeHtml(e.id)}">
      <strong>${escapeHtml(s.titel)}</strong>${s.status==='abgesagt' ? ' <span class="tag">Sitzung abgesagt</span>' : ''}
      <div style="font-size:0.82rem; color:#7a7266; margin:4px 0;">${escapeHtml(fmt(s.beginn))}${s.ende ? ' – ' + escapeHtml(new Date(s.ende).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})) + ' Uhr' : ' Uhr'}${s.ort ? ' · ' + escapeHtml(s.ort) : ''}</div>
      ${s.beschreibung ? `<div style="font-size:0.85rem; margin:4px 0;">${escapeHtml(s.beschreibung)}</div>` : ''}
      ${topListe}
      ${protokollNotizListe}
      ${pdfBtn}${protokollPdfBtn}
      <div style="font-size:0.85rem; margin-top:6px;">Deine Antwort: <strong>${ANTWORT_LABEL[e.antwort]||e.antwort}</strong></div>
      ${s.status!=='abgesagt' ? `
      <div style="display:flex; gap:6px; margin-top:8px;">
        <button class="btn ghost sitzZusageBtn" data-id="${escapeHtml(e.id)}" style="flex:1; ${e.antwort==='zusage'?'border-color:var(--ink); font-weight:bold;':''}">✅ Zusagen</button>
        <button class="btn ghost sitzAbsageBtn" data-id="${escapeHtml(e.id)}" style="flex:1; ${e.antwort==='absage'?'border-color:var(--ink); font-weight:bold;':''}">❌ Absagen</button>
      </div>` : ''}
    </div>`;
  }).join('');

  listeEl.querySelectorAll('.sitzPdfMeinBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>sitzPdfOeffnen(btn.dataset.id, aktiverSitzungenTeilnehmerTyp, aktiverSitzungenTeilnehmerId, 'tagesordnung'));
  });
  listeEl.querySelectorAll('.sitzProtokollPdfMeinBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>sitzPdfOeffnen(btn.dataset.id, aktiverSitzungenTeilnehmerTyp, aktiverSitzungenTeilnehmerId, 'protokoll'));
  });

  const antworten = async (einladungId, antwort)=>{
    try{
      await epCallOhneAktion({action:'sitzung_antwort_setzen', pass: currentAuthPass, teilnehmerTyp: aktiverSitzungenTeilnehmerTyp, teilnehmerId: aktiverSitzungenTeilnehmerId, einladungId, antwort});
      await zeigeSitzungenBereich(sitzungenVorherigerScreen);
    }catch(e){
      document.getElementById('sitzMeineError').textContent = 'Fehler: '+e.message;
    }
  };
  listeEl.querySelectorAll('.sitzZusageBtn').forEach(btn=>btn.addEventListener('click', ()=>antworten(btn.dataset.id, 'zusage')));
  listeEl.querySelectorAll('.sitzAbsageBtn').forEach(btn=>btn.addEventListener('click', ()=>antworten(btn.dataset.id, 'absage')));
}

document.getElementById('sitzMeineAbmeldenBtn').addEventListener('click', logoutApp);
document.getElementById('sitzMeineZurueckBtn').addEventListener('click', ()=>{
  if(sitzungenVorherigerScreen === 'mitglied'){
    // Bugfix (28.08.2026): "Zurück" führte für Mitglieder in eine
    // Endlosschleife zurück zur selben Sitzungsansicht, weil
    // zeigeMitgliedEinstieg() bei gesetzter mitgliedId sofort wieder
    // zeigeSitzungenBereich('mitglied') aufruft — der eigentliche
    // "Abmelden"-Button (mgIdAbmeldenBtn) auf dem Identifikations-
    // Bildschirm war dadurch nie mehr erreichbar. mitgliedId hier
    // explizit löschen, damit "Zurück" wieder zur Namensauswahl führt.
    mitgliedId = '';
    localStorage.removeItem('mitgliedId');
    mitgliedToken = '';
    localStorage.removeItem('mitgliedToken');
    zeigeMitgliedIdentifikation();
  }
  else zeigeTeamAktionsUebersicht();
});
document.getElementById('teamSitzungenBtn').addEventListener('click', ()=>zeigeSitzungenBereich('team'));

let teamFreigeschalteteFuerIcsExport = [];
// Teamende: Aktionen mit Oberaktion gebündelt und aufklappbar anzeigen.
// Liefert eine Funktion, die zu einer Aktion den passenden Container (Gruppe oder Liste) zurückgibt.
function teamOberGruppen(liste, el){
  const gruppen = {};
  (liste||[]).forEach(a=>{
    if(a.oberaktion_id && a.oberaktion_name){
      if(!gruppen[a.oberaktion_id]) gruppen[a.oberaktion_id] = {name:a.oberaktion_name, n:0};
      gruppen[a.oberaktion_id].n++;
    }
  });
  const ziele = {};
  Object.keys(gruppen).sort((x,y)=>gruppen[x].name.localeCompare(gruppen[y].name,'de')).forEach(id=>{
    const det = document.createElement('details');
    det.className = 'ober-gruppe';
    det.open = gruppen[id].n <= 6;
    const sum = document.createElement('summary');
    const t = document.createElement('span'); t.textContent = `🗂 ${gruppen[id].name}`;
    const nb = document.createElement('span'); nb.className = 'ober-anzahl'; nb.textContent = gruppen[id].n + (gruppen[id].n === 1 ? ' Aktion' : ' Aktionen');
    sum.appendChild(t); sum.appendChild(nb);
    det.appendChild(sum);
    el.appendChild(det);
    ziele[id] = det;
  });
  return a=> (a.oberaktion_id && ziele[a.oberaktion_id]) || el;
}
// Teamende-Startseite (Version 8z): Kachel-Menü wie beim Admin, darunter drei Unteransichten.
// ansicht: 'menue' (Standard) | 'aktionen' | 'offen' | 'unterlagen'
function teamAnsichtWechseln(ansicht){
  const map = {menue:'teamMenue', aktionen:'teamUnterAktionen', offen:'teamUnterOffen', unterlagen:'teamUnterUnterlagen'};
  if(!map[ansicht]) ansicht = 'menue';
  Object.keys(map).forEach(k=>{ const el = document.getElementById(map[k]); if(el) el.style.display = (k === ansicht) ? 'block' : 'none'; });
}
document.getElementById('teamKachelAktionen').addEventListener('click', ()=>teamAnsichtWechseln('aktionen'));
document.getElementById('teamKachelOffen').addEventListener('click', ()=>teamAnsichtWechseln('offen'));
document.getElementById('teamKachelUnterlagen').addEventListener('click', ()=>teamAnsichtWechseln('unterlagen'));
document.querySelectorAll('#teamAktionsScreen .team-zurueck').forEach(b=>b.addEventListener('click', ()=>teamAnsichtWechseln('menue')));
function teamBadgeSetzen(id, n, text){
  const el = document.getElementById(id);
  if(!el) return;
  if(n > 0){ el.textContent = text || String(n); el.style.display = 'inline-block'; } else { el.style.display = 'none'; }
}
async function zeigeTeamAktionsUebersicht(ansicht){
  teamAnsichtWechseln(ansicht || 'menue');
  if(pushZielOffen) setTimeout(pushZielAnwenden, 0);
  datenschutzPruefen();
  alleAuswahlScreensAusblenden();
  document.getElementById('teamAktionsScreen').style.display = 'grid';
  const errEl = document.getElementById('teamAktionsError');
  errEl.textContent = '';
  const freiEl = document.getElementById('teamFreigeschalteteListe');
  const offenEl = document.getElementById('teamOffeneListe');
  freiEl.textContent = 'Lädt…';
  offenEl.textContent = '';

  // Namen der aktuellen Person anzeigen (aus der Kartei nachschlagen)
  try{
    const person = await epCallOhneAktion({action:'team_ich', pass: currentAuthPass, personId: teamPersonId});
    document.getElementById('teamAktionsWer').textContent = person && person.vorname ? `Angemeldet als: ${person.vorname} ${person.nachname}` : '';
  }catch(e){ /* nicht kritisch, Anzeige einfach leer lassen */ }
  aktualisiereInfothekKnopf(); // nicht blockierend: Knopf "Sicherheit & Notfall" und Zähler
  aktualisiereMeldungNeuBadge(); // nicht blockierend: "Neue Antwort" am Melde-Knopf

  // Vertragsdokumente: bewusst HIER (nicht im separat freizuschaltenden
  // "Allgemein"-Bereich) — sonst würde eine/ein Teamende ohne Allgemein-
  // Zugriff ihre/seine eigenen bereitgestellten Verträge nie zu sehen
  // bekommen (Rückmeldung Markus, Session 12.09.2026).
  const vertragsdokBereich = document.getElementById('teamVertragsdokumenteBereich');
  if(vertragsdokBereich){
    vertragsdokBereich.style.display = 'block';
    renderMeineVertragsdokumente();
  }

  try{
    const [freiJson, offenJson, statusJson] = await Promise.all([
      epCallOhneAktion({action:'team_meine_freigeschalteten_aktionen', pass: currentAuthPass, personId: teamPersonId}),
      epCallOhneAktion({action:'team_aktionen_offen_list', pass: currentAuthPass}),
      epCallOhneAktion({action:'team_mein_status', pass: currentAuthPass, personId: teamPersonId}),
    ]);
    const freigeschaltet = freiJson.aktionen || [];
    const offene = offenJson.aktionen || [];
    const statusMap = {};
    (statusJson.zugriffe||[]).forEach(z=>{ statusMap[z.aktion_id] = z.status; });
    const TYP_LABEL = {ferienfreizeit:'Ferienfreizeit', tagesausflug:'Tagesausflug', wochenendfahrt:'Wochenendfahrt', gruppenstunde:'Gruppenstunde'};

    if(freigeschaltet.length === 0){
      freiEl.innerHTML = '<p style="color:#7a7266;">Noch keine Aktion für dich freigeschaltet.</p>';
    } else {
      freiEl.innerHTML = '';
      const freiZiel = teamOberGruppen(freigeschaltet, freiEl);
      freigeschaltet.forEach(a=>{
        const btn = document.createElement('button');
        btn.className = 'btn';
        btn.style.width = '100%';
        btn.style.marginBottom = '6px';
        btn.style.textAlign = 'left';
        btn.style.display = 'flex';
        btn.style.justifyContent = 'space-between';
        btn.style.alignItems = 'center';
        btn.style.gap = '8px';
        const label = document.createElement('span');
        label.textContent = `${a.name} (${TYP_LABEL[a.typ]||a.typ})${a.ort ? ' · 📍 ' + a.ort : ''}`;
        btn.appendChild(label);
        // Personalbedarf-Anzeige auch hier (nicht nur in der Interesse-
        // Liste) — rein informativ, damit freigeschaltete Teamende sehen,
        // ob für ihre eigene Aktion noch weitere Leute gesucht werden.
        if(a.benoetigte_personal !== null && a.benoetigte_personal !== undefined){
          const bedarfSpan = document.createElement('span');
          bedarfSpan.style.fontSize = '0.85em';
          bedarfSpan.style.whiteSpace = 'nowrap';
          const voll = a.freigeschaltete_anzahl >= a.benoetigte_personal;
          bedarfSpan.textContent = voll ? '🔴 Voll' : `${a.freigeschaltete_anzahl}/${a.benoetigte_personal}`;
          bedarfSpan.style.color = voll ? 'var(--awo-red)' : '#7a7266';
          bedarfSpan.style.fontWeight = voll ? '600' : 'normal';
          btn.appendChild(bedarfSpan);
        }
        btn.addEventListener('click', ()=>betreteAktion(a.id, a));
        freiZiel(a).appendChild(btn);
      });
    }

    // ICS-Export nur für die freigeschalteten Aktionen dieser Person,
    // nicht für alle Aktionen der Kartei (das ist der Admin-Kalender-Export).
    teamFreigeschalteteFuerIcsExport = freigeschaltet.filter(a=>a.start_datum);
    const icsBtn = document.getElementById('teamKalenderIcsExportBtn');
    icsBtn.style.display = teamFreigeschalteteFuerIcsExport.length > 0 ? 'flex' : 'none';

    // Bereits freigeschaltete Aktionen nicht nochmal in der "Interesse"-Liste zeigen.
    const freigeschalteteIds = new Set(freigeschaltet.map(a=>a.id));
    const offeneOhneFreigeschaltete = offene.filter(a=>!freigeschalteteIds.has(a.id));
    teamBadgeSetzen('teamAktionenBadge', freigeschaltet.length);
    teamBadgeSetzen('teamOffenBadge', offeneOhneFreigeschaltete.filter(a=>statusMap[a.id] !== 'interessiert').length);
    if(offeneOhneFreigeschaltete.length === 0){
      offenEl.innerHTML = '<p style="color:#7a7266;">Aktuell keine offenen Aktionen zur Interesse-Anmeldung.</p>';
    } else {
      offenEl.innerHTML = '';
      const offZiel = teamOberGruppen(offeneOhneFreigeschaltete, offenEl);
      offeneOhneFreigeschaltete.forEach(a=>{
        const box = document.createElement('div');
        box.style.marginBottom = '10px';
        box.style.paddingBottom = '10px';
        box.style.borderBottom = '1px solid #e5ddd0';
        const zeile = document.createElement('div');
        zeile.style.display = 'flex';
        zeile.style.alignItems = 'center';
        zeile.style.gap = '6px';
        const label = document.createElement('span');
        label.style.flex = '1';
        label.textContent = `${a.name} (${TYP_LABEL[a.typ]||a.typ})${a.ort ? ' · 📍 ' + a.ort : ''}`;
        zeile.appendChild(label);
        // Personalbedarf-Anzeige: rein informativ, blockiert die
        // Interesse-Anmeldung bewusst nicht (Admin entscheidet weiter frei,
        // z.B. für eine Warteliste oder falls doch mehr gebraucht wird).
        if(a.benoetigte_personal !== null && a.benoetigte_personal !== undefined){
          const bedarfSpan = document.createElement('span');
          bedarfSpan.style.fontSize = '0.85em';
          bedarfSpan.style.marginRight = '6px';
          bedarfSpan.style.whiteSpace = 'nowrap';
          const voll = a.freigeschaltete_anzahl >= a.benoetigte_personal;
          bedarfSpan.textContent = voll ? '🔴 Voll' : `${a.freigeschaltete_anzahl}/${a.benoetigte_personal}`;
          bedarfSpan.style.color = voll ? 'var(--awo-red)' : '#7a7266';
          bedarfSpan.style.fontWeight = voll ? '600' : 'normal';
          zeile.appendChild(bedarfSpan);
        }
        const status = statusMap[a.id];
        const btn = document.createElement('button');
        btn.className = 'btn ghost';
        if(status === 'interessiert'){
          btn.textContent = 'Interesse angemeldet ✓ (zurückziehen)';
          btn.addEventListener('click', async ()=>{
            try{
              await epCallOhneAktion({action:'team_interesse_zurueckziehen', pass: currentAuthPass, personId: teamPersonId, aktionId: a.id});
              zeigeTeamAktionsUebersicht('offen');
            }catch(e){ errEl.textContent = 'Fehler: '+e.message; }
          });
        } else {
          btn.textContent = 'Interesse anmelden';
          btn.addEventListener('click', async ()=>{
            try{
              await epCallOhneAktion({action:'team_interesse_anmelden', pass: currentAuthPass, personId: teamPersonId, aktionId: a.id});
              zeigeTeamAktionsUebersicht('offen');
            }catch(e){ errEl.textContent = 'Fehler: '+e.message; }
          });
        }
        zeile.appendChild(btn);
        box.appendChild(zeile);
        // Vom Admin hinterlegte Info anzeigen, falls vorhanden — bewusst
        // schon VOR der Interesse-Anmeldung sichtbar (z.B. Zeitraum, Ort,
        // was mitzubringen ist), damit Teamende informiert entscheiden können.
        if(a.info_fuer_interesse){
          const info = document.createElement('p');
          info.style.margin = '4px 0 0 0';
          info.style.fontSize = '0.9em';
          info.style.color = '#5a5346';
          info.style.whiteSpace = 'pre-wrap';
          info.textContent = a.info_fuer_interesse;
          box.appendChild(info);
        }
        offZiel(a).appendChild(box);
      });
    }
  }catch(e){
    freiEl.innerHTML = '';
    errEl.textContent = 'Fehler beim Laden: '+e.message;
  }
  // Allgemein-Button nur zeigen, wenn diese Person tatsächlich Zugriff hat
  // (Admin gewährt das direkt, siehe admin_allgemein_zugriff_setzen) —
  // sonst wäre der Button für die meisten Teamenden nur verwirrend, weil
  // er ohnehin mit "nicht freigeschaltet" abgelehnt würde.
  try{
    const zugriffJson = await epCallOhneAktion({action:'team_mein_allgemein_zugriff', pass: currentAuthPass, personId: teamPersonId});
    document.getElementById('teamAllgemeinBtn').style.display = zugriffJson.zugriff ? 'flex' : 'none';
  }catch(e){
    document.getElementById('teamAllgemeinBtn').style.display = 'none';
  }
}
document.getElementById('teamAndereIdentitaetBtn').addEventListener('click', ()=>{
  teamPersonId = '';
  localStorage.removeItem('teamPersonId');
  // SICHERHEITS-FIX (Audit 08/2026): personToken war an die alte Identität
  // gebunden — beim Identitätswechsel ebenfalls verwerfen, sonst würde der
  // Server (bis zum Ablauf) noch die vorherige Person akzeptieren.
  personToken = '';
  localStorage.removeItem('personToken');
  zeigeTeamIdentifikation();
});
document.getElementById('teamAktionsAbmeldenBtn').addEventListener('click', logoutApp);

// ================================================================
// ALLGEMEIN: aktionsübergreifender Bereich, KEINE Aktion. Admin trägt
// Infos ein (allgemein_infos), Team gibt Rückmeldungen (allgemein_
// rueckmeldungen) — beides unabhängig von einzelnen Aktionen. Zugriff
// wird direkt vom Admin pro Person gewährt/entzogen, kein "Interesse
// anmelden"-Schritt wie bei Aktionen.
// ================================================================
let allgVorherigerScreen = 'startMenu'; // 'startMenu' (Admin) oder 'teamAktionen' (Team) — steuert, wohin "Zurück" führt
async function zeigeAllgemeinBereich(vonWo){
  allgVorherigerScreen = vonWo;
  alleAuswahlScreensAusblenden();
  document.getElementById('allgemeinScreen').style.display = 'grid';
  document.getElementById('allgError').textContent = '';
  document.getElementById('allgInfoNeuBereich').style.display = isAdmin() ? 'block' : 'none';
  document.getElementById('allgZugriffBereich').style.display = isAdmin() ? 'block' : 'none';
  // E-Mail-Benachrichtigung: nur für Teamende mit PIN-bestätigter Identität
  // (teamPersonId) — Admin hat keine solche Kartei-Identität und pflegt
  // seine eigene E-Mail-Adresse stattdessen über die Nachweise-Detailkarte.
  const emailBereich = document.getElementById('allgEmailBereich');
  if(emailBereich){
    if(teamPersonId){
      emailBereich.style.display = 'block';
      pushKarteRendern('pushKarteTeam');
      document.getElementById('allgEmailStatus').textContent = '';
      try{
        const meineMail = await epCallOhneAktion({action:'team_meine_email_holen', pass: currentAuthPass, personId: teamPersonId});
        document.getElementById('allgEmailEingabe').value = meineMail.email || '';
        document.getElementById('allgEmailBenachrichtigenCb').checked = meineMail.emailBenachrichtigungen !== false;
        allgEmailBenachrichtigenVorher = !!meineMail.email && meineMail.emailBenachrichtigungen !== false;
      }catch(e){ /* Feld bleibt dann einfach leer, nicht kritisch */ }
    } else {
      emailBereich.style.display = 'none';
    }
  }
  await Promise.all([renderAllgInfos(), renderAllgRueck(), renderTerminanfragen(), dokListeRenderFuerRolle('allgDokumenteListe', 'team', null, teamPersonId), spLadeKatalog()]);
  if(isAdmin()) await ladeAllgZugriffListe();
}
document.getElementById('startAllgemeinBtn').addEventListener('click', ()=>zeigeAllgemeinBereich('startMenu'));
document.getElementById('teamAllgemeinBtn').addEventListener('click', ()=>zeigeAllgemeinBereich('teamAktionen'));
document.getElementById('allgSchliessenBtn').addEventListener('click', ()=>{
  alleAuswahlScreensAusblenden();
  if(allgVorherigerScreen === 'teamAktionen') zeigeTeamAktionsUebersicht();
  else zeigeStartMenu();
});
// Merkt sich, ob die Benachrichtigungen beim Laden eingeschaltet waren (für die Rückfrage beim Abschalten).
let allgEmailBenachrichtigenVorher = false;
document.getElementById('allgEmailSpeichernBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('allgEmailStatus');
  if(!teamPersonId){ statusEl.textContent = '⚠️ Keine Identität ausgewählt.'; return; }
  let email = document.getElementById('allgEmailEingabe').value.trim();
  const emailBenachrichtigungen = document.getElementById('allgEmailBenachrichtigenCb').checked;
  statusEl.textContent = '';
  // Benachrichtigungen werden abgeschaltet: Adresse für die PIN-Wiederherstellung behalten oder löschen?
  // "Behalten" ist der sichere Standard (auch beim Schließen des Dialogs).
  let adresseGeloescht = false;
  if(allgEmailBenachrichtigenVorher && !emailBenachrichtigungen && email){
    const loeschen = await bestaetigen('Die Benachrichtigungen werden ausgeschaltet. Soll die Adresse für die PIN-Wiederherstellung gespeichert bleiben?', {ok:'Adresse löschen', abbrechen:'Adresse behalten', gefahr:true});
    if(loeschen){ email = ''; adresseGeloescht = true; }
  }
  try{
    await epCallOhneAktion({action:'team_email_setzen', pass: currentAuthPass, personId: teamPersonId, email, emailBenachrichtigungen});
    allgEmailBenachrichtigenVorher = !!email && emailBenachrichtigungen;
    if(adresseGeloescht) document.getElementById('allgEmailEingabe').value = '';
    statusEl.textContent = adresseGeloescht ? '✓ Gespeichert — Adresse wurde gelöscht.' : '✓ Gespeichert.';
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
  }
});
// Widerrufen: löscht die hinterlegte E-Mail-Adresse vollständig und schaltet
// die Benachrichtigung aus — bewusst ein eigener, unmissverständlicher
// Button statt "nur Feld leeren + Speichern", damit die Widerrufs-Absicht
// nicht mit einem einfachen Tippfehler-Korrigieren verwechselt wird.
document.getElementById('allgEmailWiderrufenBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('allgEmailStatus');
  if(!teamPersonId){ statusEl.textContent = '⚠️ Keine Identität ausgewählt.'; return; }
  if(!(await bestaetigen('Adresse wirklich löschen? Dann gibt es keine E-Mail-Benachrichtigungen und keinen PIN-Reset per E-Mail mehr, bis du sie erneut einträgst.'))) return;
  statusEl.textContent = '';
  try{
    await epCallOhneAktion({action:'team_email_setzen', pass: currentAuthPass, personId: teamPersonId, email: '', emailBenachrichtigungen: false});
    document.getElementById('allgEmailEingabe').value = '';
    document.getElementById('allgEmailBenachrichtigenCb').checked = false;
    allgEmailBenachrichtigenVorher = false;
    statusEl.textContent = '✓ Adresse wurde gelöscht.';
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht widerrufen werden: '+e.message;
  }
});

async function renderAllgInfos(){
  const el = document.getElementById('allgInfoListe');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'allgemein_infos_list', pass: currentAuthPass, personId: teamPersonId});
    const infos = json.infos || [];
    if(infos.length === 0){
      el.innerHTML = '<p style="color:#7a7266;">Noch keine Infos eingetragen.</p>';
      return;
    }
    el.innerHTML = '';
    infos.forEach(i=>{
      const row = document.createElement('div');
      row.style.cssText = 'padding:10px 4px; border-bottom:1px solid #eee;';
      const delBtn = isAdmin() ? `<button class="del" title="Entfernen" style="margin-left:8px;">✕</button>` : '';
      row.innerHTML = `
        <div style="white-space:pre-wrap; margin-bottom:4px;">${escapeHtml(i.text)}</div>
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:0.78rem; color:var(--ink-soft);">
          <span>${fmtDateFull((i.erstellt_am||'').slice(0,10))}</span>
          ${delBtn}
        </div>
      `;
      if(isAdmin()){
        row.querySelector('.del').addEventListener('click', async ()=>{
          try{
            await epCallOhneAktion({action:'admin_allgemein_info_loeschen', pass: currentAuthPass, id: i.id});
            renderAllgInfos();
          }catch(e){ document.getElementById('allgError').textContent = 'Fehler: '+e.message; }
        });
      }
      el.appendChild(row);
    });
  }catch(e){
    el.innerHTML = '';
    document.getElementById('allgError').textContent = 'Fehler beim Laden der Infos: '+e.message;
  }
}
document.getElementById('allgInfoAnlegenBtn').addEventListener('click', async ()=>{
  const text = document.getElementById('allgInfoText').value.trim();
  if(!text) return;
  try{
    await epCallOhneAktion({action:'admin_allgemein_info_erstellen', pass: currentAuthPass, text});
    document.getElementById('allgInfoText').value = '';
    renderAllgInfos();
  }catch(e){
    document.getElementById('allgError').textContent = 'Fehler beim Anlegen: '+e.message;
  }
});

// renderAllgRueck: gleiches Muster wie renderWuensche (Wünsche & Anregungen
// innerhalb einer Aktion) — alle sehen alle Einträge, Admin markiert
// erledigt/löscht, Team reicht anonym oder namentlich ein.
let allgRueckErledigtOffen = false;
async function renderAllgRueck(){
  const el = document.getElementById('allgRueckListe');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'allgemein_rueckmeldungen_list', pass: currentAuthPass, personId: teamPersonId});
    const eintraege = json.rueckmeldungen || [];
    el.innerHTML = '';
    if(eintraege.length === 0){
      el.innerHTML = '<div class="dash-empty" style="border:none; padding:6px 4px;">Noch keine Rückmeldungen — sei der/die Erste!</div>';
      return;
    }
    const buildRow = r=>{
      const row = document.createElement('div');
      row.style.cssText = 'padding:10px 4px; border-bottom:1px solid #eee;';
      const autor = r.anonym ? 'Anonym' : escapeHtml(r.name || 'Teammitglied');
      const erledigtTag = r.erledigt
        ? `<span class="tag" style="margin-left:6px;">✓ erledigt${r.erledigt_am ? ' · '+fmtDateFull(r.erledigt_am.slice(0,10)) : ''}</span>`
        : '';
      const adminControls = isAdmin() ? `
        <label style="display:flex; align-items:center; gap:6px; font-size:0.82rem; white-space:nowrap;">
          <input type="checkbox" class="allg-rueck-erledigt-cb" ${r.erledigt?'checked':''}> erledigt
        </label>
        <button class="del" title="Entfernen">✕</button>
      ` : '';
      row.innerHTML = `
        <div style="white-space:pre-wrap; margin-bottom:6px;">${escapeHtml(r.text)}${erledigtTag}</div>
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; font-size:0.78rem; color:var(--ink-soft);">
          <span>${autor} · ${fmtDateFull(r.datum||'')}</span>
          <div style="display:flex; align-items:center; gap:10px;">${adminControls}</div>
        </div>
      `;
      if(isAdmin()){
        row.querySelector('.allg-rueck-erledigt-cb').addEventListener('change', async (e)=>{
          try{
            await epCallOhneAktion({action:'admin_allgemein_rueckmeldung_status', pass: currentAuthPass, id: r.id, erledigt: e.target.checked});
            renderAllgRueck();
          }catch(err){ document.getElementById('allgError').textContent = 'Fehler: '+err.message; }
        });
        row.querySelector('.del').addEventListener('click', async ()=>{
          try{
            await epCallOhneAktion({action:'admin_allgemein_rueckmeldung_loeschen', pass: currentAuthPass, id: r.id});
            renderAllgRueck();
          }catch(err){ document.getElementById('allgError').textContent = 'Fehler: '+err.message; }
        });
      }
      return row;
    };
    const offen = eintraege.filter(r=>!r.erledigt);
    const erledigt = eintraege.filter(r=>r.erledigt);
    if(offen.length===0 && erledigt.length>0){
      const hint = document.createElement('div');
      hint.className = 'dash-empty';
      hint.style.cssText = 'border:none; padding:6px 4px;';
      hint.textContent = 'Alles erledigt. ✓';
      el.appendChild(hint);
    } else {
      offen.forEach(r=> el.appendChild(buildRow(r)));
    }
    if(erledigt.length>0){
      const details = document.createElement('details');
      details.className = 'erledigt-fach';
      details.open = allgRueckErledigtOffen;
      details.addEventListener('toggle', ()=>{ allgRueckErledigtOffen = details.open; });
      const summary = document.createElement('summary');
      summary.textContent = `Erledigt (${erledigt.length})`;
      details.appendChild(summary);
      erledigt.forEach(r=> details.appendChild(buildRow(r)));
      el.appendChild(details);
    }
  }catch(e){
    el.innerHTML = '';
    document.getElementById('allgError').textContent = 'Fehler beim Laden der Rückmeldungen: '+e.message;
  }
}
document.getElementById('allgRueckAnlegenBtn').addEventListener('click', async ()=>{
  const text = document.getElementById('allgRueckText').value.trim();
  if(!text) return;
  const anonym = document.getElementById('allgRueckAnonym').checked;
  try{
    await epCallOhneAktion({action:'allgemein_rueckmeldung_erstellen', pass: currentAuthPass, personId: teamPersonId, text, anonym, name: anonym ? null : myName});
    document.getElementById('allgRueckText').value = '';
    document.getElementById('allgRueckAnonym').checked = false;
    renderAllgRueck();
  }catch(e){
    document.getElementById('allgError').textContent = 'Fehler beim Einreichen: '+e.message;
  }
});

// ---- Terminanfragen: Teamende schlagen eine neue Aktion mit Termin vor,
// Admin entscheidet (nimmt an — optional inkl. direktem Anlegen der Aktion
// — oder lehnt ab). Liste ist für alle mit Allgemein-Zugriff transparent
// sichtbar, analog zu den Rückmeldungen. ----
async function renderTerminanfragen(){
  const el = document.getElementById('taListe');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'terminanfragen_list', pass: currentAuthPass, personId: teamPersonId});
    const eintraege = json.terminanfragen || [];
    el.innerHTML = '';
    if(eintraege.length === 0){
      el.innerHTML = '<div class="dash-empty" style="border:none; padding:6px 4px;">Noch keine Terminanfragen.</div>';
      return;
    }
    const STATUS_LABEL = {offen:'⏳ Offen', angenommen:'✓ Angenommen', abgelehnt:'✕ Abgelehnt'};
    eintraege.forEach(t=>{
      const row = document.createElement('div');
      row.style.cssText = 'padding:10px 4px; border-bottom:1px solid #eee;';
      const details = [
        t.ort ? `📍 ${escapeHtml(t.ort)}` : '',
        t.verantwortlicher ? `👤 ${escapeHtml(t.verantwortlicher)}` : '',
        t.arbeitszeit ? `🕐 ${escapeHtml(t.arbeitszeit)}` : '',
        t.verdienst ? `💶 ${escapeHtml(t.verdienst)}` : '',
      ].filter(Boolean).join(' · ');
      const statusFarbe = t.status==='angenommen' ? '#3E8E4A' : (t.status==='abgelehnt' ? 'var(--awo-red)' : '#7a7266');
      const adminBtns = (isAdmin() && t.status==='offen') ? `
        <div style="display:flex; gap:6px; margin-top:8px; flex-wrap:wrap;">
          <button class="btn ghost ta-annehmen-btn" style="padding:4px 10px;">Annehmen</button>
          <button class="btn ghost ta-ablehnen-btn" style="padding:4px 10px;">Ablehnen</button>
        </div>` : '';
      const delBtn = isAdmin() ? `<button class="del" title="Entfernen" style="margin-left:8px;">✕</button>` : '';
      const aktionLink = t.erstellte_aktion_id ? ' · Aktion wurde angelegt' : '';
      row.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:start; gap:8px;">
          <div>
            <strong>${escapeHtml(t.aktion_name)}</strong> — ${fmtDateFull(t.datum)}
            <div style="font-size:0.85rem; color:var(--ink-soft); margin-top:2px;">${details}</div>
            ${t.anmerkung ? `<div style="font-size:0.85rem; margin-top:4px; white-space:pre-wrap;">${escapeHtml(t.anmerkung)}</div>` : ''}
          </div>
          ${delBtn}
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:0.78rem; color:var(--ink-soft); margin-top:6px;">
          <span>eingereicht von ${escapeHtml(t.eingereicht_von||'Teammitglied')}, ${fmtDateFull((t.eingereicht_am||'').slice(0,10))}</span>
          <span style="color:${statusFarbe}; font-weight:600;">${STATUS_LABEL[t.status]||t.status}${aktionLink}</span>
        </div>
        ${t.admin_kommentar ? `<div style="font-size:0.85rem; margin-top:6px; color:var(--ink-soft);">Kommentar: ${escapeHtml(t.admin_kommentar)}</div>` : ''}
        ${adminBtns}
      `;
      if(isAdmin()){
        const delBtnEl = row.querySelector('.del');
        if(delBtnEl) delBtnEl.addEventListener('click', async ()=>{
          try{
            await epCallOhneAktion({action:'admin_terminanfrage_loeschen', pass: currentAuthPass, id: t.id});
            renderTerminanfragen();
          }catch(e){ document.getElementById('allgError').textContent = 'Fehler: '+e.message; }
        });
        const annehmenBtn = row.querySelector('.ta-annehmen-btn');
        if(annehmenBtn) annehmenBtn.addEventListener('click', ()=>zeigeTerminanfrageAnnehmenDialog(t));
        const ablehnenBtn = row.querySelector('.ta-ablehnen-btn');
        if(ablehnenBtn) ablehnenBtn.addEventListener('click', async ()=>{
          const kommentar = (await eingabe('Kommentar zur Ablehnung (optional):', '')) || '';
          try{
            await epCallOhneAktion({action:'admin_terminanfrage_entscheiden', pass: currentAuthPass, id: t.id, status:'abgelehnt', adminKommentar: kommentar});
            renderTerminanfragen();
          }catch(e){ document.getElementById('allgError').textContent = 'Fehler: '+e.message; }
        });
      }
      el.appendChild(row);
    });
  }catch(e){
    el.innerHTML = '';
    document.getElementById('allgError').textContent = 'Fehler beim Laden der Terminanfragen: '+e.message;
  }
}

// zeigeTerminanfrageAnnehmenDialog: einfache Abfrage (prompt-basiert, wie
// an anderer Stelle der App üblich für seltene Admin-Einzelentscheidungen)
// — fragt, ob direkt eine Aktion angelegt werden soll, und wenn ja, mit
// welchem Aktions-Typ (das Anfrage-Formular selbst fragt bewusst keinen
// Typ ab, um es für Teamende einfach zu halten).
async function zeigeTerminanfrageAnnehmenDialog(t){
  const aktionAnlegen = (await bestaetigen(`"${t.aktion_name}" annehmen und direkt als neue Aktion anlegen (Name + Datum werden übernommen)?\n\nAlternativ nur als "angenommen" markieren, ohne Aktion anzulegen.`, {ok:'Annehmen & Aktion anlegen', abbrechen:'Nur als „angenommen“ markieren', gefahr:false}));
  let typ = '';
  if(aktionAnlegen){
    typ = ((await eingabe('Aktions-Typ für die neue Aktion (z.B. Tagesausflug, Gruppenstunde):', '')) || '').trim();
    if(!typ){ alert('Ohne Aktions-Typ kann keine Aktion angelegt werden — Vorgang abgebrochen.'); return; }
  }
  const kommentar = (await eingabe('Kommentar (optional):', '')) || '';
  try{
    await epCallOhneAktion({action:'admin_terminanfrage_entscheiden', pass: currentAuthPass, id: t.id, status:'angenommen', aktionAnlegen, typ, adminKommentar: kommentar});
    renderTerminanfragen();
  }catch(e){
    document.getElementById('allgError').textContent = 'Fehler: '+e.message;
  }
}

document.getElementById('taAnlegenBtn').addEventListener('click', async ()=>{
  const aktionName = document.getElementById('ta_aktion_name').value.trim();
  const datum = document.getElementById('ta_datum').value;
  const ort = document.getElementById('ta_ort').value.trim();
  const verantwortlicher = document.getElementById('ta_verantwortlicher').value.trim();
  const arbeitszeit = document.getElementById('ta_arbeitszeit').value.trim();
  const verdienst = document.getElementById('ta_verdienst').value.trim();
  const anmerkung = document.getElementById('ta_anmerkung').value.trim();
  if(!aktionName){ document.getElementById('allgError').textContent = 'Bitte einen Namen/Vorschlag für die Aktion angeben.'; return; }
  if(!datum){ document.getElementById('allgError').textContent = 'Bitte ein Datum angeben.'; return; }
  try{
    await epCallOhneAktion({action:'team_terminanfrage_erstellen', pass: currentAuthPass, personId: teamPersonId, aktionName, datum, ort, verantwortlicher, arbeitszeit, verdienst, anmerkung});
    document.getElementById('ta_aktion_name').value = '';
    document.getElementById('ta_datum').value = '';
    document.getElementById('ta_ort').value = '';
    document.getElementById('ta_verantwortlicher').value = '';
    document.getElementById('ta_arbeitszeit').value = '';
    document.getElementById('ta_verdienst').value = '';
    document.getElementById('ta_anmerkung').value = '';
    document.getElementById('allgError').textContent = '';
    renderTerminanfragen();
  }catch(e){
    document.getElementById('allgError').textContent = 'Fehler beim Einreichen: '+e.message;
  }
});

// ================================================================
// VERWALTUNG: zentraler Admin-Bereich für aktionsübergreifende interne
// Arbeit. Aktuell: Kalender (automatisch aus Start-/Enddatum aller
// Aktionen) + Schnellzugriff auf die Nachweise der jeweiligen Aktion.
// Nachweise selbst bleiben bewusst je Aktion gepflegt (Rollen-je-Woche
// und Fristen-Intervalle hängen aktuell am Datenstand der einzelnen
// Aktion) — ein vollständig aktionsübergreifendes Nachweise-Modul wäre
// ein größerer Umbau und ist hier nicht enthalten.
// ================================================================
// ================================================================
// VERWALTUNG: zentraler Admin-Bereich für aktionsübergreifende interne
// Arbeit. Enthält: Kalender (automatisch aus Start-/Enddatum aller
// Aktionen) + vollständige, Kartei-weite Nachweise-Verwaltung (siehe
// renderVwNachweise weiter unten — löst die frühere Beschränkung ab,
// dass Nachweise nur über die jeweils einzelne Aktion erreichbar waren).
// ================================================================

// vwAktionenCache: alle Aktionen — wird beim Öffnen des Kalenders ODER der
// Nachweise-Verwaltung geladen (je nachdem, was zuerst angeklickt wird),
// und von beiden gemeinsam genutzt (Kalender-Liste + Rollenhistorie-
// Auflösung "aktionId -> Aktionsname" in den Nachweisen).
let vwAktionenCache = [];
let vwAktionenCacheGeladen = false;
// Für den kombinierten Kalender (Aktionen + Sitzungen, siehe weiter unten):
// vwSitzungenFuerKalenderCache hält die normalisierten Sitzungsdaten,
// vwKalenderAuswahl die Keys der gerade angehakten Termine (Set von
// "aktion:<id>"/"sitzung:<id>"), vwKalenderAlleTermineCache die zuletzt
// gerenderte Gesamtliste (für Export und "Alle/Keine auswählen").
let vwSitzungenFuerKalenderCache = [];
let vwKalenderAuswahl = new Set();
let vwKalenderAlleTermineCache = [];

async function ladeVwAktionenCacheFallsNoetig(){
  if(vwAktionenCacheGeladen) return;
  const json = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass});
  vwAktionenCache = json.aktionen || [];
  vwAktionenCacheGeladen = true;
}

// vwSitzungenFuerKalenderCache: eigener Abruf für die Kalender-Ansicht,
// bewusst OHNE "geladen"-Flag wie bei vwAktionenCache — Sitzungs-Zu-/Absagen
// und neue Sitzungen können sich zwischen zwei Kalender-Aufrufen ändern,
// und der Abruf ist günstig genug, um ihn bei jedem Öffnen frisch zu holen.
// Nutzt dieselbe sitzSitzungenCache-Variable wie die Sitzungen-Verwaltung,
// damit beide Stellen konsistent denselben Stand zeigen.
async function ladeVwSitzungenFuerKalenderFallsNoetig(){
  const json = await epCallOhneAktion({action:'admin_sitzungen_liste', pass: currentAuthPass});
  sitzSitzungenCache = json.sitzungen || [];
  vwSitzungenFuerKalenderCache = sitzSitzungenCache;
}

// Normalisierung: Aktionen (Ganztags-Zeitraum) und Sitzungen (Uhrzeit-genau)
// auf ein gemeinsames "Termin"-Format bringen, damit Kalender-Liste und
// ICS-Export beide Quellen gleich behandeln können. "key" identifiziert den
// Termin eindeutig für die Checkbox-Auswahl (vwKalenderAuswahl-Set).
function aktionZuTermin(a){
  const beschreibungTeile = [a.typ, a.status === 'abgeschlossen' ? 'abgeschlossen' : null].filter(Boolean);
  return {
    key: 'aktion:' + a.id,
    uidPrefix: 'aktion',
    id: a.id,
    titel: a.name,
    beschreibung: beschreibungTeile.length > 0 ? beschreibungTeile.join(' · ') : null,
    ort: null,
    allDay: true,
    startIso: a.start_datum,
    endIso: a.end_datum || a.start_datum,
  };
}
function sitzungZuTermin(s){
  return {
    key: 'sitzung:' + s.id,
    uidPrefix: 'sitzung',
    id: s.id,
    titel: s.titel,
    beschreibung: s.beschreibung || null,
    ort: s.ort || null,
    allDay: false,
    startIso: s.beginn,
    endIso: s.ende || null,
  };
}

