// ---- Verwaltung: Versionsverlauf (nur Konten-Verwalter, seit 2.2.0) ----
const VV_ART = { neu: ['Neu', '#2f6b3a'], geaendert: ['Geändert', '#2F6FB5'], behoben: ['Behoben', '#b35c00'], text: ['Text', '#7a7266'] };
function vwVersionenRendern(){
  const v = window.APP_VERSIONEN || {};
  const box = document.getElementById('vwVersionenInhalt');
  document.getElementById('vwVersionenIntro').textContent = 'Du hast Version ' + v.anzeige + '. Hier steht, was sich in jeder Version geändert hat (neueste oben).';
  box.textContent = '';
  (window.APP_VERSIONSVERLAUF || []).forEach(function(eintrag, i){
    const d = document.createElement('details'); d.className = 'erledigt-fach'; d.setAttribute('data-version', eintrag.version);
    if(i === 0) d.open = true;
    const s = document.createElement('summary');
    s.textContent = (/^\d/.test(eintrag.version) ? 'Version ' : '') + eintrag.version + (eintrag.datum ? ' · ' + fmtDateFull(eintrag.datum) : '') + (eintrag.kennung ? ' · Kennung ' + eintrag.kennung : '');
    d.appendChild(s);
    (eintrag.punkte || []).forEach(function(p){
      const z = document.createElement('div'); z.style.cssText = 'display:flex; gap:8px; align-items:flex-start; padding:5px 0; border-bottom:1px solid #eee;';
      const art = VV_ART[p[0]] || VV_ART.text;
      const tag = document.createElement('span'); tag.textContent = art[0]; tag.style.cssText = 'flex:none; font-size:0.7rem; font-weight:600; color:#fff; background:' + art[1] + '; border-radius:4px; padding:2px 6px; margin-top:2px;';
      const t = document.createElement('span'); t.textContent = p[1]; t.style.fontSize = '0.9rem';
      z.appendChild(tag); z.appendChild(t); d.appendChild(z);
    });
    box.appendChild(d);
  });
}
document.getElementById('vwKachelVersionen').addEventListener('click', function(){
  document.getElementById('vwMenu').style.display = 'none';
  document.getElementById('vwVersionenView').style.display = 'block';
  vwVersionenRendern();
});
document.getElementById('vwVersionenZurueckBtn').addEventListener('click', zeigeVwMenu);
// ---- Verwaltung: Personen (Kartei) ----
let vwPersListeCache = [];
let vwZgCache = [], vwPosCache = [];
const vwZgOffen = new Set();
const VW_ZG_KAT = {admin:'Admin', team:'Teamende', vorstand:'Vorstand', mitglied:'Mitglied'};
const VW_ZG_REIHE = ['admin','vorstand','team','mitglied'];
const VW_ZG_FARBE = {admin:'#b3261e', vorstand:'#6b3fa0', team:'#1f6f43', mitglied:'#1a5fa8'};
function vwHeute(){ return new Date().toLocaleDateString('sv-SE', {timeZone:'Europe/Berlin'}); }
function vwDatumDe(d){ if(!d) return ''; const t = String(d).split('-'); return t.length===3 ? (t[2]+'.'+t[1]+'.'+t[0]) : d; }
function vwZgAktuell(z){ const h = vwHeute(); return z.von <= h && (!z.bis || z.bis >= h); }
function vwZgPosName(z){ const p = vwPosCache.find(x=>x.id===z.position_id); return p ? p.name : ''; }
function vwZgLabel(z){ return VW_ZG_KAT[z.kategorie] + (z.kategorie==='vorstand' && z.position_id ? ' · ' + vwZgPosName(z) : ''); }
function vwZgZeitraum(z){
  const h = vwHeute();
  if(z.von > h) return 'ab ' + vwDatumDe(z.von);
  return z.bis ? (vwDatumDe(z.von) + ' – ' + vwDatumDe(z.bis)) : ('seit ' + vwDatumDe(z.von));
}
function vwZgBadge(z){
  const akt = vwZgAktuell(z);
  const farbe = akt ? VW_ZG_FARBE[z.kategorie] : '#8a8478';
  return '<span style="display:inline-block; margin:2px 4px 2px 0; padding:2px 8px; border-radius:10px; font-size:0.8rem; color:#fff; background:' + farbe + (akt?'':'; opacity:0.75') + ';">' +
    escapeHtml(vwZgLabel(z)) + ' · ' + escapeHtml(vwZgZeitraum(z)) + (akt?'':' (ehemalig)') + '</span>';
}
function vwZgFormHtml(personId, z){
  z = z || {};
  const kat = z.kategorie || 'team';
  const aktivePos = vwPosCache.filter(p=>p.aktiv || p.id===z.position_id);
  return '<div class="vwZgForm" data-person="' + escapeHtml(personId) + '" data-id="' + escapeHtml(z.id||'') + '" style="margin-top:8px; padding:8px; background:#faf6ee; border-radius:8px;">' +
    '<div class="add-row" style="grid-template-columns:1fr 1fr; gap:6px;">' +
    '<select class="vwZgKat">' + VW_ZG_REIHE.map(k=>'<option value="'+k+'"'+(k===kat?' selected':'')+'>'+VW_ZG_KAT[k]+'</option>').join('') + '</select>' +
    '<select class="vwZgPos" style="display:' + (kat==='vorstand'?'block':'none') + ';"><option value="">Position wählen…</option>' +
      aktivePos.map(p=>'<option value="'+escapeHtml(p.id)+'"'+(p.id===z.position_id?' selected':'')+'>'+escapeHtml(p.name)+'</option>').join('') + '</select></div>' +
    '<div class="add-row" style="grid-template-columns:1fr 1fr; gap:6px; margin-top:6px;">' +
    '<label style="font-size:0.85rem;">Seit<input type="date" class="vwZgVon" value="' + escapeHtml(z.von || vwHeute()) + '"></label>' +
    '<label style="font-size:0.85rem;">Bis (leer = läuft noch)<input type="date" class="vwZgBis" value="' + escapeHtml(z.bis || '') + '"></label></div>' +
    '<input type="text" class="vwZgNotiz" maxlength="300" placeholder="Notiz (optional)" value="' + escapeHtml(z.notiz||'') + '" style="width:100%; box-sizing:border-box; margin-top:6px;" autocomplete="off">' +
    '<div style="display:flex; gap:6px; margin-top:6px;"><button class="btn vwZgSave" type="button">Speichern</button>' +
    '<button class="btn ghost vwZgFormAbbrechen" type="button">Abbrechen</button></div></div>';
}
function vwZgPanelHtml(personId){
  const liste = vwZgCache.filter(z=>z.person_id===personId).sort((a,b)=>(b.von||'').localeCompare(a.von||''));
  return (liste.length ? liste.map(z=>
    '<div style="padding:6px 0; border-top:1px solid #efe8da;">' + vwZgBadge(z) +
    (z.notiz ? '<div style="font-size:0.8rem; color:#7a7266;">' + escapeHtml(z.notiz) + '</div>' : '') +
    '<div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:4px;">' +
    '<button class="btn ghost vwZgEdit" type="button" data-id="' + escapeHtml(z.id) + '">✏️ Ändern</button>' +
    (vwZgAktuell(z) && !z.bis ? '<button class="btn ghost vwZgEnde" type="button" data-id="' + escapeHtml(z.id) + '">Heute beenden</button>' : '') +
    '<button class="btn ghost vwZgDel" type="button" data-id="' + escapeHtml(z.id) + '">🗑</button></div>' +
    '<div class="vwZgEditSlot" data-id="' + escapeHtml(z.id) + '"></div></div>'
  ).join('') : '<div class="dp-hint">Noch keine Zugehörigkeit eingetragen.</div>') +
  '<div class="vwZgNeuSlot" style="margin-top:6px;"><button class="btn ghost vwZgNeu" type="button" data-person="' + escapeHtml(personId) + '">＋ Zugehörigkeit hinzufügen</button></div>';
}
function vwZgFilterWerte(){
  const g = id => (document.getElementById(id) || {}).value || '';
  return {
    suche: g('vwPersSuche').trim().toLowerCase(), kat: g('vwPersKat') || 'alle', pos: g('vwPersPos'),
    status: g('vwPersZgStatus') || 'aktuell', gruppe: g('vwPersGruppe') || 'name',
    mehrfach: !!(document.getElementById('vwPersMehrfach') || {}).checked
  };
}
function vwZgPassend(z, f){
  if(f.status==='aktuell' && !vwZgAktuell(z)) return false;
  if(f.status==='ehemalig' && vwZgAktuell(z)) return false;
  if(f.kat!=='alle' && f.kat!=='keine' && z.kategorie!==f.kat) return false;
  if(f.pos && z.position_id!==f.pos) return false;
  return true;
}
function vwPersZeileHtml(p, zgs){
  const name = (p.vorname||'') + ' ' + (p.nachname||'');
  const alle = vwZgCache.filter(z=>z.person_id===p.id);
  const aktAnz = new Set(alle.filter(vwZgAktuell).map(z=>z.kategorie + '|' + (z.position_id||''))).size;
  const offen = vwZgOffen.has(p.id);
  return '<div style="display:flex; align-items:center; gap:8px; padding:8px 0; border-top:1px solid #e5ddd0; flex-wrap:wrap;">' +
    '<div style="flex:1; min-width:180px;"><strong>' + escapeHtml(name) + '</strong>' +
    (aktAnz>1 ? ' <span style="font-size:0.8rem; color:#6b3fa0;">· ' + aktAnz + ' Zugehörigkeiten gleichzeitig</span>' : '') + '<br>' +
    (zgs.length ? zgs.map(vwZgBadge).join('') : '<span style="font-size:0.85rem; color:#7a7266;">keine passende Zugehörigkeit</span>') + '<br>' +
    '<span style="font-size:0.8rem; color:#7a7266;">' + (p.pin_gesetzt ? 'PIN gesetzt' : 'noch keine PIN (hat sich noch nie angemeldet)') + '</span></div>' +
    '<div style="display:flex; gap:6px; flex-wrap:wrap;">' +
    '<button class="btn ghost vwZgToggle" type="button" data-id="' + escapeHtml(p.id) + '">🏷 Zugehörigkeiten</button>' +
    '<button class="btn ghost vwPersEdit" type="button" data-id="' + escapeHtml(p.id) + '">✏️ Bearbeiten</button>' +
    (p.pin_gesetzt ? '<button class="btn ghost vwPersPinReset" type="button" data-id="' + escapeHtml(p.id) + '" data-name="' + escapeHtml(name) + '">PIN zurücksetzen</button>' : '') +
    '<button class="btn ghost vwPersDel" type="button" data-id="' + escapeHtml(p.id) + '">🗑 Löschen</button>' +
    '</div>' +
    '<div class="vwZgPanel" id="vwZgPanel_' + escapeHtml(p.id) + '" style="display:' + (offen?'block':'none') + '; width:100%;">' + (offen ? vwZgPanelHtml(p.id) : '') + '</div>' +
    '<div class="vwPersPanel" id="vwPersPanel_' + escapeHtml(p.id) + '" style="display:none; width:100%;"></div>' +
    '</div>';
}
function vwPersZeichne(){
  const el = document.getElementById('vwPersonenInhalt');
  const f = vwZgFilterWerte();
  const sortName = (a,b)=>(a.nachname||'').localeCompare(b.nachname||'','de') || (a.vorname||'').localeCompare(b.vorname||'','de');
  // Positionsfilter nur sinnvoll bei Vorstand
  const posEl = document.getElementById('vwPersPos'); if(posEl) posEl.style.display = (f.kat==='alle' || f.kat==='vorstand') ? '' : 'none';
  const treffer = [];
  for(const p of vwPersListeCache.slice().sort(sortName)){
    const alle = vwZgCache.filter(z=>z.person_id===p.id);
    const name = ((p.vorname||'') + ' ' + (p.nachname||'')).toLowerCase();
    let zgs;
    if(f.kat==='keine'){
      if(alle.some(vwZgAktuell)) continue;
      zgs = alle;
    } else {
      zgs = alle.filter(z=>vwZgPassend(z, f));
      if(zgs.length===0 && (f.kat!=='alle' || f.pos || f.status==='ehemalig' || f.mehrfach)) continue;
    }
    if(f.mehrfach && new Set(zgs.map(z=>z.kategorie+'|'+(z.position_id||''))).size < 2) continue;
    if(f.suche){
      const hay = name + ' ' + alle.map(z=>vwZgLabel(z) + ' ' + (z.notiz||'')).join(' ').toLowerCase();
      if(!hay.toLowerCase().includes(f.suche)) continue;
    }
    zgs = zgs.slice().sort((a,b)=>VW_ZG_REIHE.indexOf(a.kategorie)-VW_ZG_REIHE.indexOf(b.kategorie));
    treffer.push({p, zgs});
  }
  const info = '<div class="dp-hint" style="margin-top:0;">' + treffer.length + ' von ' + vwPersListeCache.length + ' Personen:</div>';
  if(treffer.length===0){ el.innerHTML = '<div class="card">' + info + 'Keine Treffer für diese Auswahl.</div>'; return; }
  let html = '';
  if(f.gruppe==='kategorie'){
    // Mehrfachnennung: Person erscheint in jeder passenden Kategorie
    for(const k of VW_ZG_REIHE){
      const hier = treffer.filter(t=>t.zgs.some(z=>z.kategorie===k));
      if(!hier.length) continue;
      html += '<h3 style="margin:14px 0 4px; color:' + VW_ZG_FARBE[k] + ';">' + VW_ZG_KAT[k] + ' (' + hier.length + ')</h3>' +
        hier.map(t=>vwPersZeileHtml(t.p, t.zgs.filter(z=>z.kategorie===k))).join('');
    }
    const ohne = treffer.filter(t=>t.zgs.length===0);
    if(ohne.length) html += '<h3 style="margin:14px 0 4px;">Ohne Zugehörigkeit (' + ohne.length + ')</h3>' + ohne.map(t=>vwPersZeileHtml(t.p, [])).join('');
  } else {
    html = treffer.map(t=>vwPersZeileHtml(t.p, t.zgs)).join('');
  }
  el.innerHTML = '<div class="card" style="text-align:left;">' + info + html + '</div>';
}
function vwPosFilterFuellen(){
  const sel = document.getElementById('vwPersPos'); if(!sel) return;
  const alt = sel.value;
  sel.innerHTML = '<option value="">Alle Positionen</option>' + vwPosCache.map(p=>'<option value="'+escapeHtml(p.id)+'">'+escapeHtml(p.name)+(p.aktiv?'':' (inaktiv)')+'</option>').join('');
  sel.value = alt;
}
async function renderVwPersonen(){
  const el = document.getElementById('vwPersonenInhalt');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_personen_list', pass: currentAuthPass});
    vwPersListeCache = json.personen || [];
    if(vwPersListeCache.length === 0){ el.innerHTML = '<div class="card">Noch keine Personen in der Kartei.</div>'; return; }
    try{
      const zj = await epCallOhneAktion({action:'admin_zugehoerigkeiten_liste', pass: currentAuthPass});
      vwZgCache = zj.zugehoerigkeiten || []; vwPosCache = zj.positionen || [];
    }catch(e){
      vwZgCache = []; vwPosCache = [];
      document.getElementById('vwPersStatus').textContent = 'Zugehörigkeiten konnten nicht geladen werden (Update eingespielt?): ' + e.message;
    }
    vwPosFilterFuellen();
    vwPersZeichne();
  }catch(e){
    el.innerHTML = '<div class="card" style="color:#b3261e;">Fehler beim Laden: ' + escapeHtml(e.message) + '</div>';
  }
}
['vwPersSuche','vwPersKat','vwPersPos','vwPersZgStatus','vwPersGruppe','vwPersMehrfach'].forEach(id=>{
  const e = document.getElementById(id); if(!e) return;
  e.addEventListener(e.tagName==='INPUT' && e.type==='text' ? 'input' : 'change', vwPersZeichne);
});
document.getElementById('vwPersFilterReset').addEventListener('click', ()=>{
  document.getElementById('vwPersSuche').value=''; document.getElementById('vwPersKat').value='alle';
  document.getElementById('vwPersPos').value=''; document.getElementById('vwPersZgStatus').value='aktuell';
  document.getElementById('vwPersGruppe').value='name'; document.getElementById('vwPersMehrfach').checked=false;
  vwPersZeichne();
});
// ---- Zugehörigkeiten: Bedienung ----
document.getElementById('vwPersonenInhalt').addEventListener('click', async (ev)=>{
  const t = ev.target;
  const st = document.getElementById('vwPersStatus');
  const tog = t.closest('.vwZgToggle');
  if(tog){
    const id = tog.dataset.id, pn = document.getElementById('vwZgPanel_'+id);
    if(vwZgOffen.has(id)){ vwZgOffen.delete(id); pn.style.display='none'; pn.innerHTML=''; }
    else { vwZgOffen.add(id); pn.style.display='block'; pn.innerHTML = vwZgPanelHtml(id); }
    return;
  }
  const neu = t.closest('.vwZgNeu');
  if(neu){ neu.parentElement.innerHTML = vwZgFormHtml(neu.dataset.person); return; }
  const edit = t.closest('.vwZgEdit');
  if(edit){
    const z = vwZgCache.find(x=>x.id===edit.dataset.id); if(!z) return;
    edit.closest('div[style*="border-top"]').querySelector('.vwZgEditSlot').innerHTML = vwZgFormHtml(z.person_id, z);
    return;
  }
  if(t.closest('.vwZgFormAbbrechen')){
    const pn = t.closest('.vwZgPanel'); pn.innerHTML = vwZgPanelHtml(pn.id.replace('vwZgPanel_','')); return;
  }
  const katSel = t.closest('.vwZgKat');
  const save = t.closest('.vwZgSave');
  if(save){
    const fm = save.closest('.vwZgForm');
    const kategorie = fm.querySelector('.vwZgKat').value;
    const payload = {action:'admin_zugehoerigkeit_speichern', pass: currentAuthPass, id: fm.dataset.id || undefined,
      personId: fm.dataset.person, kategorie, positionId: kategorie==='vorstand' ? fm.querySelector('.vwZgPos').value : undefined,
      von: fm.querySelector('.vwZgVon').value, bis: fm.querySelector('.vwZgBis').value || null, notiz: fm.querySelector('.vwZgNotiz').value.trim()};
    if(kategorie==='vorstand' && !payload.positionId){ st.textContent = 'Bitte eine Vorstandsposition wählen.'; return; }
    try{ await epCallOhneAktion(payload); await vwZgNeuLaden(); st.textContent = 'Zugehörigkeit gespeichert.'; }
    catch(e){ st.textContent = '⚠️ ' + e.message; }
    return;
  }
  const ende = t.closest('.vwZgEnde');
  if(ende){
    const z = vwZgCache.find(x=>x.id===ende.dataset.id); if(!z) return;
    if(!(await bestaetigen('Diese Zugehörigkeit zum heutigen Tag beenden? Sie bleibt als ehemalig im Verlauf sichtbar.'))) return;
    try{
      await epCallOhneAktion({action:'admin_zugehoerigkeit_speichern', pass: currentAuthPass, id: z.id, personId: z.person_id,
        kategorie: z.kategorie, positionId: z.position_id || undefined, von: z.von, bis: vwHeute() < z.von ? z.von : vwHeute(), notiz: z.notiz || ''});
      await vwZgNeuLaden(); st.textContent = 'Zugehörigkeit beendet.';
    }catch(e){ st.textContent = '⚠️ ' + e.message; }
    return;
  }
  const del = t.closest('.vwZgDel');
  if(del){
    if(!(await bestaetigen('Eintrag endgültig löschen? Wenn die Person nur nicht mehr dabei ist, besser „Heute beenden“ nutzen, dann bleibt der Verlauf erhalten.'))) return;
    try{ await epCallOhneAktion({action:'admin_zugehoerigkeit_loeschen', pass: currentAuthPass, id: del.dataset.id}); await vwZgNeuLaden(); st.textContent = 'Eintrag gelöscht.'; }
    catch(e){ st.textContent = '⚠️ ' + e.message; }
    return;
  }
});
document.getElementById('vwPersonenInhalt').addEventListener('change', (ev)=>{
  if(ev.target.classList.contains('vwZgKat')){
    const pos = ev.target.closest('.vwZgForm').querySelector('.vwZgPos');
    pos.style.display = ev.target.value==='vorstand' ? 'block' : 'none';
  }
});
async function vwZgNeuLaden(){
  const zj = await epCallOhneAktion({action:'admin_zugehoerigkeiten_liste', pass: currentAuthPass});
  vwZgCache = zj.zugehoerigkeiten || []; vwPosCache = zj.positionen || [];
  vwPosFilterFuellen();
  vwPersZeichne();
}
// ---- Vorstandspositionen pflegen (erweiterbar) ----
function vwPosVerwaltenZeichne(){
  const box = document.getElementById('vwPosVerwaltenBox');
  box.innerHTML = '<div class="dp-hint" style="margin-top:0;">Vorstandspositionen (deaktivierte stehen bei neuen Einträgen nicht mehr zur Auswahl, alte Einträge bleiben erhalten):</div>' +
    vwPosCache.map(p=>'<div style="display:flex; gap:6px; align-items:center; padding:4px 0; border-top:1px solid #efe8da;">' +
      '<input type="text" class="vwPosName" data-id="' + escapeHtml(p.id) + '" value="' + escapeHtml(p.name) + '" maxlength="60" style="flex:1;" autocomplete="off">' +
      '<label style="font-size:0.85rem;"><input type="checkbox" class="vwPosAktiv" data-id="' + escapeHtml(p.id) + '"' + (p.aktiv?' checked':'') + '> aktiv</label>' +
      '<button class="btn ghost vwPosSave" type="button" data-id="' + escapeHtml(p.id) + '" data-sort="' + p.sortierung + '">Speichern</button></div>').join('') +
    '<div style="display:flex; gap:6px; margin-top:8px;"><input type="text" id="vwPosNeuName" placeholder="Neue Position, z. B. Jugendvertretung" maxlength="60" style="flex:1;" autocomplete="off">' +
    '<button class="btn" id="vwPosNeuBtn" type="button">Hinzufügen</button></div>';
}
document.getElementById('vwPosVerwaltenBtn').addEventListener('click', ()=>{
  const box = document.getElementById('vwPosVerwaltenBox');
  if(box.style.display==='block'){ box.style.display='none'; return; }
  box.style.display='block'; vwPosVerwaltenZeichne();
});
document.getElementById('vwPosVerwaltenBox').addEventListener('click', async (ev)=>{
  const st = document.getElementById('vwPersStatus');
  const sv = ev.target.closest('.vwPosSave');
  try{
    if(sv){
      const row = sv.parentElement;
      await epCallOhneAktion({action:'admin_vorstandsposition_speichern', pass: currentAuthPass, id: sv.dataset.id,
        name: row.querySelector('.vwPosName').value.trim(), aktiv: row.querySelector('.vwPosAktiv').checked, sortierung: Number(sv.dataset.sort)});
      await vwZgNeuLaden(); vwPosVerwaltenZeichne(); st.textContent = 'Position gespeichert.'; return;
    }
    if(ev.target.closest('#vwPosNeuBtn')){
      const name = document.getElementById('vwPosNeuName').value.trim();
      if(!name){ st.textContent = 'Bitte einen Namen eingeben.'; return; }
      const maxS = vwPosCache.reduce((m,p)=>Math.max(m,p.sortierung||0), 0);
      await epCallOhneAktion({action:'admin_vorstandsposition_speichern', pass: currentAuthPass, name, aktiv:true, sortierung: maxS + 10});
      await vwZgNeuLaden(); vwPosVerwaltenZeichne(); st.textContent = 'Position hinzugefügt.';
    }
  }catch(e){ st.textContent = '⚠️ ' + e.message; }
});
document.getElementById('vwPersonenInhalt').addEventListener('click', async (ev)=>{
  const editBtn = ev.target.closest('.vwPersEdit');
  const delBtn = ev.target.closest('.vwPersDel');
  const saveBtn = ev.target.closest('.vwPersSave');
  const delOk = ev.target.closest('.vwPersDelOk');
  const cancel = ev.target.closest('.vwPersCancel');
  const statusEl = document.getElementById('vwPersStatus');
  const panelFor = id => document.getElementById('vwPersPanel_'+id);
  if(cancel){ const pn = cancel.closest('.vwPersPanel'); pn.style.display='none'; pn.innerHTML=''; return; }
  if(editBtn){
    const p = vwPersListeCache.find(x=>x.id===editBtn.dataset.id); if(!p) return;
    const pn = panelFor(p.id);
    pn.style.display='block';
    pn.innerHTML = '<div class="add-row" style="grid-template-columns:1fr 1fr; margin-top:8px;">' +
      '<input type="text" class="vwPersEdV" value="' + escapeHtml(p.vorname||'') + '" placeholder="Vorname" autocomplete="off">' +
      '<input type="text" class="vwPersEdN" value="' + escapeHtml(p.nachname||'') + '" placeholder="Nachname" autocomplete="off"></div>' +
      '<div style="display:flex; gap:6px; margin-top:6px;"><button class="btn vwPersSave" type="button" data-id="' + escapeHtml(p.id) + '">Speichern</button>' +
      '<button class="btn ghost vwPersCancel" type="button">Abbrechen</button></div>';
    return;
  }
  if(saveBtn){
    const pn = saveBtn.closest('.vwPersPanel');
    const vorname = pn.querySelector('.vwPersEdV').value.trim(), nachname = pn.querySelector('.vwPersEdN').value.trim();
    if(!vorname || !nachname){ statusEl.textContent = 'Bitte Vor- und Nachname eingeben.'; return; }
    try{
      await epCallOhneAktion({action:'admin_person_umbenennen', pass: currentAuthPass, personId: saveBtn.dataset.id, vorname, nachname});
      await renderVwPersonen();
      statusEl.textContent = `Gespeichert: ${vorname} ${nachname}. Hinweis: Namen in bereits angelegten Personaleinsätzen einzelner Aktionen bleiben unverändert.`;
    }catch(e){ statusEl.textContent = 'Fehler: '+e.message; }
    return;
  }
  if(delBtn){
    const p = vwPersListeCache.find(x=>x.id===delBtn.dataset.id); if(!p) return;
    const pn = panelFor(p.id);
    pn.style.display='block';
    pn.innerHTML = '<div class="dp-hint" style="margin-top:8px; color:#b3261e;">Unwiderruflich. Zur Bestätigung den vollen Namen eintippen: <strong>' + escapeHtml(p.vorname+' '+p.nachname) + '</strong></div>' +
      '<input type="text" class="vwPersDelEin" style="width:100%; box-sizing:border-box; margin-top:6px;" autocomplete="off">' +
      '<div style="display:flex; gap:6px; margin-top:6px;"><button class="btn vwPersDelOk" type="button" data-id="' + escapeHtml(p.id) + '">Endgültig löschen</button>' +
      '<button class="btn ghost vwPersCancel" type="button">Abbrechen</button></div>';
    return;
  }
  if(delOk){
    const p = vwPersListeCache.find(x=>x.id===delOk.dataset.id); if(!p) return;
    const eingabe = delOk.closest('.vwPersPanel').querySelector('.vwPersDelEin').value.trim();
    if(eingabe !== (p.vorname+' '+p.nachname)){ statusEl.textContent = '⚠️ Der eingetippte Name stimmt nicht überein — Person wurde NICHT gelöscht.'; return; }
    try{
      await epCallOhneAktion({action:'admin_person_loeschen', pass: currentAuthPass, personId: p.id});
      await renderVwPersonen();
      statusEl.textContent = `${p.vorname} ${p.nachname} wurde gelöscht.`;
    }catch(e){ statusEl.textContent = '⚠️ '+e.message; }
    return;
  }
  const btn = ev.target.closest('.vwPersPinReset');
  if(!btn) return;
  const personId = btn.dataset.id, name = btn.dataset.name;
  if(!(await bestaetigen(`PIN von ${name} wirklich zurücksetzen? Die Person muss sich beim nächsten Anmelden eine neue PIN vergeben.`))) return;
  try{
    await epCallOhneAktion({action:'admin_person_pin_zuruecksetzen', pass: currentAuthPass, personId});
    await renderVwPersonen();
    document.getElementById('vwPersStatus').textContent = `PIN von ${name} wurde zurückgesetzt.`;
  }catch(e){
    alert('Fehler beim Zurücksetzen: '+e.message);
  }
});
document.getElementById('vwPersAnlegenBtn').addEventListener('click', async ()=>{
  const vEl = document.getElementById('vwPersVorname'), nEl = document.getElementById('vwPersNachname');
  const status = document.getElementById('vwPersStatus');
  const vorname = vEl.value.trim(), nachname = nEl.value.trim();
  if(!vorname || !nachname){ status.textContent = 'Bitte Vor- und Nachname eingeben.'; return; }
  try{
    await epCallOhneAktion({action:'admin_personen_erstellen', pass: currentAuthPass, vorname, nachname});
    vEl.value = ''; nEl.value = '';
    await renderVwPersonen();
    status.textContent = `${vorname} ${nachname} wurde angelegt.`;
  }catch(e){
    status.textContent = 'Fehler: '+e.message;
  }
});
document.getElementById('vwKachelPersonen').addEventListener('click', async ()=>{
  document.getElementById('vwMenu').style.display = 'none';
  document.getElementById('vwPersonenView').style.display = 'block';
  document.getElementById('vwPersStatus').textContent = '';
  await renderVwPersonen();
});
document.getElementById('vwPersonenZurueckBtn').addEventListener('click', zeigeVwMenu);

// ---- Verwaltung: Oberaktionen (Aktionen bündeln, Anwesenheit, Ampel) ----
let oaListe = [], oaAktionen = [], oaPersonen = [], oaDetailId = null;
const OA_AMPEL = {gruen:{farbe:'#1f8a4c', text:'Grün'}, gelb:{farbe:'#c99700', text:'Gelb'}, rot:{farbe:'#c0392b', text:'Rot'}, grau:{farbe:'#8a8478', text:'Noch keine Daten'}};
function oaAmpel(o, anw, ges){
  if(!ges) return 'grau';
  const wert = o.ampel_modus === 'anzahl' ? anw : (anw / ges * 100);
  if(wert + 1e-9 >= Number(o.ampel_gruen_ab)) return 'gruen';
  if(wert + 1e-9 >= Number(o.ampel_gelb_ab)) return 'gelb';
  return 'rot';
}
function oaSchwellenText(o){
  const e = o.ampel_modus === 'anzahl' ? ' Anwesenheiten' : ' %';
  return `Grün ab ${Number(o.ampel_gruen_ab)}${e}, Gelb ab ${Number(o.ampel_gelb_ab)}${e}, darunter Rot`;
}
function oaPersonName(id){ const p = oaPersonen.find(x=>x.id===id); return p ? ((p.vorname||'')+' '+(p.nachname||'')).trim() : '(gelöschte Person)'; }
async function oaLaden(){
  const [a, b, c] = await Promise.all([
    epCallOhneAktion({action:'admin_oberaktionen_liste', pass: currentAuthPass}),
    epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass}),
    epCallOhneAktion({action:'admin_personen_list', pass: currentAuthPass})
  ]);
  oaListe = a.oberaktionen || []; oaAktionen = b.aktionen || []; oaPersonen = c.personen || [];
}
async function renderVwOberaktionen(){
  const el = document.getElementById('vwOberaktionenInhalt');
  el.textContent = 'Lädt…';
  try{
    await oaLaden();
    if(oaDetailId && oaListe.some(o=>o.id===oaDetailId)) await oaZeichneDetail(); else { oaDetailId = null; oaZeichneListe(); }
  }catch(e){ el.innerHTML = '<div class="card" style="color:#b3261e;">Fehler beim Laden: ' + escapeHtml(e.message) + ' (SQL 80 und Backend eingespielt?)</div>'; }
}
function oaZeichneListe(){
  const el = document.getElementById('vwOberaktionenInhalt');
  const liste = oaListe.slice().sort((x,y)=>(x.abgeschlossen_am?1:0)-(y.abgeschlossen_am?1:0) || (x.name||'').localeCompare(y.name||'','de'));
  el.innerHTML = '<div class="card" style="text-align:left;"><div class="dp-hint" style="margin-top:0;">Neue Oberaktion anlegen:</div>' +
    '<div class="add-row" style="grid-template-columns:1fr auto;"><input type="text" id="oaNeuName" placeholder="z. B. Vorbereitung Ferienspiele 2027" maxlength="120" autocomplete="off"><button class="btn" id="oaNeuBtn" type="button">Anlegen</button></div></div>' +
    (liste.length ? liste.map(o=>{
      const kinder = oaAktionen.filter(a=>a.oberaktion_id===o.id);
      const erfasst = kinder.filter(a=>a.anwesenheit_erfasst_am).length;
      return '<div class="card" style="text-align:left;"><strong>🗂 ' + escapeHtml(o.name) + '</strong>' + (o.abgeschlossen_am ? ' <span style="color:#7a7266;">(abgeschlossen)</span>' : '') +
        '<div style="font-size:0.85rem; color:#7a7266;">' + kinder.length + ' Aktion' + (kinder.length===1?'':'en') + ' · bei ' + erfasst + ' Anwesenheit erfasst' + (o.ampel_aktiv ? ' · Ampel: ' + escapeHtml(oaSchwellenText(o)) : ' · Ampel aus') + '</div>' +
        '<button class="btn ghost oaOeffnen" type="button" data-id="' + escapeHtml(o.id) + '" style="margin-top:6px;">Öffnen</button></div>';
    }).join('') : '<div class="card">Noch keine Oberaktion angelegt.</div>');
}
async function oaZeichneDetail(){
  const o = oaListe.find(x=>x.id===oaDetailId); if(!o) return;
  const el = document.getElementById('vwOberaktionenInhalt');
  const kinder = oaAktionen.filter(a=>a.oberaktion_id===o.id).sort((x,y)=>(x.start_datum||'').localeCompare(y.start_datum||'') || (x.name||'').localeCompare(y.name||'','de'));
  const frei = oaAktionen.filter(a=>!a.oberaktion_id).sort((x,y)=>(x.name||'').localeCompare(y.name||'','de'));
  el.innerHTML = '<button class="btn ghost" id="oaZurueckListe" type="button" style="margin-bottom:8px;">← Alle Oberaktionen</button>' +
    '<div class="card" style="text-align:left;"><h3 style="margin:0 0 6px;">🗂 ' + escapeHtml(o.name) + '</h3>' +
    '<input type="text" id="oaName" value="' + escapeHtml(o.name) + '" maxlength="120" style="width:100%; box-sizing:border-box;" autocomplete="off">' +
    '<input type="text" id="oaBeschr" value="' + escapeHtml(o.beschreibung||'') + '" maxlength="500" placeholder="Beschreibung (optional)" style="width:100%; box-sizing:border-box; margin-top:6px;" autocomplete="off">' +
    '<div class="dp-hint">Ampel für die Teamenden (nur für die Leitung sichtbar):</div>' +
    '<label style="display:block;"><input type="checkbox" id="oaAmpelAktiv"' + (o.ampel_aktiv?' checked':'') + '> Ampel verwenden</label>' +
    '<div class="add-row" style="grid-template-columns:1fr 1fr 1fr; gap:6px; margin-top:6px;">' +
    '<label style="font-size:0.85rem;">Rechnen in<select id="oaModus"><option value="prozent"' + (o.ampel_modus==='prozent'?' selected':'') + '>Prozent</option><option value="anzahl"' + (o.ampel_modus==='anzahl'?' selected':'') + '>Anzahl Treffen</option></select></label>' +
    '<label style="font-size:0.85rem;">Grün ab<input type="number" id="oaGruen" min="0" step="any" value="' + Number(o.ampel_gruen_ab) + '"></label>' +
    '<label style="font-size:0.85rem;">Gelb ab<input type="number" id="oaGelb" min="0" step="any" value="' + Number(o.ampel_gelb_ab) + '"></label></div>' +
    '<div class="dp-hint">Beispiel: „Anzahl“, Grün ab 5, Gelb ab 3. Bei 5 von 5 grün, bei 3 oder 4 gelb, darunter rot. Bei „Prozent“ zählt der Anteil der Treffen, an denen die Person dabei war.</div>' +
    '<label style="display:block; margin-top:6px;"><input type="checkbox" id="oaAbgeschlossen"' + (o.abgeschlossen_am?' checked':'') + '> Oberaktion abgeschlossen (löscht alle Anwesenheitsdaten und die Ampel)</label>' +
    '<div style="display:flex; gap:6px; margin-top:8px; flex-wrap:wrap;"><button class="btn" id="oaSpeichern" type="button">Speichern</button><button class="btn ghost" id="oaLoeschen" type="button">🗑 Oberaktion löschen</button></div></div>' +
    '<div class="card" style="text-align:left;"><div class="dp-hint" style="margin-top:0;">Zugeordnete Aktionen und Termine (' + kinder.length + '):</div>' +
    (kinder.length ? kinder.map(a=>
      '<div style="padding:6px 0; border-top:1px solid #e5ddd0;"><strong>' + escapeHtml(a.name) + '</strong> <span style="color:#7a7266; font-size:0.85rem;">' + (a.start_datum ? vwDatumDe(a.start_datum) : 'ohne Datum') + '</span><br>' +
      '<span style="font-size:0.85rem;">' + (o.abgeschlossen_am ? 'Oberaktion abgeschlossen, keine Anwesenheitsdaten gespeichert' : (a.anwesenheit_erfasst_am ? '✅ Anwesenheit erfasst' : '⏳ Anwesenheit noch offen')) + '</span>' +
      '<div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:4px;">' + (o.abgeschlossen_am ? '' : '<button class="btn ghost oaAnwBtn" type="button" data-id="' + escapeHtml(a.id) + '">Anwesenheit</button>') +
      '<button class="btn ghost oaLoesen" type="button" data-id="' + escapeHtml(a.id) + '">Aus Oberaktion lösen</button></div>' +
      '<div class="oaAnwPanel" id="oaAnwPanel_' + escapeHtml(a.id) + '" style="display:none;"></div></div>').join('') : '<div class="dp-hint">Noch nichts zugeordnet.</div>') +
    '<div style="display:flex; gap:6px; margin-top:10px;"><select id="oaZuordnenSel" style="flex:1;"><option value="">Aktion zuordnen…</option>' +
    frei.map(a=>'<option value="' + escapeHtml(a.id) + '">' + escapeHtml(a.name) + (a.start_datum ? ' (' + vwDatumDe(a.start_datum) + ')' : '') + '</option>').join('') +
    '</select><button class="btn ghost" id="oaZuordnenBtn" type="button">Zuordnen</button></div></div>' +
    '<div class="card" style="text-align:left;" id="oaAmpelBox">Ampel lädt…</div>';
  await oaZeichneAmpel();
}
let oaAmpelDaten = null;
async function oaZeichneAmpel(){
  const box = document.getElementById('oaAmpelBox'); if(!box) return;
  const o = oaListe.find(x=>x.id===oaDetailId); if(!o) return;
  if(!o.ampel_aktiv){ box.innerHTML = '<div class="dp-hint" style="margin-top:0;">Die Ampel ist für diese Oberaktion ausgeschaltet.</div>'; return; }
  try{
    oaAmpelDaten = await epCallOhneAktion({action:'admin_ampel_auswertung', pass: currentAuthPass, oberaktionId: o.id});
  }catch(e){ box.innerHTML = '<div style="color:#b3261e;">Ampel konnte nicht geladen werden: ' + escapeHtml(e.message) + '</div>'; return; }
  const n = (oaAmpelDaten.treffen || []).length;
  box.innerHTML = '<h3 style="margin:0 0 4px;">🚦 Ampel</h3><div class="dp-hint" style="margin-top:0;">' + escapeHtml(oaSchwellenText(o)) + '. Grundlage: ' + n + ' Termin' + (n===1?'':'e') + ' mit erfasster Anwesenheit.</div>' +
    '<div class="add-row" style="grid-template-columns:1fr 1fr; gap:6px; margin-top:6px;"><input type="text" id="oaAmpelSuche" placeholder="Person suchen…" autocomplete="off">' +
    '<select id="oaAmpelFilter"><option value="">Alle Farben</option><option value="rot">Nur Rot</option><option value="gelb">Nur Gelb</option><option value="gruen">Nur Grün</option></select></div>' +
    '<div id="oaAmpelTabelle" style="margin-top:6px;"></div>';
  oaAmpelTabelle();
}
function oaAmpelTabelle(){
  const t = document.getElementById('oaAmpelTabelle'); if(!t || !oaAmpelDaten) return;
  const o = oaAmpelDaten.oberaktion;
  const suche = (document.getElementById('oaAmpelSuche').value||'').trim().toLowerCase();
  const filter = document.getElementById('oaAmpelFilter').value;
  const reihe = {rot:0, gelb:1, gruen:2, grau:3};
  const zeilen = (oaAmpelDaten.zeilen||[]).map(z=>({...z, name: oaPersonName(z.person_id), farbe: oaAmpel(o, z.anwesend, z.gesamt)}))
    .filter(z=>(!suche || z.name.toLowerCase().includes(suche)) && (!filter || z.farbe===filter))
    .sort((a,b)=>reihe[a.farbe]-reihe[b.farbe] || a.name.localeCompare(b.name,'de'));
  if(!(oaAmpelDaten.zeilen||[]).length){ t.innerHTML = '<div class="dp-hint">Noch keine Anwesenheit erfasst. Bei den zugeordneten Terminen auf „Anwesenheit“ klicken.</div>'; return; }
  if(!zeilen.length){ t.innerHTML = '<div class="dp-hint">Keine Treffer für diese Auswahl.</div>'; return; }
  t.innerHTML = zeilen.map(z=>{
    const a = OA_AMPEL[z.farbe];
    return '<div style="display:flex; align-items:center; gap:8px; padding:5px 0; border-top:1px solid #efe8da;">' +
      '<span style="display:inline-block; width:16px; height:16px; border-radius:50%; background:' + a.farbe + ';"></span>' +
      '<span style="flex:1;">' + escapeHtml(z.name) + '</span>' +
      '<span style="font-size:0.9rem;"><strong>' + z.anwesend + ' von ' + z.gesamt + '</strong> · ' + a.text + '</span></div>';
  }).join('');
}
async function oaOeffneAnwesenheit(aktionId, panel){
  panel.style.display = 'block'; panel.textContent = 'Lädt…';
  try{
    const j = await epCallOhneAktion({action:'admin_anwesenheit_lesen', pass: currentAuthPass, aktionId});
    const vorh = new Map((j.eintraege||[]).map(e=>[e.person_id, e.anwesend]));
    const kand = new Set([...(j.teamPersonIds||[]), ...vorh.keys()]);
    panel._daten = {aktionId, vorh, kand, erfasst: !!j.aktion.anwesenheit_erfasst_am, alle:false};
    oaAnwZeichne(panel);
  }catch(e){ panel.innerHTML = '<div style="color:#b3261e;">' + escapeHtml(e.message) + '</div>'; }
}
function oaAnwZeichne(panel){
  const d = panel._daten;
  const aktuell = new Map();
  panel.querySelectorAll('.oaAnwCb').forEach(cb=>aktuell.set(cb.dataset.id, cb.checked));
  const personen = oaPersonen.filter(p=>d.alle || d.kand.has(p.id))
    .sort((a,b)=>(a.nachname||'').localeCompare(b.nachname||'','de') || (a.vorname||'').localeCompare(b.vorname||'','de'));
  panel.innerHTML = '<div style="background:#faf6ee; border-radius:8px; padding:8px; margin-top:6px;">' +
    '<div class="dp-hint" style="margin-top:0;">Wer war dabei? Häkchen = anwesend. Ohne Häkchen gilt als abwesend und zählt für die Ampel.</div>' +
    '<input type="text" class="oaAnwSuche" placeholder="Person suchen…" style="width:100%; box-sizing:border-box;" autocomplete="off">' +
    '<div class="oaAnwListe" style="max-height:320px; overflow:auto; margin-top:6px;">' +
    personen.map(p=>{
      const an = aktuell.has(p.id) ? aktuell.get(p.id) : !!d.vorh.get(p.id);
      const name = ((p.vorname||'')+' '+(p.nachname||'')).trim();
      return '<label class="oaAnwZeile" data-name="' + escapeHtml(name.toLowerCase()) + '" style="display:block; padding:4px 0;"><input type="checkbox" class="oaAnwCb" data-id="' + escapeHtml(p.id) + '"' + (an?' checked':'') + '> ' + escapeHtml(name) + '</label>';
    }).join('') + '</div>' +
    '<label style="display:block; margin-top:6px; font-size:0.9rem;"><input type="checkbox" class="oaAnwAlle"' + (d.alle?' checked':'') + '> Alle Personen der Kartei anzeigen (sonst nur aktuelle Teamende)</label>' +
    '<div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:6px;"><button class="btn ghost oaAnwAlleMark" type="button">Alle anhaken</button><button class="btn ghost oaAnwKeine" type="button">Keine</button></div>' +
    '<div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:6px;"><button class="btn oaAnwSave" type="button">Speichern</button><button class="btn ghost oaAnwAbbr" type="button">Schließen</button>' +
    (d.erfasst ? '<button class="btn ghost oaAnwReset" type="button">Anwesenheit zurücksetzen</button>' : '') + '</div></div>';
}
document.getElementById('vwKachelOberaktionen').addEventListener('click', async ()=>{
  document.getElementById('vwMenu').style.display = 'none';
  document.getElementById('vwOberaktionenView').style.display = 'block';
  document.getElementById('vwOberaktionenStatus').textContent = '';
  oaDetailId = null;
  await renderVwOberaktionen();
});
document.getElementById('vwOberaktionenZurueckBtn').addEventListener('click', zeigeVwMenu);
document.getElementById('vwOberaktionenInhalt').addEventListener('input', (ev)=>{
  if(ev.target.id==='oaAmpelSuche') oaAmpelTabelle();
  if(ev.target.classList.contains('oaAnwSuche')){
    const q = ev.target.value.trim().toLowerCase();
    ev.target.closest('.oaAnwPanel').querySelectorAll('.oaAnwZeile').forEach(z=>{ z.style.display = (!q || z.dataset.name.includes(q)) ? 'block' : 'none'; });
  }
});
document.getElementById('vwOberaktionenInhalt').addEventListener('change', (ev)=>{
  if(ev.target.id==='oaAmpelFilter') oaAmpelTabelle();
  if(ev.target.classList.contains('oaAnwAlle')){
    const panel = ev.target.closest('.oaAnwPanel'); panel._daten.alle = ev.target.checked; oaAnwZeichne(panel);
  }
});
document.getElementById('vwOberaktionenInhalt').addEventListener('click', async (ev)=>{
  const t = ev.target, st = document.getElementById('vwOberaktionenStatus');
  const rufe = async (payload, okText)=>{
    try{ await epCallOhneAktion({pass: currentAuthPass, ...payload}); await oaLaden(); st.textContent = okText || ''; return true; }
    catch(e){ st.textContent = '⚠️ ' + e.message; return false; }
  };
  if(t.id==='oaNeuBtn'){
    const name = document.getElementById('oaNeuName').value.trim();
    if(!name){ st.textContent = 'Bitte einen Namen eingeben.'; return; }
    try{
      const r = await epCallOhneAktion({action:'admin_oberaktion_speichern', pass: currentAuthPass, name, ampel_aktiv:true, ampel_modus:'prozent', ampel_gruen_ab:100, ampel_gelb_ab:60});
      await oaLaden(); oaDetailId = r.id; st.textContent = 'Oberaktion angelegt. Du kannst jetzt Aktionen zuordnen und die Ampel einstellen.'; await oaZeichneDetail();
    }catch(e){ st.textContent = '⚠️ ' + e.message; }
    return;
  }
  const oeff = t.closest('.oaOeffnen');
  if(oeff){ oaDetailId = oeff.dataset.id; await oaZeichneDetail(); return; }
  if(t.id==='oaZurueckListe'){ oaDetailId = null; oaZeichneListe(); return; }
  if(t.id==='oaSpeichern'){
    const o = oaListe.find(x=>x.id===oaDetailId); if(!o) return;
    const schliesst = document.getElementById('oaAbgeschlossen').checked && !o.abgeschlossen_am;
    if(schliesst && !(await bestaetigen('Oberaktion abschließen? Dabei werden ALLE Anwesenheitsdaten und die Ampel dieser Oberaktion unwiderruflich gelöscht. Die Aktionen und Termine selbst bleiben erhalten.'))) return;
    if(await rufe({action:'admin_oberaktion_speichern', id:o.id, name:document.getElementById('oaName').value.trim(), beschreibung:document.getElementById('oaBeschr').value.trim(),
      ampel_aktiv:document.getElementById('oaAmpelAktiv').checked, ampel_modus:document.getElementById('oaModus').value,
      ampel_gruen_ab:Number(document.getElementById('oaGruen').value), ampel_gelb_ab:Number(document.getElementById('oaGelb').value),
      abgeschlossen:document.getElementById('oaAbgeschlossen').checked}, schliesst ? 'Oberaktion abgeschlossen, Anwesenheitsdaten gelöscht.' : 'Gespeichert.')) await oaZeichneDetail();
    return;
  }
  if(t.id==='oaLoeschen'){
    const o = oaListe.find(x=>x.id===oaDetailId); if(!o) return;
    if(!(await bestaetigen(`Oberaktion „${o.name}“ löschen? Die zugeordneten Aktionen bleiben erhalten und erscheinen wieder einzeln. Die Anwesenheitsdaten und die Ampel werden gelöscht.`))) return;
    if(await rufe({action:'admin_oberaktion_loeschen', id:o.id}, 'Oberaktion gelöscht.')){ oaDetailId = null; oaZeichneListe(); }
    return;
  }
  if(t.id==='oaZuordnenBtn'){
    const id = document.getElementById('oaZuordnenSel').value; if(!id){ st.textContent = 'Bitte eine Aktion wählen.'; return; }
    if(await rufe({action:'admin_aktion_oberaktion_setzen', aktionId:id, oberaktionId:oaDetailId}, 'Zugeordnet.')){ const b = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass}); oaAktionen = b.aktionen||[]; await oaZeichneDetail(); }
    return;
  }
  const loes = t.closest('.oaLoesen');
  if(loes){
    if(!(await bestaetigen('Diese Aktion aus der Oberaktion lösen? Ihre Anwesenheitsdaten werden dabei gelöscht.'))) return;
    if(await rufe({action:'admin_aktion_oberaktion_setzen', aktionId:loes.dataset.id, oberaktionId:null}, 'Gelöst.')){ const b = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass}); oaAktionen = b.aktionen||[]; await oaZeichneDetail(); }
    return;
  }
  const anw = t.closest('.oaAnwBtn');
  if(anw){ const pn = document.getElementById('oaAnwPanel_'+anw.dataset.id); if(pn.style.display==='block'){ pn.style.display='none'; pn.innerHTML=''; } else await oaOeffneAnwesenheit(anw.dataset.id, pn); return; }
  const panel = t.closest('.oaAnwPanel');
  if(panel && panel._daten){
    if(t.closest('.oaAnwAbbr')){ panel.style.display='none'; panel.innerHTML=''; return; }
    if(t.closest('.oaAnwAlleMark')){ panel.querySelectorAll('.oaAnwZeile').forEach(z=>{ if(z.style.display!=='none') z.querySelector('.oaAnwCb').checked = true; }); return; }
    if(t.closest('.oaAnwKeine')){ panel.querySelectorAll('.oaAnwCb').forEach(cb=>cb.checked=false); return; }
    if(t.closest('.oaAnwSave')){
      const eintraege = [...panel.querySelectorAll('.oaAnwCb')].map(cb=>({personId: cb.dataset.id, anwesend: cb.checked}));
      if(await rufe({action:'admin_anwesenheit_speichern', aktionId: panel._daten.aktionId, eintraege}, `Anwesenheit gespeichert (${eintraege.filter(e=>e.anwesend).length} von ${eintraege.length} anwesend).`)){
        const b = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass}); oaAktionen = b.aktionen||[]; await oaZeichneDetail();
      }
      return;
    }
    if(t.closest('.oaAnwReset')){
      if(!(await bestaetigen('Die Anwesenheit dieses Termins wirklich zurücksetzen? Der Termin zählt dann nicht mehr für die Ampel.'))) return;
      if(await rufe({action:'admin_anwesenheit_zuruecksetzen', aktionId: panel._daten.aktionId}, 'Anwesenheit zurückgesetzt.')){
        const b = await epCallOhneAktion({action:'admin_aktionen_list', pass: currentAuthPass}); oaAktionen = b.aktionen||[]; await oaZeichneDetail();
      }
      return;
    }
  }
});

