// ================================================================
// VERLEIH (Migration 52) — Materialien/Geräte, die regelmäßig
// verliehen werden. Reine Admin-Verwaltung, Anfragen laufen NICHT
// über die App (siehe Backend-Kommentar in der Edge Function).
// ================================================================
let vlArtikelCache = [];
let vlAusleihenCache = [];

async function renderVwVerleih(){
  if(!isAdmin()) return;
  document.getElementById('vlFormularContainer').style.display = 'none';
  document.getElementById('vlArtikelContainer').style.display = 'none';
  await ladeVlArtikel();
  await ladeVwAktionenCacheFallsNoetig();
  vlBefuelleAktionAuswahl();
  await ladeVlAusleihen();
}

function vlBefuelleAktionAuswahl(){
  const sel = document.getElementById('vlAktionAuswahl');
  const bisher = sel.value;
  sel.innerHTML = '<option value="">— keine —</option>' + vwAktionenCache
    .slice()
    .sort((a,b)=>(a.name||'').localeCompare(b.name||''))
    .map(a=>`<option value="${escapeHtml(a.id)}">${escapeHtml(a.name)}</option>`).join('');
  sel.value = bisher;
}

function vlArtikelOptionenHtml(ausgewaehlteId){
  return vlArtikelCache
    .slice()
    .sort((a,b)=>(a.name||'').localeCompare(b.name||''))
    .map(a=>`<option value="${escapeHtml(a.id)}" ${a.id===ausgewaehlteId?'selected':''}>${escapeHtml(a.name)}${a.aktiv ? '' : ' (inaktiv)'} — Bestand ${a.gesamt_bestand}</option>`).join('');
}

// ---------- Positionen (mehrere Artikel pro Ausleihe) ----------
// vlAktuellePositionen: Arbeits-Array für das Formular, z.B.
// [{artikelId:'...', anzahl:2}, {artikelId:'...', anzahl:1}]. Wird bei
// jeder Änderung neu gerendert (kein zusätzlicher State pro DOM-Element
// nötig, das Array ist die einzige Quelle der Wahrheit).
let vlAktuellePositionen = [{artikelId:'', anzahl:1}];

function vlRenderPositionenListe(){
  const listeEl = document.getElementById('vlPositionenListe');
  listeEl.innerHTML = vlAktuellePositionen.map((pos, idx)=>`
    <div class="add-row" style="grid-template-columns:2fr 1fr auto; align-items:center; margin-top:${idx===0?'0':'6px'};" data-idx="${idx}">
      <select class="vlPositionArtikel" data-idx="${idx}" style="width:100%; box-sizing:border-box;"><option value="">— Artikel wählen —</option>${vlArtikelOptionenHtml(pos.artikelId)}</select>
      <input type="number" class="vlPositionAnzahl" data-idx="${idx}" min="1" step="1" value="${pos.anzahl}" style="width:100%; box-sizing:border-box;">
      <button type="button" class="btn ghost vlPositionEntfernenBtn" data-idx="${idx}" style="padding:4px 8px; font-size:0.9rem;" ${vlAktuellePositionen.length<=1?'disabled title="Mindestens ein Artikel erforderlich"':''}>✕</button>
    </div>
  `).join('');
  listeEl.querySelectorAll('.vlPositionArtikel').forEach(sel=>{
    sel.addEventListener('change', ()=>{ vlAktuellePositionen[Number(sel.dataset.idx)].artikelId = sel.value; });
  });
  listeEl.querySelectorAll('.vlPositionAnzahl').forEach(inp=>{
    inp.addEventListener('change', ()=>{ vlAktuellePositionen[Number(inp.dataset.idx)].anzahl = Number(inp.value); });
  });
  listeEl.querySelectorAll('.vlPositionEntfernenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      if(vlAktuellePositionen.length <= 1) return;
      vlAktuellePositionen.splice(Number(btn.dataset.idx), 1);
      vlRenderPositionenListe();
    });
  });
}

document.getElementById('vlPositionHinzufuegenBtn').addEventListener('click', ()=>{
  vlAktuellePositionen.push({artikelId:'', anzahl:1});
  vlRenderPositionenListe();
});

// vlGebuehrBerechnen: summiert für alle aktuell gewählten Positionen den
// Artikel-Preis (normal oder reduziert, je nach Checkbox) × Anzahl und
// trägt das Ergebnis ins Leihgebühr-Feld ein. Bleibt danach ganz normal
// manuell überschreibbar — reine Ausfüllhilfe, kein automatischer Zwang.
// Positionen ohne Artikel-Auswahl oder ohne hinterlegten Preis für den
// gewählten Satz werden übersprungen und am Ende aufgelistet, statt die
// Berechnung ganz zu verweigern.
document.getElementById('vlGebuehrBerechnenBtn').addEventListener('click', ()=>{
  const statusEl = document.getElementById('vlGebuehrBerechnenStatus');
  const reduziert = document.getElementById('vlReduzierterSatz').checked;
  let summe = 0;
  const ohnePreis = [];
  let mindestensEinerMitPreis = false;
  vlAktuellePositionen.forEach(pos=>{
    if(!pos.artikelId) return;
    const artikel = vlArtikelCache.find(a=>a.id===pos.artikelId);
    if(!artikel) return;
    const preis = reduziert ? artikel.leihgebuehr_reduziert : artikel.leihgebuehr_normal;
    if(preis == null){
      ohnePreis.push(artikel.name);
      return;
    }
    mindestensEinerMitPreis = true;
    summe += Number(preis) * (Number(pos.anzahl) || 0);
  });
  if(!mindestensEinerMitPreis){
    statusEl.textContent = '⚠️ Für keinen der gewählten Artikel ist ein ' + (reduziert ? 'reduzierter' : 'normaler') + ' Preis hinterlegt.';
    return;
  }
  document.getElementById('vlLeihgebuehrBetrag').value = summe.toFixed(2);
  statusEl.textContent = '✓ ' + summe.toFixed(2) + ' € eingetragen (' + (reduziert ? 'reduzierter' : 'normaler') + ' Satz)' + (ohnePreis.length ? ' — ohne Preis: ' + ohnePreis.join(', ') : '') + '.';
});

// ---------- Artikel (Inventar) ----------
async function ladeVlArtikel(){
  const listeEl = document.getElementById('vlArtikelListe');
  listeEl.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_verleih_artikel_liste', pass: currentAuthPass});
    vlArtikelCache = json.artikel || [];
  }catch(e){
    listeEl.textContent = '⚠️ Konnte nicht geladen werden: '+e.message;
    return;
  }
  vlRenderPositionenListe();
  if(vlArtikelCache.length === 0){
    listeEl.innerHTML = '<p style="color:#7a7266; margin:0;">Noch keine Artikel angelegt.</p>';
    return;
  }
  listeEl.innerHTML = vlArtikelCache.map(a=>`
    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:4px 0; border-bottom:1px solid #e5ddd0; font-size:0.85rem;">
      <span>${escapeHtml(a.name)}${a.aktiv ? '' : ' <span class="tag">inaktiv</span>'} — Bestand ${a.gesamt_bestand}${(a.leihgebuehr_normal!=null || a.leihgebuehr_reduziert!=null) ? '<br><span style="color:#7a7266; font-size:0.8rem;">'+(a.leihgebuehr_normal!=null ? Number(a.leihgebuehr_normal).toFixed(2)+' €' : '–')+' / '+(a.leihgebuehr_reduziert!=null ? Number(a.leihgebuehr_reduziert).toFixed(2)+' €' : '–')+' (normal/reduziert)</span>' : ''}${a.beschreibung ? '<br><span style="color:#7a7266; font-size:0.8rem;">'+escapeHtml(a.beschreibung)+'</span>' : ''}</span>
      <span style="display:flex; gap:6px; white-space:nowrap;">
        <button class="btn ghost vaBearbeitenBtn" data-id="${escapeHtml(a.id)}" style="padding:2px 8px; font-size:0.78rem;">Bearbeiten</button>
        <button class="btn ghost vaLoeschenBtn" data-id="${escapeHtml(a.id)}" style="padding:2px 8px; font-size:0.78rem;">Löschen</button>
      </span>
    </div>
  `).join('');
  listeEl.querySelectorAll('.vaBearbeitenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const a = vlArtikelCache.find(x=>x.id===btn.dataset.id);
      if(!a) return;
      document.getElementById('vaBearbeiteId').value = a.id;
      document.getElementById('vaName').value = a.name;
      document.getElementById('vaBeschreibung').value = a.beschreibung || '';
      document.getElementById('vaGesamtBestand').value = a.gesamt_bestand;
      document.getElementById('vaWiederbeschaffungswert').value = a.wiederbeschaffungswert != null ? a.wiederbeschaffungswert : '';
      document.getElementById('vaLeihgebuehrNormal').value = a.leihgebuehr_normal != null ? a.leihgebuehr_normal : '';
      document.getElementById('vaLeihgebuehrReduziert').value = a.leihgebuehr_reduziert != null ? a.leihgebuehr_reduziert : '';
      document.getElementById('vaAktiv').checked = a.aktiv;
      document.getElementById('vaAbbrechenBtn').style.display = 'block';
      document.getElementById('vaStatus').textContent = '';
    });
  });
  listeEl.querySelectorAll('.vaLoeschenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const a = vlArtikelCache.find(x=>x.id===btn.dataset.id);
      if(!a) return;
      if(!(await bestaetigen(`Artikel "${a.name}" wirklich löschen? Bestehende Ausleihen bleiben als Eintrag erhalten. Alternativ: über "Bearbeiten" nur auf "inaktiv" setzen.`))) return;
      try{
        await epCallOhneAktion({action:'admin_verleih_artikel_loeschen', pass: currentAuthPass, id: a.id});
        await ladeVlArtikel();
      }catch(e){
        alert('Konnte nicht gelöscht werden: '+e.message);
      }
    });
  });
}

document.getElementById('vaSpeichernBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('vaStatus');
  const id = document.getElementById('vaBearbeiteId').value || undefined;
  const name = document.getElementById('vaName').value.trim();
  const beschreibung = document.getElementById('vaBeschreibung').value.trim();
  const gesamtBestand = Number(document.getElementById('vaGesamtBestand').value);
  const wbwRoh = document.getElementById('vaWiederbeschaffungswert').value;
  const wiederbeschaffungswert = wbwRoh === '' ? null : Number(wbwRoh);
  const lgNormalRoh = document.getElementById('vaLeihgebuehrNormal').value;
  const leihgebuehrNormal = lgNormalRoh === '' ? null : Number(lgNormalRoh);
  const lgReduziertRoh = document.getElementById('vaLeihgebuehrReduziert').value;
  const leihgebuehrReduziert = lgReduziertRoh === '' ? null : Number(lgReduziertRoh);
  const aktiv = document.getElementById('vaAktiv').checked;
  if(!name){ statusEl.textContent = '⚠️ Bitte einen Namen angeben.'; return; }
  if(!Number.isInteger(gesamtBestand) || gesamtBestand < 0){ statusEl.textContent = '⚠️ Ungültiger Gesamtbestand.'; return; }
  try{
    await epCallOhneAktion({action:'admin_verleih_artikel_speichern', pass: currentAuthPass, id, name, beschreibung, gesamtBestand, wiederbeschaffungswert, leihgebuehrNormal, leihgebuehrReduziert, aktiv});
    document.getElementById('vaBearbeiteId').value = '';
    document.getElementById('vaName').value = '';
    document.getElementById('vaBeschreibung').value = '';
    document.getElementById('vaGesamtBestand').value = 1;
    document.getElementById('vaWiederbeschaffungswert').value = '';
    document.getElementById('vaLeihgebuehrNormal').value = '';
    document.getElementById('vaLeihgebuehrReduziert').value = '';
    document.getElementById('vaAktiv').checked = true;
    document.getElementById('vaAbbrechenBtn').style.display = 'none';
    statusEl.textContent = '✓ Gespeichert.';
    await ladeVlArtikel();
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
  }
});
document.getElementById('vaAbbrechenBtn').addEventListener('click', ()=>{
  document.getElementById('vaBearbeiteId').value = '';
  document.getElementById('vaName').value = '';
  document.getElementById('vaBeschreibung').value = '';
  document.getElementById('vaGesamtBestand').value = 1;
  document.getElementById('vaWiederbeschaffungswert').value = '';
  document.getElementById('vaLeihgebuehrNormal').value = '';
  document.getElementById('vaLeihgebuehrReduziert').value = '';
  document.getElementById('vaAktiv').checked = true;
  document.getElementById('vaAbbrechenBtn').style.display = 'none';
  document.getElementById('vaStatus').textContent = '';
});

// ---------- Ausleihen ----------
const VL_STATUS_LABEL = {
  angefragt: 'Angefragt',
  ausgeliehen: 'Ausgeliehen',
  zurueckgegeben: 'Zurückgegeben',
  storniert: 'Storniert',
};

// Feste Zustands-Werte bei Rückgabe (Migration 60) — Klick-Chips statt
// Freitext, damit der Zustand auf einen Blick vergleichbar ist.
const VL_ZUSTAND_LABEL = {
  neuwertig: 'Neuwertig',
  gut: 'Gut',
  gebraucht: 'Gebraucht',
  beschaedigt: 'Beschädigt',
  defekt: 'Defekt',
};

// Öffnet das Zustand/Notiz-Panel einer Ausleihe — sowohl beim Umschalten
// auf "Zurückgegeben" per Quick-Select als auch später zum Korrigieren
// über den "(ändern)"-Link. statusZuSetzen ist der Status, der beim
// Bestätigen gesetzt werden soll (bei reiner Korrektur: der aktuelle).
function vlOeffneZustandPanel(id, statusZuSetzen){
  const panel = document.querySelector(`.vlZustandPanel[data-id="${CSS.escape(id)}"]`);
  if(!panel) return;
  const a = vlAusleihenCache.find(x=>x.id===id);
  panel.dataset.statusZuSetzen = statusZuSetzen;
  // Jede Position hat ihren eigenen Zustand/Notiz (Migration 75) — pro
  // Positions-Block einzeln aus den zwischengespeicherten Werten dieser
  // Position vorbelegen (statt eines einzigen Werts für die ganze Ausleihe).
  panel.querySelectorAll('.vlZustandPositionBlock').forEach(block=>{
    const posId = block.dataset.positionId;
    const p = ((a && a.positionen) || []).find(x=>x.id===posId);
    const aktuellerZustand = (p && p.rueckgabe_zustand) || '';
    block.dataset.zustand = aktuellerZustand;
    block.querySelectorAll('.vlZustandChip').forEach(btn=>{
      const aktiv = btn.dataset.wert === aktuellerZustand;
      btn.style.background = aktiv ? 'var(--green)' : '';
      btn.style.color = aktiv ? '#fff' : '';
    });
    const notizFeld = block.querySelector('.vlZustandNotizFeld');
    notizFeld.value = (p && p.rueckgabe_notiz) || '';
  });
  panel.style.display = 'block';
  panel.scrollIntoView({behavior:'smooth', block:'center'});
}

async function ladeVlAusleihen(){
  const listeEl = document.getElementById('vwVerleihAusleihenListe');
  listeEl.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_verleih_ausleihen_liste', pass: currentAuthPass});
    vlAusleihenCache = json.ausleihen || [];
  }catch(e){
    listeEl.innerHTML = '<div class="dp-hint">⚠️ Fehler beim Laden: '+escapeHtml(e.message)+'</div>';
    return;
  }
  if(vlAusleihenCache.length === 0){
    listeEl.innerHTML = '<p style="color:#7a7266; margin:0;">Noch keine Ausleihen erfasst.</p>';
    return;
  }

  const heute = todayIso();
  const aktiveStatus = ['angefragt', 'ausgeliehen'];
  const aktiv = vlAusleihenCache.filter(a=>aktiveStatus.includes(a.status));
  const abgeschlossen = vlAusleihenCache.filter(a=>!aktiveStatus.includes(a.status));

  const laufend = aktiv.filter(a=>a.von_datum <= heute && a.bis_datum >= heute).sort((a,b)=>a.bis_datum.localeCompare(b.bis_datum));
  const kommend = aktiv.filter(a=>a.von_datum > heute).sort((a,b)=>a.von_datum.localeCompare(b.von_datum));
  const ueberfaellig = aktiv.filter(a=>a.bis_datum < heute).sort((a,b)=>a.bis_datum.localeCompare(b.bis_datum));

  const zeile = a=>{
    const zeitraum = a.von_datum === a.bis_datum ? fmtDateFull(a.von_datum) : `${fmtDateFull(a.von_datum)} – ${fmtDateFull(a.bis_datum)}`;
    const positionen = a.positionen || [];
    // Mehrere Positionen: "Zelt × 2, Kocher × 1" statt nur einem Artikel.
    const artikelText = positionen.length > 0
      ? positionen.map(p=>`${escapeHtml(p.artikel_name_snapshot || '(gelöschter Artikel)')} × ${p.anzahl}`).join(', ')
      : '(keine Artikel)';
    const kautionInfo = a.kaution_betrag != null
      ? ` · Kaution ${Number(a.kaution_betrag).toFixed(2)} €${a.kaution_bezahlt ? ' (bezahlt)' : ' (offen)'}${a.status==='zurueckgegeben' ? (a.kaution_erstattet ? ', erstattet' : ', noch nicht erstattet') : ''}`
      : '';
    const leihgebuehrInfo = a.leihgebuehr_betrag != null
      ? ` · Leihgebühr ${Number(a.leihgebuehr_betrag).toFixed(2)} €${a.leihgebuehr_bezahlt ? ' (bezahlt)' : ' (offen)'}`
      : '';
    const interneNotizAnzeige = a.interne_notiz ? `<div style="font-size:0.8rem; color:#7a7266; margin-top:2px; font-style:italic;">Intern: ${escapeHtml(a.interne_notiz)}</div>` : '';
    // Zustand/Notiz je Artikel (Migration 75) statt einem Gesamtwert für
    // die ganze Rückgabe — nur Positionen anzeigen, zu denen tatsächlich
    // schon etwas erfasst wurde.
    const positionenMitZustand = positionen.filter(p=>p.rueckgabe_zustand || p.rueckgabe_notiz);
    const zustandAnzeige = positionenMitZustand.length > 0
      ? `<div style="font-size:0.8rem; color:#7a7266; margin-top:2px;">${positionenMitZustand.map(p=>{
          const zLabel = p.rueckgabe_zustand ? `<strong>${escapeHtml(VL_ZUSTAND_LABEL[p.rueckgabe_zustand] || p.rueckgabe_zustand)}</strong>` : '(kein Zustand erfasst)';
          const notizText = p.rueckgabe_notiz ? ` — ${escapeHtml(p.rueckgabe_notiz)}` : '';
          return `${escapeHtml(p.artikel_name_snapshot || '(gelöschter Artikel)')}: ${zLabel}${notizText}`;
        }).join('<br>')} · <a href="#" class="vlZustandBearbeitenLink" data-id="${escapeHtml(a.id)}">ändern</a></div>`
      : '';
    const versandHinweis = a.vertrag_email_versendet_am
      ? ` <span style="color:#a39a8a;">(zuletzt gesendet am ${escapeHtml(fmtDateFull(String(a.vertrag_email_versendet_am).slice(0,10)))} an ${escapeHtml(a.vertrag_email_adresse||'')})</span>`
      : '';
    const unterschriftAnzeige = a.unterschrift_entleiher_data
      ? `<div style="font-size:0.8rem; color:#7a7266; margin-top:2px;">✍️ Digital unterschrieben am ${escapeHtml(fmtDateFull(String(a.unterschrift_entleiher_am||'').slice(0,10)))} · <a href="#" class="vlVertragEmailLink" data-id="${escapeHtml(a.id)}">📧 per E-Mail senden</a>${versandHinweis}</div>`
      : '';
    // Zustand/Notiz-Panel: standardmäßig ausgeblendet, öffnet sich per
    // vlOeffneZustandPanel() (Umschalten auf "Zurückgegeben" oder Klick
    // auf "ändern"). Klick-Chips für den Zustand statt Freitext-Prompt,
    // Textfeld speziell für Schadensbeschreibungen.
    const zustandPanel = `
    <div class="vlZustandPanel" data-id="${escapeHtml(a.id)}" style="display:none; margin:8px 0 0 24px; padding:8px; background:#f7f4ee; border-radius:6px;">
      <div class="dp-hint" style="margin:0 0 6px 0;">Zustand je Artikel bei Rückgabe:</div>
      ${positionen.map(p=>`
      <div class="vlZustandPositionBlock" data-position-id="${escapeHtml(p.id)}" style="margin-bottom:10px; padding-bottom:8px; border-bottom:1px solid #e6e0d4;">
        <div style="font-size:0.82rem; font-weight:600; margin-bottom:4px;">${escapeHtml(p.artikel_name_snapshot || '(gelöschter Artikel)')} × ${p.anzahl}</div>
        <div style="display:flex; gap:4px; flex-wrap:wrap; margin-bottom:6px;">
          ${Object.entries(VL_ZUSTAND_LABEL).map(([wert,label])=>`<button type="button" class="btn ghost vlZustandChip" data-wert="${wert}" style="padding:4px 8px; font-size:0.78rem;">${label}</button>`).join('')}
        </div>
        <label style="font-size:0.82rem; display:block;">Schäden / Notiz zu diesem Artikel (optional)
          <textarea class="vlZustandNotizFeld" rows="2" style="width:100%; margin-top:2px; box-sizing:border-box; font-family:inherit;"></textarea>
        </label>
      </div>`).join('')}
      <div style="display:flex; gap:6px; margin-top:4px;">
        <button type="button" class="btn ghost vlZustandBestaetigenBtn" style="flex:1;">Bestätigen</button>
        <button type="button" class="btn ghost vlZustandAbbrechenBtn" style="flex:1;">Abbrechen</button>
      </div>
    </div>`;
    // Checkbox als ganz normales Inline-Element direkt vor dem Artikelnamen
    // (echter Dokumentfluss, keine absolute Positionierung mehr) — dadurch
    // sitzt sie zuverlässig "vor dem Text" statt ihn zu überlappen, und die
    // Folgezeilen (Zeitraum/Notiz/Status) werden per margin-left optisch
    // unter den Text statt unter die Checkbox eingerückt.
    return `
    <div class="card" style="margin-bottom:8px;" data-id="${escapeHtml(a.id)}">
      <input type="checkbox" class="vlAuswahlCheckbox" data-id="${escapeHtml(a.id)}" style="margin-right:8px; vertical-align:middle;" title="Für gemeinsamen Leihvertrag auswählen">
      <strong>${artikelText}</strong> — <span>${escapeHtml(a.entleiher_name)}</span>
      <div style="font-size:0.82rem; color:#7a7266; margin:4px 0 0 24px;">${escapeHtml(zeitraum)}${leihgebuehrInfo}${kautionInfo}</div>
      ${interneNotizAnzeige ? interneNotizAnzeige.replace('margin-top:2px;', 'margin-top:2px; margin-left:24px;') : ''}
      ${zustandAnzeige ? zustandAnzeige.replace('margin-top:2px;', 'margin-top:2px; margin-left:24px;') : ''}
      ${unterschriftAnzeige ? unterschriftAnzeige.replace('margin-top:2px;', 'margin-top:2px; margin-left:24px;') : ''}
      <div style="display:flex; gap:6px; align-items:center; margin-top:6px; margin-left:24px; flex-wrap:wrap;">
        <select class="vlStatusSelect" data-id="${escapeHtml(a.id)}" style="flex:1; min-width:0;">
          ${Object.entries(VL_STATUS_LABEL).map(([wert,label])=>`<option value="${wert}" ${a.status===wert?'selected':''}>${label}</option>`).join('')}
        </select>
        <button class="btn ghost vlBearbeitenBtn" data-id="${escapeHtml(a.id)}" style="padding:4px 8px; font-size:0.78rem; white-space:nowrap;">Bearbeiten</button>
        <button class="btn ghost vlLoeschenBtn" data-id="${escapeHtml(a.id)}" style="padding:4px 8px; font-size:0.78rem; white-space:nowrap;">Löschen</button>
      </div>
      ${zustandPanel}
    </div>`;
  };

  let html = '';
  if(ueberfaellig.length > 0){
    html += '<div class="dp-hint" style="margin:0 0 4px 0; color:var(--awo-red);">Überfällig (Bis-Datum bereits vorbei, noch nicht zurückgegeben):</div>';
    html += ueberfaellig.map(zeile).join('');
  }
  if(laufend.length > 0){
    html += '<div class="dp-hint" style="margin:8px 0 4px 0;">Laufend:</div>';
    html += laufend.map(zeile).join('');
  }
  if(kommend.length > 0){
    html += '<div class="dp-hint" style="margin:8px 0 4px 0;">Kommend:</div>';
    html += kommend.map(zeile).join('');
  }
  if(abgeschlossen.length > 0){
    html += `<details class="erledigt-fach" style="margin-top:8px;"><summary>Abgeschlossen/Storniert (${abgeschlossen.length})</summary>`;
    html += abgeschlossen.sort((a,b)=>b.bis_datum.localeCompare(a.bis_datum)).map(zeile).join('');
    html += '</details>';
  }
  if(!html) html = '<p style="color:#7a7266; margin:0;">Noch keine Ausleihen erfasst.</p>';
  listeEl.innerHTML = html;

  // Auswahl-Checkboxen: Set bleibt über ein Neuladen der Liste hinweg
  // erhalten (z.B. nach einem Statuswechsel), damit eine begonnene
  // Vertrags-Auswahl nicht verloren geht. IDs, die es nicht mehr gibt
  // (z.B. gelöschte Ausleihe), fallen beim nächsten Klick auf den
  // Vertrags-Button automatisch raus (Filter unten).
  listeEl.querySelectorAll('.vlAuswahlCheckbox').forEach(cb=>{
    cb.checked = vlAusgewaehlteIds.has(cb.dataset.id);
    cb.addEventListener('change', ()=>{
      if(cb.checked) vlAusgewaehlteIds.add(cb.dataset.id);
      else vlAusgewaehlteIds.delete(cb.dataset.id);
      vlAktualisiereVertragsButton();
    });
  });
  vlAktualisiereVertragsButton();

  listeEl.querySelectorAll('.vlStatusSelect').forEach(sel=>{
    sel.addEventListener('change', async ()=>{
      const a = vlAusleihenCache.find(x=>x.id===sel.dataset.id);
      if(!a) return;
      const neuerStatus = sel.value;
      if(neuerStatus === 'zurueckgegeben' && a.status !== 'zurueckgegeben'){
        // Zustand/Notiz per Klick-Panel statt Browser-Prompt erfassen —
        // Select bleibt bis zum Bestätigen/Abbrechen unverändert stehen.
        vlOeffneZustandPanel(a.id, neuerStatus);
        return;
      }
      sel.disabled = true;
      try{
        await epCallOhneAktion({action:'admin_verleih_ausleihe_status_setzen', pass: currentAuthPass, id: a.id, status: neuerStatus});
        await ladeVlAusleihen();
      }catch(e){
        alert('Status konnte nicht geändert werden: '+e.message);
        sel.disabled = false;
        sel.value = a.status;
      }
    });
  });
  listeEl.querySelectorAll('.vlZustandBearbeitenLink').forEach(link=>{
    link.addEventListener('click', (ev)=>{
      ev.preventDefault();
      vlOeffneZustandPanel(link.dataset.id, 'zurueckgegeben');
    });
  });
  // Versand eines bereits digital unterschriebenen Vertrags (erneut oder
  // erstmalig, falls beim Unterschreiben keine E-Mail angegeben wurde) —
  // schlankes prompt() reicht hier, da nur eine einzelne Adresse
  // abgefragt wird und dies ein seltener Korrektur-/Nachtrags-Fall ist.
  listeEl.querySelectorAll('.vlVertragEmailLink').forEach(link=>{
    link.addEventListener('click', async (ev)=>{
      ev.preventDefault();
      const id = link.dataset.id;
      const a = vlAusleihenCache.find(x=>x.id===id);
      if(!a) return;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const vorschlag = a.vertrag_email_adresse || (emailRegex.test(a.entleiher_kontakt||'') ? a.entleiher_kontakt.trim() : '');
      const email = (await eingabe('An welche E-Mail-Adresse soll der unterschriebene Leihvertrag gesendet werden?', vorschlag || ''));
      if(!email) return;
      if(!emailRegex.test(email.trim())){ alert('Das ist keine gültige E-Mail-Adresse.'); return; }
      link.textContent = '… wird gesendet';
      try{
        const doc = await baueLeihvertragPDF([a]);
        const pdfBase64 = doc.output('datauristring').split(',')[1];
        const dateiSicherName = (a.entleiher_name || 'Entleiher').replace(/[^\p{L}\p{N}]+/gu, '_');
        await epCallOhneAktion({
          action:'admin_verleih_ausleihe_vertrag_per_email', pass: currentAuthPass,
          ids:[a.id], empfaengerEmail: email.trim(), entleiherName: a.entleiher_name,
          pdfBase64, dateiname:`Leihvertrag_${dateiSicherName}_${stamp()}.pdf`,
        });
        await ladeVlAusleihen();
      }catch(e){
        alert('Versand fehlgeschlagen: '+e.message);
        link.textContent = '📧 per E-Mail senden';
      }
    });
  });
  listeEl.querySelectorAll('.vlZustandChip').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const block = btn.closest('.vlZustandPositionBlock');
      block.dataset.zustand = btn.dataset.wert;
      block.querySelectorAll('.vlZustandChip').forEach(b=>{
        const aktiv = b === btn;
        b.style.background = aktiv ? 'var(--green)' : '';
        b.style.color = aktiv ? '#fff' : '';
      });
    });
  });
  listeEl.querySelectorAll('.vlZustandBestaetigenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const panel = btn.closest('.vlZustandPanel');
      const id = panel.dataset.id;
      const a = vlAusleihenCache.find(x=>x.id===id);
      if(!a) return;
      const statusZuSetzen = panel.dataset.statusZuSetzen || a.status;
      // Zustand/Notiz je Position einsammeln (Migration 75).
      const positionenPayload = Array.from(panel.querySelectorAll('.vlZustandPositionBlock')).map(block=>({
        id: block.dataset.positionId,
        rueckgabeZustand: block.dataset.zustand || '',
        rueckgabeNotiz: block.querySelector('.vlZustandNotizFeld').value.trim(),
      }));
      btn.disabled = true;
      try{
        await epCallOhneAktion({
          action:'admin_verleih_ausleihe_status_setzen', pass: currentAuthPass, id,
          status: statusZuSetzen, positionen: positionenPayload,
        });
        await ladeVlAusleihen();
      }catch(e){
        alert('Konnte nicht gespeichert werden: '+e.message);
        btn.disabled = false;
      }
    });
  });
  listeEl.querySelectorAll('.vlZustandAbbrechenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const panel = btn.closest('.vlZustandPanel');
      panel.style.display = 'none';
      const id = panel.dataset.id;
      const a = vlAusleihenCache.find(x=>x.id===id);
      const sel = listeEl.querySelector(`.vlStatusSelect[data-id="${CSS.escape(id)}"]`);
      if(sel && a) sel.value = a.status;
    });
  });
  listeEl.querySelectorAll('.vlBearbeitenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const a = vlAusleihenCache.find(x=>x.id===btn.dataset.id);
      if(!a) return;
      document.getElementById('vlBearbeiteId').value = a.id;
      const positionenText = (a.positionen||[]).map(p=>p.artikel_name_snapshot).join(', ');
      document.getElementById('vlFormueberschrift').textContent = `Ausleihe bearbeiten (${positionenText}):`;
      vlAktuellePositionen = (a.positionen && a.positionen.length > 0)
        ? a.positionen.map(p=>({artikelId: p.artikel_id || '', anzahl: p.anzahl}))
        : [{artikelId:'', anzahl:1}];
      vlRenderPositionenListe();
      document.getElementById('vlEntleiherName').value = a.entleiher_name;
      document.getElementById('vlEntleiherKontakt').value = a.entleiher_kontakt || '';
      document.getElementById('vlEntleiherAnschrift').value = a.entleiher_anschrift || '';
      document.getElementById('vlInterneNotiz').value = a.interne_notiz || '';
      document.getElementById('vlVonDatum').value = a.von_datum;
      document.getElementById('vlBisDatum').value = a.bis_datum;
      document.getElementById('vlAktionAuswahl').value = a.aktion_id || '';
      document.getElementById('vlKautionBetrag').value = a.kaution_betrag != null ? a.kaution_betrag : '';
      document.getElementById('vlKautionBezahlt').checked = !!a.kaution_bezahlt;
      document.getElementById('vlKautionErstattet').checked = !!a.kaution_erstattet;
      document.getElementById('vlLeihgebuehrBetrag').value = a.leihgebuehr_betrag != null ? a.leihgebuehr_betrag : '';
      document.getElementById('vlLeihgebuehrBezahlt').checked = !!a.leihgebuehr_bezahlt;
      // vlReduzierterSatz ist reine Ausfüllhilfe für die Berechnung, keine
      // gespeicherte Eigenschaft der Ausleihe — beim Bearbeiten daher immer
      // zurückgesetzt, unabhängig davon, mit welchem Satz der bestehende
      // leihgebuehr_betrag ursprünglich berechnet wurde.
      document.getElementById('vlReduzierterSatz').checked = false;
      document.getElementById('vlGebuehrBerechnenStatus').textContent = '';
      document.getElementById('vlStatus').textContent = '';
      document.getElementById('vlFormularContainer').style.display = 'block';
      document.getElementById('vlPositionenListe').scrollIntoView({behavior:'smooth', block:'center'});
    });
  });
  listeEl.querySelectorAll('.vlLoeschenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const a = vlAusleihenCache.find(x=>x.id===btn.dataset.id);
      if(!a) return;
      const positionenText = (a.positionen||[]).map(p=>p.artikel_name_snapshot).join(', ');
      if(!(await bestaetigen(`Ausleihe "${positionenText}" an ${a.entleiher_name} wirklich löschen? Für abgesagte/stornierte Ausleihen besser den Status "Storniert" wählen, statt zu löschen.`))) return;
      try{
        await epCallOhneAktion({action:'admin_verleih_ausleihe_loeschen', pass: currentAuthPass, id: a.id});
        await ladeVlAusleihen();
      }catch(e){
        alert('Konnte nicht gelöscht werden: '+e.message);
      }
    });
  });
}

function vlFormularZuruecksetzen(){
  document.getElementById('vlBearbeiteId').value = '';
  document.getElementById('vlFormueberschrift').textContent = 'Neue Ausleihe erfassen:';
  vlAktuellePositionen = [{artikelId:'', anzahl:1}];
  vlRenderPositionenListe();
  document.getElementById('vlEntleiherName').value = '';
  document.getElementById('vlEntleiherKontakt').value = '';
  document.getElementById('vlEntleiherAnschrift').value = '';
  document.getElementById('vlInterneNotiz').value = '';
  document.getElementById('vlVonDatum').value = '';
  document.getElementById('vlBisDatum').value = '';
  document.getElementById('vlAktionAuswahl').value = '';
  document.getElementById('vlKautionBetrag').value = '';
  document.getElementById('vlKautionBezahlt').checked = false;
  document.getElementById('vlKautionErstattet').checked = false;
  document.getElementById('vlLeihgebuehrBetrag').value = '';
  document.getElementById('vlLeihgebuehrBezahlt').checked = false;
  document.getElementById('vlReduzierterSatz').checked = false;
  document.getElementById('vlGebuehrBerechnenStatus').textContent = '';
  document.getElementById('vlStatus').textContent = '';
}

document.getElementById('vlSpeichernBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('vlStatus');
  const id = document.getElementById('vlBearbeiteId').value || undefined;
  const entleiherName = document.getElementById('vlEntleiherName').value.trim();
  const entleiherKontakt = document.getElementById('vlEntleiherKontakt').value.trim();
  const entleiherAnschrift = document.getElementById('vlEntleiherAnschrift').value.trim();
  const interneNotiz = document.getElementById('vlInterneNotiz').value.trim();
  const vonDatum = document.getElementById('vlVonDatum').value;
  const bisDatum = document.getElementById('vlBisDatum').value;
  const aktionId = document.getElementById('vlAktionAuswahl').value || undefined;
  const kautionRoh = document.getElementById('vlKautionBetrag').value;
  const kautionBetrag = kautionRoh === '' ? null : Number(kautionRoh);
  const kautionBezahlt = document.getElementById('vlKautionBezahlt').checked;
  const kautionErstattet = document.getElementById('vlKautionErstattet').checked;
  const leihgebuehrRoh = document.getElementById('vlLeihgebuehrBetrag').value;
  const leihgebuehrBetrag = leihgebuehrRoh === '' ? null : Number(leihgebuehrRoh);
  const leihgebuehrBezahlt = document.getElementById('vlLeihgebuehrBezahlt').checked;

  const positionen = vlAktuellePositionen
    .filter(p=>p.artikelId)
    .map(p=>({artikelId: p.artikelId, anzahl: Number(p.anzahl)}));
  if(positionen.length === 0){ statusEl.textContent = '⚠️ Bitte mindestens einen Artikel auswählen.'; return; }
  if(positionen.some(p=>!Number.isInteger(p.anzahl) || p.anzahl < 1)){ statusEl.textContent = '⚠️ Ungültige Anzahl bei mindestens einem Artikel.'; return; }
  if(!entleiherName){ statusEl.textContent = '⚠️ Bitte einen Namen des Entleihers angeben.'; return; }
  if(!vonDatum || !bisDatum){ statusEl.textContent = '⚠️ Bitte Von- und Bis-Datum angeben.'; return; }
  if(bisDatum < vonDatum){ statusEl.textContent = '⚠️ Bis-Datum muss nach dem Von-Datum liegen.'; return; }

  try{
    const json = await epCallOhneAktion({
      action:'admin_verleih_ausleihe_speichern', pass: currentAuthPass, id,
      positionen, entleiherName, entleiherKontakt, entleiherAnschrift, interneNotiz, vonDatum, bisDatum, aktionId,
      kautionBetrag, kautionBezahlt, kautionErstattet, leihgebuehrBetrag, leihgebuehrBezahlt,
    });
    vlFormularZuruecksetzen();
    document.getElementById('vlFormularContainer').style.display = 'none';
    await ladeVlAusleihen();
    if(json.warnung) alert('✓ Gespeichert. ⚠️ '+json.warnung);
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
  }
});
document.getElementById('vlAbbrechenBtn').addEventListener('click', ()=>{
  vlFormularZuruecksetzen();
  document.getElementById('vlFormularContainer').style.display = 'none';
});
document.getElementById('vlNeueAusleiheBtn').addEventListener('click', ()=>{
  vlFormularZuruecksetzen();
  document.getElementById('vlFormularContainer').style.display = 'block';
  document.getElementById('vlEntleiherName').scrollIntoView({behavior:'smooth', block:'center'});
});
document.getElementById('vlArtikelToggleBtn').addEventListener('click', ()=>{
  const c = document.getElementById('vlArtikelContainer');
  c.style.display = (c.style.display === 'none') ? 'block' : 'none';
  if(c.style.display === 'block') c.scrollIntoView({behavior:'smooth', block:'start'});
});

// ================================================================
// SITZUNGEN (Migration 55) — Sitzungsplanung mit Einladungen an
// Teamende UND/ODER Mitglieder (neue, eigene Personengruppe ohne
// Team-Rolle). Freischaltung für die Sitzungsplanung ist EINMALIG pro
// Person (nicht pro Sitzung), siehe Unter-Tab "Zugriff".
// ================================================================
let sitzZugriffCache = {team:[], mitglieder:[]};
let mgCache = [];
let sitzSitzungenCache = [];
let sitzAusgewaehlteEinladungen = new Set(); // Set von "typ:id"

async function renderVwSitzungen(){
  if(!isAdmin()) return;
  const listeTabBtn = document.querySelector('.sitzUnterTabBtn[data-tab="liste"]');
  if(listeTabBtn) listeTabBtn.click();
  document.getElementById('sitzFormularContainer').style.display = 'none';
  sitzFormularZuruecksetzen();
  await Promise.all([ladeSitzZugriff(), ladeMgListe()]);
  renderSitzEinladenListe();
  await ladeSitzungenListe();
}

// ---------- Zugriff (Team + Mitglieder kombiniert) ----------
async function ladeSitzZugriff(){
  const teamEl = document.getElementById('szTeamListe');
  const mgEl = document.getElementById('szMitgliederListe');
  teamEl.textContent = 'Lädt…'; mgEl.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_sitzungszugriff_liste', pass: currentAuthPass});
    sitzZugriffCache = {team: json.team||[], mitglieder: json.mitglieder||[]};
  }catch(e){
    teamEl.innerHTML = '⚠️ Fehler: '+escapeHtml(e.message); mgEl.textContent=''; return;
  }
  const zeile = (typ, p)=>`
    <label style="display:flex; align-items:center; gap:8px; padding:4px 0; border-bottom:1px solid #e5ddd0; font-size:0.85rem;">
      <input type="checkbox" class="szToggle" data-typ="${typ}" data-id="${escapeHtml(p.id)}" ${p.freigeschaltet?'checked':''}>
      <span>${escapeHtml(p.name)}</span>
    </label>`;
  teamEl.innerHTML = sitzZugriffCache.team.length>0 ? sitzZugriffCache.team.map(p=>zeile('team',p)).join('') : '<p style="color:#7a7266; margin:0;">Keine Teamenden in der Kartei.</p>';
  mgEl.innerHTML = sitzZugriffCache.mitglieder.length>0 ? sitzZugriffCache.mitglieder.map(p=>zeile('mitglied',p)).join('') : '<p style="color:#7a7266; margin:0;">Noch keine Mitglieder angelegt (siehe Tab "Mitglieder").</p>';
  document.querySelectorAll('.szToggle').forEach(cb=>{
    cb.addEventListener('change', async ()=>{
      cb.disabled = true;
      try{
        await epCallOhneAktion({action:'admin_sitzungszugriff_setzen', pass: currentAuthPass, teilnehmerTyp: cb.dataset.typ, teilnehmerId: cb.dataset.id, freigeschaltet: cb.checked});
        await ladeSitzZugriff();
        renderSitzEinladenListe();
      }catch(e){
        alert('Konnte nicht geändert werden: '+e.message);
        cb.checked = !cb.checked;
        cb.disabled = false;
      }
    });
  });
}

// ---------- Mitglieder (eigene Personengruppe) ----------
async function ladeMgListe(){
  const el = document.getElementById('mgListe');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_mitglieder_liste', pass: currentAuthPass});
    mgCache = json.mitglieder || [];
  }catch(e){
    el.innerHTML = '⚠️ Fehler: '+escapeHtml(e.message); return;
  }
  if(mgCache.length===0){ el.innerHTML = '<p style="color:#7a7266; margin:0;">Noch keine Mitglieder angelegt.</p>'; return; }
  el.innerHTML = mgCache.map(m=>`
    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:4px 0; border-bottom:1px solid #e5ddd0; font-size:0.85rem;">
      <span>${escapeHtml(m.name)}${m.ist_vorstand ? ' <span style="color:#7a7266;">★ Vorstand</span>' : ''}<br><span style="color:#7a7266; font-size:0.8rem;">${escapeHtml(m.email)}${m.pin_hash ? ' · PIN gesetzt' : ' · noch keine PIN'}</span></span>
      <span style="display:flex; gap:6px; white-space:nowrap; flex-wrap:wrap;">
        <button class="btn ghost mgBearbeitenBtn" data-id="${escapeHtml(m.id)}" style="padding:2px 8px; font-size:0.78rem;">Bearbeiten</button>
        ${m.pin_hash ? `<button class="btn ghost mgPinResetBtn" data-id="${escapeHtml(m.id)}" style="padding:2px 8px; font-size:0.78rem;">PIN zurücksetzen</button>` : ''}
        <button class="btn ghost mgLoeschenBtn" data-id="${escapeHtml(m.id)}" style="padding:2px 8px; font-size:0.78rem;">Löschen</button>
      </span>
    </div>
  `).join('');
  el.querySelectorAll('.mgBearbeitenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const m = mgCache.find(x=>x.id===btn.dataset.id);
      if(!m) return;
      document.getElementById('mgBearbeiteId').value = m.id;
      document.getElementById('mgName').value = m.name;
      document.getElementById('mgEmail').value = m.email;
      document.getElementById('mgIstVorstand').checked = !!m.ist_vorstand;
      document.getElementById('mgAbbrechenBtn').style.display = 'block';
      document.getElementById('mgStatus').textContent = '';
    });
  });
  el.querySelectorAll('.mgPinResetBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      if(!(await bestaetigen('PIN dieses Mitglieds wirklich zurücksetzen?'))) return;
      try{
        await epCallOhneAktion({action:'admin_mitglied_pin_zuruecksetzen', pass: currentAuthPass, id: btn.dataset.id});
        await ladeMgListe();
      }catch(e){ alert('Fehler: '+e.message); }
    });
  });
  el.querySelectorAll('.mgLoeschenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const m = mgCache.find(x=>x.id===btn.dataset.id);
      if(!m) return;
      if(!(await bestaetigen(`Mitglied "${m.name}" wirklich löschen? Bereits verschickte Einladungen bleiben als Eintrag erhalten.`))) return;
      try{
        await epCallOhneAktion({action:'admin_mitglied_loeschen', pass: currentAuthPass, id: m.id});
        await ladeMgListe();
        await ladeSitzZugriff();
        renderSitzEinladenListe();
      }catch(e){ alert('Fehler: '+e.message); }
    });
  });
}
document.getElementById('mgSpeichernBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('mgStatus');
  const id = document.getElementById('mgBearbeiteId').value || undefined;
  const name = document.getElementById('mgName').value.trim();
  const email = document.getElementById('mgEmail').value.trim();
  const istVorstand = document.getElementById('mgIstVorstand').checked;
  if(!name){ statusEl.textContent = '⚠️ Bitte einen Namen angeben.'; return; }
  if(!email.includes('@')){ statusEl.textContent = '⚠️ Bitte eine gültige E-Mail angeben.'; return; }
  try{
    await epCallOhneAktion({action:'admin_mitglied_speichern', pass: currentAuthPass, id, name, email, istVorstand});
    document.getElementById('mgBearbeiteId').value = '';
    document.getElementById('mgName').value = '';
    document.getElementById('mgEmail').value = '';
    document.getElementById('mgIstVorstand').checked = false;
    document.getElementById('mgAbbrechenBtn').style.display = 'none';
    statusEl.textContent = '✓ Gespeichert.';
    await ladeMgListe();
    await ladeSitzZugriff();
    renderSitzEinladenListe();
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
  }
});
document.getElementById('mgAbbrechenBtn').addEventListener('click', ()=>{
  document.getElementById('mgBearbeiteId').value = '';
  document.getElementById('mgName').value = '';
  document.getElementById('mgEmail').value = '';
  document.getElementById('mgIstVorstand').checked = false;
  document.getElementById('mgAbbrechenBtn').style.display = 'none';
  document.getElementById('mgStatus').textContent = '';
});

// ---------- Einladen-Checkliste im Sitzungs-Formular ----------
function renderSitzEinladenListe(){
  const el = document.getElementById('sitzEinladenListe');
  const freiTeam = sitzZugriffCache.team.filter(p=>p.freigeschaltet);
  const freiMg = sitzZugriffCache.mitglieder.filter(p=>p.freigeschaltet);
  if(freiTeam.length===0 && freiMg.length===0){
    el.innerHTML = '<p style="color:#7a7266; margin:0; font-size:0.85rem;">Noch niemand für die Sitzungsplanung freigeschaltet (siehe Tab "Zugriff").</p>';
    return;
  }
  const zeile = (typ,p)=>{
    const key = typ+':'+p.id;
    return `<label style="display:flex; align-items:center; gap:8px; padding:3px 0; font-size:0.85rem;">
      <input type="checkbox" class="sitzEinladenCheckbox" data-key="${escapeHtml(key)}" ${sitzAusgewaehlteEinladungen.has(key)?'checked':''}>
      <span>${escapeHtml(p.name)} <span style="color:#7a7266; font-size:0.78rem;">(${typ==='team'?'Team':'Mitglied'})</span></span>
    </label>`;
  };
  el.innerHTML = [...freiTeam.map(p=>zeile('team',p)), ...freiMg.map(p=>zeile('mitglied',p))].join('');
  el.querySelectorAll('.sitzEinladenCheckbox').forEach(cb=>{
    cb.addEventListener('change', ()=>{
      if(cb.checked) sitzAusgewaehlteEinladungen.add(cb.dataset.key);
      else sitzAusgewaehlteEinladungen.delete(cb.dataset.key);
    });
  });
}

function isoZuDatetimeLocal(iso){
  const d = new Date(iso);
  const pad = n=>String(n).padStart(2,'0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

// ---------- Sitzungen (Liste + Formular) ----------
async function ladeSitzungenListe(){
  const el = document.getElementById('vwSitzungenListe');
  el.textContent = 'Lädt…';
  try{
    const json = await epCallOhneAktion({action:'admin_sitzungen_liste', pass: currentAuthPass});
    sitzSitzungenCache = json.sitzungen || [];
  }catch(e){
    el.innerHTML = '<div class="dp-hint">⚠️ Fehler: '+escapeHtml(e.message)+'</div>';
    return;
  }
  if(sitzSitzungenCache.length===0){
    el.innerHTML = '<p style="color:#7a7266; margin:0;">Noch keine Sitzungen geplant.</p>';
    return;
  }
  const fmt = iso=>new Date(iso).toLocaleString('de-DE', {weekday:'short', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'});

  const zeile = s=>{
    const einladungen = s.einladungen || [];
    const zusagen = einladungen.filter(e=>e.antwort==='zusage').length;
    const absagen = einladungen.filter(e=>e.antwort==='absage').length;
    const offen = einladungen.filter(e=>e.antwort==='offen').length;
    const teilnehmerZeilen = einladungen.map(e=>{
      const badge = e.antwort==='zusage' ? '✅' : e.antwort==='absage' ? '❌' : '⏳';
      return `${badge} ${escapeHtml(e.teilnehmer_name_snapshot)}`;
    }).join('<br>');
    return `
    <div class="card" style="margin-bottom:8px; ${s.status==='abgesagt'?'opacity:0.6;':''}" data-id="${escapeHtml(s.id)}">
      <strong>${escapeHtml(s.titel)}</strong>${s.status==='abgesagt' ? ' <span class="tag">abgesagt</span>' : ''}
      <div style="font-size:0.82rem; color:#7a7266; margin:4px 0;">${escapeHtml(fmt(s.beginn))}${s.ende ? ' – ' + escapeHtml(new Date(s.ende).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})) + ' Uhr' : ' Uhr'}${s.ort ? ' · ' + escapeHtml(s.ort) : ''}${s.tagesordnung_pdf_dateiname ? ' · 📎 Tagesordnung' : ''}${s.protokoll_pdf_dateiname ? ' · 📎 Protokoll' : ''}</div>
      ${einladungen.length>0 ? `<div style="font-size:0.8rem; color:#7a7266; margin-bottom:4px;">${zusagen} Zusage(n), ${absagen} Absage(n), ${offen} offen</div><details><summary style="font-size:0.8rem; cursor:pointer;">Teilnehmer (${einladungen.length})</summary><div style="font-size:0.82rem; margin-top:4px;">${teilnehmerZeilen}</div></details>` : '<div style="font-size:0.8rem; color:#7a7266;">Niemand eingeladen</div>'}
      <div style="display:flex; gap:6px; margin-top:8px; flex-wrap:wrap;">
        <button class="btn ghost sitzEinladenSendenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">📧 Einladungen senden</button>
        <button class="btn ghost sitzWordExportBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">⬇ Einladung als Word</button>
        ${s.tagesordnung_pdf_dateiname ? `<button class="btn ghost sitzPdfAnsehenListenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">📎 Tagesordnung ansehen</button>` : ''}
        <button class="btn ghost sitzBearbeitenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">Bearbeiten</button>
        <button class="btn ghost sitzLoeschenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">Löschen</button>
      </div>
      <div style="display:flex; gap:6px; margin-top:6px; flex-wrap:wrap; border-top:1px solid #e5ddd0; padding-top:6px;">
        <button class="btn ghost sitzProtokollSendenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">📧 Protokoll senden</button>
        <button class="btn ghost sitzProtokollWordExportBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">⬇ Protokoll als Word</button>
        ${s.protokoll_pdf_dateiname ? `<button class="btn ghost sitzProtokollPdfAnsehenListenBtn" data-id="${escapeHtml(s.id)}" style="padding:4px 8px; font-size:0.78rem;">📎 Protokoll ansehen</button>` : ''}
      </div>
      ${s.benachrichtigt_am ? `<div style="font-size:0.75rem; color:#7a7266; margin-top:4px;">Einladung zuletzt verschickt: ${escapeHtml(fmt(s.benachrichtigt_am))}</div>` : ''}
      ${s.protokoll_versendet_am ? `<div style="font-size:0.75rem; color:#7a7266; margin-top:2px;">Protokoll zuletzt verschickt: ${escapeHtml(fmt(s.protokoll_versendet_am))}</div>` : ''}
    </div>`;
  };

  // Gruppierung analog zum Verleih-Bereich (Überfällig/Laufend/Kommend/
  // Abgeschlossen): Anstehend und "Vergangen, Protokoll offen" bleiben
  // aufgeklappt sichtbar (letztere bewusst hervorgehoben, damit nichts
  // vergessen wird), Abgeschlossen und Abgesagt sind eingeklappt.
  // "Protokoll erfasst" wird heuristisch daran erkannt, ob Anwesende
  // eingetragen oder ein Protokoll-PDF hinterlegt ist — es gibt kein
  // eigenes "fertig"-Flag, um keine zusätzliche Migration zu brauchen.
  const jetzt = new Date();
  const istProtokollErfasst = s => !!((s.protokoll_anwesende && s.protokoll_anwesende.trim()) || s.protokoll_pdf_dateiname);
  const abgesagt = sitzSitzungenCache.filter(s=>s.status==='abgesagt').sort((a,b)=>(b.beginn||'').localeCompare(a.beginn||''));
  const rest = sitzSitzungenCache.filter(s=>s.status!=='abgesagt');
  const anstehend = rest.filter(s=>new Date(s.beginn) > jetzt).sort((a,b)=>(a.beginn||'').localeCompare(b.beginn||''));
  const vergangen = rest.filter(s=>new Date(s.beginn) <= jetzt);
  const protokollOffen = vergangen.filter(s=>!istProtokollErfasst(s)).sort((a,b)=>(b.beginn||'').localeCompare(a.beginn||''));
  const abgeschlossen = vergangen.filter(istProtokollErfasst).sort((a,b)=>(b.beginn||'').localeCompare(a.beginn||''));

  let html = '';
  if(anstehend.length > 0){
    html += '<div class="dp-hint" style="margin:0 0 4px 0;">Anstehend:</div>';
    html += anstehend.map(zeile).join('');
  }
  if(protokollOffen.length > 0){
    html += '<div class="dp-hint" style="margin:8px 0 4px 0; color:var(--awo-red);">Vergangen, Protokoll noch offen:</div>';
    html += protokollOffen.map(zeile).join('');
  }
  if(abgeschlossen.length > 0){
    html += `<details class="erledigt-fach" style="margin-top:8px;"><summary>Abgeschlossen (${abgeschlossen.length})</summary>`;
    html += abgeschlossen.map(zeile).join('');
    html += '</details>';
  }
  if(abgesagt.length > 0){
    html += `<details class="erledigt-fach" style="margin-top:8px;"><summary>Abgesagt (${abgesagt.length})</summary>`;
    html += abgesagt.map(zeile).join('');
    html += '</details>';
  }
  if(!html) html = '<p style="color:#7a7266; margin:0;">Noch keine Sitzungen geplant.</p>';
  el.innerHTML = html;

  el.querySelectorAll('.sitzEinladenSendenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      if(!(await bestaetigen('Einladungen (per E-Mail) an alle Eingeladenen mit hinterlegter E-Mail verschicken?'))) return;
      btn.disabled = true;
      try{
        const json = await epCallOhneAktion({action:'admin_sitzung_einladungen_senden', pass: currentAuthPass, id: btn.dataset.id});
        alert(`Versendet an ${json.versendet} Empfänger.`);
        await ladeSitzungenListe();
      }catch(e){
        alert('Fehler: '+e.message);
      }finally{
        btn.disabled = false;
      }
    });
  });
  el.querySelectorAll('.sitzProtokollSendenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      if(!(await bestaetigen('Protokoll (per E-Mail) an alle Eingeladenen mit hinterlegter E-Mail verschicken?'))) return;
      btn.disabled = true;
      try{
        const json = await epCallOhneAktion({action:'admin_sitzung_protokoll_senden', pass: currentAuthPass, id: btn.dataset.id});
        alert(`Versendet an ${json.versendet} Empfänger.`);
        await ladeSitzungenListe();
      }catch(e){
        alert('Fehler: '+e.message);
      }finally{
        btn.disabled = false;
      }
    });
  });
  el.querySelectorAll('.sitzBearbeitenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const s = sitzSitzungenCache.find(x=>x.id===btn.dataset.id);
      if(!s) return;
      sitzFormularBefuellen(s);
      document.getElementById('sitzFormularContainer').style.display = 'block';
      document.getElementById('sitzTitel').scrollIntoView({behavior:'smooth', block:'center'});
    });
  });
  el.querySelectorAll('.sitzWordExportBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const s = sitzSitzungenCache.find(x=>x.id===btn.dataset.id);
      if(!s) return;
      exportiereSitzungAlsWord(s);
    });
  });
  el.querySelectorAll('.sitzProtokollWordExportBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const s = sitzSitzungenCache.find(x=>x.id===btn.dataset.id);
      if(!s) return;
      exportiereSitzungAlsProtokollWord(s);
    });
  });
  el.querySelectorAll('.sitzPdfAnsehenListenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>sitzPdfOeffnen(btn.dataset.id, undefined, undefined, 'tagesordnung'));
  });
  el.querySelectorAll('.sitzProtokollPdfAnsehenListenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>sitzPdfOeffnen(btn.dataset.id, undefined, undefined, 'protokoll'));
  });
  el.querySelectorAll('.sitzLoeschenBtn').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const s = sitzSitzungenCache.find(x=>x.id===btn.dataset.id);
      if(!s) return;
      if(!(await bestaetigen(`Sitzung "${s.titel}" wirklich löschen?`))) return;
      try{
        await epCallOhneAktion({action:'admin_sitzung_loeschen', pass: currentAuthPass, id: s.id});
        await ladeSitzungenListe();
      }catch(e){ alert('Fehler: '+e.message); }
    });
  });
}

// ---------- Tagesordnungspunkte: {text, notiz} pro TOP (Migration 57) ----------
// "text" = inhaltlicher TOP (vor der Sitzung), "notiz" = Protokoll-Notiz
// dazu (nach der Sitzung ergänzt, bleibt bis dahin leer).
let sitzAktuelleTops = [];

function sitzRenderTopListe(){
  const el = document.getElementById('sitzTopListe');
  el.innerHTML = sitzAktuelleTops.map((top, idx)=>`
    <div style="border:1px solid #e5ddd0; border-radius:8px; padding:6px; margin-top:${idx===0?'0':'6px'};">
      <div style="display:flex; gap:6px; align-items:center;">
        <input type="text" class="sitzTopTextInput" data-idx="${idx}" value="${escapeHtml(top.text)}" placeholder="z.B. Projekte" style="flex:1; box-sizing:border-box;">
        <button type="button" class="btn ghost sitzTopEntfernenBtn" data-idx="${idx}" style="padding:4px 8px; font-size:0.9rem;">✕</button>
      </div>
      <input type="text" class="sitzTopNotizInput" data-idx="${idx}" value="${escapeHtml(top.notiz||'')}" placeholder="Protokoll-Notiz (optional, nach der Sitzung)" style="width:100%; margin-top:4px; box-sizing:border-box; font-size:0.85rem; color:#5a5248;">
    </div>
  `).join('');
  el.querySelectorAll('.sitzTopTextInput').forEach(inp=>{
    inp.addEventListener('input', ()=>{ sitzAktuelleTops[Number(inp.dataset.idx)].text = inp.value; });
  });
  el.querySelectorAll('.sitzTopNotizInput').forEach(inp=>{
    inp.addEventListener('input', ()=>{ sitzAktuelleTops[Number(inp.dataset.idx)].notiz = inp.value; });
  });
  el.querySelectorAll('.sitzTopEntfernenBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      sitzAktuelleTops.splice(Number(btn.dataset.idx), 1);
      sitzRenderTopListe();
    });
  });
}
document.getElementById('sitzTopHinzufuegenBtn').addEventListener('click', ()=>{
  sitzAktuelleTops.push({text:'', notiz:''});
  sitzRenderTopListe();
});

// ---------- PDF-Anhänge (Migration 56/57) — generisch für "art":
// 'tagesordnung' (Standard) ODER 'protokoll', jeweils eigene DOM-Elemente ----------
const SITZ_PDF_ELEMENTE = {
  tagesordnung: {aktuell:'sitzPdfAktuell', datei:'sitzPdfDatei', hochladen:'sitzPdfHochladenBtn', status:'sitzPdfStatus'},
  protokoll: {aktuell:'sitzProtokollPdfAktuell', datei:'sitzProtokollPdfDatei', hochladen:'sitzProtokollPdfHochladenBtn', status:'sitzProtokollPdfStatus'},
};

function sitzPdfAnzeigeAktualisieren(s, art){
  const ids = SITZ_PDF_ELEMENTE[art];
  const el = document.getElementById(ids.aktuell);
  const uploadBtn = document.getElementById(ids.hochladen);
  const dateinameFeld = art === 'protokoll' ? 'protokoll_pdf_dateiname' : 'tagesordnung_pdf_dateiname';
  if(s && s.id){
    uploadBtn.disabled = false;
    uploadBtn.textContent = '📎 Hochladen';
    if(s[dateinameFeld]){
      el.innerHTML = `Aktuell: ${escapeHtml(s[dateinameFeld])} — <button type="button" class="btn ghost sitzPdfAnsehenFormularBtn" style="padding:2px 6px; font-size:0.78rem;">Ansehen</button> <button type="button" class="btn ghost sitzPdfEntfernenFormularBtn" style="padding:2px 6px; font-size:0.78rem;">Entfernen</button>`;
      el.querySelector('.sitzPdfAnsehenFormularBtn').addEventListener('click', ()=>sitzPdfOeffnen(s.id, undefined, undefined, art));
      el.querySelector('.sitzPdfEntfernenFormularBtn').addEventListener('click', async ()=>{
        if(!(await bestaetigen('Anhang wirklich entfernen?'))) return;
        try{
          await epCallOhneAktion({action:'admin_sitzung_pdf_entfernen', pass: currentAuthPass, id: s.id, art});
          await ladeSitzungenListe();
          sitzPdfAnzeigeAktualisieren(sitzSitzungenCache.find(x=>x.id===s.id), art);
        }catch(e){ alert('Fehler: '+e.message); }
      });
    } else {
      el.textContent = 'Kein Anhang hinterlegt.';
    }
  } else {
    uploadBtn.disabled = true;
    uploadBtn.textContent = '📎 Hochladen (erst nach dem ersten Speichern möglich)';
    el.textContent = '';
  }
}

// sitzPdfOeffnen: OHNE teilnehmerTyp -> Admin-Pfad (checkAdminAuthGebremst
// erkennt admin/team über currentAuthPass); MIT teilnehmerTyp -> Team-/
// Mitglied-Pfad (prüft zusätzlich, ob eine eigene Einladung existiert).
// "art": 'tagesordnung' (Standard) oder 'protokoll'.
async function sitzPdfOeffnen(sitzungId, teilnehmerTyp, teilnehmerId, art){
  try{
    const payload = {action:'sitzung_pdf_link', pass: currentAuthPass, id: sitzungId, art: art || 'tagesordnung'};
    if(teilnehmerTyp){ payload.teilnehmerTyp = teilnehmerTyp; payload.teilnehmerId = teilnehmerId; }
    const json = await epCallOhneAktion(payload);
    window.open(json.url, '_blank');
  }catch(e){
    alert('Anhang konnte nicht geöffnet werden: '+e.message);
  }
}

function sitzPdfUploadHandlerRegistrieren(art){
  const ids = SITZ_PDF_ELEMENTE[art];
  document.getElementById(ids.hochladen).addEventListener('click', async ()=>{
    const id = document.getElementById('sitzBearbeiteId').value;
    const statusEl = document.getElementById(ids.status);
    statusEl.textContent = '';
    if(!id){ statusEl.textContent = '⚠️ Bitte die Sitzung zuerst speichern.'; return; }
    const fileInput = document.getElementById(ids.datei);
    const datei = fileInput.files[0];
    if(!datei){ statusEl.textContent = '⚠️ Bitte eine PDF-Datei auswählen.'; return; }
    if(datei.type !== 'application/pdf'){ statusEl.textContent = '⚠️ Bitte eine PDF-Datei auswählen.'; return; }
    // Größen-Obergrenze VOR dem Lesen prüfen (App-Audit Befund 2, 30.08.2026)
    // — gleicher Grenzwert wie serverseitig (admin_sitzung_pdf_hochladen),
    // hier aber sofort und ohne Server-Roundtrip, damit bei einer zu großen
    // Datei nicht erst unnötig hochgeladen und decodiert wird.
    const MAX_PDF_BYTES = 8 * 1024 * 1024;
    if(datei.size > MAX_PDF_BYTES){
      statusEl.textContent = `⚠️ Datei ist zu groß (${(datei.size/1024/1024).toFixed(1)} MB, erlaubt sind max. 8 MB). Bitte die PDF-Datei komprimieren oder verkleinern.`;
      return;
    }
    statusEl.textContent = 'Lädt hoch…';
    try{
      const dateiBase64 = await new Promise((resolve, reject)=>{
        const reader = new FileReader();
        reader.onload = ()=>resolve(reader.result.split(',')[1]);
        reader.onerror = ()=>reject(new Error('Datei konnte nicht gelesen werden.'));
        reader.readAsDataURL(datei);
      });
      await epCallOhneAktion({action:'admin_sitzung_pdf_hochladen', pass: currentAuthPass, id, art, dateiname: datei.name, dateiBase64});
      statusEl.textContent = '✓ Hochgeladen.';
      fileInput.value = '';
      await ladeSitzungenListe();
      sitzPdfAnzeigeAktualisieren(sitzSitzungenCache.find(x=>x.id===id), art);
    }catch(e){
      statusEl.textContent = '⚠️ Fehler: '+e.message;
    }
  });
}
sitzPdfUploadHandlerRegistrieren('tagesordnung');
sitzPdfUploadHandlerRegistrieren('protokoll');

// ---------- Word-Export der Einladung (Migration 56) ----------
// Baut die Einladung im Format der Papier-Vorlage nach (siehe
// Einladung_Vorstandssitzung_07_01_2026.pdf): formale Standard-TOPs
// automatisch VOR/NACH den inhaltlichen Punkten aus tagesordnungspunkte,
// gleiches HTML->.doc-Verfahren wie beim bestehenden Jahresbericht-Export
// (Word/LibreOffice öffnen das direkt als frei bearbeitbares Dokument).
const SITZ_TOP_STANDARD_START = [
  'Eröffnung und Begrüßung durch den Vorsitzenden',
  'Feststellung der Ordnungsmäßigkeit der Ladung',
  'Feststellung der Anwesenden',
  'Feststellung der Beschlussfähigkeit',
  'Genehmigung der Tagesordnung',
];
const SITZ_TOP_STANDARD_ENDE = 'Verschiedenes';

async function exportiereSitzungAlsWord(s){
  const escapeDoc = (t) => escapeHtml(String(t==null?'':t));
  const beginnDatum = new Date(s.beginn);
  const datumDe = beginnDatum.toLocaleDateString('de-DE');
  const uhrzeitDe = beginnDatum.toLocaleTimeString('de-DE', {hour:'2-digit', minute:'2-digit'});
  const heuteDe = new Date().toLocaleDateString('de-DE');
  const logo = await ladeLogoAlsDataURL();

  const inhaltlicheTops = (Array.isArray(s.tagesordnungspunkte) ? s.tagesordnungspunkte : []).filter(t=>t.text && t.text.trim()).map(t=>t.text);
  const alleTops = [...SITZ_TOP_STANDARD_START, ...inhaltlicheTops, SITZ_TOP_STANDARD_ENDE];
  const topZeilen = alleTops.map((t,i)=>`<tr><td style="width:60pt;">TOP ${i+1}</td><td>${escapeDoc(t)}</td></tr>`).join('');
  const unterzeichnerNamen = s.unterzeichner_namen || 'Lena Tillmanns & Nick Hambloch';
  const unterzeichnerZusatz = s.unterzeichner_zusatz || 'Vorsitzende AWO Jugendwerk Erftstadt';

  const html = `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta charset="utf-8">
<title>Einladung ${escapeDoc(s.titel)}</title>
<!--[if gte mso 9]>
<xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument></xml>
<![endif]-->
<style>
  body{ font-family:Calibri,Arial,sans-serif; font-size:11pt; color:#222; }
  h1{ font-size:16pt; margin:0; }
  .titelzeile{ display:table; width:100%; margin-bottom:6pt; }
  .titelzeile .logo{ display:table-cell; vertical-align:middle; width:70pt; }
  .titelzeile .logo img{ width:55pt; }
  .titelzeile .links{ display:table-cell; vertical-align:middle; }
  .einladung{ text-align:center; font-size:15pt; font-weight:bold; margin:24pt 0; }
  .feldzeile{ margin:4pt 0; }
  table{ border-collapse:collapse; width:100%; margin-top:8pt; }
  td{ border:1pt solid #999; padding:5pt 8pt; font-size:10.5pt; vertical-align:top; }
  .unterschrift{ margin-top:28pt; }
</style>
</head>
<body>
  <div class="titelzeile">${logo ? `<div class="logo"><img src="${logo.dataUrl}" width="55"></div>` : ''}<div class="links"><h1>Jugendwerk AWO Erftstadt</h1></div></div>

  <div class="einladung">Einladung<br>zur<br>${escapeDoc(s.titel)}</div>

  <p style="text-align:right;">Erftstadt, den ${heuteDe}</p>
  <p class="feldzeile">Datum: ${datumDe}</p>
  <p class="feldzeile">Beginn: ${uhrzeitDe} Uhr</p>
  <p class="feldzeile">Ort: ${escapeDoc(s.ort || '')}</p>

  <p><strong><u>Tagesordnung</u></strong></p>
  <table>${topZeilen}</table>

  <p class="unterschrift">Mit freundlichen Grüßen</p>
  <p>${escapeDoc(unterzeichnerNamen)}<br><span style="font-size:9pt;">(${escapeDoc(unterzeichnerZusatz)})</span></p>
</body>
</html>`;

  const blob = new Blob(['\ufeff', html], {type: 'application/msword;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Einladung_${s.titel.replace(/[^\p{L}\p{N}]+/gu,'_')}_${stamp()}.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// ---------- Word-Export des PROTOKOLLS (Migration 57) ----------
// Gleicher Aufbau wie die Einladung, aber: Titel "Protokoll" statt
// "Einladung", jeder TOP zeigt zusätzlich die Protokoll-Notiz (falls
// vorhanden), plus ein Abschnitt "Anwesende".
async function exportiereSitzungAlsProtokollWord(s){
  const escapeDoc = (t) => escapeHtml(String(t==null?'':t));
  const beginnDatum = new Date(s.beginn);
  const datumDe = beginnDatum.toLocaleDateString('de-DE');
  const uhrzeitDe = beginnDatum.toLocaleTimeString('de-DE', {hour:'2-digit', minute:'2-digit'});
  const heuteDe = new Date().toLocaleDateString('de-DE');
  const logo = await ladeLogoAlsDataURL();

  const inhaltlicheTops = (Array.isArray(s.tagesordnungspunkte) ? s.tagesordnungspunkte : []).filter(t=>t.text && t.text.trim());
  const alleTops = [
    ...SITZ_TOP_STANDARD_START.map(t=>({text:t, notiz:''})),
    ...inhaltlicheTops,
    {text: SITZ_TOP_STANDARD_ENDE, notiz:''},
  ];
  const topZeilen = alleTops.map((t,i)=>`<tr><td style="width:60pt;">TOP ${i+1}</td><td>${escapeDoc(t.text)}</td><td>${escapeDoc(t.notiz||'')}</td></tr>`).join('');
  const unterzeichnerNamen = s.unterzeichner_namen || 'Lena Tillmanns & Nick Hambloch';
  const unterzeichnerZusatz = s.unterzeichner_zusatz || 'Vorsitzende AWO Jugendwerk Erftstadt';
  const anwesende = s.protokoll_anwesende || '';

  const html = `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta charset="utf-8">
<title>Protokoll ${escapeDoc(s.titel)}</title>
<!--[if gte mso 9]>
<xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument></xml>
<![endif]-->
<style>
  body{ font-family:Calibri,Arial,sans-serif; font-size:11pt; color:#222; }
  h1{ font-size:16pt; margin:0; }
  .titelzeile{ display:table; width:100%; margin-bottom:6pt; }
  .titelzeile .logo{ display:table-cell; vertical-align:middle; width:70pt; }
  .titelzeile .logo img{ width:55pt; }
  .titelzeile .links{ display:table-cell; vertical-align:middle; }
  .einladung{ text-align:center; font-size:15pt; font-weight:bold; margin:24pt 0; }
  .feldzeile{ margin:4pt 0; }
  table{ border-collapse:collapse; width:100%; margin-top:8pt; }
  td, th{ border:1pt solid #999; padding:5pt 8pt; font-size:10.5pt; vertical-align:top; }
  th{ background:#EDE4D3; text-align:left; }
  .unterschrift{ margin-top:28pt; }
</style>
</head>
<body>
  <div class="titelzeile">${logo ? `<div class="logo"><img src="${logo.dataUrl}" width="55"></div>` : ''}<div class="links"><h1>Jugendwerk AWO Erftstadt</h1></div></div>

  <div class="einladung">Protokoll<br>zur<br>${escapeDoc(s.titel)}</div>

  <p style="text-align:right;">Erftstadt, den ${heuteDe}</p>
  <p class="feldzeile">Datum: ${datumDe}</p>
  <p class="feldzeile">Beginn: ${uhrzeitDe} Uhr</p>
  <p class="feldzeile">Ort: ${escapeDoc(s.ort || '')}</p>
  ${anwesende ? `<p class="feldzeile">Anwesende: ${escapeDoc(anwesende)}</p>` : ''}

  <p><strong><u>Tagesordnung &amp; Beschlüsse</u></strong></p>
  <table><tr><th style="width:60pt;">TOP</th><th>Thema</th><th>Beschluss/Notiz</th></tr>${topZeilen}</table>

  <p class="unterschrift">Mit freundlichen Grüßen</p>
  <p>${escapeDoc(unterzeichnerNamen)}<br><span style="font-size:9pt;">(${escapeDoc(unterzeichnerZusatz)})</span></p>
</body>
</html>`;

  const blob = new Blob(['\ufeff', html], {type: 'application/msword;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Protokoll_${s.titel.replace(/[^\p{L}\p{N}]+/gu,'_')}_${stamp()}.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function sitzFormularBefuellen(s){
  document.getElementById('sitzBearbeiteId').value = s.id;
  document.getElementById('sitzFormueberschrift').textContent = `Sitzung bearbeiten (${s.titel}):`;
  document.getElementById('sitzTitel').value = s.titel;
  document.getElementById('sitzBeschreibung').value = s.beschreibung || '';
  document.getElementById('sitzOrt').value = s.ort || '';
  document.getElementById('sitzBeginn').value = isoZuDatetimeLocal(s.beginn);
  document.getElementById('sitzEnde').value = s.ende ? isoZuDatetimeLocal(s.ende) : '';
  document.getElementById('sitzAbgesagt').checked = s.status === 'abgesagt';
  sitzAktuelleTops = Array.isArray(s.tagesordnungspunkte) ? s.tagesordnungspunkte.map(t=>({text: t.text||'', notiz: t.notiz||''})) : [];
  sitzRenderTopListe();
  document.getElementById('sitzUnterzeichnerNamen').value = s.unterzeichner_namen || 'Lena Tillmanns & Nick Hambloch';
  document.getElementById('sitzUnterzeichnerZusatz').value = s.unterzeichner_zusatz || 'Vorsitzende AWO Jugendwerk Erftstadt';
  document.getElementById('sitzProtokollAnwesende').value = s.protokoll_anwesende || '';
  // Protokoll-Akkordeon automatisch aufklappen, wenn der Beginn bereits in
  // der Vergangenheit liegt (dann ist der Bereich relevant) — bei einer
  // noch bevorstehenden Sitzung bleibt es zugeklappt.
  document.getElementById('sitzProtokollDetails').open = new Date(s.beginn) <= new Date();
  sitzPdfAnzeigeAktualisieren(s, 'tagesordnung');
  sitzPdfAnzeigeAktualisieren(s, 'protokoll');
  document.getElementById('sitzPdfStatus').textContent = '';
  document.getElementById('sitzProtokollPdfStatus').textContent = '';
  sitzAusgewaehlteEinladungen = new Set((s.einladungen||[]).map(e=>e.teilnehmer_typ+':'+e.teilnehmer_id));
  renderSitzEinladenListe();
  document.getElementById('sitzStatus').textContent = '';
}

function sitzFormularZuruecksetzen(){
  document.getElementById('sitzBearbeiteId').value = '';
  document.getElementById('sitzFormueberschrift').textContent = 'Neue Sitzung erfassen:';
  document.getElementById('sitzTitel').value = '';
  document.getElementById('sitzBeschreibung').value = '';
  document.getElementById('sitzOrt').value = '';
  document.getElementById('sitzBeginn').value = '';
  document.getElementById('sitzEnde').value = '';
  document.getElementById('sitzAbgesagt').checked = false;
  sitzAktuelleTops = [];
  sitzRenderTopListe();
  document.getElementById('sitzUnterzeichnerNamen').value = 'Lena Tillmanns & Nick Hambloch';
  document.getElementById('sitzUnterzeichnerZusatz').value = 'Vorsitzende AWO Jugendwerk Erftstadt';
  document.getElementById('sitzProtokollAnwesende').value = '';
  document.getElementById('sitzProtokollDetails').open = false;
  document.getElementById('sitzPdfDatei').value = '';
  document.getElementById('sitzPdfStatus').textContent = '';
  document.getElementById('sitzProtokollPdfDatei').value = '';
  document.getElementById('sitzProtokollPdfStatus').textContent = '';
  sitzPdfAnzeigeAktualisieren(null, 'tagesordnung');
  sitzPdfAnzeigeAktualisieren(null, 'protokoll');
  sitzAusgewaehlteEinladungen = new Set();
  renderSitzEinladenListe();
  document.getElementById('sitzStatus').textContent = '';
}

document.getElementById('sitzNeueBtn').addEventListener('click', ()=>{
  sitzFormularZuruecksetzen();
  document.getElementById('sitzFormularContainer').style.display = 'block';
  document.getElementById('sitzTitel').scrollIntoView({behavior:'smooth', block:'center'});
});

document.getElementById('sitzSpeichernBtn').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('sitzStatus');
  const id = document.getElementById('sitzBearbeiteId').value || undefined;
  const titel = document.getElementById('sitzTitel').value.trim();
  const beschreibung = document.getElementById('sitzBeschreibung').value.trim();
  const ort = document.getElementById('sitzOrt').value.trim();
  const beginnRoh = document.getElementById('sitzBeginn').value;
  const endeRoh = document.getElementById('sitzEnde').value;
  const status = document.getElementById('sitzAbgesagt').checked ? 'abgesagt' : 'geplant';
  const unterzeichnerNamen = document.getElementById('sitzUnterzeichnerNamen').value.trim();
  const unterzeichnerZusatz = document.getElementById('sitzUnterzeichnerZusatz').value.trim();
  const protokollAnwesende = document.getElementById('sitzProtokollAnwesende').value.trim();
  if(!titel){ statusEl.textContent = '⚠️ Bitte einen Titel angeben.'; return; }
  if(!beginnRoh){ statusEl.textContent = '⚠️ Bitte einen Beginn-Zeitpunkt angeben.'; return; }
  const beginn = new Date(beginnRoh).toISOString();
  const ende = endeRoh ? new Date(endeRoh).toISOString() : undefined;
  const einladungen = [...sitzAusgewaehlteEinladungen].map(key=>{
    const [teilnehmerTyp, teilnehmerId] = key.split(':');
    return {teilnehmerTyp, teilnehmerId};
  });
  const tagesordnungspunkte = sitzAktuelleTops
    .filter(t=>t.text && t.text.trim())
    .map(t=>({text: t.text.trim(), notiz: (t.notiz||'').trim() || null}));
  try{
    const json = await epCallOhneAktion({action:'admin_sitzung_speichern', pass: currentAuthPass, id, titel, beschreibung, ort, beginn, ende, status, tagesordnungspunkte, unterzeichnerNamen, unterzeichnerZusatz, protokollAnwesende, einladungen});
    await ladeSitzungenListe();
    // NACH dem Speichern im Bearbeiten-Modus für genau diese Sitzung
    // bleiben (statt komplett zu leeren) — sonst wäre der PDF-Upload nach
    // dem allerersten Anlegen einer neuen Sitzung nicht sofort möglich
    // (der Upload-Button braucht eine bereits gespeicherte Sitzungs-ID).
    const aktualisiert = sitzSitzungenCache.find(x=>x.id===(json.sitzung?.id || id));
    if(aktualisiert) sitzFormularBefuellen(aktualisiert);
    else sitzFormularZuruecksetzen();
    statusEl.textContent = '✓ Gespeichert.';
  }catch(e){
    statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
  }
});
document.getElementById('sitzAbbrechenBtn').addEventListener('click', ()=>{
  sitzFormularZuruecksetzen();
  document.getElementById('sitzFormularContainer').style.display = 'none';
});

// ---------- Leihvertrag-PDF-Export ----------
// Baut den Leihvertrag nach der Papier-Vorlage "Leihvertrag nach §§ 598 ff.
// BGB" nach (siehe Vorlage_Verleihvertrag.pdf), mit folgenden bewussten
// Abweichungen (Rechtscheck 25.08.2026, mit Markus abgestimmt):
//   - §5 "Entgelt/Spende" ENTFERNT (es wird real keine Leihgebühr/Spende
//     genommen) und durch "§5 Kaution" ersetzt, die die in der App bereits
//     erfasste Kaution abbildet (leer/"keine Kaution", falls nicht gesetzt).
//   - Neuer §7 Datenschutz-Hinweis.
//   - Neuer §8 zu minderjährigen Entleihern (zusätzliche Unterschriftszeile
//     für Erziehungsberechtigte — die App erfasst kein Geburtsdatum des
//     Entleihers, daher immer mit abgedruckt statt bedingt einblendbar).
// Mehrere gleichzeitige Ausleihen DESSELBEN Entleihers lassen sich über die
// Checkboxen in der Ausleihen-Liste zu einem gemeinsamen Vertrag mit
// mehrzeiliger Gegenstands-Tabelle zusammenfassen.
let vlAusgewaehlteIds = new Set();

function vlAktualisiereVertragsButton(){
  const btn = document.getElementById('vlVertragErstellenBtn');
  const unterschreibenBtn = document.getElementById('vlDigitalUnterschreibenBtn');
  if(!btn) return;
  const anzahl = vlAusgewaehlteIds.size;
  btn.disabled = anzahl === 0;
  btn.textContent = anzahl > 0
    ? `📄 Leihvertrag für ${anzahl} Ausleihe${anzahl>1?'n':''} erstellen`
    : '📄 Leihvertrag erstellen';
  if(unterschreibenBtn) unterschreibenBtn.disabled = anzahl === 0;
}

// vlHoleAusgewaehlteAusleihenGleicherEntleiher: gemeinsame Auswahl-Logik
// für beide Buttons (PDF ohne Unterschrift / digital unterschreiben) —
// prüft, dass alle ausgewählten Ausleihen noch existieren und demselben
// Entleiher gehören, da ein Vertrag nur EINEN Entleiher haben kann.
function vlHoleAusgewaehlteAusleihenGleicherEntleiher(){
  const ausgewaehlt = vlAusleihenCache.filter(a=>vlAusgewaehlteIds.has(a.id));
  if(ausgewaehlt.length === 0) return null;
  const namen = new Set(ausgewaehlt.map(a=>(a.entleiher_name||'').trim().toLowerCase()));
  if(namen.size > 1){
    alert('Die ausgewählten Ausleihen gehören zu unterschiedlichen Entleihern. Bitte nur Ausleihen DESSELBEN Entleihers für einen gemeinsamen Vertrag auswählen.');
    return null;
  }
  ausgewaehlt.sort((a,b)=>a.von_datum.localeCompare(b.von_datum));
  return ausgewaehlt;
}

document.getElementById('vlVertragErstellenBtn').addEventListener('click', async ()=>{
  const ausgewaehlt = vlHoleAusgewaehlteAusleihenGleicherEntleiher();
  if(!ausgewaehlt) return;
  const btn = document.getElementById('vlVertragErstellenBtn');
  btn.disabled = true;
  try{
    await erstelleVerleihvertragPDF(ausgewaehlt);
  }catch(e){
    alert('Vertrag konnte nicht erstellt werden: '+e.message);
  }finally{
    vlAktualisiereVertragsButton();
  }
});
document.getElementById('vlDigitalUnterschreibenBtn').addEventListener('click', ()=>{
  const ausgewaehlt = vlHoleAusgewaehlteAusleihenGleicherEntleiher();
  if(!ausgewaehlt) return;
  vlZeigeUnterschriftDialog(ausgewaehlt);
});

function vlLeihvertragSpalten(){
  return [
    {label:'Nr.', width:9},
    {label:'Gegenstand', width:42},
    {label:'Bezeichnung', width:55},
    {label:'Wiederbesch.-wert', width:38},
    {label:'Zustand', width:26},
  ];
}

// zeichneVertragsFusszeile: identische Kontakt-/Vereinsdaten wie im
// Papier-Original, wird am Ende auf JEDER Seite ergänzt (siehe Aufruf am
// Ende von erstelleVerleihvertragPDF).
function zeichneVertragsFusszeile(doc, marginL){
  const y = 283;
  doc.setDrawColor(200);
  doc.line(marginL, y-3, 190, y-3);
  doc.setFont('helvetica','bold');
  doc.setFontSize(6.5);
  doc.setTextColor(90);
  const spalten = [
    {x: marginL, titel:'Anschrift', zeilen:['AWO Jugendwerk Erftstadt','Bahnhofstr. 7','50374 Erftstadt']},
    {x: marginL+42, titel:'Geschäftsführer*in', zeilen:['Markus Becker']},
    {x: marginL+78, titel:'Kassenwart*in', zeilen:['Markus Becker']},
    {x: marginL+108, titel:'Bankverbindung', zeilen:['Kreissparkasse Köln','IBAN DE30 3705 0299 0194 2788 45','BIC COKSDE33XXX']},
    {x: marginL+150, titel:'Kontakt', zeilen:['E-Mail: jugendwerk-awo-erftstadt@web.de','Mobil: 0163 7927731']},
  ];
  spalten.forEach(s=>{
    doc.setFont('helvetica','bold');
    doc.text(s.titel, s.x, y);
    doc.setFont('helvetica','normal');
    doc.text(s.zeilen, s.x, y+3);
  });
  doc.setTextColor(0);
}

// vlSignaturPadInit: richtet ein <canvas> als einfaches Signatur-Pad ein
// (Pointer Events = Maus/Touch/Stift einheitlich, kein separates
// Touch-Handling nötig). Skaliert intern auf devicePixelRatio für scharfe
// Linien, unabhängig von der angezeigten CSS-Größe.
function vlSignaturPadInit(canvas){
  const ctx = canvas.getContext('2d');
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#2B2B2B';
  let zeichnet = false;
  let leer = true;
  function position(ev){
    const r = canvas.getBoundingClientRect();
    return { x: ev.clientX - r.left, y: ev.clientY - r.top };
  }
  canvas.addEventListener('pointerdown', ev=>{
    zeichnet = true;
    leer = false;
    const p = position(ev);
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    canvas.setPointerCapture(ev.pointerId);
  });
  canvas.addEventListener('pointermove', ev=>{
    if(!zeichnet) return;
    const p = position(ev);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
  });
  const beenden = ()=>{ zeichnet = false; };
  canvas.addEventListener('pointerup', beenden);
  canvas.addEventListener('pointerleave', beenden);
  canvas.addEventListener('pointercancel', beenden);
  return {
    clear(){ ctx.clearRect(0, 0, canvas.width, canvas.height); leer = true; },
    isEmpty(){ return leer; },
    toDataUrl(){ return canvas.toDataURL('image/png'); },
  };
}

// vlZeigeUnterschriftDialog: Signatur-Pad-Dialog für Entleiher, Verleiher
// (Admin vor Ort) und optional Erziehungsberechtigte (bei minderjährigen
// Entleihern, siehe §8 des Vertrags). Nach dem Speichern werden die
// Unterschriften an der/den Ausleihe(n) hinterlegt (Migration 61) UND
// direkt in die erstellte PDF eingebettet.
async function vlZeigeUnterschriftDialog(ausgewaehlt){
  let overlay = document.getElementById('vlUnterschriftOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'vlUnterschriftOverlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.35); z-index:1000; display:flex; align-items:center; justify-content:center; padding:20px;';
    document.body.appendChild(overlay);
  }
  const erste = ausgewaehlt[0];
  const vonDatum = ausgewaehlt.reduce((min,a)=> a.von_datum < min ? a.von_datum : min, erste.von_datum);
  const bisDatum = ausgewaehlt.reduce((max,a)=> a.bis_datum > max ? a.bis_datum : max, erste.bis_datum);
  const zeitraumText = vonDatum === bisDatum ? fmtDateFull(vonDatum) : `${fmtDateFull(vonDatum)} – ${fmtDateFull(bisDatum)}`;

  overlay.innerHTML = `
    <div class="card" style="max-width:560px; width:100%; max-height:90vh; overflow-y:auto; position:relative;">
      <button class="btn ghost" id="vlUnterschriftSchliessenBtn" style="position:absolute; top:14px; right:14px;">✕</button>
      <h3 style="margin-top:0;">✍️ Leihvertrag digital unterschreiben</h3>
      <p class="dp-hint" style="margin-top:0;">${escapeHtml(erste.entleiher_name)} · ${escapeHtml(zeitraumText)}${ausgewaehlt.length>1 ? ` · ${ausgewaehlt.length} Ausleihen zusammengefasst` : ''}</p>
      <button class="btn ghost" type="button" id="vlVertragVorschauBtn" style="width:100%; font-size:0.82rem; padding:5px 8px; margin-bottom:6px;">📄 Vertrag zum Lesen öffnen</button>

      <label style="font-size:0.85rem; display:block; margin-top:12px;">Unterschrift Entleiher</label>
      <canvas id="vlSigEntleiher" style="width:100%; height:130px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
      <button class="btn ghost" type="button" id="vlSigEntleiherLoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>

      <label style="font-size:0.85rem; display:block; margin-top:14px;">Unterschrift Verleiher (AWO Jugendwerk Erftstadt)</label>
      <canvas id="vlSigVerleiher" style="width:100%; height:130px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
      <button class="btn ghost" type="button" id="vlSigVerleiherLoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>

      <label style="display:flex; align-items:center; gap:6px; margin-top:14px; font-weight:normal; font-size:0.85rem;">
        <input type="checkbox" id="vlSigMinderjaehrig" style="width:auto;">
        Entleiher ist minderjährig — zusätzliche Unterschrift der/des Erziehungsberechtigten
      </label>
      <div id="vlSigErziehungsberechtigteBereich" style="display:none;">
        <label style="font-size:0.85rem; display:block; margin-top:6px;">Unterschrift Erziehungsberechtigte/r</label>
        <canvas id="vlSigErziehungsberechtigte" style="width:100%; height:130px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
        <button class="btn ghost" type="button" id="vlSigErziehungsberechtigteLoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>
      </div>

      <label style="font-size:0.85rem; display:block; margin-top:14px;">E-Mail für Vertragsversand (optional)
        <input type="email" id="vlUnterschriftEmail" placeholder="entleiher@example.com" style="width:100%; margin-top:2px; box-sizing:border-box;">
      </label>
      <label style="display:flex; align-items:center; gap:6px; margin-top:6px; font-weight:normal; font-size:0.85rem;">
        <input type="checkbox" id="vlUnterschriftEmailSenden" style="width:auto;">
        Unterschriebenen Vertrag zusätzlich automatisch an diese Adresse senden
      </label>

      <div class="err" id="vlUnterschriftError" style="margin-top:10px;"></div>
      <div style="display:flex; gap:6px; margin-top:12px;">
        <button class="btn" id="vlUnterschriftSpeichernBtn" style="flex:1;">Unterschriften speichern &amp; PDF erstellen</button>
        <button class="btn ghost" id="vlUnterschriftAbbrechenBtn" style="flex:1;">Abbrechen</button>
      </div>
    </div>`;
  overlay.style.display = 'flex';
  // E-Mail-Feld vorbelegen, falls entleiher_kontakt bereits wie eine
  // gültige Adresse aussieht (das Feld ist generisches Freitext-Kontaktfeld,
  // kann also auch eine Telefonnummer o.ä. enthalten).
  const vlEmailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if(vlEmailRegex.test(erste.entleiher_kontakt||'')){
    document.getElementById('vlUnterschriftEmail').value = erste.entleiher_kontakt.trim();
  }

  // Signatur-Pads erst NACH dem Einfügen ins DOM initialisieren, da die
  // Größenberechnung (devicePixelRatio-Skalierung) das tatsächliche
  // Canvas-Layout braucht.
  const padEntleiher = vlSignaturPadInit(document.getElementById('vlSigEntleiher'));
  const padVerleiher = vlSignaturPadInit(document.getElementById('vlSigVerleiher'));
  let padErziehungsberechtigte = null;

  document.getElementById('vlSigEntleiherLoeschenBtn').addEventListener('click', ()=>padEntleiher.clear());
  document.getElementById('vlSigVerleiherLoeschenBtn').addEventListener('click', ()=>padVerleiher.clear());

  const minderjaehrigCb = document.getElementById('vlSigMinderjaehrig');
  const erzBereich = document.getElementById('vlSigErziehungsberechtigteBereich');
  minderjaehrigCb.addEventListener('change', ()=>{
    erzBereich.style.display = minderjaehrigCb.checked ? 'block' : 'none';
    // Pad erst bei Bedarf initialisieren (Canvas ist vorher display:none
    // und hätte dann eine Größe von 0×0).
    if(minderjaehrigCb.checked && !padErziehungsberechtigte){
      padErziehungsberechtigte = vlSignaturPadInit(document.getElementById('vlSigErziehungsberechtigte'));
      document.getElementById('vlSigErziehungsberechtigteLoeschenBtn').addEventListener('click', ()=>padErziehungsberechtigte.clear());
    }
  });

  const schliessen = ()=>{ overlay.style.display = 'none'; };
  document.getElementById('vlUnterschriftSchliessenBtn').addEventListener('click', schliessen);
  document.getElementById('vlUnterschriftAbbrechenBtn').addEventListener('click', schliessen);
  overlay.addEventListener('click', (e)=>{ if(e.target===overlay) schliessen(); });

  // Vertrag zum Lesen öffnen: Fenster MUSS synchron im Klick-Moment
  // geöffnet werden (window.open('', '_blank')), bevor die asynchrone
  // PDF-Erstellung (Logo laden etc.) läuft — sonst blockieren viele
  // Browser (v.a. mobil) das spätere Setzen der URL als Popup.
  document.getElementById('vlVertragVorschauBtn').addEventListener('click', async ()=>{
    const vorschauFenster = window.open('', '_blank');
    try{
      const vorschauDoc = await baueLeihvertragPDF(ausgewaehlt);
      const blobUrl = vorschauDoc.output('bloburl');
      if(vorschauFenster) vorschauFenster.location.href = blobUrl;
      else alert('Der Vertrag konnte nicht in einem neuen Tab geöffnet werden — bitte Popup-Blocker für diese Seite deaktivieren.');
    }catch(e){
      if(vorschauFenster) vorschauFenster.close();
      alert('Vorschau konnte nicht erstellt werden: '+e.message);
    }
  });

  document.getElementById('vlUnterschriftSpeichernBtn').addEventListener('click', async ()=>{
    const errEl = document.getElementById('vlUnterschriftError');
    errEl.textContent = '';
    if(padEntleiher.isEmpty()){ errEl.textContent = '⚠️ Bitte die Unterschrift des Entleihers erfassen.'; return; }
    if(padVerleiher.isEmpty()){ errEl.textContent = '⚠️ Bitte die Unterschrift des Verleihers erfassen.'; return; }
    if(minderjaehrigCb.checked && (!padErziehungsberechtigte || padErziehungsberechtigte.isEmpty())){
      errEl.textContent = '⚠️ Bitte die Unterschrift der/des Erziehungsberechtigten erfassen (oder Häkchen entfernen, falls nicht zutreffend).';
      return;
    }
    const entleiherData = padEntleiher.toDataUrl();
    const verleiherData = padVerleiher.toDataUrl();
    const erziehungsberechtigteData = (minderjaehrigCb.checked && padErziehungsberechtigte) ? padErziehungsberechtigte.toDataUrl() : null;
    const emailSenden = document.getElementById('vlUnterschriftEmailSenden').checked;
    const emailAdresse = document.getElementById('vlUnterschriftEmail').value.trim();
    if(emailSenden && !vlEmailRegex.test(emailAdresse)){
      errEl.textContent = '⚠️ Bitte eine gültige E-Mail-Adresse angeben, oder das Häkchen entfernen.';
      return;
    }

    const btn = document.getElementById('vlUnterschriftSpeichernBtn');
    btn.disabled = true;
    try{
      await epCallOhneAktion({
        action:'admin_verleih_ausleihe_unterschrift_speichern', pass: currentAuthPass,
        ids: ausgewaehlt.map(a=>a.id), entleiherData, verleiherData, erziehungsberechtigteData,
      });
      schliessen();
      // PDF nur EINMAL bauen — lokaler Download UND E-Mail-Versand nutzen
      // dasselbe erzeugte Dokument, statt es zweimal zu generieren.
      const unterschriften = {
        entleiher: entleiherData, verleiher: verleiherData, erziehungsberechtigte: erziehungsberechtigteData,
        am: new Date().toISOString(),
      };
      const doc = await baueLeihvertragPDF(ausgewaehlt, unterschriften);
      const dateiSicherName = (erste.entleiher_name || 'Entleiher').replace(/[^\p{L}\p{N}]+/gu, '_');
      const dateiname = `Leihvertrag_${dateiSicherName}_${stamp()}.pdf`;
      doc.save(dateiname);
      if(emailSenden){
        try{
          const pdfBase64 = doc.output('datauristring').split(',')[1];
          await epCallOhneAktion({
            action:'admin_verleih_ausleihe_vertrag_per_email', pass: currentAuthPass,
            ids: ausgewaehlt.map(a=>a.id), empfaengerEmail: emailAdresse, entleiherName: erste.entleiher_name,
            pdfBase64, dateiname,
          });
        }catch(e){
          alert('Der Vertrag wurde gespeichert und heruntergeladen, aber der E-Mail-Versand ist fehlgeschlagen: '+e.message);
        }
      }
      await ladeVlAusleihen();
    }catch(e){
      errEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
      btn.disabled = false;
    }
  });
}

async function baueLeihvertragPDF(ausleihenAuswahl, unterschriften){
  await ladeBibliothek('jspdf');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  const marginL = 20, marginR = 190;
  const seitenUnten = 270; // unter dieser Höhe wird umgebrochen (Fußzeile kommt separat, siehe unten)
  let y = 18;

  function pruefeSeitenumbruch(benoetigterPlatz){
    if(y + benoetigterPlatz > seitenUnten){
      doc.addPage();
      y = 20;
    }
  }
  function addUeberschrift(text){
    pruefeSeitenumbruch(9);
    doc.setFont('helvetica','bold');
    doc.setFontSize(12);
    doc.text(text, marginL, y);
    y += 7;
  }
  function addAbsatz(text, abstandDanach){
    doc.setFont('helvetica','normal');
    doc.setFontSize(10.5);
    const zeilen = doc.splitTextToSize(text, marginR - marginL);
    pruefeSeitenumbruch(zeilen.length * 5);
    doc.text(zeilen, marginL, y);
    y += zeilen.length * 5 + (abstandDanach != null ? abstandDanach : 6);
  }
  function addFeldZeile(label, wert){
    pruefeSeitenumbruch(7);
    doc.setFont('helvetica','normal');
    doc.setFontSize(10.5);
    doc.text(label, marginL, y);
    doc.setDrawColor(120);
    doc.line(marginL + 32, y+1, marginR, y+1);
    if(wert) doc.text(String(wert), marginL + 34, y);
    y += 7;
  }

  // Briefkopf: Logo rechts oben, Vereinsname/Adresse links, Datum rechtsbündig
  const logo = await ladeLogoAlsDataURL();
  const logoBreite = 26;
  if(logo){
    const logoHoehe = logoBreite * logo.hoehe / logo.breite;
    doc.addImage(logo.dataUrl, 'PNG', marginR - logoBreite, y - 8, logoBreite, logoHoehe);
  }
  doc.setFont('helvetica','normal');
  doc.setFontSize(8.5);
  doc.text('AWO Jugendwerk Erftstadt · Bahnhofstr. 7 · 50374 Erftstadt', marginL, y);
  doc.text(`Erftstadt, den ${fmtDateFull(todayIso())}`, marginR, y + 14, {align:'right'});

  y = 42;
  doc.setFont('helvetica','bold');
  doc.setFontSize(16);
  doc.text('Leihvertrag nach §§ 598 ff. BGB', 105, y, {align:'center'});
  y += 12;

  // Verleiher: feste Organisationsdaten, nicht editierbar (Verein ist immer
  // der Verleiher).
  addUeberschrift('Verleiher:');
  addFeldZeile('Name:', 'AWO Jugendwerk Erftstadt, vertr. durch Markus Becker (Geschäftsführer)');
  addFeldZeile('Anschrift:', 'Bahnhofstr. 7, 50374 Erftstadt');
  addFeldZeile('Telefon/E-Mail:', 'jugendwerk-awo-erftstadt@web.de');
  y += 3;

  // Entleiher: aus der/den ausgewählten Ausleihe(n) — alle ausgewählten
  // teilen denselben Entleiher (siehe Prüfung vor dem Aufruf dieser Funktion).
  const erste = ausleihenAuswahl[0];
  addUeberschrift('Entleiher:');
  addFeldZeile('Name:', erste.entleiher_name);
  addFeldZeile('Anschrift:', erste.entleiher_anschrift || '');
  addFeldZeile('Telefon/E-Mail:', erste.entleiher_kontakt || '');
  y += 4;

  // § 1 Vertragsgegenstand — Tabelle mit einer Zeile pro ausgewählter Ausleihe.
  // "Bezeichnung" und "Wiederbeschaffungswert" kommen vom zugehörigen Artikel
  // (vlArtikelCache), falls der Artikel noch existiert — sonst bleiben die
  // Spalten leer. "Zustand" bleibt IMMER leer zum handschriftlichen Ausfüllen
  // bei Übergabe, da der Zustand zum Ausleihzeitpunkt nicht in der App erfasst wird.
  // Leihgebühr-/Kautionssumme schon hier berechnet (statt erst bei §5), da
  // der Einleitungssatz "unentgeltlich" nur stimmt, wenn tatsächlich keine
  // Leihgebühr vereinbart wurde.
  const leihgebuehrSumme = ausleihenAuswahl.reduce((s,a)=> s + (a.leihgebuehr_betrag != null ? Number(a.leihgebuehr_betrag) : 0), 0);
  const kautionSumme = ausleihenAuswahl.reduce((s,a)=> s + (a.kaution_betrag != null ? Number(a.kaution_betrag) : 0), 0);
  addUeberschrift('§ 1 Vertragsgegenstand');
  addAbsatz(
    leihgebuehrSumme > 0
      ? 'Der Verleiher überlässt dem Entleiher nach § 598 BGB die nachfolgenden Gegenstände gegen die in § 5 genannte Leihgebühr zum Gebrauch.'
      : 'Der Verleiher überlässt dem Entleiher nach § 598 BGB die nachfolgenden Gegenstände unentgeltlich zum Gebrauch.',
    4
  );

  const spalten = vlLeihvertragSpalten();
  const tabellenBreite = spalten.reduce((s,c)=>s+c.width,0);
  function zeichneTabellenkopf(){
    pruefeSeitenumbruch(10);
    doc.setFont('helvetica','bold');
    doc.setFontSize(8.5);
    let x = marginL;
    spalten.forEach(s=>{ doc.text(s.label, x, y); x += s.width; });
    y += 2;
    doc.setDrawColor(120);
    doc.line(marginL, y, marginL + tabellenBreite, y);
    y += 4.5;
    doc.setFont('helvetica','normal');
    doc.setFontSize(8.5);
  }
  zeichneTabellenkopf();
  // Alle Positionen ALLER ausgewählten Ausleihen zu einer gemeinsamen Liste
  // abflachen — eine Ausleihe kann jetzt bereits mehrere Artikel enthalten
  // (Migration 54), und mehrere Ausleihen lassen sich zusätzlich über die
  // Checkbox-Auswahl zu einem Vertrag zusammenfassen.
  const allePositionen = ausleihenAuswahl.flatMap(a => a.positionen || []);
  allePositionen.forEach((pos, i)=>{
    const artikel = vlArtikelCache.find(art=>art.id === pos.artikel_id);
    const beschreibung = artikel?.beschreibung || '';
    const wert = artikel?.wiederbeschaffungswert != null ? Number(artikel.wiederbeschaffungswert).toFixed(2)+' €' : '';
    const zellen = [String(i+1), pos.artikel_name_snapshot || '', beschreibung, wert, ''];
    const gewrappt = zellen.map((z,idx)=>doc.splitTextToSize(z, spalten[idx].width - 2));
    const zeilenhoehe = Math.max(...gewrappt.map(g=>g.length), 1) * 4 + 2;
    if(y + zeilenhoehe > seitenUnten){
      doc.addPage();
      y = 20;
      zeichneTabellenkopf();
    }
    let x = marginL;
    gewrappt.forEach((g,idx)=>{ doc.text(g, x, y); x += spalten[idx].width; });
    y += zeilenhoehe;
    doc.setDrawColor(230);
    doc.line(marginL, y-1.5, marginL + tabellenBreite, y-1.5);
  });
  y += 6;

  // § 2 Dauer der Leihe — bei mehreren zusammengefassten Ausleihen wird der
  // GESAMTE Zeitraum genannt (frühestes Von-Datum bis spätestes Bis-Datum),
  // auch wenn einzelne Gegenstände darin kürzere Teilzeiträume haben.
  const vonDatum = ausleihenAuswahl.reduce((min,a)=> a.von_datum < min ? a.von_datum : min, erste.von_datum);
  const bisDatum = ausleihenAuswahl.reduce((max,a)=> a.bis_datum > max ? a.bis_datum : max, erste.bis_datum);
  addUeberschrift('§ 2 Dauer der Leihe');
  addAbsatz(`1. Die Leihe beginnt am ${fmtDateFull(vonDatum)} und endet spätestens am ${fmtDateFull(bisDatum)}.`, 2);
  addAbsatz('2. Wird keine feste Dauer vereinbart, ist die Sache nach Gebrauch bzw. auf Verlangen des Verleihers zurückzugeben (§ 604 BGB).', 2);
  addAbsatz('3. Eine Verlängerung bedarf der schriftlichen Zustimmung des Verleihers.', 6);

  // § 3 Gebrauch der Gegenstände
  addUeberschrift('§ 3 Gebrauch der Gegenstände');
  addAbsatz('1. Der Entleiher verpflichtet sich, die Gegenstände sorgfältig und nur zu dem vereinbarten Zweck zu verwenden (§ 603 BGB).', 2);
  addAbsatz('2. Eine Weitergabe an Dritte ist ohne ausdrückliche schriftliche Zustimmung des Verleihers unzulässig.', 2);
  addAbsatz('3. Der Entleiher trägt die gewöhnlichen Kosten der Benutzung (§ 601 Abs. 1 BGB).', 6);

  // § 4 Rückgabe
  addUeberschrift('§ 4 Rückgabe');
  addAbsatz('1. Der Entleiher verpflichtet sich, die Gegenstände unverzüglich nach Ablauf der vereinbarten Zeit oder nach Erreichen des Zwecks in ordnungsgemäßem, gereinigtem und funktionsfähigem Zustand zurückzugeben (§ 604 BGB).', 2);
  addAbsatz('2. Der Entleiher haftet für alle Schäden an den Gegenständen, die während der Leihe entstehen, sofern er diese vorsätzlich oder fahrlässig verursacht hat. In diesem Fall ist er verpflichtet, den Schaden auf eigene Kosten zu beheben oder gleichwertigen Ersatz zu leisten.', 2);
  addAbsatz('3. Für Verlust oder Untergang der Gegenstände haftet der Entleiher ebenfalls, soweit er dies zu vertreten hat.', 2);
  addAbsatz('4. Für normale Abnutzung infolge des vertragsgemäßen Gebrauchs haftet der Entleiher nicht.', 6);

  // § 5 Leihgebühr und Kaution — ersetzt das ursprüngliche "§5
  // Entgelt/Spende" der Papier-Vorlage: der Normalfall bleibt
  // unentgeltlicher Verleih (§ 598 BGB), es lässt sich aber optional eine
  // Leihgebühr vereinbaren (nicht rückerstattbar, anders als die Kaution)
  // sowie die in der App bereits erfasste Kaution abbilden. Bei mehreren
  // zusammengefassten Ausleihen wird jeweils die Summe genannt (Berechnung
  // siehe oben bei §1, dort schon für den Einleitungssatz gebraucht).
  addUeberschrift('§ 5 Leihgebühr und Kaution');
  if(leihgebuehrSumme <= 0 && kautionSumme <= 0){
    addAbsatz('Für diese Ausleihe werden weder eine Leihgebühr noch eine Kaution erhoben. Die Leihe erfolgt unentgeltlich (§ 598 BGB).', 6);
  } else {
    const paragraphen = [];
    if(leihgebuehrSumme > 0){
      paragraphen.push(`Für diese Ausleihe wird eine Leihgebühr in Höhe von ${leihgebuehrSumme.toFixed(2)} € erhoben, fällig bei Übergabe der Gegenstände. Die Leihgebühr wird nicht zurückerstattet.`);
    } else {
      paragraphen.push('Für diese Ausleihe wird keine Leihgebühr erhoben.');
    }
    if(kautionSumme > 0){
      paragraphen.push(`Für diese Ausleihe wird eine Kaution in Höhe von ${kautionSumme.toFixed(2)} € vereinbart.`);
      paragraphen.push('Die Kaution wird bei ordnungsgemäßer, vollständiger und rechtzeitiger Rückgabe der Gegenstände in vollem Umfang zurückerstattet.');
      paragraphen.push('Bei Beschädigung, Verlust oder verspäteter Rückgabe kann die Kaution ganz oder teilweise mit den nach § 4 entstandenen Kosten verrechnet werden.');
    } else {
      paragraphen.push('Für diese Ausleihe wird keine Kaution erhoben.');
    }
    paragraphen.forEach((text,i)=> addAbsatz(`${i+1}. ${text}`, i===paragraphen.length-1 ? 6 : 2));
  }

  // § 6 Haftung des Verleihers
  addUeberschrift('§ 6 Haftung des Verleihers');
  addAbsatz('Der Verleiher haftet nur für Vorsatz und grobe Fahrlässigkeit (§ 599 BGB). Für Mängel der Sache haftet er nicht, außer bei arglistigem Verschweigen.', 6);

  // § 7 Datenschutz (neu ggü. Papier-Vorlage)
  addUeberschrift('§ 7 Datenschutz');
  addAbsatz('Die im Rahmen dieses Vertrags erhobenen personenbezogenen Daten (Name, Anschrift, Kontaktdaten) werden ausschließlich zur Abwicklung und Dokumentation dieses Leihverhältnisses verarbeitet und nach den geltenden datenschutzrechtlichen Vorgaben behandelt.', 6);

  // § 8 Minderjährige Entleiher (neu ggü. Papier-Vorlage)
  addUeberschrift('§ 8 Minderjährige Entleiher');
  addAbsatz('Ist der/die Entleiher/in zum Zeitpunkt des Vertragsschlusses minderjährig, wird dieser Vertrag nur mit Einwilligung und Unterschrift der/des Erziehungsberechtigten wirksam (§ 107 BGB). Die entsprechende Unterschriftszeile befindet sich am Ende dieses Vertrags.', 6);

  // § 9 Sonstiges (entspricht §7 der Papier-Vorlage, hier verschoben wegen §7/§8 neu)
  addUeberschrift('§ 9 Sonstiges');
  addAbsatz('1. Änderungen und Ergänzungen dieses Vertrags bedürfen der Schriftform.', 2);
  addAbsatz('2. Sollten einzelne Bestimmungen dieses Vertrags unwirksam sein, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.', 2);
  addAbsatz('3. Es gilt das Recht der Bundesrepublik Deutschland.', 10);

  // Unterschriften — falls eine digitale Unterschrift vorliegt (gerade
  // frisch über den Signatur-Dialog erfasst, oder bereits früher für
  // dieselbe Ausleihe digital unterschrieben und jetzt erneut als PDF
  // exportiert), wird das Signatur-Bild über der jeweiligen Linie
  // eingefügt statt sie für die handschriftliche Unterschrift leer zu
  // lassen.
  if(!unterschriften && erste.unterschrift_entleiher_data){
    unterschriften = {
      entleiher: erste.unterschrift_entleiher_data,
      verleiher: erste.unterschrift_verleiher_data,
      erziehungsberechtigte: erste.unterschrift_erziehungsberechtigte_data || null,
      am: erste.unterschrift_entleiher_am,
    };
  }
  pruefeSeitenumbruch(34);
  doc.setFont('helvetica','normal');
  doc.setFontSize(10.5);
  doc.text('Ort, Datum:', marginL, y);
  doc.setDrawColor(120);
  doc.line(marginL + 26, y+1, marginR, y+1);
  y += 20;
  const sigBreite = 55, sigHoehe = 16;
  if(unterschriften?.verleiher) doc.addImage(unterschriften.verleiher, 'PNG', marginL, y - sigHoehe, sigBreite, sigHoehe);
  if(unterschriften?.entleiher) doc.addImage(unterschriften.entleiher, 'PNG', marginL + 90, y - sigHoehe, sigBreite, sigHoehe);
  doc.line(marginL, y, marginL + 70, y);
  doc.line(marginL + 90, y, marginR, y);
  y += 5;
  doc.text('(Verleiher)', marginL, y);
  doc.text('(Entleiher)', marginL + 90, y);
  if(unterschriften?.am){
    doc.setFontSize(7);
    doc.setTextColor(120);
    const signiertText = `digital unterschrieben am ${fmtDateFull(String(unterschriften.am).slice(0,10))}`;
    doc.text(signiertText, marginL, y + 4);
    doc.text(signiertText, marginL + 90, y + 4);
    doc.setTextColor(0);
    doc.setFontSize(10.5);
    y += 4;
  }
  y += 16;
  if(unterschriften?.erziehungsberechtigte) doc.addImage(unterschriften.erziehungsberechtigte, 'PNG', marginL, y - sigHoehe, sigBreite, sigHoehe);
  doc.line(marginL, y, marginL + 70, y);
  y += 5;
  doc.setFontSize(9);
  doc.text('(Erziehungsberechtigte/r, falls Entleiher minderjährig)', marginL, y);

  // Fußzeile mit Vereinskontaktdaten auf JEDER Seite (analog Papier-Vorlage)
  const gesamtSeiten = doc.internal.getNumberOfPages();
  for(let s=1; s<=gesamtSeiten; s++){
    doc.setPage(s);
    zeichneVertragsFusszeile(doc, marginL);
  }

  return doc;
}

// erstelleVerleihvertragPDF: baut die PDF und lädt sie direkt herunter
// (für den fertigen, unterschriebenen — oder bewusst noch unterschriftslos
// ausgedruckten — Vertrag).
async function erstelleVerleihvertragPDF(ausleihenAuswahl, unterschriften){
  const doc = await baueLeihvertragPDF(ausleihenAuswahl, unterschriften);
  const erste = ausleihenAuswahl[0];
  const dateiSicherName = (erste.entleiher_name || 'Entleiher').replace(/[^\p{L}\p{N}]+/gu, '_');
  doc.save(`Leihvertrag_${dateiSicherName}_${stamp()}.pdf`);
}

async function renderVwKalender(){
  const kalEl = document.getElementById('vwKalenderListe');
  kalEl.textContent = 'Lädt…';
  kalAnsicht = { jahr: 0, monat: 0, gewaehlt: '', proTag: {} }; // bei jedem Öffnen wieder auf den heutigen Monat
  try{
    await Promise.all([ladeVwAktionenCacheFallsNoetig(), ladeVwSitzungenFuerKalenderFallsNoetig()]);
    const aktionen = vwAktionenCache;

    // --- Kalender ---
    const heute = todayIso();
    const mitTermin = aktionen.filter(a=>a.start_datum).sort((a,b)=>a.start_datum.localeCompare(b.start_datum));
    const ohneTermin = aktionen.filter(a=>!a.start_datum);
    // Kombinierte Liste aus Aktions- und Sitzungsterminen, als einheitliche
    // "Termin"-Objekte (siehe aktionZuTermin/sitzungZuTermin weiter unten) —
    // abgesagte Sitzungen bleiben außen vor, die will niemand im Kalender.
    const alleTermine = [
      ...mitTermin.map(aktionZuTermin),
      ...vwSitzungenFuerKalenderCache.filter(s=>s.status!=='abgesagt').map(sitzungZuTermin),
    ].sort((a,b)=>a.startIso.localeCompare(b.startIso));
    // Auswahl bei jedem Öffnen zurücksetzen auf "alles an" — der Admin soll
    // jedes Mal bewusst abwählen, was NICHT in die Datei soll, statt sich
    // eine alte Auswahl von vorletzter Woche zu merken.
    vwKalenderAuswahl = new Set(alleTermine.map(t=>t.key));

    const kommende = alleTermine.filter(t=>(t.endIso||t.startIso) >= heute);
    const vergangene = alleTermine.filter(t=>(t.endIso||t.startIso) < heute).reverse();

    const terminZeile = t=>{
      const zeitraum = t.allDay
        ? ((t.endIso && t.endIso !== t.startIso) ? `${fmtDateFull(t.startIso)} – ${fmtDateFull(t.endIso)}` : fmtDateFull(t.startIso))
        : new Date(t.startIso).toLocaleString('de-DE', {weekday:'short', day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'}) + ' Uhr';
      const typLabel = t.uidPrefix === 'sitzung' ? '🗓️ Sitzung' : '📌 Aktion';
      const row = document.createElement('label');
      row.style.cssText = 'display:flex; align-items:flex-start; gap:8px; padding:8px 4px; border-bottom:1px solid #eee; cursor:pointer;';
      row.innerHTML = `<input type="checkbox" class="vwKalenderCheckbox" data-key="${escapeHtml(t.key)}" ${vwKalenderAuswahl.has(t.key)?'checked':''} style="margin-top:3px;">
        <span><strong>${escapeHtml(t.titel)}</strong><div style="font-size:0.82rem; color:var(--ink-soft);">${escapeHtml(zeitraum)} · ${typLabel}${t.ort ? ' · '+escapeHtml(t.ort) : ''}</div></span>`;
      return row;
    };

    kalEl.innerHTML = '';
    if(alleTermine.length === 0){
      kalEl.innerHTML = '<div class="dash-empty" style="border:none; padding:6px 4px;">Noch kein Termin vorhanden — weder bei Aktionen noch bei Sitzungen.</div>';
    } else {
      if(kommende.length > 0){
        const label = document.createElement('div');
        label.className = 'dp-hint';
        label.style.margin = '0 0 4px 0';
        label.textContent = 'Kommend:';
        kalEl.appendChild(label);
        kommende.forEach(t=>kalEl.appendChild(terminZeile(t)));
      }
      if(vergangene.length > 0){
        const details = document.createElement('details');
        details.className = 'erledigt-fach';
        const summary = document.createElement('summary');
        summary.textContent = `Vergangen (${vergangene.length})`;
        details.appendChild(summary);
        vergangene.forEach(t=>details.appendChild(terminZeile(t)));
        kalEl.appendChild(details);
      }
      kalEl.querySelectorAll('.vwKalenderCheckbox').forEach(cb=>{
        cb.addEventListener('change', ()=>{
          if(cb.checked) vwKalenderAuswahl.add(cb.dataset.key);
          else vwKalenderAuswahl.delete(cb.dataset.key);
        });
      });
    }
    if(ohneTermin.length > 0){
      const hint = document.createElement('div');
      hint.style.cssText = 'font-size:0.82rem; color:var(--ink-soft); margin-top:8px;';
      hint.textContent = `Aktionen ohne Termin: ${ohneTermin.map(a=>a.name).join(', ')}`;
      kalEl.appendChild(hint);
    }
    // Für den Export-Button und die "Alle/Keine"-Buttons merken, welche
    // Termine gerade überhaupt zur Auswahl stehen.
    vwKalenderAlleTermineCache = alleTermine;
    // Monatsraster (Version 8zc): Aktionen + Sitzungen + offene Fristen. Fristen sind optional: schlägt der Abruf fehl, bleibt der Rest.
    let fristenFuerKalender = [];
    try{
      const jf = await epCallOhneAktion({action:'admin_fristen_liste', pass: currentAuthPass});
      fristenFuerKalender = (jf.fristen || []).filter(f=>!f.erledigt_am && f.faellig_am);
    }catch(e){}
    kalMonatAufbauen(alleTermine, fristenFuerKalender);
  }catch(e){
    kalEl.innerHTML = '<div class="dp-hint">⚠️ Fehler beim Laden: '+escapeHtml(e.message)+'</div>';
  }
}

// ================================================================
// MONATSKALENDER (Admin, Version 8zc)
// Raster Mo-So mit farbigen Punkten je Terminart; Klick auf einen Tag
// zeigt die Termine darunter. Aktionen laufen über alle Tage ihres
// Zeitraums, Sitzungen stehen am Tag ihres Beginns (lokale Zeit),
// offene Fristen am Fälligkeitstag.
// ================================================================
let kalAnsicht = { jahr: 0, monat: 0, gewaehlt: '', proTag: {} };
const KAL_MONATE = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const KAL_WOCHENTAGE = ['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'];
function kalIso(j, m, t){ return j + '-' + String(m + 1).padStart(2,'0') + '-' + String(t).padStart(2,'0'); }
function kalLokalesDatum(iso){
  const d = new Date(iso);
  return isNaN(d.getTime()) ? '' : kalIso(d.getFullYear(), d.getMonth(), d.getDate());
}
function kalTageZwischen(von, bis){
  const aus = [];
  if(!/^\d{4}-\d{2}-\d{2}$/.test(von || '')) return aus;
  let ende = /^\d{4}-\d{2}-\d{2}$/.test(bis || '') ? bis : von;
  if(ende < von) ende = von;
  const d = new Date(von + 'T12:00:00');
  for(let i = 0; i < 400; i++){
    const s = kalIso(d.getFullYear(), d.getMonth(), d.getDate());
    aus.push(s);
    if(s >= ende) break;
    d.setDate(d.getDate() + 1);
  }
  return aus;
}
function kalMonatAufbauen(termine, fristen){
  const proTag = {};
  const ablegen = function(tag, e){ (proTag[tag] = proTag[tag] || []).push(e); };
  (termine || []).forEach(function(t){
    if(t.uidPrefix === 'sitzung'){
      const tag = kalLokalesDatum(t.startIso);
      if(tag) ablegen(tag, { art: 'sitzung', titel: t.titel, uhr: new Date(t.startIso).toLocaleTimeString('de-DE', {hour:'2-digit', minute:'2-digit'}) + ' Uhr', ort: t.ort, info: t.beschreibung, sort: 10 + new Date(t.startIso).getTime() / 1e13 });
    } else {
      const von = String(t.startIso || '').slice(0, 10), bis = String(t.endIso || '').slice(0, 10);
      const tage = kalTageZwischen(von, bis);
      tage.forEach(function(tag, i){
        ablegen(tag, { art: 'aktion', titel: t.titel, uhr: tage.length > 1 ? 'Tag ' + (i + 1) + ' von ' + tage.length + ' (' + fmtDateFull(von) + ' – ' + fmtDateFull(bis) + ')' : 'ganztägig', ort: null, info: t.beschreibung, sort: 0 });
      });
    }
  });
  (fristen || []).forEach(function(f){
    const tag = String(f.faellig_am).slice(0, 10);
    ablegen(tag, { art: 'frist', titel: f.titel, uhr: 'fällig' + (f.wiederholung && f.wiederholung !== 'keine' ? ', wiederkehrend' : ''), ort: null, info: f.notiz, sort: 100 });
  });
  const heute = todayIso();
  if(!kalAnsicht.jahr){
    kalAnsicht.jahr = Number(heute.slice(0, 4)); kalAnsicht.monat = Number(heute.slice(5, 7)) - 1; kalAnsicht.gewaehlt = heute;
  }
  kalAnsicht.proTag = proTag;
  kalMonatRendern();
}
function kalMonatRendern(){
  const wurzel = document.getElementById('vwKalenderRaster');
  if(!wurzel) return;
  const { jahr, monat, gewaehlt, proTag } = kalAnsicht;
  const heute = todayIso();
  wurzel.textContent = '';
  const kopf = document.createElement('div'); kopf.className = 'kal-kopf';
  const knopf = function(text, label, fn){ const b = document.createElement('button'); b.type = 'button'; b.className = 'btn ghost'; b.textContent = text; b.setAttribute('aria-label', label); b.addEventListener('click', fn); return b; };
  const wechsel = function(delta){
    const d = new Date(jahr, monat + delta, 1);
    kalAnsicht.jahr = d.getFullYear(); kalAnsicht.monat = d.getMonth();
    kalMonatRendern();
  };
  kopf.appendChild(knopf('‹', 'Vorheriger Monat', function(){ wechsel(-1); }));
  const mitte = document.createElement('div'); mitte.style.cssText = 'text-align:center; flex:1;';
  const titel = document.createElement('strong'); titel.id = 'vwKalenderMonatTitel'; titel.textContent = KAL_MONATE[monat] + ' ' + jahr; mitte.appendChild(titel);
  const hb = knopf('Heute', 'Zum heutigen Tag', function(){
    kalAnsicht.jahr = Number(heute.slice(0, 4)); kalAnsicht.monat = Number(heute.slice(5, 7)) - 1; kalAnsicht.gewaehlt = heute; kalMonatRendern();
  });
  hb.style.cssText = 'font-size:0.78rem; padding:2px 10px; margin-left:8px;'; mitte.appendChild(hb);
  kopf.appendChild(mitte);
  kopf.appendChild(knopf('›', 'Nächster Monat', function(){ wechsel(1); }));
  wurzel.appendChild(kopf);
  const grid = document.createElement('div'); grid.className = 'kal-grid';
  ['Mo','Di','Mi','Do','Fr','Sa','So'].forEach(function(w){ const z = document.createElement('div'); z.className = 'kal-wt'; z.textContent = w; grid.appendChild(z); });
  const erster = new Date(jahr, monat, 1);
  const versatz = (erster.getDay() + 6) % 7; // Montag = 0
  const start = new Date(jahr, monat, 1 - versatz);
  const zeilen = Math.ceil((versatz + new Date(jahr, monat + 1, 0).getDate()) / 7);
  for(let i = 0; i < zeilen * 7; i++){
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    const iso = kalIso(d.getFullYear(), d.getMonth(), d.getDate());
    const b = document.createElement('button'); b.type = 'button';
    b.className = 'kal-tag' + (d.getMonth() !== monat ? ' anderer' : '') + (iso === heute ? ' heute' : '') + (iso === gewaehlt ? ' gewaehlt' : '');
    b.setAttribute('data-tag', iso);
    const eintraege = proTag[iso] || [];
    b.setAttribute('aria-label', fmtDateFull(iso) + (eintraege.length ? ', ' + eintraege.length + ' Termin' + (eintraege.length > 1 ? 'e' : '') : ''));
    const zahl = document.createElement('span'); zahl.textContent = String(d.getDate()); b.appendChild(zahl);
    const punkte = document.createElement('span'); punkte.className = 'kal-punkte';
    ['aktion', 'sitzung', 'frist'].forEach(function(art){
      if(eintraege.some(function(e){ return e.art === art; })){ const p = document.createElement('span'); p.className = 'kal-punkt ' + art; punkte.appendChild(p); }
    });
    b.appendChild(punkte);
    b.addEventListener('click', function(){
      kalAnsicht.gewaehlt = iso;
      if(d.getMonth() !== monat){ kalAnsicht.jahr = d.getFullYear(); kalAnsicht.monat = d.getMonth(); }
      kalMonatRendern();
    });
    grid.appendChild(b);
  }
  wurzel.appendChild(grid);
  const leg = document.createElement('div'); leg.className = 'kal-legende';
  [['aktion','Aktion'],['sitzung','Sitzung'],['frist','Frist']].forEach(function(l){
    const s = document.createElement('span'); const p = document.createElement('span'); p.className = 'kal-punkt ' + l[0]; s.appendChild(p); s.appendChild(document.createTextNode(l[1])); leg.appendChild(s);
  });
  wurzel.appendChild(leg);
  kalTagRendern();
}
function kalTagRendern(){
  const box = document.getElementById('vwKalenderTag');
  if(!box) return;
  const iso = kalAnsicht.gewaehlt;
  box.textContent = '';
  if(!iso) return;
  const d = new Date(iso + 'T12:00:00');
  const h = document.createElement('strong'); h.id = 'vwKalenderTagTitel';
  h.textContent = KAL_WOCHENTAGE[(d.getDay() + 6) % 7] + ', ' + fmtDateFull(iso); box.appendChild(h);
  const liste = (kalAnsicht.proTag[iso] || []).slice().sort(function(a, b){ return a.sort - b.sort; });
  if(!liste.length){
    const leer = document.createElement('div'); leer.className = 'dash-empty'; leer.style.cssText = 'border:none; padding:6px 0;'; leer.textContent = 'An diesem Tag ist nichts eingetragen.'; box.appendChild(leer);
    return;
  }
  const ART = { aktion: '📌 Aktion', sitzung: '🗓️ Sitzung', frist: '⏰ Frist' };
  liste.forEach(function(e){
    const k = document.createElement('div'); k.className = 'kal-eintrag ' + e.art;
    const t = document.createElement('strong'); t.textContent = e.titel; k.appendChild(t);
    const z = document.createElement('div'); z.className = 'kal-zeile';
    z.textContent = ART[e.art] + ' · ' + e.uhr + (e.ort ? ' · ' + e.ort : ''); k.appendChild(z);
    if(e.info){ const i = document.createElement('div'); i.className = 'kal-zeile'; i.textContent = String(e.info).slice(0, 200); k.appendChild(i); }
    box.appendChild(k);
  });
}
// TYP_LABEL_ODER_NAME entfernt — a.typ ist seit der freien
// Aktions-Typen-Verwaltung bereits der Anzeigetext selbst.

// ICS-Kalenderexport: reines Frontend-Feature, kein Backend-Aufruf nötig.
// Nutzt die bereits geladenen vwAktionenCache-Daten (Kalender muss vorher
// einmal geöffnet worden sein, das passiert automatisch beim Draufklicken
// des Buttons, falls der Cache noch leer ist).
function icsEscape(text){
  return String(text || '')
    .replace(/\\/g, '\\\\')
    .replace(/;/g, '\\;')
    .replace(/,/g, '\\,')
    .replace(/\n/g, '\\n');
}
// Zufälliger Bestandteil für jede UID: verhindert, dass z.B. der
// Admin-Export und der Team-Export derselben Aktion die gleiche UID
// erzeugen. Gleiche UIDs führen bei erneutem Import (Google Kalender u.a.)
// dazu, dass der Import versucht, das bereits vorhandene Event zu ÄNDERN
// statt ein neues anzulegen — das schlägt dann mit "modification_failed"
// fehl. Mit einer pro Export einmalig gewürfelten Kennung legt jeder
// Import stattdessen zuverlässig ein neues Event an.
function icsZufaelligeKennung(){
  if(window.crypto && typeof window.crypto.randomUUID === 'function'){
    return window.crypto.randomUUID();
  }
  return 'r' + Math.random().toString(36).slice(2) + Date.now().toString(36);
}
function icsDateOhneBindestrich(iso){
  // erwartet 'YYYY-MM-DD', liefert 'YYYYMMDD'
  return String(iso).replace(/-/g, '');
}
function icsDatumPlusEinTag(iso){
  // DTEND bei Ganztags-Events ist exklusiv (DATE-Only-Konvention),
  // daher muss End-Datum + 1 Tag angegeben werden.
  const d = new Date(iso + 'T00:00:00');
  d.setDate(d.getDate() + 1);
  const jj = d.getFullYear();
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const tt = String(d.getDate()).padStart(2,'0');
  return `${jj}${mm}${tt}`;
}
// Uhrzeit-genaue Termine (Sitzungen): volles ISO-Datum/Uhrzeit (inkl.
// Zeitzonen-Offset, wie von Postgres timestamptz geliefert) in das von
// RFC 5545 verlangte UTC-Format YYYYMMDDTHHMMSSZ umrechnen.
function icsDatumZeitUtc(iso){
  return new Date(iso).toISOString().replace(/[-:]/g,'').split('.')[0] + 'Z';
}
// Sitzungen ohne eingetragenes Ende (Feld ist optional) bekommen im Export
// eine Standard-Dauer von 60 Minuten — reine Export-Annahme, ändert nichts
// an den in der App gespeicherten Daten.
function sitzungStandardEnde(beginnIso){
  const d = new Date(beginnIso);
  d.setMinutes(d.getMinutes() + 60);
  return d.toISOString();
}
// RFC 5545 verlangt max. 75 Oktette pro physischer Zeile; längere Inhalte
// (z.B. lange Aktionsnamen) müssen gefaltet werden (Folgezeile beginnt mit
// einem Leerzeichen). Ohne das lehnen manche Kalender-Apps (Google, Outlook,
// Apple Kalender) den Import mit Fehler ab, statt die Zeile zu kürzen.
function icsZeileFalten(zeile){
  const byteLaenge = s => new TextEncoder().encode(s).length;
  if(byteLaenge(zeile) <= 75) return [zeile];
  const ergebnis = [];
  let aktuell = '';
  let aktuellBytes = 0;
  let istErsteZeile = true;
  // Iteration über Codepoints (nicht UTF-16-Einheiten), damit kein
  // Mehrbyte-Zeichen mittendrin zerschnitten wird.
  for(const zeichen of zeile){
    const zeichenBytes = byteLaenge(zeichen);
    const limit = istErsteZeile ? 75 : 74; // Folgezeile: 1 Byte für das führende Leerzeichen reservieren
    if(aktuellBytes + zeichenBytes > limit && aktuell.length > 0){
      ergebnis.push(istErsteZeile ? aktuell : ' '+aktuell);
      aktuell = '';
      aktuellBytes = 0;
      istErsteZeile = false;
    }
    aktuell += zeichen;
    aktuellBytes += zeichenBytes;
  }
  if(aktuell.length > 0) ergebnis.push(istErsteZeile ? aktuell : ' '+aktuell);
  return ergebnis;
}
// erzeugeIcsInhalt: nimmt normalisierte "Termin"-Objekte entgegen (siehe
// aktionZuTermin/sitzungZuTermin) — Ganztags-Termine (Aktionen) UND
// uhrzeit-genaue Termine (Sitzungen) in einer Datei gemischt möglich.
function erzeugeIcsInhalt(termine){
  const jetztStamp = icsDatumZeitUtc(new Date().toISOString());
  const exportKennung = icsZufaelligeKennung();
  const zeilen = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//AWO Jugendwerk Erftstadt//Ferienspiele-Planung//DE',
    'CALSCALE:GREGORIAN',
  ];
  termine.forEach(t=>{
    if(!t.startIso) return;
    zeilen.push(
      'BEGIN:VEVENT',
      `UID:${t.uidPrefix}-${t.id}-${exportKennung}@ferienspiele-planung.awo-jugendwerk-erftstadt`,
      `DTSTAMP:${jetztStamp}`,
    );
    if(t.allDay){
      zeilen.push(
        `DTSTART;VALUE=DATE:${icsDateOhneBindestrich(t.startIso)}`,
        `DTEND;VALUE=DATE:${icsDatumPlusEinTag(t.endIso || t.startIso)}`,
      );
    } else {
      zeilen.push(
        `DTSTART:${icsDatumZeitUtc(t.startIso)}`,
        `DTEND:${icsDatumZeitUtc(t.endIso || sitzungStandardEnde(t.startIso))}`,
      );
    }
    zeilen.push(`SUMMARY:${icsEscape(t.titel)}`);
    if(t.beschreibung){
      zeilen.push(`DESCRIPTION:${icsEscape(t.beschreibung)}`);
    }
    if(t.ort){
      zeilen.push(`LOCATION:${icsEscape(t.ort)}`);
    }
    zeilen.push('END:VEVENT');
  });
  zeilen.push('END:VCALENDAR');
  // Jede logische Zeile ggf. falten (siehe icsZeileFalten), dann mit CRLF
  // verbinden — inklusive abschließendem CRLF nach der letzten Zeile, da
  // manche Kalender-Apps eine Datei ohne Zeilenumbruch am Ende ablehnen.
  const gefaltet = zeilen.flatMap(icsZeileFalten);
  return gefaltet.join('\r\n') + '\r\n';
}
document.getElementById('vwKalenderAlleBtn').addEventListener('click', ()=>{
  vwKalenderAuswahl = new Set(vwKalenderAlleTermineCache.map(t=>t.key));
  document.querySelectorAll('.vwKalenderCheckbox').forEach(cb=>cb.checked = true);
});
document.getElementById('vwKalenderKeineBtn').addEventListener('click', ()=>{
  vwKalenderAuswahl = new Set();
  document.querySelectorAll('.vwKalenderCheckbox').forEach(cb=>cb.checked = false);
});
document.getElementById('vwKalenderIcsExportBtn').addEventListener('click', async ()=>{
  const btn = document.getElementById('vwKalenderIcsExportBtn');
  const alterText = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Erzeuge Datei…';
  try{
    const ausgewaehlt = vwKalenderAlleTermineCache.filter(t=>vwKalenderAuswahl.has(t.key));
    if(ausgewaehlt.length === 0){
      alert('Keine Termine ausgewählt — bitte mindestens einen Termin ankreuzen.');
      return;
    }
    const inhalt = erzeugeIcsInhalt(ausgewaehlt);
    const blob = new Blob([inhalt], {type: 'text/calendar;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ferienspiele-termine_${stamp()}.ics`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }catch(e){
    alert('Fehler beim Erzeugen der Kalenderdatei: ' + e.message);
  }finally{
    btn.disabled = false;
    btn.textContent = alterText;
  }
});

document.getElementById('teamKalenderIcsExportBtn').addEventListener('click', ()=>{
  const btn = document.getElementById('teamKalenderIcsExportBtn');
  if(teamFreigeschalteteFuerIcsExport.length === 0){
    alert('Keine deiner freigeschalteten Aktionen hat einen Termin — nichts zu exportieren.');
    return;
  }
  const alterText = btn.textContent;
  try{
    const inhalt = erzeugeIcsInhalt(teamFreigeschalteteFuerIcsExport.map(aktionZuTermin));
    const blob = new Blob([inhalt], {type: 'text/calendar;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `meine-termine_${stamp()}.ics`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }catch(e){
    alert('Fehler beim Erzeugen der Kalenderdatei: ' + e.message);
  }
});

async function ladeAllgZugriffListe(){
  const listeEl = document.getElementById('allgZugriffListe');
  const selectEl = document.getElementById('allgZugriffKarteiSelect');
  listeEl.textContent = 'Lädt…';
  try{
    const [zugriffJson, karteiJson] = await Promise.all([
      epCallOhneAktion({action:'admin_allgemein_zugriff_liste', pass: currentAuthPass}),
      epCallOhneAktion({action:'admin_personen_list', pass: currentAuthPass}),
    ]);
    const zugriffe = zugriffJson.zugriffe || [];
    const kartei = karteiJson.personen || [];
    if(zugriffe.length === 0){
      listeEl.innerHTML = '<p style="color:#7a7266;">Noch niemandem Zugriff gewährt.</p>';
    } else {
      listeEl.innerHTML = '';
      zugriffe.forEach(z=>{
        const zeile = document.createElement('div');
        zeile.style.cssText = 'display:flex; align-items:center; gap:6px; margin-bottom:6px;';
        const name = z.person ? `${z.person.vorname} ${z.person.nachname}` : z.person_id;
        const label = document.createElement('span');
        label.style.flex = '1';
        label.textContent = name;
        zeile.appendChild(label);
        const entziehenBtn = document.createElement('button');
        entziehenBtn.className = 'btn ghost';
        entziehenBtn.textContent = 'Zugriff entziehen';
        entziehenBtn.addEventListener('click', async ()=>{
          try{
            await epCallOhneAktion({action:'admin_allgemein_zugriff_setzen', pass: currentAuthPass, personId: z.person_id, gewaehrt: false});
            ladeAllgZugriffListe();
          }catch(e){ document.getElementById('allgError').textContent = 'Fehler: '+e.message; }
        });
        zeile.appendChild(entziehenBtn);
        listeEl.appendChild(zeile);
      });
    }
    // Dropdown nur mit Personen ohne bereits bestehenden Zugriff befüllen.
    const bereitsIds = new Set(zugriffe.map(z=>z.person_id));
    const auswahl = kartei.filter(p=>!bereitsIds.has(p.id));
    selectEl.innerHTML = '<option value="">– Person auswählen –</option>' +
      auswahl.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.vorname+' '+p.nachname)}</option>`).join('');
  }catch(e){
    listeEl.innerHTML = '';
    document.getElementById('allgError').textContent = 'Fehler beim Laden der Zugriffsliste: '+e.message;
  }
}
document.getElementById('allgZugriffGewaehrenBtn').addEventListener('click', async ()=>{
  const personId = document.getElementById('allgZugriffKarteiSelect').value;
  if(!personId) return;
  try{
    await epCallOhneAktion({action:'admin_allgemein_zugriff_setzen', pass: currentAuthPass, personId, gewaehrt: true});
    ladeAllgZugriffListe();
  }catch(e){
    document.getElementById('allgError').textContent = 'Fehler beim Gewähren: '+e.message;
  }
});

// ================================================================
// ADMIN: Aktion verwalten (Module, Sichtbarkeit, Freischaltungen)
// ================================================================
let avAktuelleAktion = null;

// Reiter in "Aktion verwalten" (reine Anzeige, ändert keine Daten)
function avZeigeTab(key){
  document.querySelectorAll('#aktionVerwaltenScreen .av-panel').forEach(function(p){ p.style.display = (p.id==='avPanel_'+key) ? '' : 'none'; });
  document.querySelectorAll('#aktionVerwaltenScreen .av-tab').forEach(function(b){
    var aktiv = b.getAttribute('data-avtab')===key;
    b.setAttribute('aria-selected', aktiv ? 'true' : 'false');
    b.style.background = aktiv ? 'var(--awo-red, #E2001A)' : '';
    b.style.color = aktiv ? '#fff' : '';
  });
  var e=document.getElementById('avError'); if(e) e.textContent='';
}
document.querySelectorAll('#aktionVerwaltenScreen .av-tab').forEach(function(b){
  b.addEventListener('click', function(){ avZeigeTab(b.getAttribute('data-avtab')); });
});
async function zeigeAktionVerwalten(aktion){
  avAktuelleAktion = aktion;
  avZeigeTab('grund');
  alleAuswahlScreensAusblenden();
  document.getElementById('aktionVerwaltenScreen').style.display = 'grid';
  document.getElementById('avError').textContent = '';
  document.getElementById('avAktionName').textContent = aktion.name;
  document.getElementById('avNameInput').value = aktion.name;
  document.getElementById('avOrtInput').value = aktion.ort || '';
  avLadeTypAuswahl(aktion.typ);
  document.getElementById('avLoeschenBereich').style.display = 'none';
  document.getElementById('avLoeschenNameEingabe').value = '';
  document.getElementById('avLoeschenNameSoll').textContent = aktion.name;
  avAktualisiereStatusAnzeige();
  document.getElementById('avSichtbarCheckbox').checked = !!aktion.sichtbar_fuer_interesse;
  avLadeSichtbarkeit(aktion);
  document.getElementById('avElternZugriffCheckbox').checked = !!aktion.eltern_zugriff;
  document.getElementById('avBenachrichtigungenAktivCheckbox').checked = aktion.benachrichtigungen_aktiv !== false;
  document.getElementById('avInfoText').value = aktion.info_fuer_interesse || '';
  document.getElementById('avEmailText').value = aktion.email_text || '';
  await ladeAvEmailVorlagenSelect();
  try{
    const oj = await epCallOhneAktion({action:'admin_oberaktionen_liste', pass: currentAuthPass});
    const sel = document.getElementById('avOberaktionSelect');
    sel.innerHTML = '<option value="">– keine –</option>' + (oj.oberaktionen||[]).filter(o=>!o.abgeschlossen_am || o.id===aktion.oberaktion_id)
      .map(o=>'<option value="' + escapeHtml(o.id) + '">' + escapeHtml(o.name) + '</option>').join('');
    sel.value = aktion.oberaktion_id || '';
  }catch(e){ /* Oberaktionen noch nicht verfügbar */ }
  document.getElementById('avBenoetigtePersonalInput').value = (aktion.benoetigte_personal===null || aktion.benoetigte_personal===undefined) ? '' : aktion.benoetigte_personal;
  document.getElementById('avStartDatumInput').value = aktion.start_datum || '';
  document.getElementById('avEndDatumInput').value = aktion.end_datum || '';
  document.getElementById('avOffiziellerBeginnInput').value = aktion.offizieller_beginn || '';
  document.getElementById('avOffiziellesEndeInput').value = aktion.offizielles_ende || '';
  // time-Spalten kommen von Supabase als "HH:MM:SS" — <input type="time">
  // akzeptiert auch "HH:MM:SS", daher kein Kürzen nötig.
  document.getElementById('avOffiziellerBeginnZeitInput').value = aktion.offizieller_beginn_zeit || '';
  document.getElementById('avOffiziellesEndeZeitInput').value = aktion.offizielles_ende_zeit || '';

  const module = aktion.aktive_module || {};
  const modulListe = document.getElementById('avModulListe');
  modulListe.innerHTML = '';
  Object.keys(MODUL_LABEL).forEach(key=>{
    const label = document.createElement('label');
    label.style.display = 'flex';
    label.style.alignItems = 'center';
    label.style.gap = '6px';
    label.style.fontWeight = 'normal';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.style.width = 'auto';
    checkbox.dataset.modulKey = key;
    checkbox.checked = !(key in module) || !!module[key];
    label.appendChild(checkbox);
    label.appendChild(document.createTextNode(MODUL_LABEL[key]));
    modulListe.appendChild(label);
  });

  const kacheln = aktion.aktive_dashboard_kacheln || {};
  const kachelListe = document.getElementById('avDashboardKachelnListe');
  kachelListe.innerHTML = '';
  Object.keys(DASHBOARD_KACHEL_LABEL).forEach(key=>{
    const label = document.createElement('label');
    label.style.display = 'flex';
    label.style.alignItems = 'center';
    label.style.gap = '6px';
    label.style.fontWeight = 'normal';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.style.width = 'auto';
    checkbox.dataset.kachelKey = key;
    checkbox.checked = !(key in kacheln) || !!kacheln[key];
    label.appendChild(checkbox);
    label.appendChild(document.createTextNode(DASHBOARD_KACHEL_LABEL[key]));
    kachelListe.appendChild(label);
  });

  await avLadeFreischaltungen(aktion.id);
}

async function avLadeFreischaltungen(aktionId){
  const listeEl = document.getElementById('avFreischaltungListe');
  const standEl = document.getElementById('avPersonalStandAnzeige');
  listeEl.textContent = 'Lädt…';
  standEl.textContent = '';
  try{
    const json = await epCallOhneAktion({action:'admin_freischaltung_liste', pass: currentAuthPass, aktionId});
    const zugriffe = json.zugriffe || [];
    const anzahlFreigeschaltet = zugriffe.filter(z=>z.status==='freigeschaltet').length;
    const bedarf = avAktuelleAktion ? avAktuelleAktion.benoetigte_personal : null;
    if(bedarf===null || bedarf===undefined){
      standEl.textContent = `${anzahlFreigeschaltet} freigeschaltet (kein Personalbedarf festgelegt).`;
    } else if(anzahlFreigeschaltet >= bedarf){
      standEl.textContent = `${anzahlFreigeschaltet} von ${bedarf} — voll ✓`;
      standEl.style.color = '#3E8E4A';
    } else {
      standEl.textContent = `${anzahlFreigeschaltet} von ${bedarf} — noch ${bedarf-anzahlFreigeschaltet} gesucht`;
      standEl.style.color = '#7a7266';
    }
    if(zugriffe.length === 0){
      listeEl.innerHTML = '<p style="color:#7a7266;">Noch niemand hat Interesse angemeldet.</p>';
      return;
    }
    listeEl.innerHTML = '';
    zugriffe.forEach(z=>{
      const zeile = document.createElement('div');
      zeile.style.display = 'flex';
      zeile.style.alignItems = 'center';
      zeile.style.gap = '6px';
      zeile.style.marginBottom = '6px';
      const name = z.person ? `${z.person.vorname} ${z.person.nachname}` : z.person_id;
      const label = document.createElement('span');
      label.style.flex = '1';
      label.textContent = name + (z.status==='freigeschaltet' ? ' — freigeschaltet ✓' : ' — hat Interesse angemeldet');
      zeile.appendChild(label);
      const btn = document.createElement('button');
      btn.className = 'btn ghost';
      btn.textContent = z.status === 'freigeschaltet' ? 'Zugriff entziehen' : 'Freischalten';
      btn.addEventListener('click', async ()=>{
        try{
          await epCallOhneAktion({action:'admin_freischaltung_setzen', pass: currentAuthPass, aktionId, personId: z.person_id, freigeschaltet: z.status !== 'freigeschaltet'});
          avLadeFreischaltungen(aktionId);
        }catch(e){
          document.getElementById('avError').textContent = 'Fehler: '+e.message;
        }
      });
      zeile.appendChild(btn);
      listeEl.appendChild(zeile);
    });
  }catch(e){
    listeEl.innerHTML = '';
    document.getElementById('avError').textContent = 'Fehler beim Laden: '+e.message;
  }
}

