    // muss die Änderung SOFORT wirken — sonst bleiben Nav-Reiter und die
    // Anleitung-Liste (die beide von currentAktionInfo.aktive_module lesen,
    // siehe applyModulFilter/modulAktiv) auf dem alten Stand, bis man die
    // Aktion verlässt und neu betritt.
    if(currentAktionInfo && currentAktionInfo.id === avAktuelleAktion.id){
      currentAktionInfo.aktive_module = aktiveModule;
      applyModulFilter(currentAktionInfo);
      renderAnleitung();
    }
    document.getElementById('avError').textContent = '';
    document.getElementById('avError').style.color = '#3E8E4A';
    document.getElementById('avError').textContent = 'Gespeichert.';
