// hier zum Auswählen anbieten — nutzt denselben Cache (emailVorlagenCache),
// damit die Liste nicht doppelt gepflegt werden muss.
async function ladeAvEmailVorlagenSelect(){
  const select = document.getElementById('avEmailVorlageSelect');
  if(!select) return;
  if(!emailVorlagenGeladen){
    try{
      const json = await epCallOhneAktion({action:'admin_email_vorlagen_list', pass: currentAuthPass});
      emailVorlagenCache = json.vorlagen || [];
      emailVorlagenGeladen = true;
    }catch(e){
      console.error('E-Mail-Vorlagen konnten nicht geladen werden:', e);
      return;
    }
  }
  select.innerHTML = '<option value="">— Vorlage auswählen —</option>' +
    emailVorlagenCache.map(v=>`<option value="${escapeHtml(v.id)}">${escapeHtml(v.titel)}</option>`).join('');
}
