document.getElementById('avElternLinkKopierenBtn').addEventListener('click', async ()=>{
  if(!avAktuelleAktion) return;
  // Basis-URL ohne bestehende Query-Parameter (z.B. ?aktion=... vom aktuell
  // offenen Team/Admin-Kontext), damit der kopierte Link garantiert nur den
  // Eltern-relevanten Parameter enthält.
  const basisUrl = location.origin + location.pathname;
  const link = `${basisUrl}?aktion=${avAktuelleAktion.id}`;
  try{
    await navigator.clipboard.writeText(link);
    document.getElementById('avError').style.color = '#3E8E4A';
    document.getElementById('avError').textContent = 'Eltern-Link kopiert: ' + link;
  }catch(err){
    // Clipboard-API kann z.B. ohne HTTPS/Berechtigung fehlschlagen — Link
    // dann wenigstens sichtbar anzeigen, statt stillschweigend nichts zu tun.
    document.getElementById('avError').style.color = '';
    document.getElementById('avError').textContent = 'Kopieren fehlgeschlagen. Link: ' + link;
  }
});
