// avAktualisiereStatusAnzeige: aktualisiert Text/Button je nach Status
// der aktuell verwalteten Aktion. Wird beim Öffnen des Screens und nach
// jedem Statuswechsel aufgerufen.
function avAktualisiereStatusAnzeige(){
  if(!avAktuelleAktion) return;
  const abgeschlossen = avAktuelleAktion.status === 'abgeschlossen';
  document.getElementById('avStatusAnzeige').textContent = abgeschlossen ? 'Abgeschlossen (schreibgeschützt)' : 'Aktiv';
  document.getElementById('avStatusToggleBtn').textContent = abgeschlossen ? 'Aktion reaktivieren' : 'Aktion abschließen';
}
document.getElementById('avStatusToggleBtn').addEventListener('click', async ()=>{
  if(!avAktuelleAktion) return;
  const neuerStatus = avAktuelleAktion.status === 'abgeschlossen' ? 'aktiv' : 'abgeschlossen';
  const frage = neuerStatus === 'abgeschlossen'
    ? `"${avAktuelleAktion.name}" wirklich abschließen? Die Aktion wird danach schreibgeschützt. Anschließend wird automatisch ein Abschluss-Archiv (PDF) heruntergeladen.`
    : `"${avAktuelleAktion.name}" wieder aktivieren? Team und Admin können danach wieder Änderungen vornehmen.`;
  if(!(await bestaetigen(frage))) return;
  try{
    const json = await epCallOhneAktion({action:'admin_aktionen_status_setzen', pass: currentAuthPass, aktionId: avAktuelleAktion.id, status: neuerStatus});
    avAktuelleAktion.status = (json.aktion && json.aktion.status) || neuerStatus;
    avAktualisiereStatusAnzeige();
    document.getElementById('avError').style.color = '#3E8E4A';
    document.getElementById('avError').textContent = neuerStatus === 'abgeschlossen' ? 'Aktion abgeschlossen.' : 'Aktion reaktiviert.';
    if(neuerStatus === 'abgeschlossen'){
      document.getElementById('avError').textContent += ' Abschluss-Archiv wird erstellt…';
      try{
        await erstelleUndLadeAbschlussArchiv(avAktuelleAktion);
        document.getElementById('avError').textContent = 'Aktion abgeschlossen. Abschluss-Archiv wurde heruntergeladen.';
      }catch(archivFehler){
        console.error('Abschluss-Archiv konnte nicht erstellt werden:', archivFehler);
        document.getElementById('avError').textContent = 'Aktion abgeschlossen — Abschluss-Archiv konnte aber nicht erstellt werden (' + archivFehler.message + '). Die Aktion selbst ist trotzdem abgeschlossen.';
      }
    }
  }catch(e){
    document.getElementById('avError').style.color = '';
    document.getElementById('avError').textContent = 'Fehler beim Ändern des Status: '+e.message;
  }
});
