// findTodayDay: sucht unter allen regulären Programmtagen den mit heutigem Datum
function findTodayDay(){
  const today = todayIso();
  for(const week of state.weeks){
    const day = week.days.find(d=>d.date===today);
    if(day) return {week, day};
  }
  return null;
}
function switchToTab(tab){
  if(tab==='verlauf' && !isAdmin()) return; // Verlauf nur für Admin — egal von wo aus versucht
  document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  document.querySelectorAll('.main section').forEach(s=>s.style.display='none');
  document.getElementById('tab-'+tab).style.display='block';
  if(tab==='kinder') renderKinderAdmin();
  if(tab==='umfragen'){ renderUmfragenAdmin(); renderHinweiseAdmin(); renderLaeuseAdmin(); }
  if(tab==='gruppen' && isAdmin()) ladeKinderGruppenBedarf();
  if(tab==='anleitung') renderAnleitung();
  if(tab==='wuensche') renderWuensche();
  if(tab==='verfuegbarkeit') renderVerfuegbarkeit();
  if(tab==='feedback') renderFeedback();
  if(tab==='aufgaben') renderAufgaben();
  if(tab==='personal' && isAdmin()){ ladePersonenKartei(); renderFormaleRolle(); }
}

// ---- WETTER (Open-Meteo, kostenlos & ohne API-Key) ----
const WETTER_LAT = 50.8158, WETTER_LON = 6.7556; // Erftstadt
let weatherCache = null; // {fetchedAt, byDate:{iso:{code,tmax,tmin,precip}}}

async function ensureWeather(){
  const now = Date.now();
  if(weatherCache && (now - weatherCache.fetchedAt) < 30*60*1000) return weatherCache;
  try{
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${WETTER_LAT}&longitude=${WETTER_LON}&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=Europe%2FBerlin&forecast_days=16`;
    const res = await fetch(url);
    const data = await res.json();
    const byDate = {};
    (data.daily?.time || []).forEach((iso, i)=>{
      byDate[iso] = {
        code: data.daily.weathercode[i],
        tmax: Math.round(data.daily.temperature_2m_max[i]),
        tmin: Math.round(data.daily.temperature_2m_min[i]),
        precip: data.daily.precipitation_probability_max[i]
      };
    });
    weatherCache = {fetchedAt: now, byDate};
  }catch(e){
    console.error('Wetter-Abruf fehlgeschlagen:', e);
    if(!weatherCache) weatherCache = {fetchedAt: now, byDate:{}};
  }
  return weatherCache;
}

// weatherIcon: WMO-Wettercode grob in ein Emoji übersetzen
function weatherIcon(code){
  if(code===0) return '☀️';
  if([1,2].includes(code)) return '🌤️';
  if(code===3) return '☁️';
  if([45,48].includes(code)) return '🌫️';
  if([51,53,55,56,57,80,81,82].includes(code)) return '🌦️';
  if([61,63,65,66,67].includes(code)) return '🌧️';
  if([71,73,75,77,85,86].includes(code)) return '❄️';
  if([95,96,99].includes(code)) return '⛈️';
  return '🌡️';
}

// naechsteSechsKalenderTage: generische Vorhersage ab heute, unabhängig von
// Aktionsterminen. Bewusst KEIN d.toISOString() zur Datumsbildung — das
// rechnet intern auf UTC um und verschiebt bei Sommerzeit (UTC+2) jedes
// Datum um einen Tag zurück, wodurch es nicht mehr zu den Schlüsseln in
// wx.byDate passt (die, wie todayIso(), lokale Kalendertage sind) — genau
// der Bug, der die Kachel trotz "Fallback" leer ließ (08/2026).
function naechsteSechsKalenderTage(){
  const tage = [];
  const pad = n => String(n).padStart(2,'0');
  const d = new Date();
  for(let i=0;i<6;i++){
    const iso = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
    tage.push({date:iso, label:`${isoWeekdayShort(iso)} ${fmtDate(iso)}`});
    d.setDate(d.getDate()+1);
  }
  return tage;
}

// renderWeatherCard: baut die Wetter-Kachel und füllt sie asynchron nach,
// sobald die Vorhersage geladen ist (Karte zeigt bis dahin "Lade…").
// Zeigt primär die nächsten Ferienspiele-/Aktionstage (mit Datum). Fallback
// auf die generische 6-Tage-Vorhersage ab heute in ZWEI Fällen, damit die
// Kachel NIE leer/nutzlos bleibt:
//  1) Keine anstehenden Aktionstage mit Datum gefunden (z.B. Aktion vorbei,
//     oder interne Veranstaltung ohne durchgehende Tages-Termine).
//  2) Anstehende Aktionstage gefunden, aber ALLE liegen außerhalb des von
//     Open-Meteo abgedeckten 16-Tage-Zeitraums (z.B. Aktion erst in einigen
//     Monaten) — sonst zeigt jede Zelle nur "außerhalb Vorhersage", was
//     faktisch auch "kein Wetter" ist (Rückmeldung 08/2026).
async function renderWeatherCard(container){
  const card = document.createElement('div');
  card.className = 'dash-card dash-wide';
  card.innerHTML = `<div class="dash-label" style="margin-bottom:6px;">Wetter Erftstadt</div><div class="dash-empty">Lade Vorhersage…</div>`;
  container.appendChild(card);

  const today = todayIso();
  const upcoming = [];
  state.weeks.forEach(week=>{
    week.days.forEach(day=>{ if(day.date && day.date >= today) upcoming.push({date:day.date, label:`${isoWeekdayShort(day.date)} ${fmtDate(day.date)}`}); });
  });
  (state.zusatzTage||[]).forEach(z=>{
    if(z.date && z.date >= today) upcoming.push({date:z.date, label:`${isoWeekdayShort(z.date)} ${fmtDate(z.date)}${z.label?' · '+z.label:''}`});
  });
  upcoming.sort((a,b)=>a.date.localeCompare(b.date));
  let nextDays = upcoming.slice(0,6);
  let ueberschrift = 'Wetter Erftstadt — nächste Ferienspiele-Tage';

  if(nextDays.length===0){
    nextDays = naechsteSechsKalenderTage();
    ueberschrift = 'Wetter Erftstadt — nächste Tage';
  }

  const wx = await ensureWeather();

  // Fall 2: Aktionstage gefunden, aber keiner davon von der Vorhersage
  // abgedeckt (zu weit in der Zukunft) — auf die generische Vorhersage
  // umschwenken, statt eine Kachel voller "außerhalb Vorhersage" zu zeigen.
  if(!nextDays.some(d=>wx.byDate[d.date])){
    nextDays = naechsteSechsKalenderTage();
    ueberschrift = 'Wetter Erftstadt — nächste Tage (Aktionstermin liegt außerhalb der 16-Tage-Vorhersage)';
  }

  const cells = nextDays.map(d=>{
    const w = wx.byDate[d.date];
    if(!w){
      return `<div style="text-align:center; min-width:90px;"><div style="font-size:0.75rem; color:var(--ink-soft);">${escapeHtml(d.label)}</div><div style="font-size:0.75rem; color:var(--ink-soft); margin-top:6px;">außerhalb Vorhersage</div></div>`;
    }
    return `<div style="text-align:center; min-width:90px;">
      <div style="font-size:0.75rem; color:var(--ink-soft);">${escapeHtml(d.label)}</div>
      <div style="font-size:1.6rem; margin-top:2px;">${weatherIcon(w.code)}</div>
      <div style="font-size:0.85rem; font-weight:600;">${w.tmax}° / ${w.tmin}°</div>
      <div style="font-size:0.7rem; color:var(--ink-soft);">☔ ${w.precip ?? '–'}%</div>
    </div>`;
  }).join('');
  card.innerHTML = `
    <div class="dash-label" style="margin-bottom:10px;">${escapeHtml(ueberschrift)}</div>
    <div style="display:flex; gap:18px; flex-wrap:wrap;">${cells}</div>
  `;
}

// ---- KONFLIKT-ERKENNUNG PERSONAL/GRUPPEN ----
// levenshtein: einfache Editier-Distanz für Tippfehler-Erkennung
function levenshtein(a, b){
  const m = a.length, n = b.length;
  const d = Array.from({length:m+1}, (_,i)=>[i, ...Array(n).fill(0)]);
  for(let j=0;j<=n;j++) d[0][j]=j;
  for(let i=1;i<=m;i++){
    for(let j=1;j<=n;j++){
      d[i][j] = a[i-1]===b[j-1] ? d[i-1][j-1] : 1 + Math.min(d[i-1][j], d[i][j-1], d[i-1][j-1]);
    }
  }
  return d[m][n];
}
function normName(s){ return (s||'').trim().toLowerCase().replace(/\s+/g,' '); }

// simpleHash: erzeugt eine stabile, kurze ID aus einem Text (für Dismiss-Zuordnung)
function simpleHash(str){
  let h = 0;
  for(let i=0;i<str.length;i++){ h = ((h<<5)-h) + str.charCodeAt(i); h |= 0; }
  return 'c' + Math.abs(h).toString(36);
}

function computeConflicts(){
  const conflicts = [];
  const personalList = (state.personal||[]).filter(p=>Array.isArray(p.einsatzTage));
  const gruppenList = (state.gruppen||[]).filter(g=>g.zuordnung);

  // a) Gruppen-Zuordnung ohne passenden Personaleinsatz in der Woche
  // (Springer/Flex-markierte Personen werden bewusst ausgenommen — die
  // haben noch keine festen Tage und sollen keinen Konflikt auslösen).
  // Funktioniert weiterhin für bestehende, historisch an feste Wochentage
  // gebundene Einsatzeinträge (deren IDs seit der Umstellung auf freie
  // Einsatztage NICHT mehr verändert werden). Neu über die freien
  // Einsatztage eingetragene Tage lösen hier bewusst keinen Wochen-Konflikt
  // aus, da sie keiner der drei Ferienspiele-Wochen mehr fest zugeordnet sind.
  state.weeks.forEach(week=>{
    const weekDayIds = new Set(week.days.map(d=>d.id));
    gruppenList.forEach(g=>{
      if(!g.zuordnung[week.id]) return;
      if(g.istPlatzhalter) return;
      const match = personalList.find(p=>normName(p.name)===normName(g.name));
      const hasEinsatzThisWeek = match && match.einsatzTage.some(id=>weekDayIds.has(id));
      if(!hasEinsatzThisWeek){
        conflicts.push({
          level:'warn',
          text: `${g.name}: in ${week.label} einer Gruppe zugeordnet, aber ${match ? 'kein Einsatztag in dieser Woche eingetragen' : 'nicht im Personaleinsatz zu finden'}.`,
          tab:'gruppen'
        });
      }
    });
  });

  // b) Personaleinsatz ohne Gruppen-Zuordnung in der Woche (informativ, schwächer)
  state.weeks.forEach(week=>{
    const weekDayIds = new Set(week.days.map(d=>d.id));
    personalList.forEach(p=>{
      const worksThisWeek = p.einsatzTage.some(id=>weekDayIds.has(id));
      if(!worksThisWeek) return;
      const match = gruppenList.find(g=>normName(g.name)===normName(p.name));
      const hasGroupThisWeek = match && match.zuordnung[week.id];
      if(!hasGroupThisWeek){
        conflicts.push({
          level:'info',
          text: `${p.name}: in ${week.label} im Personaleinsatz, aber keiner Gruppe zugeordnet.`,
          tab:'personal'
        });
      }
    });
  });

  // c) Mögliche Tippfehler zwischen den beiden Namenslisten
  const gruppenNames = [...new Set(gruppenList.map(g=>g.name))];
  const personalNames = [...new Set(personalList.map(p=>p.name))];
  gruppenNames.forEach(gn=>{
    personalNames.forEach(pn=>{
      if(normName(gn)===normName(pn)) return;
      if(gn.length<3 || pn.length<3) return;
      const dist = levenshtein(normName(gn), normName(pn));
      if(dist>0 && dist<=2){
        conflicts.push({
          level:'warn',
          text: `Möglicher Tippfehler: „${gn}“ (Gruppen) vs. „${pn}“ (Personal) — dieselbe Person?`,
          tab:'personal'
        });
      }
    });
  });

  // d) Doppelte Namen innerhalb einer Liste
  function findDupes(list, tab){
    const seen = {};
    list.forEach(name=>{
      const key = normName(name);
      seen[key] = (seen[key]||0)+1;
    });
    Object.keys(seen).forEach(key=>{
      if(seen[key]>1){
        const original = list.find(n=>normName(n)===key);
        conflicts.push({level:'warn', text:`„${original}“ ist mehrfach eingetragen.`, tab});
      }
    });
  }
  findDupes(gruppenNames.length?gruppenList.map(g=>g.name):[], 'gruppen');
  findDupes(personalList.map(p=>p.name), 'personal');

  conflicts.forEach(c=>{ c.id = simpleHash(c.tab+'|'+c.level+'|'+c.text); });
  return conflicts;
}

let showDismissedConflicts = false;

function renderConflictsCard(container){
  const all = computeConflicts();
  const dismissedIds = new Set(state.dismissedConflicts||[]);
  const active = all.filter(c=>!dismissedIds.has(c.id));
  const dismissed = all.filter(c=>dismissedIds.has(c.id));

  const card = document.createElement('div');
  card.className = 'dash-card dash-wide';

  const dismissedNote = (isAdmin() && dismissed.length>0)
    ? `<div style="margin-top:10px;"><span class="dp-chip" id="toggleDismissed" style="cursor:pointer;">${dismissed.length} ausgeblendete${dismissed.length>1?'':'r'} Konflikt${dismissed.length>1?'e':''} ${showDismissedConflicts?'verbergen':'anzeigen'}</span></div>`
    : '';

  if(active.length===0){
    card.innerHTML = `<div class="dash-label" style="margin-bottom:6px;">Konflikt-Prüfung Personal/Gruppen</div><div class="dash-empty">Keine aktiven Konflikte. ✓</div>${dismissedNote}`;
  } else {
    card.style.borderColor = 'var(--awo-red)';
    card.innerHTML = `
      <div class="dash-label" style="margin-bottom:6px; color:var(--awo-red);">⚠️ ${active.length} Konflikt${active.length>1?'e':''} gefunden</div>
      <ul style="list-style:none; padding-left:0;">${active.map(c=>`
        <li style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; padding:4px 0; ${c.level==='info'?'color:var(--ink-soft);':''}">
          <span>${escapeHtml(c.text)}</span>
          ${isAdmin() ? `<button class="del" data-dismiss="${c.id}" title="Als geprüft ausblenden" style="white-space:nowrap;">✓ ok</button>` : ''}
        </li>`).join('')}</ul>
      ${dismissedNote}
    `;
  }

  if(isAdmin() && showDismissedConflicts && dismissed.length>0){
    const box = document.createElement('div');
    box.style.cssText = 'margin-top:8px; padding-top:8px; border-top:1px solid var(--line);';
    box.innerHTML = dismissed.map(c=>`
      <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; padding:4px 0; opacity:.6; font-size:0.85rem;">
        <span>${escapeHtml(c.text)}</span>
        <button class="del" data-restore="${c.id}" style="white-space:nowrap;">Wiederherstellen</button>
      </div>`).join('');
    card.appendChild(box);
  }

  card.querySelectorAll('[data-dismiss]').forEach(btn=>{
    btn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      const id = btn.dataset.dismiss;
      const conflictText = all.find(c=>c.id===id)?.text || '';
      await commit(s=>{
        if(!Array.isArray(s.dismissedConflicts)) s.dismissedConflicts = [];
        if(!s.dismissedConflicts.includes(id)) s.dismissedConflicts.push(id);
      }, 'System', `Konflikt als geprüft ausgeblendet: ${conflictText}`, null);
      renderDashboard();
    });
  });
  card.querySelectorAll('[data-restore]').forEach(btn=>{
    btn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      const id = btn.dataset.restore;
      const conflictText = all.find(c=>c.id===id)?.text || '';
      await commit(s=>{
        s.dismissedConflicts = (s.dismissedConflicts||[]).filter(x=>x!==id);
      }, 'System', `Konflikt wiederhergestellt: ${conflictText}`, null);
      renderDashboard();
    });
  });
  const toggle = card.querySelector('#toggleDismissed');
  if(toggle){
    toggle.addEventListener('click', (e)=>{
      e.stopPropagation();
      showDismissedConflicts = !showDismissedConflicts;
      renderDashboard();
    });
  }

  container.appendChild(card);
}

// Lade-Sperre fürs Kinderzahlen-Cache, damit das Dashboard nicht parallel
// zum Gruppen-Tab denselben Ladevorgang mehrfach anstößt.
let kinderBedarfLoading = false;
// Cache für die "Teamende (freigeschaltet)"-Kachel — lazy geladen, analog
// zu den anderen Dashboard-Karten (kinderGruppenBedarfCache, Nachweise, ...).
let teamendeFreigeschaltetCache = null;
let teamendeFreigeschaltetLoading = false;

function renderDashboard(){
  const dashEl = document.getElementById('dashboard');
  if(!dashEl) return;

  const today = todayIso();
  const todayInfo = findTodayDay();
  const todayZusatz = (state.zusatzTage||[]).find(z=>z.date===today);

  document.getElementById('dash-greeting').textContent = myName ? `Hallo ${myName}!` : 'Übersicht';
  document.getElementById('dash-date').textContent =
    `${isoWeekdayShort(today)}, ${fmtDateFull(today)}` +
    (todayInfo ? ` — ${todayInfo.week.label}` : (todayZusatz ? ` — Zusatztag${todayZusatz.label?' ('+todayZusatz.label+')':''}` : ' — außerhalb der Ferienspiele-Zeit'));

  // Offizieller Beginn/Ende (Migration 65): unabhängig vom Arbeitszeitraum
  // (start_datum/end_datum), nur wenn mindestens eins der beiden Felder
  // gesetzt ist. Aktuell bewusst nur hier sichtbar (Teamende/Admin
  // innerhalb der Aktion), nicht im Eltern-Zugang/Kalender-Export.
  const ozEl = document.getElementById('dash-offizieller-zeitraum');
  const oBeginn = currentAktionInfo && currentAktionInfo.offizieller_beginn;
  const oEnde = currentAktionInfo && currentAktionInfo.offizielles_ende;
  const oBeginnZeit = currentAktionInfo && currentAktionInfo.offizieller_beginn_zeit;
  const oEndeZeit = currentAktionInfo && currentAktionInfo.offizielles_ende_zeit;
  if(oBeginn || oEnde){
    // fmtDatumMitZeit: Datum, optional gefolgt von "HH:MM Uhr" (Uhrzeit-
    // Spalten kommen als "HH:MM:SS", daher auf 5 Zeichen kürzen).
    const fmtDatumMitZeit = (datum, zeit) => datum
      ? fmtDateFull(datum) + (zeit ? `, ${zeit.slice(0,5)} Uhr` : '')
      : '';
    const zeitraumText = (oBeginn && oEnde)
      ? (oBeginn === oEnde && !oBeginnZeit && !oEndeZeit
          ? fmtDateFull(oBeginn)
          : `${fmtDatumMitZeit(oBeginn, oBeginnZeit)} – ${fmtDatumMitZeit(oEnde, oEndeZeit)}`)
      : fmtDatumMitZeit(oBeginn || oEnde, oBeginn ? oBeginnZeit : oEndeZeit);
    ozEl.textContent = `📅 Offiziell: ${zeitraumText}`;
    ozEl.style.display = 'block';
  } else {
    ozEl.style.display = 'none';
  }

  // Dokumente (Migration 67): globale + dieser Aktion zugeordnete
  // Dokumente, die für Team freigeschaltet sind. Einmal pro Aktion
  // geladen (Cache über dashDokumenteAktionId), damit renderDashboard()
  // trotz häufiger Aufrufe nicht bei jedem Klick neu nachfragt.
  if(currentAktionId && dashDokumenteAktionId !== currentAktionId && !dashDokumenteLoading){
    dashDokumenteLoading = true;
    dashDokumenteAktionId = currentAktionId;
    dokListeRenderFuerRolle('dash-dokumente-liste', 'team', currentAktionId, teamPersonId).then(()=>{
      dashDokumenteLoading = false;
      const wrapEl = document.getElementById('dash-dokumente-wrap');
      const listeEl = document.getElementById('dash-dokumente-liste');
      if(wrapEl && listeEl) wrapEl.style.display = listeEl.innerHTML.trim() ? 'block' : 'none';
    });
  }

  const grid = document.createElement('div');
  grid.className = 'dash-grid';

  // Oben: Wetter
  if(dashboardKachelAktiv('wetter')) renderWeatherCard(grid);

  // Karte: Kranke Teamende heute (tagesaktuell) — ausschließlich für Admin,
  // da Krankmeldungen im Personal-Tab ebenfalls admin-only sind.
  if(isAdmin() && modulAktiv('personal') && dashboardKachelAktiv('krankmeldungen')){
    const kmCard = document.createElement('div');
    kmCard.className = 'dash-card';
    const kmToday = (state.krankmeldungen||[]).filter(k=>k.von<=today && today<=k.bis);
    const kmNames = kmToday.map(k=>{
      const p = (state.personal||[]).find(x=>x.id===k.personId);
      return {name:p?p.name:'(unbekannt)', grund:k.grund, bis:k.bis};
    });
    kmCard.innerHTML = `
      <div class="dash-num" style="${kmNames.length>0?'color:var(--awo-red);':''}">${kmNames.length}</div>
      <div class="dash-label">Kranke Teamende heute</div>
      ${kmNames.length>0
        ? '<ul>'+kmNames.map(k=>`<li>${escapeHtml(k.name)}${k.grund?' · '+escapeHtml(k.grund):''} <span style="color:var(--ink-soft); font-size:0.78rem;">(bis ${escapeHtml(fmtDateFull(k.bis))})</span></li>`).join('')+'</ul>'
        : '<div class="dash-empty">Niemand krankgemeldet.</div>'}
    `;
    kmCard.addEventListener('click', ()=>switchToTab('personal'));
    grid.appendChild(kmCard);
  }

  // Karte: Kinderanzahl pro Gruppe (tagesaktuell, aus dem Kinder-/Gruppen-Tab)
  if(modulAktiv('gruppen') && dashboardKachelAktiv('kinder_pro_gruppe')){
  const kiGrCard = document.createElement('div');
  kiGrCard.className = 'dash-card';
  if(todayInfo){
    if(kinderGruppenBedarfCache === null){
      if(!kinderBedarfLoading){
        kinderBedarfLoading = true;
        ladeKinderGruppenBedarf().then(()=>{ kinderBedarfLoading = false; renderDashboard(); });
      }
      kiGrCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Kinderanzahl pro Gruppe</div><div class="dash-empty">Lade Kinderzahlen…</div>`;
    } else {
      const gnList = state.gruppenNamen || [];
      const kinderProGruppe = kinderGruppenBedarfCache[todayInfo.week.id] || {};
      const gesamt = gnList.reduce((sum,gn)=> sum + (kinderProGruppe[gn.name]||0), 0);

      // Zusatzzeile: wie viele der heutigen Kinder sind vom Team bereits als
      // anwesend bestätigt bzw. von den Eltern für heute abgemeldet worden.
      // Nutzt denselben kinderCache, den ladeKinderGruppenBedarf() gerade
      // mitbefüllt hat (kein zusätzlicher Abruf nötig).
      let bestaetigtZeile = '';
      if(kinderCache.kinder && kinderCache.kinder.length){
        const kinderHeute = kinderCache.kinder.filter(k=>{
          const wochenDesKindes = k.wochen || [];
          return wochenDesKindes.length === 0 || wochenDesKindes.includes(todayInfo.week.id);
        });
        const bestaetigtHeute = kinderHeute.filter(k => ((k.anmeldungen||{})[todayInfo.day.id]||{}).bestaetigt).length;
        const abgemeldetHeute = kinderHeute.filter(k => ((k.anmeldungen||{})[todayInfo.day.id]||{}).status === 'ab').length;
        bestaetigtZeile = `<div class="dp-hint" style="margin-top:8px;">✓ ${bestaetigtHeute} von ${kinderHeute.length} heute vom Team bestätigt${abgemeldetHeute>0?` · ${abgemeldetHeute} abgemeldet`:''}</div>`;
      }

      kiGrCard.innerHTML = `
        <div class="dash-num">${gesamt}</div>
        <div class="dash-label">Kinderanzahl pro Gruppe (${escapeHtml(todayInfo.week.label)})</div>
        ${gnList.length>0
          ? '<ul>'+gnList.map(gn=>`<li>${escapeHtml(gn.name)}: ${kinderProGruppe[gn.name]||0}</li>`).join('')+'</ul>'
          : '<div class="dash-empty">Noch keine Gruppen angelegt.</div>'}
        ${bestaetigtZeile}
      `;
    }
  } else {
    kiGrCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Kinderanzahl pro Gruppe</div><div class="dash-empty">Heute kein Ferienspiele-Tag.</div>`;
  }
  kiGrCard.addEventListener('click', ()=>switchToTab('gruppen'));
  grid.appendChild(kiGrCard);
  }

  // Karte: Teamendenanzahl pro Gruppe (tagesaktuell, aus dem Gruppen-Tab)
  if(modulAktiv('gruppen') && dashboardKachelAktiv('team_pro_gruppe')){
  const teGrCard = document.createElement('div');
  teGrCard.className = 'dash-card';
  if(todayInfo){
    const gnList = state.gruppenNamen || [];
    const gruppenList = (state.gruppen||[]).filter(g=>g.zuordnung && g.zuordnung[todayInfo.week.id]);
    const staffCounts = {};
    gnList.forEach(gn=>{ staffCounts[gn.id] = 0; });
    gruppenList.forEach(g=>{
      const gid = g.zuordnung[todayInfo.week.id];
      if(staffCounts[gid] !== undefined) staffCounts[gid]++;
    });
    teGrCard.innerHTML = `
      <div class="dash-num">${gruppenList.length}</div>
      <div class="dash-label">Teamendenanzahl pro Gruppe (${escapeHtml(todayInfo.week.label)})</div>
      ${gnList.length>0
        ? '<ul>'+gnList.map(gn=>`<li>${escapeHtml(gn.name)}: ${staffCounts[gn.id]||0}</li>`).join('')+'</ul>'
        : '<div class="dash-empty">Noch keine Gruppen angelegt.</div>'}
    `;
  } else {
    teGrCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Teamendenanzahl pro Gruppe</div><div class="dash-empty">Heute kein Ferienspiele-Tag.</div>`;
  }
  teGrCard.addEventListener('click', ()=>switchToTab('gruppen'));
  grid.appendChild(teGrCard);
  }

  // Karte: Teamende (freigeschaltet) — unabhängig von Gruppen/Personal-
  // Struktur, gedacht für interne Veranstaltungen (z.B. Weihnachtsfeier),
  // bei denen einfach nur interessiert, wie viele Teamende überhaupt
  // kommen. Zählt alle für DIESE Aktion freigeschalteten Personen aus
  // team_zugriff (zweistufiger Team-Zugang) — unabhängig davon, ob sie im
  // Personal-Tab einen Einsatztag eingetragen haben oder nicht.
  if(isAdmin() && dashboardKachelAktiv('teamende_freigeschaltet')){
    const teamendeCard = document.createElement('div');
    teamendeCard.className = 'dash-card';
    if(teamendeFreigeschaltetCache === null){
      if(!teamendeFreigeschaltetLoading){
        teamendeFreigeschaltetLoading = true;
        epCall({action:'admin_freischaltung_liste', pass: currentAuthPass}).then(json=>{
          teamendeFreigeschaltetCache = (json.zugriffe || []).filter(z=>z.status==='freigeschaltet');
          teamendeFreigeschaltetLoading = false;
          renderDashboard();
        }).catch(()=>{
          teamendeFreigeschaltetLoading = false;
        });
      }
      teamendeCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Teamende (freigeschaltet)</div><div class="dash-empty">Lade…</div>`;
    } else {
      const namen = teamendeFreigeschaltetCache.map(z=>z.person ? `${z.person.vorname} ${z.person.nachname}` : z.person_id);
      teamendeCard.innerHTML = `
        <div class="dash-num">${namen.length}</div>
        <div class="dash-label">Teamende (freigeschaltet)</div>
        ${namen.length>0
          ? '<ul>'+namen.slice(0,8).map(n=>`<li>${escapeHtml(n)}</li>`).join('')+(namen.length>8?`<li>… und ${namen.length-8} weitere</li>`:'')+'</ul>'
          : '<div class="dash-empty">Noch niemand freigeschaltet.</div>'}
      `;
    }
    teamendeCard.addEventListener('click', ()=>{
      if(currentAktionInfo) zeigeAktionVerwalten(currentAktionInfo);
    });
    grid.appendChild(teamendeCard);
  }

  // Karte: Foto-/Video-Einwilligung ungeklärt — bewusst NICHT an "heute ist
  // Ferienspiele-Tag" gekoppelt (anders als die Gruppen-Karten oben), da der
  // Sinn genau ist, das VOR Aktionsstart zu klären, nicht erst am ersten Tag.
  // Nur Admin (wie die Foto-/Video-Felder selbst auch nur für Admin editierbar sind).
  if(isAdmin() && modulAktiv('kinder') && dashboardKachelAktiv('foto_einwilligung')){
    const fotoCard = document.createElement('div');
    fotoCard.className = 'dash-card';
    // kinderCache/kinderGruppenBedarfCache werden sonst nur von der
    // Gruppen-Karte oben nachgeladen — falls das Gruppen-Modul für diese
    // Aktion deaktiviert ist, hier selbst anstoßen. kinderGruppenBedarfCache
    // (statt kinderCache.kinder.length) als Lade-Indikator, damit "0 Kinder
    // angelegt" nicht fälschlich als "noch am Laden" missverstanden wird.
    if(kinderGruppenBedarfCache === null && !kinderBedarfLoading){
      kinderBedarfLoading = true;
      ladeKinderGruppenBedarf().then(()=>{ kinderBedarfLoading = false; renderDashboard(); });
    }
    if(kinderGruppenBedarfCache === null){
      fotoCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Foto-/Video-Einwilligung</div><div class="dash-empty">Lade Kinderdaten…</div>`;
    } else if(!kinderCache.kinder || kinderCache.kinder.length === 0){
      fotoCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Foto-/Video-Einwilligung</div><div class="dash-empty">Noch keine Kinder angelegt.</div>`;
    } else {
      const ungeklaert = kinderCache.kinder.filter(k => !fotoZweckeGeklaert(k) || (k.video_erlaubt !== true && k.video_erlaubt !== false));
      fotoCard.innerHTML = ungeklaert.length > 0
        ? `<div class="dash-num" style="color:var(--awo-red,#E2001A);">${ungeklaert.length}</div><div class="dash-label">Kinder ohne geklärte Foto-/Video-Erlaubnis</div><div class="dp-hint" style="margin-top:8px;">Vor Aktionsstart klären — die Eltern tragen die Foto-Zwecke im Eltern-Portal ein, Video und Korrekturen pflegt ihr in der Kinder-Liste.</div>`
        : `<div class="dash-num">0</div><div class="dash-label">Kinder ohne geklärte Foto-/Video-Erlaubnis</div><div class="dash-empty">Alles geklärt. ✓</div>`;
    }
    fotoCard.addEventListener('click', ()=>{
      switchToTab('kinder');
      const sel = document.getElementById('k_foto_filter');
      const zw = document.getElementById('k_foto_zweck');
      if(sel && zw){ sel.value = ''; zw.value = '__offen'; renderKinderList(); }
    });
    grid.appendChild(fotoCard);
  }

  // Karte: Nachweise (Führungszeugnis, Erste Hilfe, ...) — nur Admin.
  // Seit dem Umbau auf aktionsübergreifende Nachweise-Verwaltung kein
  // eigenes Aktions-Modul mehr (Nachweise gelten für die ganze Kartei) —
  // die Karte zeigt hier trotzdem nur die Personen der AKTUELLEN Aktion
  // als schnellen Überblick, Klick führt in den vollständigen
  // Verwaltungsbereich.
  if(isAdmin() && dashboardKachelAktiv('nachweise')){
    const nwCard = document.createElement('div');
    nwCard.className = 'dash-card';
    if((!nachweiseCacheLoaded && !nachweiseLoading) || (!globaleEinstellungenGeladen && !globaleEinstellungenLoading)){
      if(!nachweiseCacheLoaded && !nachweiseLoading){ nachweiseLoading = true; ladeNachweiseCache().then(()=>{ nachweiseLoading = false; renderDashboard(); }); }
      if(!globaleEinstellungenGeladen && !globaleEinstellungenLoading){ globaleEinstellungenLoading = true; ladeGlobaleEinstellungen().then(()=>{ globaleEinstellungenLoading = false; renderDashboard(); }); }
    }
    if(!nachweiseCacheLoaded || !globaleEinstellungenGeladen){
      nwCard.innerHTML = `<div class="dash-num">–</div><div class="dash-label">Nachweise</div><div class="dash-empty">Lade Nachweise…</div>`;
    } else {
      const betroffene = (state.personal||[]).map(p=>({p, status:nachweisStatus(p)})).filter(x=>x.status.stufe!=='ok');
      nwCard.innerHTML = `
        <div class="dash-num" style="${betroffene.length>0?'color:var(--awo-red);':''}">${betroffene.length}</div>
        <div class="dash-label">Nachweise fehlen/laufen ab</div>
        ${betroffene.length>0
          ? '<ul>'+betroffene.slice(0,6).map(x=>`<li>${escapeHtml(x.p.name)}: ${escapeHtml(x.status.hinweise[0]||'')}</li>`).join('')+(betroffene.length>6?`<li>… und ${betroffene.length-6} weitere</li>`:'')+'</ul>'
          : '<div class="dash-empty">Alles vollständig. ✓</div>'}
      `;
    }
    nwCard.addEventListener('click', async ()=>{
      await zeigeVerwaltung();
      document.getElementById('vwKachelNachweise').click();
    });
    grid.appendChild(nwCard);
  }

  // Karte: Einkauf offen (gesamt + heute)
  if(modulAktiv('einkauf') && dashboardKachelAktiv('einkauf')){
  const ekCard = document.createElement('div');
  ekCard.className = 'dash-card';
  const ekOffen = (state.einkauf||[]).filter(e=>!e.done);
  const ekHeute = ekOffen.filter(e=>e.date===today);
  ekCard.innerHTML = `
    <div class="dash-num">${ekOffen.length}</div>
    <div class="dash-label">Offene Einkäufe (davon ${ekHeute.length} heute)</div>
    ${ekHeute.length>0
      ? '<ul>'+ekHeute.slice(0,6).map(e=>`<li>${escapeHtml(e.text)}</li>`).join('')+'</ul>'
      : '<div class="dash-empty">Für heute nichts offen.</div>'}
  `;
  ekCard.addEventListener('click', ()=>switchToTab('einkauf'));
  grid.appendChild(ekCard);
  }

  // Karte: Material offen
  if(modulAktiv('material') && dashboardKachelAktiv('material')){
  const maCard = document.createElement('div');
  maCard.className = 'dash-card';
  const maOffen = (state.material||[]).filter(m=>!m.done);
  maCard.innerHTML = `
    <div class="dash-num">${maOffen.length}</div>
    <div class="dash-label">Offene Materialpunkte</div>
    ${maOffen.length>0
      ? '<ul>'+maOffen.slice(0,6).map(m=>`<li>${escapeHtml(m.text)}</li>`).join('')+(maOffen.length>6?`<li>… und ${maOffen.length-6} weitere</li>`:'')+'</ul>'
      : '<div class="dash-empty">Alles erledigt. ✓</div>'}
  `;
  maCard.addEventListener('click', ()=>switchToTab('material'));
  grid.appendChild(maCard);
  }

  // Karte: To-Dos heute (tagesaktuell, respektiert Sichtbarkeit team/admin)
  if(modulAktiv('todo') && dashboardKachelAktiv('todo')){
  const todoCard = document.createElement('div');
  todoCard.className = 'dash-card';
  const todosHeute = (state.todos||[]).filter(t => (isAdmin() || t.visibility!=='admin') && t.date===today && !t.done);
  todoCard.innerHTML = `
    <div class="dash-num">${todosHeute.length}</div>
    <div class="dash-label">To-Dos heute</div>
    ${todosHeute.length>0
      ? '<ul>'+todosHeute.slice(0,6).map(t=>`<li>${escapeHtml(t.text)}</li>`).join('')+(todosHeute.length>6?`<li>… und ${todosHeute.length-6} weitere</li>`:'')+'</ul>'
      : '<div class="dash-empty">Nichts für heute eingetragen.</div>'}
  `;
  todoCard.addEventListener('click', ()=>switchToTab('todo'));
  grid.appendChild(todoCard);
  }

  // Unten: letzte Änderungen (breit) — nur für Admin, da inhaltlich Verlauf-Vorschau
  if(isAdmin() && modulAktiv('verlauf') && dashboardKachelAktiv('verlauf')){
    const vlCard = document.createElement('div');
    vlCard.className = 'dash-card dash-wide';
    const recent = [...(state.changelog||[])].sort((a,b)=>b.ts-a.ts).slice(0,5);
    vlCard.innerHTML = `
      <div class="dash-label" style="margin-bottom:6px;">Letzte Änderungen im Team</div>
      ${recent.length>0
        ? '<ul>'+recent.map(e=>{
            const when = new Date(e.ts).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
            return `<li>${escapeHtml(e.summary)} <span style="color:var(--ink-soft); font-size:0.78rem;">— ${escapeHtml(e.user||'Teammitglied')}, ${when}</span></li>`;
          }).join('')+'</ul>'
        : '<div class="dash-empty">Noch keine Änderungen protokolliert.</div>'}
    `;
    vlCard.addEventListener('click', ()=>switchToTab('verlauf'));
    grid.appendChild(vlCard);
  }

  dashEl.innerHTML = '';
  dashEl.appendChild(grid);
}

function getActiveWeek(){
  return state.weeks.find(w=>w.id===activeWeekId) || state.weeks[0];
}
function getActiveDay(){
  const week = getActiveWeek();
  return week ? week.days.find(d=>d.id===activeDayId) : null;
}
// fmtDate / fmtDateFull: Datum von 2026-07-01 in 01.07. bzw. 01.07.2026 umwandeln
function fmtDate(iso){
  if(!iso) return '';
  const [y,m,d] = iso.split('-');
  return `${d}.${m}.`;
}
function fmtDateFull(iso){
  if(!iso) return 'kein Datum';
  const [y,m,d] = iso.split('-');
  return `${d}.${m}.${y}`;
}
function weekRange(week){
  const dated = week.days.filter(d=>d.date);
  if(dated.length===0) return 'ohne Datum';
  return fmtDate(dated[0].date) + '–' + fmtDate(dated[dated.length-1].date);
}

// renderWeektabs: die drei Wochen-Reiter oben im Programm-Tab
function renderWeektabs(){
  const el = document.getElementById('weektabs');
  el.innerHTML='';
  state.weeks.forEach(w=>{
    const b = document.createElement('button');
    b.className = 'weektab'+(w.id===activeWeekId?' active':'');
    b.innerHTML = `${w.label}<span class="range">${weekRange(w)}</span>`;
    b.addEventListener('click', ()=>{
      activeWeekId = w.id;
      activeDayId = w.days[0]?.id || null;
      renderWeektabs(); renderFilmstrip(); renderDaydate(); renderProgramm();
    });
    el.appendChild(b);
  });
}

// renderFilmstrip: Tagesleiste (Mo–Fr) der aktiven Woche, Zahl = Anzahl Programmpunkte
function renderFilmstrip(){
  const el = document.getElementById('filmstrip');
  el.innerHTML='';
  const week = getActiveWeek();
  if(!week) return;
  week.days.forEach(d=>{
    const f = document.createElement('div');
    f.className = 'frame'+(d.id===activeDayId?' active':'');
    f.innerHTML = `<div class="d">${d.weekday}</div><div class="n">${d.activities.length}</div><div class="dt">${d.date?fmtDate(d.date):'–'}</div>`;
    f.title = d.activities.length + ' Programmpunkt(e)';
    f.addEventListener('click', ()=>{ activeDayId=d.id; renderFilmstrip(); renderDaydate(); renderProgramm(); });
    el.appendChild(f);
  });
}

// renderDaydate: Datumsanzeige + Datumsfeld für den angeklickten Tag
function renderDaydate(){
  const el = document.getElementById('daydate');
  const week = getActiveWeek();
  const day = getActiveDay();
  if(!week || !day){ el.innerHTML=''; return; }
  el.innerHTML = `
    <span>${week.label} · ${day.weekday} · ${fmtDateFull(day.date)}</span>
    <input type="date" id="dayDateInput" value="${day.date||''}">
  `;
  document.getElementById('dayDateInput').addEventListener('change', async (e)=>{
    const newDate = e.target.value;
    await commit(s=>{
      const t = findDayIn(s, day.id);
      if(t) t.day.date = newDate;
    }, 'Programm', `Datum für ${week.label}, ${day.weekday} auf ${fmtDateFull(newDate)} gesetzt`, day.id);
    renderWeektabs();
    renderFilmstrip();
    renderDaydate();
  });
}

// "Automatisch datieren": ab Startmontag alle 3 Wochen (Mo–Fr) durchdatieren
// WICHTIG: toISOString() rechnet in UTC um und kann dadurch je nach Zeitzone
// (z.B. deutsche Sommerzeit) den Tag um einen verschieben. Stattdessen bauen
// wir das Datum direkt aus den lokalen Kalender-Bestandteilen zusammen.
function localIsoDate(d){
  const pad = n => String(n).padStart(2,'0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
}
document.getElementById('autoFill').addEventListener('click', async ()=>{
  const start = document.getElementById('autoStart').value;
  if(!start){ return; }
  const base = new Date(start+'T00:00:00');
  await commit(s=>{
    s.weeks.forEach((week, wi)=>{
      week.days.forEach((day, di)=>{
        const d = new Date(base);
        d.setDate(base.getDate() + wi*7 + di);
        day.date = localIsoDate(d);
      });
    });
  }, 'Programm', `Alle 3 Wochen automatisch datiert (Start: ${fmtDateFull(start)})`, null);
  renderWeektabs();
  renderFilmstrip();
  renderDaydate();
});

function findDayById(dayId){
  for(const week of state.weeks){
    const day = week.days.find(d=>d.id===dayId);
    if(day) return {week, day};
  }
  return null;
}
// buildDayOptionsHtml: Auswahlliste aller 15 Tage (für die Kopieren-Funktion)
function buildDayOptionsHtml(){
  return state.weeks.map(week=>{
    const opts = week.days.map(d=>{
      const label = `${d.weekday}${d.date?' · '+fmtDate(d.date):''}`;
      return `<option value="${d.id}">${escapeHtml(label)}</option>`;
    }).join('');
    return `<optgroup label="${escapeHtml(week.label)}">${opts}</optgroup>`;
  }).join('');
}

// renderProgramm: Aktivitäten-Karten des aktiven Tags, sortiert nach Uhrzeit
function renderProgramm(){
  const list = document.getElementById('programmList');
  const day = getActiveDay();
  list.innerHTML='';
  if(!day || day.activities.length===0){
    list.innerHTML = `<div class="empty">Noch keine Aktivität für <strong>${day?day.weekday:''}</strong> eingetragen. Unten hinzufügen.</div>`;
    return;
  }
  const sorted = [...day.activities].sort((a,b)=>a.time.localeCompare(b.time));
  sorted.forEach(a=>{
    const card = document.createElement('div');
    card.className='card'+(newIds.has(a.id)?' is-new':'');
    card.innerHTML = `
      <div class="card-head">
        <div>
          <h3>${escapeHtml(a.title)}${newIds.has(a.id)?'<span class="badge-new">NEU</span>':''}</h3>
          <div class="meta">
            ${a.ort?`<span>📍 ${escapeHtml(a.ort)}</span>`:''}
            ${a.verantw?`<span>👤 ${escapeHtml(a.verantw)}</span>`:''}
          </div>
        </div>
        <div style="display:flex; align-items:center; gap:10px;">
          <div class="time">${a.time}</div>
          <button class="del" data-action="edit">Bearbeiten</button>
          <button class="del" data-action="copy">Kopieren</button>
          <button class="del" data-action="delete">Entfernen</button>
        </div>
      </div>
      <div class="copy-panel" data-panel="edit" style="display:none;">
        <div class="add-row" style="grid-template-columns:100px 1.3fr 1fr 1fr;">
          <input type="time" class="edit-time" value="${a.time}">
          <input type="text" class="edit-title" placeholder="Aktivität" value="${escapeHtml(a.title)}">
          <input type="text" class="edit-ort" placeholder="Ort" value="${escapeHtml(a.ort||'')}">
          <input type="text" class="edit-verantw" placeholder="Verantwortlich" value="${escapeHtml(a.verantw||'')}">
        </div>
        <div style="display:flex; gap:8px; margin-top:10px;">
          <button class="btn" data-action="save-edit">Speichern</button>
          <button class="btn ghost" data-action="cancel-edit">Abbrechen</button>
        </div>
      </div>
      <div class="copy-panel" data-panel="copy" style="display:none;">
        <div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center;">
          <select class="copy-select"></select>
          <button class="btn" data-action="confirm">Kopieren</button>
          <button class="btn ghost" data-action="cancel">Abbrechen</button>
        </div>
      </div>
    `;
    const editPanel = card.querySelector('[data-panel="edit"]');
    const panel = card.querySelector('[data-panel="copy"]');
    const select = card.querySelector('.copy-select');
    card.querySelector('[data-action="edit"]').addEventListener('click', ()=>{
      panel.style.display = 'none';
      const isOpen = editPanel.style.display !== 'none';
      editPanel.style.display = isOpen ? 'none' : 'block';
    });
    card.querySelector('[data-action="cancel-edit"]').addEventListener('click', ()=>{
      editPanel.style.display = 'none';
    });
    card.querySelector('[data-action="save-edit"]').addEventListener('click', async ()=>{
      const newTime = card.querySelector('.edit-time').value || a.time;
      const newTitle = card.querySelector('.edit-title').value.trim();
      const newOrt = card.querySelector('.edit-ort').value.trim();
      const newVerantw = card.querySelector('.edit-verantw').value.trim();
      if(!newTitle) return;
      await commit(s=>{
        const t = findDayIn(s, day.id);
        const act = t ? t.day.activities.find(x=>x.id===a.id) : null;
        if(act){ act.time=newTime; act.title=newTitle; act.ort=newOrt; act.verantw=newVerantw; }
      }, 'Programm', `Aktivität „${a.title}“ (${day.weekday}) bearbeitet`, a.id);
      editPanel.style.display = 'none';
      renderFilmstrip();
      renderProgramm();
    });
    card.querySelector('[data-action="copy"]').addEventListener('click', ()=>{
      editPanel.style.display = 'none';
      const isOpen = panel.style.display !== 'none';
      if(isOpen){ panel.style.display='none'; return; }
      select.innerHTML = buildDayOptionsHtml();
      select.value = day.id;
      panel.style.display='block';
    });
    card.querySelector('[data-action="cancel"]').addEventListener('click', ()=>{
      panel.style.display='none';
    });
    card.querySelector('[data-action="confirm"]').addEventListener('click', async ()=>{
      const target = findDayById(select.value);
      if(!target) return;
      const newAct = {id:cid(), time:a.time, title:a.title, ort:a.ort, verantw:a.verantw};
      await commit(s=>{
        const t = findDayIn(s, target.day.id);
        if(t) t.day.activities.push(newAct);
      }, 'Programm', `Aktivität „${a.title}“ nach ${target.week.label}, ${target.day.weekday}${target.day.date?' ('+fmtDate(target.day.date)+')':''} kopiert`, newAct.id);
      panel.style.display='none';
      renderFilmstrip();
      renderProgramm();
    });
    card.querySelector('[data-action="delete"]').addEventListener('click', async ()=>{
      await commit(s=>{
        const t = findDayIn(s, day.id);
        if(t) t.day.activities = t.day.activities.filter(x=>x.id!==a.id);
      }, 'Programm', `Aktivität „${a.title}“ (${day.weekday}) entfernt`, null);
      renderFilmstrip();
      renderProgramm();
    });
    list.appendChild(card);
  });
}

// "+ Hinzufügen" im Programm: neue Aktivität für den aktiven Tag speichern
document.getElementById('p_add').addEventListener('click', async ()=>{
  const time = document.getElementById('p_time').value || '00:00';
  const title = document.getElementById('p_title').value.trim();
  const ort = document.getElementById('p_ort').value.trim();
  const verantw = document.getElementById('p_verantw').value.trim();
  if(!title) return;
  const day = getActiveDay();
  if(!day) return;
  const newAct = {id:cid(), time, title, ort, verantw};
  await commit(s=>{
    const t = findDayIn(s, day.id);
    if(t) t.day.activities.push(newAct);
  }, 'Programm', `Neue Aktivität „${title}“ am ${day.weekday}${day.date?' ('+fmtDate(day.date)+')':''} hinzugefügt`, newAct.id);
  document.getElementById('p_title').value='';
  document.getElementById('p_ort').value='';
  document.getElementById('p_verantw').value='';
  renderFilmstrip();
  renderProgramm();
});

// ---- GRUPPENEINTEILUNG ----
// Tabelle: pro Person eine Zeile, Haken für Gruppe 1–6 und Woche 1–3
// ---- GRUPPENEINTEILUNG (pro Woche einzeln) ----
// renderGruppenNamen: verwaltbare Liste der Gruppennamen (z.B. "Gruppe Adler")
function renderGruppenNamen(){
  const el = document.getElementById('gn_list');
  if(!el) return;
  const names = state.gruppenNamen || [];
  if(names.length===0){
    el.innerHTML = '<div class="dp-hint" style="margin-top:0;">Noch keine Gruppen angelegt.</div>';
    return;
  }
  el.innerHTML = '';
  names.forEach(gn=>{
    const chip = document.createElement('span');
    chip.className = 'dp-chip sel';
    chip.innerHTML = escapeHtml(gn.name) + ' <span style="cursor:pointer; margin-left:4px;" title="Gruppe löschen">✕</span>';
    chip.querySelector('span').addEventListener('click', async ()=>{
      await commit(s=>{
        s.gruppenNamen = (s.gruppenNamen||[]).filter(x=>x.id!==gn.id);
        (s.gruppen||[]).forEach(p=>{
          if(p.zuordnung){
            Object.keys(p.zuordnung).forEach(wk=>{
              if(p.zuordnung[wk]===gn.id) delete p.zuordnung[wk];
            });
          }
        });
      }, 'Gruppen', `Gruppe „${gn.name}“ gelöscht`, null);
      renderGruppen();
    });
    el.appendChild(chip);
  });
}

document.getElementById('gn_add').addEventListener('click', async ()=>{
  const name = document.getElementById('gn_name').value.trim();
  if(!name) return;
  const newGn = {id:cid(), name};
  await commit(s=>{
    if(!Array.isArray(s.gruppenNamen)) s.gruppenNamen = [];
    s.gruppenNamen.push(newGn);
  }, 'Gruppen', `Gruppe „${name}“ angelegt`, null);
  document.getElementById('gn_name').value = '';
  renderGruppen();
});

// renderGruppen: Tabelle Name × Woche, je Zelle ein Dropdown zur Gruppenwahl
// renderGruppenSummary: Wochenübersicht, wie viele Betreuer in welcher
// Gruppe stecken — aktualisiert sich automatisch, da bei jeder Änderung
// der Zuordnung renderGruppen() (und damit auch diese Funktion) neu läuft.
// ---- PERSONALBEDARF (Kinder pro Teamende) ----
document.getElementById('bedarf_verhaeltnis').value = state && state.kinderProTeamende ? state.kinderProTeamende : 8;
document.getElementById('bedarf_speichern').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('bedarf_status');
  const wert = parseInt(document.getElementById('bedarf_verhaeltnis').value, 10);
  if(!wert || wert <= 0){ statusEl.textContent = '⚠️ Bitte eine Zahl größer 0 eingeben.'; return; }
  await commit(s=>{ s.kinderProTeamende = wert; }, 'Gruppen', `Verhältnis Kinder pro Teamende auf ${wert} gesetzt`, null);
  statusEl.textContent = '✓ Gespeichert.';
  renderGruppenBedarf();
});

// kinderGruppenBedarfCache: { [weekId]: { [gruppenName]: anzahlKinder } }
// wird beim Öffnen des Gruppen-Tabs neu geladen (siehe switchToTab)
let kinderGruppenBedarfCache = null;

async function ladeKinderGruppenBedarf(){
  const el = document.getElementById('gruppenBedarf');
  if(!el) return;
  try{
    const data = await epCall({action:'admin_list', pass: currentAuthPass});
    // kinderCache mit befüllen (nicht nur lokale Zählung) — wird von der
    // Dashboard-Kachel für "heute bestätigt/abgemeldet" mitgenutzt, ohne
    // dafür einen zweiten Abruf zu brauchen.
    kinderCache = { kinder: data.kinder || [], days: data.days || [] };
    const zaehlung = {};
    (data.kinder||[]).forEach(k=>{
      Object.entries(k.gruppen_zuordnung||{}).forEach(([weekId, gruppenName])=>{
        if(!gruppenName) return;
        if(!zaehlung[weekId]) zaehlung[weekId] = {};
        zaehlung[weekId][gruppenName] = (zaehlung[weekId][gruppenName]||0) + 1;
      });
    });
    kinderGruppenBedarfCache = zaehlung;
  }catch(e){
    kinderGruppenBedarfCache = null;
    console.error('Kinder-Gruppenzahlen konnten nicht geladen werden:', e);
  }
  renderGruppenBedarf();
}

function renderGruppenBedarf(){
  const el = document.getElementById('gruppenBedarf');
  if(!el) return;
  if(!isAdmin()){ el.innerHTML = ''; return; }
  const verhaeltnisInput = document.getElementById('bedarf_verhaeltnis');
  if(verhaeltnisInput && document.activeElement !== verhaeltnisInput){
    verhaeltnisInput.value = state && state.kinderProTeamende ? state.kinderProTeamende : 8;
  }
  const gnList = state.gruppenNamen || [];
  if(gnList.length === 0){ el.innerHTML = ''; return; }
  if(kinderGruppenBedarfCache === null){
    el.innerHTML = '<div class="dp-hint" style="margin:0 0 14px 0;">Lade Kinderzahlen für den Personalbedarf…</div>';
    return;
  }
  const verhaeltnis = state.kinderProTeamende || 8;
  const gruppenList = (state.gruppen||[]).filter(g=>g.zuordnung);
  const gnById = {};
  gnList.forEach(gn=>{ gnById[gn.id] = gn.name; });

  const wrap = document.createElement('div');
  wrap.className = 'gs-wrap';

  state.weeks.forEach(week=>{
    const staffCounts = {};
    gnList.forEach(gn=>{ staffCounts[gn.id] = 0; });
    gruppenList.forEach(g=>{
      const gid = g.zuordnung[week.id];
      if(gid && staffCounts[gid] !== undefined) staffCounts[gid]++;
    });
    const kinderProGruppe = (kinderGruppenBedarfCache[week.id]) || {};

    const rows = gnList.map(gn=>{
      const anzahlKinder = kinderProGruppe[gn.name] || 0;
      const benoetigt = Math.ceil(anzahlKinder / verhaeltnis);
      const vorhanden = staffCounts[gn.id];
      const differenz = vorhanden - benoetigt;
      let anzeige, cssKlasse;
      if(differenz < 0){ anzeige = `+${-differenz}`; cssKlasse = ' gs-none'; }
      else if(differenz > 0){ anzeige = `−${differenz}`; cssKlasse = ' gs-ueberschuss'; }
      else { anzeige = '✓'; cssKlasse = ''; }
      return `
        <div class="gs-row${cssKlasse}">
          <span>${escapeHtml(gn.name)} — ${anzahlKinder} Kind${anzahlKinder===1?'':'er'}, ${vorhanden} Teamende</span>
          <span class="gs-count">${anzeige}</span>
        </div>`;
    }).join('');

    const box = document.createElement('div');
    box.className = 'gs-week';
    box.innerHTML = `<h4>${escapeHtml(week.label)} — Personalbedarf</h4>${rows}`;
    wrap.appendChild(box);
  });

  el.innerHTML = '';
  el.appendChild(wrap);
  const hint = document.createElement('div');
  hint.className = 'dp-hint';
  hint.textContent = `Berechnung: aufgerundet 1 Teamende pro ${verhaeltnis} Kind(ern) — Kinderzahlen aus dem "Kinder"-Tab, Zuordnung nach Gruppenname. „+X" = X Teamende fehlen noch, „−X" = X Teamende sind mehr zugeordnet als nötig, „✓" = passt genau.`;
  el.appendChild(hint);
}

function renderGruppenSummary(){
  const el = document.getElementById('gruppenSummary');
  if(!el) return;
  const gruppenList = (state.gruppen||[]).filter(g=>g.zuordnung);
  const gnList = state.gruppenNamen||[];

  if(gnList.length===0){
    el.innerHTML = '';
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'gs-wrap';

  state.weeks.forEach(week=>{
    const counts = {};
    gnList.forEach(gn=>{ counts[gn.id] = 0; });
    let ohneGruppe = 0;
    gruppenList.forEach(g=>{
      const gid = g.zuordnung[week.id];
      if(gid && counts[gid] !== undefined) counts[gid]++;
      else if(!gid) { /* nicht in dieser Woche zugeordnet, zählt nicht mit */ }
    });
    gruppenList.forEach(g=>{
      if(!g.zuordnung[week.id]) ohneGruppe++;
    });

    const box = document.createElement('div');
    box.className = 'gs-week';
    const rows = gnList.map(gn=>`
      <div class="gs-row${counts[gn.id]===0?' gs-none':''}">
        <span>${escapeHtml(gn.name)}</span>
        <span class="gs-count">${counts[gn.id]}</span>
      </div>`).join('');
    box.innerHTML = `
      <h4>${escapeHtml(week.label)}</h4>
      ${rows}
      ${ohneGruppe>0 ? `<div class="gs-empty-hint">${ohneGruppe} Betreuer ohne Gruppe in dieser Woche</div>` : ''}
    `;
    wrap.appendChild(box);
  });

  el.innerHTML = '';
  el.appendChild(wrap);
}

function renderGruppen(){
  renderGruppenNamen();
  renderGruppenSummary();
  const list = document.getElementById('gruppenList');
  list.innerHTML='';
  if(!state.gruppen || state.gruppen.length===0){
    list.innerHTML = `<div class="empty">Noch niemand eingetragen.</div>`;
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'pe-tablewrap';
  const table = document.createElement('table');
  table.className = 'pe-table';

  const thead = document.createElement('thead');
  const headRow = document.createElement('tr');
  headRow.innerHTML = `<th>Name</th>` +
    state.weeks.map(w=>`<th>${escapeHtml(w.label)}</th>`).join('') +
    `<th title="Person ist noch flexibel/als Springer vorgesehen — Konflikt-Prüfung ignoriert fehlenden Personaleinsatz">Springer/Flex</th>` +
    `<th></th>`;
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement('tbody');
  state.gruppen.forEach(g=>{
    const tr = document.createElement('tr');
    if(newIds.has(g.id)) tr.className = 'is-new';
    const isLegacy = !g.zuordnung && (g.betreuer || g.kap || Array.isArray(g.gr) || Array.isArray(g.wo));
    let weekCells = '';
    if(isLegacy){
      const legacyInfo = [g.betreuer?('Betreuer: '+g.betreuer):'', g.kap?('Kapazität: '+g.kap):''].filter(Boolean).join(' · ') || '(alter Eintrag)';
      weekCells = `<td class="pe-legacy" colspan="${state.weeks.length}">${escapeHtml(legacyInfo)}</td>`;
    } else {
      const zuordnung = g.zuordnung || {};
      const gnById2 = {};
      (state.gruppenNamen||[]).forEach(gn=>{ gnById2[gn.id] = gn.name; });
      weekCells = state.weeks.map(w=>{
        const current = zuordnung[w.id] || '';
        if(!isAdmin()){
          return `<td>${current ? escapeHtml(gnById2[current]||'?') : '<span style="color:var(--ink-soft);">–</span>'}</td>`;
        }
        const options = ['<option value="">–</option>'].concat(
          (state.gruppenNamen||[]).map(gn=>`<option value="${gn.id}"${gn.id===current?' selected':''}>${escapeHtml(gn.name)}</option>`)
        ).join('');
        return `<td><select data-week="${w.id}">${options}</select></td>`;
      }).join('');
    }
    const flexCell = isLegacy ? '' : (isAdmin()
      ? `<td style="text-align:center;"><input type="checkbox" data-flex ${g.istPlatzhalter?'checked':''} title="Springer/Flex — noch keine festen Tage bekannt"></td>`
      : `<td style="text-align:center;">${g.istPlatzhalter?'✓':'–'}</td>`);
    tr.innerHTML = `
      <td class="pe-name">${escapeHtml(g.name)}${newIds.has(g.id)?'<span class="badge-new">NEU</span>':''}${g.istPlatzhalter?'<span class="tag" style="margin-left:6px;">Springer</span>':''}</td>
      ${weekCells}
      ${flexCell}
      <td>${isAdmin()?'<button class="del">Entfernen</button>':''}</td>
    `;
    if(!isLegacy && isAdmin()){
      tr.querySelectorAll('select[data-week]').forEach(sel=>{
        sel.addEventListener('change', async ()=>{
          const weekId = sel.dataset.week;
          const groupId = sel.value;
          const week = state.weeks.find(w=>w.id===weekId);
          const gn = (state.gruppenNamen||[]).find(x=>x.id===groupId);
          await commit(s=>{
            const person = (s.gruppen||[]).find(x=>x.id===g.id);
            if(!person) return;
            if(!person.zuordnung) person.zuordnung = {};
            if(groupId) person.zuordnung[weekId] = groupId;
            else delete person.zuordnung[weekId];
          }, 'Gruppen', `${g.name}: ${week?week.label:'Woche'} → ${gn?gn.name:'keine Gruppe'}`, g.id);
          renderGruppen();
        });
      });
      const flexBox = tr.querySelector('[data-flex]');
      if(flexBox){
        flexBox.addEventListener('change', async ()=>{
          const checked = flexBox.checked;
          await commit(s=>{
            const person = (s.gruppen||[]).find(x=>x.id===g.id);
            if(person) person.istPlatzhalter = checked;
          }, 'Gruppen', `${g.name} als Springer/Flex ${checked?'markiert':'entmarkiert'}`, g.id);
          renderGruppen();
        });
      }
    }
    const delBtnG = tr.querySelector('.del');
    if(delBtnG){
      delBtnG.addEventListener('click', async ()=>{
        await commit(s=>{
          s.gruppen = (s.gruppen||[]).filter(x=>x.id!==g.id);
        }, 'Gruppen', `${g.name} aus der Gruppeneinteilung entfernt`, null);
        renderGruppen();
      });
    }
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  wrap.appendChild(table);
  list.appendChild(wrap);
}

// "+ Hinzufügen" bei Gruppen: neue Person (nur Name), Zuordnung dann pro Woche per Dropdown
document.getElementById('g_add').addEventListener('click', async ()=>{
  const name = document.getElementById('g_name').value.trim();
  const personId = document.getElementById('g_kartei_select').value;
  if(!personId){ alert('Bitte zuerst die Person aus der Kartei auswählen oder neu anlegen — nötig für den zuverlässigen Betreuungsschlüssel-Abgleich mit dem Personaleinsatz.'); return; }
  if(!name) return;
  const newEntry = {id:cid(), personId, name, zuordnung:{}};
  await commit(s=>{
    if(!Array.isArray(s.gruppen)) s.gruppen = [];
    s.gruppen.push(newEntry);
  }, 'Gruppen', `${name} zur Gruppeneinteilung hinzugefügt`, newEntry.id);
  document.getElementById('g_name').value='';
  document.getElementById('g_kartei_select').value='';
  renderGruppen();
});

// ---- PERSONALEINSATZ ----
// peSelected: merkt sich die angeklickten Tage im Auswahl-Bereich (vor dem Hinzufügen)
let peSelected = new Set();

// peAnsicht: Tabelle (kompakte Übersicht) oder Kacheln (eine Kachel pro
// Person, Klick öffnet die Detailkarte mit allem — optische Alternative,
// beide zeigen dieselben Daten). peKachelOffenePersonId: welche Person in
// der Kacheln-Ansicht gerade als Detailkarte geöffnet ist.
let peAnsicht = localStorage.getItem('peAnsicht') === 'kacheln' ? 'kacheln' : 'tabelle';
let peKachelOffenePersonId = null;

function dayChipLabel(d){
  return d.weekday + (d.date ? ' ' + fmtDate(d.date) : '');
}

// isoWeekdayShort: Wochentagskürzel (Mo/Di/…) aus einem Datum berechnen
function isoWeekdayShort(iso){
  if(!iso) return '?';
  const d = new Date(iso+'T00:00:00');
  return ['So','Mo','Di','Mi','Do','Fr','Sa'][d.getDay()];
}
// zusatzSorted: Zusatztage nach Datum sortiert zurückgeben
function zusatzSorted(){
  return [...(state.zusatzTage||[])].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
}
function zusatzChipLabel(z){
  return isoWeekdayShort(z.date) + ' ' + fmtDate(z.date) + (z.label ? ' · ' + z.label : '');
}
function findZusatz(id){
  return (state.zusatzTage||[]).find(z=>z.id===id) || null;
}

// renderPeDayPicker: anklickbare Tages-Chips (bereits angelegte Einsatztage)
// im Hinzufügen-Bereich für eine neue Person — seit der Umstellung auf
// freie Einsatztage OHNE die feste Wochen-Auswahl (siehe baueAllDaysListe).
function renderPeDayPicker(){
  const el = document.getElementById('pe_days');
  if(!el) return;
  el.innerHTML = '';
  const zusatz = zusatzSorted();
  if(zusatz.length === 0){
    el.innerHTML = '<div class="dp-hint" style="margin-top:0;">Noch keine Einsatztage angelegt — oben ein Datum eintragen.</div>';
    return;
  }
  const row = document.createElement('div');
  row.className = 'dp-week';
  zusatz.forEach(z=>{
    const chip = document.createElement('span');
    chip.className = 'dp-chip' + (peSelected.has(z.id) ? ' sel' : '');
    chip.textContent = zusatzChipLabel(z);
    chip.addEventListener('click', ()=>{
      if(peSelected.has(z.id)) peSelected.delete(z.id);
      else peSelected.add(z.id);
      chip.classList.toggle('sel');
    });
    row.appendChild(chip);
  });
  el.appendChild(row);
}

// renderPeGewaehlteTage: zeigt die für die neu anzulegende Person bereits
// gewählten Tage (egal ob über das freie Datumsfeld oder die Wochen-/
// Zusatztage-Chips ausgewählt) als entfernbare Chip-Liste an.
function renderPeGewaehlteTage(){
  const el = document.getElementById('pe_neu_gewaehlte_tage');
  if(!el) return;
  if(peSelected.size === 0){ el.innerHTML = ''; return; }
  const lookup = buildDayLookup();
  const sortiert = [...peSelected].sort((a,b)=>{
    const da = (lookup[a]||{}).date || '9999-99-99';
    const db = (lookup[b]||{}).date || '9999-99-99';
    return da.localeCompare(db);
  });
  el.innerHTML = sortiert.map(id=>{
    const info = lookup[id];
    const label = info ? info.label : '(unbekannt)';
    return `<span class="dp-chip sel" data-dayid="${id}">${escapeHtml(label)} <span class="pe-neu-tag-remove" data-dayid="${id}" style="cursor:pointer; margin-left:2px;" title="Entfernen">✕</span></span>`;
  }).join(' ');
  el.querySelectorAll('.pe-neu-tag-remove').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      peSelected.delete(btn.dataset.dayid);
      renderPersonal();
    });
  });
}

// "+ Tag hinzufügen": beliebiges einzelnes Datum zur Auswahl für die neu
// anzulegende Person hinzufügen (passt das Datum zu einem bestehenden
// Einsatztag, wird dessen ID wiederverwendet, sonst wird automatisch ein
// neuer Einsatztag angelegt).
document.getElementById('pe_neu_datum_add_btn').addEventListener('click', async ()=>{
  const input = document.getElementById('pe_neu_datum');
  const dateIso = input.value;
  if(!dateIso) return;
  try{
    let dayId;
    await commit(s=>{
      dayId = findOrCreateTagIdForDate(s, dateIso);
    }, 'Personal', `Einsatztag ${isoWeekdayShort(dateIso)} ${fmtDate(dateIso)} angelegt`, null);
    peSelected.add(dayId);
    input.value = '';
    renderPersonal();
  }catch(e){
    alert('Datum konnte nicht angelegt werden: '+e.message);
  }
});

// renderZusatzList: Liste der angelegten Einsatztage mit ✕ zum Löschen
function renderZusatzList(){
  const el = document.getElementById('zt_list');
  if(!el) return;
  el.innerHTML = '';
  const zusatz = zusatzSorted();
  if(zusatz.length===0){
    el.innerHTML = '<div class="dp-hint">Noch keine Einsatztage angelegt.</div>';
    return;
  }
  const row = document.createElement('div');
  row.className = 'dp-week';
  zusatz.forEach(z=>{
    const chip = document.createElement('span');
    chip.className = 'dp-chip sel';
    chip.innerHTML = escapeHtml(zusatzChipLabel(z)) + ' <span style="cursor:pointer; margin-left:4px;" title="Einsatztag löschen">✕</span>';
    chip.querySelector('span').addEventListener('click', async ()=>{
      await commit(s=>{
        s.zusatzTage = (s.zusatzTage||[]).filter(x=>x.id!==z.id);
        (s.personal||[]).forEach(p=>{
          if(Array.isArray(p.einsatzTage)) p.einsatzTage = p.einsatzTage.filter(id=>id!==z.id);
        });
      }, 'Personal', `Einsatztag ${zusatzChipLabel(z)} gelöscht`, null);
      peSelected.delete(z.id);
      renderPersonal();
    });
    row.appendChild(chip);
  });
  el.appendChild(row);
}

// renderPersonal: die große Einsatz-Tabelle.
// Spalten = alle Tage chronologisch (Zusatztage einsortiert), Zellen per Klick umschaltbar
// ================================================================
// TAGESSÄTZE (nur Admin) + QUITTUNGS-PDF
// Tagessätze liegen NICHT in app_state (das wäre über den öffentlichen
// anon-Key für jeden mit den Browser-Entwicklertools einsehbar), sondern
// in der eigenen Tabelle "personal_gehalt", die ausschließlich über die
// Edge Function "eltern-portal" (Aktionen admin_gehalt_*) erreichbar ist
// und dort zusätzlich prüft, dass wirklich das Admin- und nicht nur das
// Team-Passwort verwendet wurde. Team-Zugang bekommt diese Werte serverseitig
// gar nicht erst ausgeliefert.
// ================================================================
let gehaltCache = {};       // { personalId: {tagessatz, rollen_pro_tag, lohnart, stundensatz, stunden_pro_tag, zeiterfassung_pro_tag} } — nur befüllt für Admin
let gehaltCacheLoaded = false;
let gehaltLoading = false;

// rollenCache: die zentral gepflegten Verantwortungs-Rollen mit eigenem
// Tagessatz (z.B. "Leitung" = 60 EUR). Nur für Admin geladen/sichtbar.
let rollenCache = [];
let rollenCacheLoaded = false;
let rollenLoading = false;

async function ladeGehaltCache(){
  if(!isAdmin()) return;
  try{
    const data = await epCallWithRetry({action:'admin_gehalt_list', pass: currentAuthPass});
    gehaltCache = {};
    (data.gehaelter||[]).forEach(g=>{ gehaltCache[g.id] = g; });
    gehaltCacheLoaded = true;
  }catch(e){
    console.error('Tagessätze konnten nicht geladen werden:', e);
  }
}

async function ladeRollenCache(){
  if(!isAdmin()) return;
  try{
    const data = await epCallWithRetry({action:'admin_rollen_list', pass: currentAuthPass});
    rollenCache = data.rollen || [];
    rollenCacheLoaded = true;
  }catch(e){
    console.error('Verantwortungs-Rollen konnten nicht geladen werden:', e);
  }
}

// tagessatzFuerTag: ermittelt den geltenden Tagessatz für einen konkreten Tag
// einer Person — Rollen-Override, falls für diesen Tag eine Rolle zugeordnet
// ist, sonst der normale (Standard-)Tagessatz der Person. Gilt nur im
// Tagessatz-Modell (lohnart==='tagessatz', Standard).
function tagessatzFuerTag(personId, tagId){
  const gehalt = gehaltCache[personId] || {};
  const rollenProTag = gehalt.rollen_pro_tag || {};
  const rollenId = rollenProTag[tagId];
  if(rollenId){
    const rolle = rollenCache.find(r=>r.id===rollenId);
    if(rolle) return rolle.betrag;
  }
  return gehalt.tagessatz;
}

// lohnartFuerPerson: liefert 'tagessatz' (Standard) oder 'stundenlohn'.
function lohnartFuerPerson(personId){
  return (gehaltCache[personId]||{}).lohnart || 'tagessatz';
}

// stundenFuerTag: geleistete Stunden an einem konkreten Tag (nur relevant im
// Stundenlohn-Modell). null = noch nicht eingetragen.
function stundenFuerTag(personId, tagId){
  const gehalt = gehaltCache[personId] || {};
  const stundenProTag = gehalt.stunden_pro_tag || {};
  const wert = stundenProTag[tagId];
  return (wert===undefined || wert===null || wert==='') ? null : Number(wert);
}

// gesamtbetragFuerPerson: Summe über alle Einsatztage. Im Tagessatz-Modell
// (Standard) je nach Tag mit dem dort geltenden Satz (Rollen-Override oder
// Standard-Tagessatz); im Stundenlohn-Modell Stunden × einheitlicher
// Stundensatz der Person (siehe 47_gehalt_lohnart_stundenlohn.sql — bewusst
// KEIN Rollen-Override beim Stundenlohn, ein fester Satz über alle Stunden).
function gesamtbetragFuerPerson(p){
  const tage = Array.isArray(p.einsatzTage) ? p.einsatzTage : [];
  const gehalt = gehaltCache[p.id] || {};
  let summe = 0;
  let unvollstaendig = false;
  if(lohnartFuerPerson(p.id) === 'stundenlohn'){
    const stundensatz = (gehalt.stundensatz===null || gehalt.stundensatz===undefined) ? null : Number(gehalt.stundensatz);
    tage.forEach(tagId=>{
      const stunden = stundenFuerTag(p.id, tagId);
      if(stunden==null || stundensatz==null){ unvollstaendig = true; return; }
      summe += stunden * stundensatz;
    });
  } else {
    tage.forEach(tagId=>{
      const satz = tagessatzFuerTag(p.id, tagId);
      if(satz==null){ unvollstaendig = true; return; }
      summe += satz;
    });
  }
  return {summe, unvollstaendig, anzahlTage: tage.length};
}

// gesamtStundenFuerPerson: Summe der eingetragenen Stunden über alle
// Einsatztage (nur sinnvoll im Stundenlohn-Modell) — für Quittung/Export.
function gesamtStundenFuerPerson(p){
  const tage = Array.isArray(p.einsatzTage) ? p.einsatzTage : [];
  let summe = 0;
  let unvollstaendig = false;
  tage.forEach(tagId=>{
    const stunden = stundenFuerTag(p.id, tagId);
    if(stunden==null){ unvollstaendig = true; return; }
    summe += stunden;
  });
  return {summe, unvollstaendig};
}

// ---- Zahl in Worten (für "EUR in Worten" auf der Quittung) ----
const ZW_EINER = ['null','ein','zwei','drei','vier','fünf','sechs','sieben','acht','neun','zehn','elf','zwölf','dreizehn','vierzehn','fünfzehn','sechzehn','siebzehn','achtzehn','neunzehn'];
const ZW_ZEHNER = ['', '', 'zwanzig','dreißig','vierzig','fünfzig','sechzig','siebzig','achtzig','neunzig'];

function zahlWorteUnter1000(n){
  if(n < 20) return ZW_EINER[n];
  if(n < 100){
    const e = n % 10, z = Math.floor(n/10);
    return e === 0 ? ZW_ZEHNER[z] : ZW_EINER[e]+'und'+ZW_ZEHNER[z];
  }
  const h = Math.floor(n/100), rest = n % 100;
  return (h===1?'ein':ZW_EINER[h])+'hundert' + (rest ? zahlWorteUnter1000(rest) : '');
}

function zahlInWorten(n){
  n = Math.round(n);
  if(n === 0) return 'null';
  if(n < 1000) return zahlWorteUnter1000(n);
  const tausender = Math.floor(n/1000), rest = n % 1000;
  const tausenderWort = tausender === 1 ? 'eintausend' : zahlWorteUnter1000(tausender)+'tausend';
  return tausenderWort + (rest ? zahlWorteUnter1000(rest) : '');
}

function betragInWorten(betrag){
  const euro = Math.floor(betrag + 1e-9);
  const cent = Math.round((betrag - euro)*100);
  let text = zahlInWorten(euro) + ' Euro';
  if(cent > 0) text += ' ' + zahlInWorten(cent) + ' Cent';
  return text.charAt(0).toUpperCase() + text.slice(1);
}

// baueQuittungPDF: baut die Quittungs-PDF (Name, Zeitraum, Betrag aus
// Einsatztagen × Tagessatz, oder Stunden × Stundensatz im Stundenlohn-
// Modell). Ohne "unterschrift" bleibt die Zeile "Stempel/Unterschrift"
// leer wie bisher (Ausdrucken + Unterschreiben); mit übergebener
// Unterschrift (PNG-Data-URL, siehe qtSignaturPad/zeigeQuittungUnterschriftDialog)
// wird sie dort eingebettet, analog zum Leihvertrag (Migration 61/baueLeihvertragPDF).
// Gibt {doc, dateiname} zurück, oder null wenn die Voraussetzungen fehlen
// (in dem Fall wurde bereits eine passende Meldung angezeigt).
async function baueQuittungPDF(p, unterschrift){
  const anzahlTage = Array.isArray(p.einsatzTage) ? p.einsatzTage.length : 0;
  if(anzahlTage === 0){
    alert(`${p.name} hat noch keine Einsatztage eingetragen.`);
    return null;
  }
  const istStundenlohn = lohnartFuerPerson(p.id) === 'stundenlohn';
  const {summe, unvollstaendig} = gesamtbetragFuerPerson(p);
  if(unvollstaendig){
    alert(istStundenlohn
      ? `Für mindestens einen Einsatztag von ${p.name} fehlen die Stunden oder es ist kein Stundensatz hinterlegt. Bitte erst in der Personal-Tabelle ergänzen.`
      : `Für mindestens einen Einsatztag von ${p.name} ist keine Rolle mit Tagessatz hinterlegt. Bitte erst in der Personal-Tabelle ergänzen.`);
    return null;
  }
  const betrag = Math.round(summe * 100) / 100;
  // Prüfen, ob an allen Tagen derselbe Satz gilt (für den "Für:"-Text) oder
  // ob durch Rollen-Zuordnung unterschiedliche Sätze zusammenkommen. Nur
  // relevant im Tagessatz-Modell — im Stundenlohn-Modell gilt ohnehin immer
  // ein einheitlicher Stundensatz über alle Stunden.
  const saetze = istStundenlohn ? [] : p.einsatzTage.map(tagId=>tagessatzFuerTag(p.id, tagId));
  const einheitlicherSatz = saetze.length>0 && saetze.every(s=>s===saetze[0]) ? saetze[0] : null;
  const gesamtStunden = istStundenlohn ? gesamtStundenFuerPerson(p).summe : 0;
  const stundensatzWert = istStundenlohn ? Number((gehaltCache[p.id]||{}).stundensatz) : null;
  const heute = new Date();
  const pad = n => String(n).padStart(2,'0');
  const datumDe = `${pad(heute.getDate())}.${pad(heute.getMonth()+1)}.${heute.getFullYear()}`;

  await ladeBibliothek('jspdf');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();

  doc.setFont('helvetica','bold');
  doc.setFontSize(18);
  doc.text('Quittung', 20, 25);

  doc.setFont('helvetica','normal');
  doc.setFontSize(11);

  // Aufwandsentschädigungen sind nicht umsatzsteuerpflichtig -> 0% MwSt,
  // Netto ist deshalb gleich Brutto. Trotzdem alle drei Zeilen ausweisen,
  // damit die Quittung wie die bisherige Papier-Vorlage aufgebaut ist.
  const nettoStr = betrag.toFixed(2).replace('.',',');
  const bruttoStr = betrag.toFixed(2).replace('.',','); // Netto = Brutto bei 0% MwSt
  const mwstBetragStr = (0).toFixed(2).replace('.',',');

  doc.text('Netto:', 20, 42);
  doc.text(`${nettoStr} EUR`, 70, 42);

  doc.text('+ 0 % MwSt:', 20, 49);
  doc.text(`${mwstBetragStr} EUR`, 70, 49);
  doc.setFontSize(9);
  doc.text('(Aufwandsentschädigung, nicht umsatzsteuerpflichtig)', 105, 49);
  doc.setFontSize(11);

  doc.line(20, 53, 120, 53);

  doc.setFont('helvetica','bold');
  doc.text('Gesamt (Brutto):', 20, 60);
  doc.text(`${bruttoStr} EUR`, 70, 60);
  doc.setFont('helvetica','normal');

  doc.text(`(${betragInWorten(betrag)})`, 20, 68);

  doc.text('Von:', 20, 83);
  doc.text('AWO Jugendwerk Erftstadt', 45, 83);

  doc.text('Für:', 20, 93);
  const stundenText = (Math.round(gesamtStunden*100)/100).toString().replace('.',',');
  const fuerText = istStundenlohn
    ? `Aufwandsentschädigung ${p.name} (${stundenText} Std. à ${stundensatzWert.toFixed(2).replace('.',',')} EUR/h)`
    : (einheitlicherSatz!==null
        ? `Aufwandsentschädigung ${p.name} (${anzahlTage} Einsatztag${anzahlTage===1?'':'e'} à ${einheitlicherSatz.toFixed(2)} EUR)`
        : `Aufwandsentschädigung ${p.name} (${anzahlTage} Einsatztage, unterschiedliche Tagessätze je nach Verantwortung — siehe Personal-Tab)`);
  doc.text(doc.splitTextToSize(fuerText, 145), 45, 93);

  doc.text(`Ort: Erftstadt`, 20, 113);
  doc.text(`Datum: ${datumDe}`, 100, 113);

  doc.setFontSize(10);
  doc.text('Buchungsvermerke:', 20, 140);
  doc.line(20, 160, 90, 160);

  doc.text('Stempel/Unterschrift:', 110, 140);
  doc.line(110, 160, 190, 160);
  if(unterschrift){
    doc.addImage(unterschrift, 'PNG', 112, 143, 70, 15);
    doc.setFontSize(8);
    doc.text(`digital unterschrieben am ${datumDe}`, 110, 166);
    doc.setFontSize(10);
  }

  const dateiname = `Quittung_${p.name.replace(/\s+/g,'_')}_${heute.getFullYear()}${pad(heute.getMonth()+1)}${pad(heute.getDate())}.pdf`;
  return {doc, dateiname};
}

async function erstelleQuittungPDF(p){
  const ergebnis = await baueQuittungPDF(p, null);
  if(!ergebnis) return;
  ergebnis.doc.save(ergebnis.dateiname);
}

// qtEmailVorschlagFuerPerson: schlägt eine E-Mail-Adresse aus der Kartei
// vor (personenKarteiCache, wie beim Personal-Tab bereits geladen) — via
// p.personId, falls die Person mit der Kartei verknüpft ist (analog zu
// nachweisId(p), siehe Kommentar dort), sonst über p.id als Fallback für
// ältere, nicht verknüpfte Einträge.
function qtEmailVorschlagFuerPerson(p){
  const karteiId = p.personId || p.id;
  const kartei = (personenKarteiCache||[]).find(k=>k.id===karteiId);
  return (kartei && kartei.email) ? kartei.email : '';
}

// zeigeQuittungUnterschriftDialog: Signatur-Pad-Dialog für die/den
// Teamende(n) selbst (Empfangsbestätigung, siehe Migrationskommentar
// 70_quittung_unterschrift_email.sql) — KEINE zweite Unterschrift nötig,
// anders als beim Leihvertrag. Ablauf identisch: Admin öffnet den Dialog
// im Personal-Tab und reicht das Handy zum Unterschreiben weiter.
async function zeigeQuittungUnterschriftDialog(p){
  const anzahlTage = Array.isArray(p.einsatzTage) ? p.einsatzTage.length : 0;
  if(anzahlTage === 0){ alert(`${p.name} hat noch keine Einsatztage eingetragen.`); return; }

  let overlay = document.getElementById('qtUnterschriftOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'qtUnterschriftOverlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.35); z-index:1000; display:flex; align-items:center; justify-content:center; padding:20px;';
    document.body.appendChild(overlay);
  }

  overlay.innerHTML = `
    <div class="card" style="max-width:520px; width:100%; max-height:90vh; overflow-y:auto; position:relative;">
      <button class="btn ghost" id="qtUnterschriftSchliessenBtn" style="position:absolute; top:14px; right:14px;">✕</button>
      <h3 style="margin-top:0;">✍️ Quittung digital unterschreiben</h3>
      <p class="dp-hint" style="margin-top:0;">${escapeHtml(p.name)}</p>

      <label style="font-size:0.85rem; display:block; margin-top:10px;">Unterschrift (Empfangsbestätigung)</label>
      <canvas id="qtSigTeamende" style="width:100%; height:130px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
      <button class="btn ghost" type="button" id="qtSigLoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>

      <label style="font-size:0.85rem; display:block; margin-top:14px;">E-Mail für Versand (optional)
        <input type="email" id="qtUnterschriftEmail" placeholder="name@beispiel.de" style="width:100%; margin-top:2px; box-sizing:border-box;">
      </label>
      <label style="display:flex; align-items:center; gap:6px; margin-top:6px; font-weight:normal; font-size:0.85rem;">
        <input type="checkbox" id="qtUnterschriftEmailSenden" style="width:auto;">
        Unterschriebene Quittung zusätzlich direkt an diese Adresse senden
      </label>

      <div class="err" id="qtUnterschriftError" style="margin-top:10px;"></div>
      <div style="display:flex; gap:6px; margin-top:12px;">
        <button class="btn" id="qtUnterschriftSpeichernBtn" style="flex:1;">Unterschrift speichern &amp; PDF erstellen</button>
        <button class="btn ghost" id="qtUnterschriftAbbrechenBtn" style="flex:1;">Abbrechen</button>
      </div>
    </div>`;
  overlay.style.display = 'flex';

  const vorschlagEmail = qtEmailVorschlagFuerPerson(p);
  if(vorschlagEmail) document.getElementById('qtUnterschriftEmail').value = vorschlagEmail;

  // vlSignaturPadInit ist ein generisches Canvas-Signatur-Pad (ursprünglich
  // für den Leihvertrag gebaut, siehe Migration 61), hier unverändert
  // wiederverwendet statt dupliziert.
  const pad = vlSignaturPadInit(document.getElementById('qtSigTeamende'));
  document.getElementById('qtSigLoeschenBtn').addEventListener('click', ()=>pad.clear());

  const schliessen = ()=>{ overlay.style.display = 'none'; };
  document.getElementById('qtUnterschriftSchliessenBtn').addEventListener('click', schliessen);
  document.getElementById('qtUnterschriftAbbrechenBtn').addEventListener('click', schliessen);
  overlay.addEventListener('click', (e)=>{ if(e.target===overlay) schliessen(); });

  document.getElementById('qtUnterschriftSpeichernBtn').addEventListener('click', async ()=>{
    const errEl = document.getElementById('qtUnterschriftError');
    errEl.textContent = '';
    if(pad.isEmpty()){ errEl.textContent = '⚠️ Bitte die Unterschrift erfassen.'; return; }
    const unterschriftData = pad.toDataUrl();
    const emailSenden = document.getElementById('qtUnterschriftEmailSenden').checked;
    const emailAdresse = document.getElementById('qtUnterschriftEmail').value.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if(emailSenden && !emailRegex.test(emailAdresse)){
      errEl.textContent = '⚠️ Bitte eine gültige E-Mail-Adresse angeben, oder das Häkchen entfernen.';
      return;
    }
    const btn = document.getElementById('qtUnterschriftSpeichernBtn');
    btn.disabled = true;
    try{
      await epCallWithRetry({action:'admin_gehalt_quittung_unterschrift_speichern', pass: currentAuthPass, id: p.id, unterschriftData});
      schliessen();
      const ergebnis = await baueQuittungPDF(p, unterschriftData);
      if(ergebnis){
        ergebnis.doc.save(ergebnis.dateiname);
        if(emailSenden){
          try{
            const pdfBase64 = ergebnis.doc.output('datauristring').split(',')[1];
            await epCallWithRetry({
              action:'admin_gehalt_quittung_per_email', pass: currentAuthPass,
              id: p.id, empfaengerEmail: emailAdresse, personName: p.name,
              pdfBase64, dateiname: ergebnis.dateiname,
            });
          }catch(e){
            alert('Die Quittung wurde gespeichert und heruntergeladen, aber der E-Mail-Versand ist fehlgeschlagen: '+e.message);
          }
        }
      }
      await ladeGehaltCache();
      renderPersonal();
    }catch(e){
      errEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
      btn.disabled = false;
    }
  });
}

// qtErneutSenden: verschickt eine bereits digital unterschriebene Quittung
// erneut per E-Mail (z.B. an eine andere Adresse), ohne den Unterschrift-
// Dialog erneut zu öffnen — schlankes prompt() wie an anderer Stelle der
// App üblich für seltene Admin-Einzelaktionen (siehe z.B. Leihvertrag-
// Versand-Link).
async function qtErneutSenden(p){
  const gehaltRow = gehaltCache[p.id] || {};
  if(!gehaltRow.quittung_unterschrift_data){
    alert('Diese Quittung wurde noch nicht digital unterschrieben.');
    return;
  }
  const vorschlag = gehaltRow.quittung_email_adresse || qtEmailVorschlagFuerPerson(p);
  const email = (await eingabe('An welche E-Mail-Adresse soll die Quittung gesendet werden?', vorschlag || ''));
  if(!email) return;
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){
    alert('Ungültige E-Mail-Adresse.');
    return;
  }
  const ergebnis = await baueQuittungPDF(p, gehaltRow.quittung_unterschrift_data);
  if(!ergebnis) return;
  try{
    const pdfBase64 = ergebnis.doc.output('datauristring').split(',')[1];
    await epCallWithRetry({
      action:'admin_gehalt_quittung_per_email', pass: currentAuthPass,
      id: p.id, empfaengerEmail: email.trim(), personName: p.name,
      pdfBase64, dateiname: ergebnis.dateiname,
    });
    alert('Quittung wurde per E-Mail versendet.');
    await ladeGehaltCache();
    renderPersonal();
  }catch(e){
    alert('Versand fehlgeschlagen: '+e.message);
  }
}

// ================================================================
// PERSONAL-VERTRAGSDOKUMENTE (Migration 71/72): digitale Teamer-/
// Leitungsverträge, Selbstverpflichtungserklärung, Foto-/Video-
// Einwilligung der Teamenden — analog zu Leihvertrag/Quittung. Ein
// Dokument je (Aktion, Person, Dokumenttyp), siehe Migrationskommentar.
// ================================================================
let vertragsdokumenteCache = {};       // { "<personId>|<dokTyp>": zeile }
let vertragsdokumenteCacheLoaded = false;
let vertragsdokumenteLoading = false;

async function ladeVertragsdokumenteCache(){
  if(!isAdmin()) return;
  try{
    const data = await epCallWithRetry({action:'vertragsdokumente_list', pass: currentAuthPass});
    vertragsdokumenteCache = {};
    (data.dokumente||[]).forEach(d=>{ vertragsdokumenteCache[d.person_id+'|'+d.dokument_typ] = d; });
    vertragsdokumenteCacheLoaded = true;
  }catch(e){
    console.error('Vertragsdokumente konnten nicht geladen werden:', e);
  }
}

// Feste Tagessätze je Teamervertrag-Unterart, aus der Papier-Vorlage
// (Teamervertrag_Ferienspiele_Blanko.docx) — drei sich gegenseitig
// ausschließende Varianten des gleichen Vertrags.
const VT_TEAMERVERTRAG_ARTEN = {
  gruppenteamende: {label:'Gruppenteamende — mit Gruppenleitung', vertragstext:'mit Gruppenleitung (Gruppen-Teamende)', satz:35},
  teamende:        {label:'Teamende — mit Juleica-Fortbildung',    vertragstext:'mit Juleica-Fortbildung (Teamende)',    satz:30},
  hilfsteamende:   {label:'Hilfsteamende — ohne Juleica-Fortbildung', vertragstext:'ohne Juleica-Fortbildung (Hilfsteamende)', satz:25},
};

// vtDokumentTypVorschlag: rät den Dokumenttyp aus dem frei eingetragenen
// Rollentext (p.rolle) — bleibt im Dialog änderbar, ist nur ein Vorschlag.
function vtDokumentTypVorschlag(p){
  return /gesamtleitung/i.test(p.rolle||'') ? 'leitungsvertrag' : 'teamervertrag';
}
function vtTeamerArtVorschlag(p){
  const rolle = p.rolle||'';
  if(/gruppenteamende|gruppenleitung/i.test(rolle)) return 'gruppenteamende';
  if(/hilfsteamende/i.test(rolle)) return 'hilfsteamende';
  return 'teamende';
}

// wochenZeitraeumeFuerPerson: liefert für jede Woche/Gruppe, in der die
// Person mindestens einen Einsatztag hat, den frühesten/spätesten
// Einsatztag dieser Gruppe — Grundlage für die automatisch abgeleiteten
// Zeiträume im Teamervertrag (Rückmeldung Markus: "ja soll abgeleitet
// werden"). Nutzt baueAllDaysListe() (nicht nur state.weeks direkt), da
// Zusatztage (z.B. Aufbau, Wochenende) außerhalb der Wochen-Struktur
// liegen, aber genauso als Einsatztag zählen — ein Abgleich nur gegen
// state.weeks hätte solche Personen fälschlich als "ohne Einsatztage"
// gemeldet.
function wochenZeitraeumeFuerPerson(p){
  const dateById = {}, gruppeById = {};
  baueAllDaysListe().forEach(d=>{ if(d.date){ dateById[d.id] = d.date; gruppeById[d.id] = d.group; } });
  const eigeneIds = (p.einsatzTage||[]).filter(id=>dateById[id]);
  if(eigeneIds.length===0) return [];
  const nachGruppe = {};
  eigeneIds.forEach(id=>{
    const g = gruppeById[id] || 'Einsatztage';
    (nachGruppe[g] = nachGruppe[g] || []).push(dateById[id]);
  });
  return Object.entries(nachGruppe).map(([label, daten])=>{
    daten.sort();
    return {label, von: daten[0], bis: daten[daten.length-1]};
  }).sort((a,b)=>a.von.localeCompare(b.von));
}

// vtNameSplit: teilt p.name in Vor-/Nachname (gleiche Heuristik wie beim
// Bescheinigungsdialog: letztes Wort = Nachname, Rest = Vorname).
function vtNameSplit(p){
  const teile = (p.name||'').trim().split(/\s+/);
  return {
    vorname: teile.length>1 ? teile.slice(0,-1).join(' ') : (teile[0]||''),
    nachname: teile.length>1 ? teile[teile.length-1] : '',
  };
}

// vtGeburtsdatumFuerPerson: aus der Kartei (personenKarteiCache), sofern
// die Person damit verknüpft ist (gleiche Verknüpfungslogik wie nachweisId).
function vtGeburtsdatumFuerPerson(p){
  const kartei = (personenKarteiCache||[]).find(k=>k.id===nachweisId(p));
  return (kartei && kartei.geburtsdatum) ? kartei.geburtsdatum : '';
}

// vtIstMinderjaehrig: Alter zum Aktionsbeginn (oder heute, falls kein
// Aktionsdatum hinterlegt) — nutzt die bereits bestehende berechneAlter().
// Gibt null zurück, wenn kein Geburtsdatum vorliegt (Dialog zeigt dann
// einen Hinweis zur manuellen Prüfung, siehe zeigeVertragDialog).
function vtIstMinderjaehrig(geburtsdatum){
  if(!geburtsdatum) return null;
  const stichtag = (avAktuelleAktion && avAktuelleAktion.start_datum) || todayIso();
  const alter = berechneAlter(geburtsdatum, stichtag);
  return alter!=null ? alter < 18 : null;
}

// bauePersonalVertragPDF: baut eines der vier Vertragsdokumente. "formular"
// enthält die im Dialog erfassten/bestätigten Werte (siehe zeigeVertragDialog),
// "unterschriften" die PNG-Data-URLs ({auftraggeber, person, erz1, erz2, am}).
// Nutzt dieselben Hilfsfunktionen (Seitenumbruch, Fußzeile, Logo) wie
// baueLeihvertragPDF, damit alle Vertragsdokumente einheitlich aussehen.
async function bauePersonalVertragPDF(p, dokumentTyp, formular, unterschriften){
  await ladeBibliothek('jspdf');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  const marginL = 20, marginR = 190;
  const seitenUnten = 270;
  let y = 18;

  function pruefeSeitenumbruch(benoetigterPlatz){
    if(y + benoetigterPlatz > seitenUnten){ doc.addPage(); y = 20; }
  }
  function addUeberschrift(text){
    pruefeSeitenumbruch(9);
    doc.setFont('helvetica','bold'); doc.setFontSize(12);
    doc.text(text, marginL, y); y += 7;
  }
  function addAbsatz(text, abstandDanach){
    doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
    const zeilen = doc.splitTextToSize(text, marginR - marginL);
    pruefeSeitenumbruch(zeilen.length * 5);
    doc.text(zeilen, marginL, y);
    y += zeilen.length * 5 + (abstandDanach != null ? abstandDanach : 6);
  }
  function addFeldZeile(label, wert){
    pruefeSeitenumbruch(7);
    doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
    doc.text(label, marginL, y);
    doc.setDrawColor(120);
    doc.line(marginL + 45, y+1, marginR, y+1);
    if(wert) doc.text(String(wert), marginL + 47, y);
    y += 7;
  }
  // Kästchen wird als Rechteck gezeichnet statt über ein Unicode-Symbol
  // (☑/☐) dargestellt — jsPDFs Standard-Font (Helvetica/WinAnsi) enthält
  // diese Zeichen nicht zuverlässig, ein Kästchen aus Linien funktioniert
  // dagegen mit jeder Schriftart.
  function addCheckbox(checked, text){
    pruefeSeitenumbruch(6);
    doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
    doc.setDrawColor(60);
    doc.rect(marginL, y - 3.6, 4, 4);
    if(checked){
      doc.setLineWidth(0.5);
      doc.line(marginL + 0.5, y - 1.8, marginL + 1.7, y - 0.2);
      doc.line(marginL + 1.7, y - 0.2, marginL + 3.6, y - 3.4);
      doc.setLineWidth(0.2);
    }
    const zeilen = doc.splitTextToSize(text, marginR - marginL - 8);
    doc.text(zeilen, marginL + 7, y);
    y += Math.max(zeilen.length,1) * 5 + 1;
  }

  const logo = await ladeLogoAlsDataURL();
  if(logo){
    const logoBreite = 26, logoHoehe = logoBreite * logo.hoehe / logo.breite;
    doc.addImage(logo.dataUrl, 'PNG', marginR - logoBreite, y - 8, logoBreite, logoHoehe);
  }
  doc.setFont('helvetica','normal'); doc.setFontSize(8.5);
  doc.text('AWO Jugendwerk Erftstadt · Bahnhofstr. 7 · 50374 Erftstadt', marginL, y);
  doc.text(`Erftstadt, den ${fmtDateFull(todayIso())}`, marginR, y + 14, {align:'right'});
  y = 42;

  const {vorname, nachname} = vtNameSplit(p);
  const geburtsdatum = formular.geburtsdatum ? fmtDateFull(formular.geburtsdatum) : '';

  function unterschriftenblock(zeilen){
    // zeilen: Array aus {label, data} — bis zu zwei nebeneinander pro Reihe.
    pruefeSeitenumbruch(34);
    doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
    doc.text('Ort, Datum:', marginL, y);
    doc.line(marginL + 26, y+1, marginR, y+1);
    y += 20;
    const sigBreite = 55, sigHoehe = 16;
    for(let i=0; i<zeilen.length; i+=2){
      const paar = zeilen.slice(i, i+2);
      paar.forEach((z, idx)=>{
        const x = marginL + idx*90;
        if(z.data) doc.addImage(z.data, 'PNG', x, y - sigHoehe, sigBreite, sigHoehe);
        doc.line(x, y, x + (paar.length>1?70:150), y);
      });
      y += 5;
      paar.forEach((z, idx)=>{ doc.text(`(${z.label})`, marginL + idx*90, y); });
      if(unterschriften?.am && paar.some(z=>z.data)){
        doc.setFontSize(7); doc.setTextColor(120);
        paar.forEach((z, idx)=>{ if(z.data) doc.text(`digital unterschrieben am ${fmtDateFull(String(unterschriften.am).slice(0,10))}`, marginL + idx*90, y+4); });
        doc.setTextColor(0); doc.setFontSize(10.5);
      }
      y += 20;
    }
  }

  if(dokumentTyp === 'teamervertrag'){
    const art = VT_TEAMERVERTRAG_ARTEN[formular.art] || VT_TEAMERVERTRAG_ARTEN.teamende;
    doc.setFont('helvetica','bold'); doc.setFontSize(16);
    doc.text('Ehrenamtsvertrag für Teamende / Hilfsteamende', 105, y, {align:'center'});
    y += 12;
    addAbsatz('Das Stadtjugendwerk der AWO Erftstadt (nachfolgend „Auftraggeber" genannt) schließt für den Zeitraum der Ferienspiele folgenden Vertrag für: '+art.vertragstext+' ab.', 4);
    (formular.wochen||[]).forEach(w=>{
      addFeldZeile(`${w.label}:`, `${fmtDateFull(w.von)} – ${fmtDateFull(w.bis)}`);
    });
    addFeldZeile('Name:', p.name);
    addFeldZeile('Geburtsdatum:', geburtsdatum || '(bitte ergänzen)');
    y += 2;
    addUeberschrift('§ 1 Auftragsinhalt');
    addAbsatz('Der/die Teamende erbringt im oben genannten Zeitraum für den Auftraggeber im Rahmen der gemeinnützigen Arbeit des Auftraggebers folgende Tätigkeiten/Aufgaben: Aufsicht von Kindern und Jugendlichen; Betreuung und Unterhaltung der Kinder und Jugendlichen; eigenverantwortliches Arbeiten im Rahmen seiner/ihrer Verantwortung und Fähigkeiten; Vor- und Nachbereitung der Unterhaltungsangebote/Projekte; Teilnahme an Teambesprechungen; Verhalten nach dem Verhaltenskodex und den Richtlinien zur Jugendarbeit des Bundesjugendwerkes; Unterzeichnung einer Selbstverpflichtungserklärung; stets dem Kindeswohl bedacht zu agieren; ggf. Führen einer Gruppe.', 4);
    addAbsatz(`Die Tätigkeiten werden ehrenhalber, also unentgeltlich übernommen. Es werden Stundennachweise geführt. Die Aufwandsentschädigung beträgt ${(formular.tagessatz!=null?formular.tagessatz:art.satz).toFixed(2)} € ${formular.verguetungModell==='stundenlohn' ? 'pro geleisteter Stunde (individuell vereinbarter Stundenlohn)' : 'pro anwesendem Tag'} (im Rahmen der steuerlichen Freibeträge gemäß § 3 Nr. 26a EStG — sollte der Freibetrag durch weitere Tätigkeiten bereits ausgeschöpft sein, ist dies dem Auftraggeber mitzuteilen). Dieser Vertrag begründet kein arbeitsrechtliches Rechtsverhältnis; es ergeben sich keine Ansprüche auf Übernahme in ein sozialversicherungspflichtiges Beschäftigungsverhältnis. Der/die Teamende ist während der Arbeitszeit sowie auf Fahrten hin und zurück über die BGW versichert.`, 6);
    addUeberschrift('§ 2 Weisungsrecht, Einsatzzeit, Hausordnung');
    addAbsatz('Der/die Teamende richtet sich bei der Erfüllung der Tätigkeiten nach den Weisungen des Auftraggebers. Die Regelarbeitszeit ist von Montag bis Freitag 08:00–17:00 Uhr. Bei Anwesenheit von mehr als 4,5 Stunden ist eine Mindestpause von 30 Minuten vorgesehen. Die Arbeitszeit endet mit dem Abschluss der Nachbesprechung. Im Verhinderungsfall hat der/die Teamende den Auftraggeber zu informieren und evtl. betroffene Dritte rechtzeitig zu benachrichtigen. Der/die Teamende ist außerdem verpflichtet, die betriebliche Ordnung zu beachten und mit anvertrauten Arbeitsmitteln pfleglich umzugehen.', 6);
    addUeberschrift('§ 3 Kündigung');
    addAbsatz('Beide Parteien können den Vertrag ordentlich kündigen; die Kündigungsfrist beträgt 3 Tage. Der Vertrag kann auch in beiderseitigem Einvernehmen mit kürzerer Frist aufgehoben werden. Eine Frist entfällt, wenn ein wichtiger Grund eine fristlose Kündigung rechtfertigt.', 6);
    addUeberschrift('§ 4 Haftung');
    addAbsatz('Der/die Teamende haftet bei Schäden gegenüber dem Auftraggeber nur für Vorsatz und grobe Fahrlässigkeit. Für Haftungsfragen gelten im Übrigen die Regelungen des BGB. Für Schäden gegen Dritte hat der Auftraggeber eine Haftpflichtversicherung abgeschlossen.', 6);
    addUeberschrift('§ 5 Unfälle und Schäden des/der Teamenden');
    addAbsatz('Der Auftraggeber haftet dem/der Teamenden für Schäden, die dieser/diese während der Verrichtung des Auftrags wegen eines Verschuldens des Auftraggebers erleidet — soweit diese nicht durch die gesetzliche Unfallversicherung gedeckt sind.', 6);
    addUeberschrift('§ 6 Verschwiegenheit & Datenschutz');
    addAbsatz('Der/die Teamende verpflichtet sich, über betriebliche sowie über alle vertraulichen Angelegenheiten und Vorgänge, die ihm/ihr in Ausübung und Vorbereitung seiner/ihrer Tätigkeit anvertraut oder sonst bekannt werden, Stillschweigen zu bewahren. Verletzungen können zu Schadensersatzforderungen und zur Kündigung führen. Die Verschwiegenheitspflicht gilt nicht, soweit gesetzliche Meldepflichten bestehen — insbesondere nach § 8a SGB VIII bei Verdacht auf Kindeswohlgefährdung.', 4);
    addAbsatz('Datenschutzinformation gemäß Art. 13 DSGVO: Verantwortlicher ist das AWO Jugendwerk Erftstadt, Bahnhofstr. 7, 50374 Erftstadt, jugendwerk-awo-erftstadt@web.de. Ihre Daten (Name, Geburtsdatum, Kontoverbindung) werden zur Durchführung des Ehrenamtsverhältnisses und zur Auszahlung der Aufwandsentschädigung verarbeitet (Rechtsgrundlage Art. 6 Abs. 1 lit. b DSGVO). Speicherdauer: 10 Jahre nach Vertragsende (steuerrechtliche Aufbewahrungspflicht). Es besteht ein Recht auf Auskunft, Berichtigung und Löschung sowie ein Beschwerderecht bei der zuständigen Aufsichtsbehörde (z. B. LDI NRW).', 6);
    addUeberschrift('§ 7 Salvatorische Klausel');
    addAbsatz('Sollten einzelne Bestimmungen dieses Vertrags ganz oder teilweise unwirksam sein oder werden, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.', 6);
    addUeberschrift('§ 8 Erweitertes Führungszeugnis');
    addAbsatz('Der/die Teamende ist verpflichtet, vor Tätigkeitsbeginn ein erweitertes Führungszeugnis gemäß § 30a BZRG vorzulegen, das zum Zeitpunkt der Vorlage nicht älter als drei Monate sein darf. Bei einschlägigen Eintragungen ist der Auftraggeber berechtigt, den Vertrag fristlos zu kündigen.', formular.minderjaehrig ? 4 : 6);
    if(formular.minderjaehrig){
      addAbsatz('Bei Teamenden unter 18 Jahren ist die Unterschrift eines Erziehungsberechtigten zwingend erforderlich. Mit der Unterschrift bestätigt/bestätigen die/der Erziehungsberechtigte(n) ihr Einverständnis mit allen Vertragsbedingungen.', 6);
    }
    const zeilen = [
      {label:'Auftraggeber', data: unterschriften?.auftraggeber},
      {label:'Teamende/r', data: unterschriften?.person},
    ];
    if(formular.minderjaehrig){
      zeilen.push({label:'Erziehungsberechtigte/r 1', data: unterschriften?.erz1});
      if(unterschriften?.erz2) zeilen.push({label:'Erziehungsberechtigte/r 2', data: unterschriften?.erz2});
    }
    unterschriftenblock(zeilen);

  } else if(dokumentTyp === 'leitungsvertrag'){
    doc.setFont('helvetica','bold'); doc.setFontSize(16);
    doc.text('Ehrenamtsvertrag für Gesamtleitung der Ferienspiele', 105, y, {align:'center'});
    y += 12;
    addAbsatz('Das Stadtjugendwerk der AWO Erftstadt (nachfolgend „Auftraggeber" genannt) schließt für den Zeitraum der Ferienspiele folgenden Ehrenamtsvertrag als Gesamtleitung ab.', 4);
    addFeldZeile('Zeitraum:', formular.zeitraumVon && formular.zeitraumBis ? `${fmtDateFull(formular.zeitraumVon)} – ${fmtDateFull(formular.zeitraumBis)}` : '(bitte ergänzen)');
    addFeldZeile('Name:', p.name);
    addFeldZeile('Geburtsdatum:', geburtsdatum || '(bitte ergänzen)');
    y += 2;
    addUeberschrift('§ 1 Auftragsinhalt');
    addAbsatz('Die Gesamtleitung erbringt im oben genannten Zeitraum für den Auftraggeber im Rahmen der gemeinnützigen Arbeit des Auftraggebers folgende Tätigkeiten/Aufgaben: Gesamtverantwortung für Planung, Organisation und Durchführung der Ferienspiele; fachliche und organisatorische Leitung aller Teamenden vor Ort; Aufsicht über alle Kinder und Jugendlichen im Rahmen der Ferienspiele; Krisenmanagement und abschließende Entscheidungsverantwortung bei schwierigen Situationen vor Ort; Ansprechperson für Erziehungsberechtigte, externe Partner und den Auftraggeber; Planung, Einberufung und Leitung von Teambesprechungen; Koordination der Gruppen und Programmangebote; Vor- und Nachbereitung der Ferienspiele in Abstimmung mit dem Auftraggeber; Unterzeichnung einer Selbstverpflichtungserklärung und Vorlage des erweiterten Führungszeugnisses; stets dem Kindeswohl bedacht zu agieren.', 4);
    addAbsatz(`Die Tätigkeiten werden ehrenhalber, also unentgeltlich übernommen. Es werden Tätigkeitsnachweise geführt. Die Aufwandsentschädigung beträgt ${(formular.tagessatz!=null?formular.tagessatz:90).toFixed(2)} € ${formular.verguetungModell==='stundenlohn' ? 'pro geleisteter Stunde (individuell vereinbarter Stundenlohn)' : 'pro anwesendem Tag'} (im Rahmen der steuerlichen Freibeträge gemäß § 3 Nr. 26 EStG). Dieser Vertrag begründet kein arbeitsrechtliches Rechtsverhältnis; es ergeben sich keine Ansprüche auf Übernahme in ein sozialversicherungspflichtiges Beschäftigungsverhältnis. Die Gesamtleitung ist während der Arbeitszeit sowie auf Fahrten hin und zurück über die BGW versichert.`, 6);
    addUeberschrift('§ 2 Weisungsrecht, Einsatzzeit, Hausordnung');
    addAbsatz('Die Gesamtleitung richtet sich bei der Erfüllung der Tätigkeiten nach den Weisungen des Auftraggebers. Die Gesamtleitung wird von insgesamt drei Personen gleichberechtigt wahrgenommen; dieser Vertrag wird mit jeder Person einzeln abgeschlossen. Entscheidungen werden im gegenseitigen Einvernehmen getroffen. Die Regelarbeitszeit ist von Montag bis Freitag 08:00–17:00 Uhr. Bei Anwesenheit von mehr als 4,5 Stunden ist eine Mindestpause von 30 Minuten vorgesehen. Die Arbeitszeit endet mit dem Abschluss der Nachbesprechung. Im Verhinderungsfall ist der Auftraggeber und sind evtl. betroffene Dritte rechtzeitig zu informieren. Die Gesamtleitung ist außerdem verpflichtet, die betriebliche Ordnung zu beachten und mit anvertrauten Arbeitsmitteln pfleglich umzugehen.', 6);
    addUeberschrift('§ 3 Kündigung');
    addAbsatz('Beide Parteien können den Vertrag ordentlich kündigen; die Kündigungsfrist beträgt 3 Tage. Der Vertrag kann auch in beiderseitigem Einvernehmen mit kürzerer Frist aufgehoben werden. Eine Frist entfällt, wenn ein wichtiger Grund eine fristlose Kündigung rechtfertigt.', 6);
    addUeberschrift('§ 4 Haftung der Gesamtleitung');
    addAbsatz('Die Gesamtleitung haftet bei Schäden gegenüber dem Auftraggeber nur für Vorsatz und grobe Fahrlässigkeit. Für Haftungsfragen gelten im Übrigen die Regelungen des BGB. Für Schäden gegen Dritte hat der Auftraggeber eine Haftpflichtversicherung abgeschlossen.', 6);
    addUeberschrift('§ 5 Unfälle und Schäden der Gesamtleitung');
    addAbsatz('Der Auftraggeber haftet der Gesamtleitung für Schäden, die diese während der Verrichtung des Auftrags wegen eines Verschuldens des Auftraggebers erleidet — soweit diese nicht durch die gesetzliche Unfallversicherung gedeckt sind.', 6);
    addUeberschrift('§ 6 Verschwiegenheit & Datenschutz');
    addAbsatz('Die Gesamtleitung verpflichtet sich, über betriebliche sowie über alle vertraulichen Angelegenheiten und Vorgänge, die ihr in Ausübung und Vorbereitung ihrer Tätigkeit anvertraut oder sonst bekannt werden, Stillschweigen zu bewahren. Verletzungen können zu Schadensersatzforderungen und zur Kündigung führen. Die Verschwiegenheitspflicht gilt nicht, soweit gesetzliche Meldepflichten bestehen — insbesondere nach § 8a SGB VIII bei Verdacht auf Kindeswohlgefährdung.', 4);
    addAbsatz('Datenschutzinformation gemäß Art. 13 DSGVO: Verantwortlicher ist das AWO Jugendwerk Erftstadt, Bahnhofstr. 7, 50374 Erftstadt, jugendwerk-awo-erftstadt@web.de. Ihre Daten (Name, Geburtsdatum, Kontoverbindung) werden zur Durchführung des Ehrenamtsverhältnisses und zur Auszahlung der Aufwandsentschädigung verarbeitet (Rechtsgrundlage Art. 6 Abs. 1 lit. b DSGVO). Speicherdauer: 10 Jahre nach Vertragsende (steuerrechtliche Aufbewahrungspflicht). Es besteht ein Recht auf Auskunft, Berichtigung und Löschung sowie ein Beschwerderecht bei der zuständigen Aufsichtsbehörde (z. B. LDI NRW).', 6);
    addUeberschrift('§ 7 Salvatorische Klausel');
    addAbsatz('Sollten einzelne Bestimmungen dieses Vertrags ganz oder teilweise unwirksam sein oder werden, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.', 6);
    addUeberschrift('§ 8 Erweitertes Führungszeugnis');
    addAbsatz('Die Gesamtleitung ist verpflichtet, vor Tätigkeitsbeginn ein erweitertes Führungszeugnis gemäß § 30a BZRG vorzulegen, das zum Zeitpunkt der Vorlage nicht älter als drei Monate sein darf. Bei einschlägigen Eintragungen ist der Auftraggeber berechtigt, den Vertrag fristlos zu kündigen.', 6);
    unterschriftenblock([
      {label:'Auftraggeber', data: unterschriften?.auftraggeber},
      {label:'Gesamtleitung', data: unterschriften?.person},
    ]);

  } else if(dokumentTyp === 'selbstverpflichtung'){
    doc.setFont('helvetica','bold'); doc.setFontSize(16);
    doc.text('Selbstverpflichtungserklärung', 105, y, {align:'center'});
    doc.setFontSize(11); y += 7;
    doc.text('Wahrnehmung von Aufgaben in der Kinder- und Jugendhilfe', 105, y, {align:'center'});
    y += 12;
    addFeldZeile('Nachname:', nachname);
    addFeldZeile('Vorname:', vorname);
    addFeldZeile('Geburtsdatum:', geburtsdatum || '(bitte ergänzen)');
    addFeldZeile('Geburtsort:', formular.geburtsort || '(vor Ort handschriftlich einzutragen)');
    y += 2;
    addAbsatz('Ich achte die körperliche, psychische und geistige Unversehrtheit mir anvertrauter Kinder. Hierfür gehe ich folgende Verpflichtungen ein:', 4);
    addAbsatz('1. Ich versichere, nicht wegen einer in § 72a Abs. 1 SGB VIII benannten Straftat rechtskräftig verurteilt worden zu sein und keine Kenntnis davon zu haben, dass ein Straf- oder staatsanwaltschaftliches Ermittlungsverfahren wegen einer solchen Straftat gegen mich anhängig ist.', 3);
    addAbsatz('2. Ich versichere ferner, nicht in einem anderen Staat außerhalb der Bundesrepublik Deutschland wegen vergleichbarer Straftaten verurteilt worden zu sein oder Kenntnis von entsprechenden Ermittlungsverfahren zu haben.', 3);
    addAbsatz('3. Ich bin darüber informiert, dass eine nicht wahrheitsgemäße Angabe bzw. ein Verstoß gegen die Mitteilungspflicht personalrechtliche Konsequenzen bis zur Beendigung meines Beschäftigungsverhältnisses haben kann.', 3);
    addAbsatz('4. Ich habe das Schutzkonzept des AWO Jugendwerks Erftstadt in der jeweils aktuellen Fassung zur Kenntnis genommen und werde es beachten.', 3);
    addAbsatz('5. Die Inhalte dieser Selbstverpflichtung habe ich verstanden. Ich stimme mit ihnen überein, werde nach ihnen handeln und sie nach innen und außen vertreten.', 8);
    unterschriftenblock([{label:'Unterschrift', data: unterschriften?.person}]);

  } else if(dokumentTyp === 'foto_einwilligung'){
    doc.setFont('helvetica','bold'); doc.setFontSize(16);
    doc.text('Einverständniserklärung Foto-/Videoaufnahmen', 105, y, {align:'center'});
    y += 12;
    addUeberschrift('Verantwortliche Stelle');
    addAbsatz('AWO Jugendwerk Erftstadt, Bahnhofstr. 7, 50374 Erftstadt, jugendwerk-awo-erftstadt@web.de', 6);
    addFeldZeile('Name:', p.name);
    addFeldZeile('Geburtsdatum:', geburtsdatum || '(bitte ergänzen)');
    y += 2;
    addAbsatz('Ich erkläre hiermit mein ausdrückliches Einverständnis, dass Foto- und/oder Videoaufnahmen von mir angefertigt und für folgende Zwecke verarbeitet und veröffentlicht werden dürfen:', 4);
    addCheckbox(!!formular.zweckWebsite, 'Veröffentlichung auf der Website (Internet)');
    addCheckbox(!!formular.zweckPrint, 'Nutzung in (Print-)Publikationen (z. B. Broschüren, Veranstaltungsprogramme)');
    addCheckbox(!!formular.zweckSocial, 'Veröffentlichung in Social-Media-Kanälen (z. B. Facebook, Instagram)');
    addCheckbox(!!formular.zweckOeffentlichkeitsarbeit, 'Nutzung im Rahmen von Öffentlichkeitsarbeit / Marketing');
    if(formular.zweckAndereText) addCheckbox(true, 'Andere: '+formular.zweckAndereText);
    y += 2;
    addAbsatz('Die Veröffentlichung darf weltweit und zeitlich unbefristet erfolgen, sofern nicht anders angegeben.', 6);
    addUeberschrift('Rechtsgrundlage & Widerrufsrecht');
    addAbsatz('Die Anfertigung und Nutzung der Aufnahmen erfolgt auf Grundlage der freiwillig erteilten Einwilligung (Art. 6 Abs. 1 lit. a DSGVO) unter Beachtung des Rechts am eigenen Bild (§ 22 KUG). Diese Einwilligung kann jederzeit ohne Angabe von Gründen mit Wirkung für die Zukunft widerrufen werden — formlos per E-Mail an jugendwerk-awo-erftstadt@web.de oder schriftlich an AWO Jugendwerk Erftstadt, Bahnhofstr. 7, 50374 Erftstadt. Der Widerruf hat keine rückwirkende Kraft auf bereits erfolgte, nicht rückgängig zu machende Veröffentlichungen.', formular.minderjaehrig ? 4 : 6);
    if(formular.minderjaehrig){
      addAbsatz('Da die abgebildete Person zum Zeitpunkt der Einwilligung minderjährig ist, ist zusätzlich die Unterschrift der/des Erziehungsberechtigten erforderlich.', 6);
    }
    unterschriftenblock(formular.minderjaehrig
      ? [{label:'abgebildete Person', data: unterschriften?.person}, {label:'Erziehungsberechtigte/r 1', data: unterschriften?.erz1}]
      : [{label:'abgebildete Person', data: unterschriften?.person}]);
  }

  const gesamtSeiten = doc.internal.getNumberOfPages();
  for(let s=1; s<=gesamtSeiten; s++){ doc.setPage(s); zeichneVertragsFusszeile(doc, marginL); }
  return doc;
}

const VT_TITEL = {
  teamervertrag: 'Teamer-/Leitungsvertrag', leitungsvertrag: 'Teamer-/Leitungsvertrag',
  selbstverpflichtung: 'Selbstverpflichtungserklärung', foto_einwilligung: 'Foto-/Video-Einwilligung',
};
const VT_DATEINAME = {
  teamervertrag: 'Ehrenamtsvertrag', leitungsvertrag: 'Ehrenamtsvertrag_Gesamtleitung',
  selbstverpflichtung: 'Selbstverpflichtungserklaerung', foto_einwilligung: 'Foto-Video-Einwilligung',
};

// zeigeVertragDialog: EIN Dialog für alle vier Dokumenttypen — welche
// Felder/Unterschriften angezeigt werden, hängt vom übergebenen
// dokumentTypVorgabe ab (bei 'teamervertrag' kann der Admin im Dialog noch
// auf 'leitungsvertrag' umschalten, siehe <select>). Reicht das Handy pro
// Unterschrift einzeln weiter (Auftraggeber -> Person -> ggf.
// Erziehungsberechtigte), analog zum Leihvertrag.
function vtBenoetigtAuftraggeberClientSeitig(dokumentTyp){
  return dokumentTyp === 'teamervertrag' || dokumentTyp === 'leitungsvertrag';
}

// vtButtonKlick: entscheidet anhand des Caches, ob ein frisches Dokument
// erstellt wird (zeigeVertragDialog) oder ob für diesen Dokumenttyp bereits
// eine Personen-Unterschrift vorliegt und nur noch die Auftraggeber-
// Unterschrift fehlt (zeigeAuftraggeberFertigstellenDialog) — z.B. weil
// die/der Teamende im eigenen Zugang bereits selbst unterschrieben hat.
// Beim "📄 Vertrag"-Button (dokumentTypVorgabe='teamervertrag') werden
// dafür beide möglichen Varianten (Teamer-/Leitungsvertrag) geprüft, da
// zu diesem Zeitpunkt noch nicht feststeht, welche davon ggf. bereits
// vorbereitet/unterschrieben wurde.
async function vtButtonKlick(p, dokumentTypVorgabe){
  let offenerTyp = null;
  if(dokumentTypVorgabe === 'teamervertrag'){
    for(const t of ['teamervertrag','leitungsvertrag']){
      const z = vertragsdokumenteCache[nachweisId(p)+'|'+t];
      if(z && z.unterschrift_person_am && !z.unterschrift_auftraggeber_am){ offenerTyp = t; break; }
    }
  } else if(vtBenoetigtAuftraggeberClientSeitig(dokumentTypVorgabe)){
    const z = vertragsdokumenteCache[nachweisId(p)+'|'+dokumentTypVorgabe];
    if(z && z.unterschrift_person_am && !z.unterschrift_auftraggeber_am) offenerTyp = dokumentTypVorgabe;
  }
  if(offenerTyp){
    try{
      const geholt = await epCallWithRetry({action:'admin_vertrag_dokument_holen', pass: currentAuthPass, personId: nachweisId(p), dokumentTyp: offenerTyp});
      zeigeAuftraggeberFertigstellenDialog(p, offenerTyp, geholt.dokument);
      return;
    }catch(e){
      alert('Konnte das vorliegende Dokument nicht laden: '+e.message);
      return;
    }
  }
  zeigeVertragDialog(p, dokumentTypVorgabe);
}

// zeigeAuftraggeberFertigstellenDialog: schlanker Dialog, wenn die/der
// Teamende die eigene Unterschrift bereits selbst im Team-Zugang erfasst
// hat (oder der Admin das Dokument nur vorbereitet und die Person
// zwischenzeitlich remote unterschrieben hat) — Inhalt ist als Snapshot
// bereits fest ("daten" aus der DB, nicht mehr editierbar), es fehlt nur
// noch die Auftraggeber-Unterschrift (+ Erziehungsberechtigte, falls
// minderjährig und noch nicht erfasst). Nach dem Speichern wird bei
// Vollständigkeit automatisch die fertige PDF gebaut und per E-Mail an
// die Person verschickt (Rückmeldung Markus: "informiert, dass der
// Vertrag fertig ist").
async function zeigeAuftraggeberFertigstellenDialog(p, dokumentTyp, dok){
  let overlay = document.getElementById('vtFertigOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'vtFertigOverlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.35); z-index:1000; display:flex; align-items:center; justify-content:center; padding:20px;';
    document.body.appendChild(overlay);
  }
  const daten = dok.daten || {};
  const minderjaehrigUndOffen = !!daten.minderjaehrig && !dok.unterschrift_erz1_data;

  overlay.innerHTML = `
    <div class="card" style="max-width:520px; width:100%; max-height:90vh; overflow-y:auto; position:relative;">
      <button class="btn ghost" id="vtFertigSchliessenBtn" style="position:absolute; top:14px; right:14px;">✕</button>
      <h3 style="margin-top:0;">📄 ${escapeHtml(VT_TITEL[dokumentTyp])} — ${escapeHtml(p.name)}</h3>
      <p class="dp-hint" style="margin-top:0;">✓ ${escapeHtml(p.name)} hat bereits am ${escapeHtml(fmtDateFull(String(dok.unterschrift_person_am).slice(0,10)))} unterschrieben. Es fehlt nur noch deine Unterschrift als Auftraggeber.</p>
      <button class="btn ghost" type="button" id="vtFertigVorschauBtn" style="width:100%; font-size:0.82rem; padding:5px 8px; margin-bottom:6px;">📄 Zum Lesen öffnen</button>

      <label style="font-size:0.85rem; display:block; margin-top:8px;">Unterschrift Auftraggeber (AWO Jugendwerk Erftstadt)</label>
      <canvas id="vtFertigSigAg" style="width:100%; height:120px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
      <button class="btn ghost" type="button" id="vtFertigSigAgLoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>

      <div id="vtFertigErzBereich" style="display:${minderjaehrigUndOffen?'block':'none'};">
        <label style="font-size:0.85rem; display:block; margin-top:14px;">Unterschrift Erziehungsberechtigte/r 1 (Person ist minderjährig)</label>
        <canvas id="vtFertigSigErz1" style="width:100%; height:120px; border:1px solid #e5ddd0; border-radius:6px; background:#fff; touch-action:none; display:block; margin-top:4px;"></canvas>
        <button class="btn ghost" type="button" id="vtFertigSigErz1LoeschenBtn" style="font-size:0.78rem; padding:3px 8px; margin-top:4px;">Löschen</button>
      </div>

      <label style="font-size:0.85rem; display:block; margin-top:14px;">E-Mail der Person für den automatischen Versand
        <input type="email" id="vtFertigEmail" placeholder="name@beispiel.de" style="width:100%; margin-top:2px; box-sizing:border-box;">
      </label>

      <div class="err" id="vtFertigError" style="margin-top:10px;"></div>
      <div style="display:flex; gap:6px; margin-top:12px;">
        <button class="btn" id="vtFertigSpeichernBtn" style="flex:1;">Unterschreiben, fertigstellen &amp; an Person senden</button>
        <button class="btn ghost" id="vtFertigAbbrechenBtn" style="flex:1;">Abbrechen</button>
      </div>
    </div>`;
  overlay.style.display = 'flex';

  const vorschlagEmail = qtEmailVorschlagFuerPerson(p);
  if(vorschlagEmail) document.getElementById('vtFertigEmail').value = vorschlagEmail;

  const padAg = vlSignaturPadInit(document.getElementById('vtFertigSigAg'));
  document.getElementById('vtFertigSigAgLoeschenBtn').addEventListener('click', ()=>padAg.clear());
  let padErz1 = null;
  if(minderjaehrigUndOffen){
    padErz1 = vlSignaturPadInit(document.getElementById('vtFertigSigErz1'));
    document.getElementById('vtFertigSigErz1LoeschenBtn').addEventListener('click', ()=>padErz1.clear());
  }

  const schliessen = ()=>{ overlay.style.display = 'none'; };
  document.getElementById('vtFertigSchliessenBtn').addEventListener('click', schliessen);
  document.getElementById('vtFertigAbbrechenBtn').addEventListener('click', schliessen);
  overlay.addEventListener('click', (e)=>{ if(e.target===overlay) schliessen(); });

  document.getElementById('vtFertigVorschauBtn').addEventListener('click', async ()=>{
    const vorschauFenster = window.open('', '_blank');
    try{
      const unterschriften = {person: dok.unterschrift_person_data, erz1: dok.unterschrift_erz1_data, am: dok.unterschrift_person_am};
      const doc = await bauePersonalVertragPDF(p, dokumentTyp, daten, unterschriften);
      const blobUrl = doc.output('bloburl');
      if(vorschauFenster) vorschauFenster.location.href = blobUrl;
      else alert('Konnte nicht in einem neuen Tab geöffnet werden — bitte Popup-Blocker deaktivieren.');
    }catch(e){
      if(vorschauFenster) vorschauFenster.close();
      alert('Vorschau konnte nicht erstellt werden: '+e.message);
    }
  });

  document.getElementById('vtFertigSpeichernBtn').addEventListener('click', async ()=>{
    const errEl = document.getElementById('vtFertigError');
    errEl.textContent = '';
    if(padAg.isEmpty()){ errEl.textContent = '⚠️ Bitte die Unterschrift des Auftraggebers erfassen.'; return; }
    if(minderjaehrigUndOffen && (!padErz1 || padErz1.isEmpty())){ errEl.textContent = '⚠️ Bitte die Unterschrift der/des Erziehungsberechtigten erfassen.'; return; }
    const email = document.getElementById('vtFertigEmail').value.trim();
    const emailGueltig = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

    const btn = document.getElementById('vtFertigSpeichernBtn');
    btn.disabled = true;
    try{
      const auftraggeberData = padAg.toDataUrl();
      const erz1Data = (minderjaehrigUndOffen && padErz1 && !padErz1.isEmpty()) ? padErz1.toDataUrl() : null;
      const ergebnis = await epCallWithRetry({
        action:'admin_vertrag_unterschrift_speichern', pass: currentAuthPass,
        personId: nachweisId(p), dokumentTyp, auftraggeberData, erz1Data,
      });
      schliessen();
      if(ergebnis.vollstaendig){
        const geholt = await epCallWithRetry({action:'admin_vertrag_dokument_holen', pass: currentAuthPass, personId: nachweisId(p), dokumentTyp});
        const finalesDok = geholt.dokument;
        const unterschriften = {
          auftraggeber: finalesDok.unterschrift_auftraggeber_data, person: finalesDok.unterschrift_person_data,
          erz1: finalesDok.unterschrift_erz1_data, erz2: finalesDok.unterschrift_erz2_data,
          am: finalesDok.unterschrift_person_am,
        };
        const finalesDaten = finalesDok.daten || daten;
        const finalPdf = await bauePersonalVertragPDF(p, dokumentTyp, finalesDaten, unterschriften);
        const dateiSicherName = (p.name||'Person').replace(/[^\p{L}\p{N}]+/gu, '_');
        const dateiname = `${VT_DATEINAME[dokumentTyp]}_${dateiSicherName}_${stamp()}.pdf`;
        finalPdf.save(dateiname);
        if(emailGueltig){
          try{
            const pdfBase64 = finalPdf.output('datauristring').split(',')[1];
            await epCallWithRetry({
              action:'admin_vertrag_per_email', pass: currentAuthPass,
              personId: nachweisId(p), dokumentTyp, empfaengerEmail: email, personName: p.name,
              pdfBase64, dateiname,
            });
            alert('Vertrag ist vollständig unterschrieben und wurde per E-Mail an '+p.name+' versendet.');
          }catch(e){
            alert('Vertrag ist vollständig unterschrieben, der automatische Versand ist aber fehlgeschlagen: '+e.message+' — bitte über „📧 senden" erneut versuchen.');
          }
        } else {
          alert('Vertrag ist vollständig unterschrieben und wurde heruntergeladen. Für den automatischen Versand fehlt eine gültige E-Mail-Adresse — bitte über „📧 senden" nachträglich verschicken.');
        }
      }
      await ladeVertragsdokumenteCache();
      renderPersonal();
    }catch(e){
      errEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
      btn.disabled = false;
    }
  });
}

