// ================================================================
// FORMALE ROLLE JE WOCHE (Personal-Tab, pro Aktion)
// Bewusst hier statt in der aktionsübergreifenden Nachweise-Verwaltung
// editierbar: die Wochen-Struktur (state.weeks) gehört zur jeweils
// gerade geöffneten Aktion. Schreibt seit dem Umbau mit dem Schlüssel-
// Format "<currentAktionId>::<wocheId>", damit die Rollenhistorie in der
// Nachweise-Verwaltung die Aktion zuverlässig auflösen kann.
// ================================================================
// renderFormaleRolle: formale Rolle (Leitung/Gruppen-Teamende/Teamende/
// Hilfsteamende) — Grundlage für die Nachweise-Pflicht. Bewusst PRO
// EINSATZTAG statt (wie ursprünglich) pro Woche editierbar: erstens
// funktioniert das auch bei tageweise arbeitenden Aktionen ohne
// Wochen-Struktur, zweitens kann sich die formale Rolle einer Person auch
// innerhalb einer Woche von Tag zu Tag ändern. Nutzt dieselbe Einsatztage-
// Liste (dayLookup/p.einsatzTage) wie der Tagessatz/Stundenlohn-Bereich.
// Schlüssel im JSON weiterhin "<aktionId>::<id>" — die zweite Hälfte ist
// jetzt eine Einsatztag-ID statt einer Wochen-ID; das Backend behandelt das
// Feld ohnehin nur als generisches JSON, keine Migration nötig. Ältere,
// noch wochenweise gespeicherte Einträge bleiben in der (rein lesenden)
// Rollenhistorie in der Nachweise-Verwaltung weiterhin sichtbar.
function renderFormaleRolle(){
  if(!isAdmin()) return;
  const wrap = document.getElementById('formaleRolleListe');
  if(!wrap) return;

  if(!nachweiseCacheLoaded && !nachweiseLoading){
    nachweiseLoading = true;
    ladeNachweiseCache().then(()=>{ nachweiseLoading = false; renderFormaleRolle(); });
  }
  if(!nachweiseCacheLoaded){
    wrap.innerHTML = '<div class="dp-hint">Lade…</div>';
    return;
  }

  const personen = state.personal || [];
  if(personen.length===0){
    wrap.innerHTML = '<div class="dp-hint" style="font-weight:normal;">Noch keine Teamenden angelegt.</div>';
    return;
  }

  const dayLookup = buildDayLookup();
  const rollenOptionen = ['', 'Leitung', 'Gruppen-Teamende', 'Teamende', 'Hilfsteamende'];
  wrap.innerHTML = '';
  personen.forEach(p=>{
    const nachweisIdWert = nachweisId(p);
    const n = nachweiseCache[nachweisIdWert] || {};
    const rollenProTag = n.formale_rolle_pro_woche || {};
    const einsatzTage = Array.isArray(p.einsatzTage) ? p.einsatzTage : [];
    const sortierteTage = [...einsatzTage].sort((a,b)=>{
      const da = (dayLookup[a]||{}).date || '9999-99-99';
      const db = (dayLookup[b]||{}).date || '9999-99-99';
      return da.localeCompare(db);
    });

    const card = document.createElement('div');
    card.style.cssText = 'padding:8px 4px; border-bottom:1px solid #eee;';
    const tageHtml = sortierteTage.length>0
      ? `<div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(160px,1fr)); gap:8px;">
          ${sortierteTage.map(tagId=>{
            const info = dayLookup[tagId];
            const label = info ? info.label : '(unbekannter Tag)';
            const schluessel = `${currentAktionId}::${tagId}`;
            const aktuellerWert = rollenProTag[schluessel] || '';
            return `
              <label style="font-size:0.82rem; color:var(--ink-soft); display:block;">${escapeHtml(label)}
                <select data-tag-rolle="${tagId}" style="display:block; width:100%; margin-top:2px;">
                  ${rollenOptionen.map(o=>`<option value="${o}" ${aktuellerWert===o?'selected':''}>${o||'—'}</option>`).join('')}
                </select>
              </label>
            `;
          }).join('')}
        </div>`
      : '<div class="dp-hint" style="margin-top:0; font-weight:normal;">Noch keine Einsatztage eingetragen — oben im Personal-Bereich zuerst Tage zuweisen.</div>';
    card.innerHTML = `
      <div style="font-weight:600; margin-bottom:6px;">${escapeHtml(p.name)}</div>
      ${tageHtml}
      <div class="dp-hint" id="fr_status_${p.id}" style="margin-top:4px;"></div>
    `;

    card.querySelectorAll('[data-tag-rolle]').forEach(sel=>{
      sel.addEventListener('change', async ()=>{
        const tagId = sel.dataset.tagRolle;
        const schluessel = `${currentAktionId}::${tagId}`;
        const statusEl = document.getElementById('fr_status_'+p.id);
        const neuesObjekt = {...((nachweiseCache[nachweisIdWert]||{}).formale_rolle_pro_woche || {})};
        if(sel.value) neuesObjekt[schluessel] = sel.value;
        else delete neuesObjekt[schluessel];
        try{
          await epCallWithRetry({action:'admin_nachweise_set', pass: currentAuthPass, id: nachweisIdWert, patch: {formale_rolle_pro_woche: neuesObjekt}});
          nachweiseCache[nachweisIdWert] = {...(nachweiseCache[nachweisIdWert]||{id:nachweisIdWert}), formale_rolle_pro_woche: neuesObjekt};
          if(statusEl) statusEl.textContent = '✓ Gespeichert.';
        }catch(e){
          if(statusEl) statusEl.textContent = '⚠️ Konnte nicht gespeichert werden: '+e.message;
        }
      });
    });

    wrap.appendChild(card);
  });
}

// renderRollenVerwaltung: kleine Verwaltung der Verantwortungs-Rollen mit
// eigenem Tagessatz (nur Admin). Diese Rollen lassen sich anschließend in
// der Personal-Tabelle pro Tag einer Person zuordnen.
function renderRollenVerwaltung(){
  const el = document.getElementById('rollenVerwaltung');
  if(!el) return;
  if(!isAdmin()){ el.innerHTML = ''; return; }

  if(!rollenCacheLoaded){
    el.innerHTML = '<div class="dp-hint" style="margin-top:0;">Lade Rollen…</div>';
    return;
  }

  const rollenZeilen = rollenCache.map(r=>`
    <div style="display:flex; align-items:center; gap:8px; margin-bottom:6px;">
      <span style="flex:1;">${escapeHtml(r.name)}</span>
      <span style="color:var(--ink-soft); font-size:0.85rem;">${Number(r.betrag).toFixed(2).replace('.',',')} EUR/Tag</span>
      <button class="del" data-id="${r.id}">✕</button>
    </div>
  `).join('');

  el.innerHTML = `
    <div class="card" style="border-style:dashed;">
      <div style="display:flex; justify-content:space-between; align-items:center; cursor:pointer;" id="rollenToggle">
        <strong>Verantwortungs-Rollen &amp; Tagessätze verwalten</strong>
        <span id="rollenToggleIcon">▸</span>
      </div>
      <div id="rollenBody" style="display:none; margin-top:12px;">
        <p class="sub" style="margin:0 0 10px 0;">Diese Rollen lassen sich anschließend in der Personal-Tabelle pro Tag zuordnen — wenn sich die Verantwortung (und damit der Satz) an einem Tag ändert.</p>
        ${rollenZeilen || '<div class="dp-hint" style="margin-top:0;">Noch keine Rollen angelegt.</div>'}
        <div class="add-row" style="grid-template-columns:1fr auto auto; margin-top:10px;">
          <input type="text" id="rolle_name" placeholder="Rollenname (z.B. Leitung)">
          <input type="number" id="rolle_betrag" placeholder="EUR/Tag" min="0" step="0.5" style="width:100px;">
          <button class="btn" id="rolle_add">+ Hinzufügen</button>
        </div>
      </div>
    </div>
  `;

  document.getElementById('rollenToggle').addEventListener('click', ()=>{
    const body = document.getElementById('rollenBody');
    const icon = document.getElementById('rollenToggleIcon');
    const offen = body.style.display !== 'none';
    body.style.display = offen ? 'none' : 'block';
    icon.textContent = offen ? '▸' : '▾';
  });

  el.querySelectorAll('.del').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      if(!(await bestaetigen('Diese Rolle wirklich löschen? Tage, die bisher dieser Rolle zugeordnet waren, fallen dann auf den normalen Tagessatz zurück.'))) return;
      try{
        await epCallWithRetry({action:'admin_rollen_delete', pass: currentAuthPass, id: btn.dataset.id});
        rollenCache = rollenCache.filter(r=>r.id!==btn.dataset.id);
        renderRollenVerwaltung();
        renderPersonal();
      }catch(e){
        alert('Rolle konnte nicht gelöscht werden: '+e.message);
      }
    });
  });

  document.getElementById('rolle_add').addEventListener('click', async ()=>{
    const name = document.getElementById('rolle_name').value.trim();
    const betrag = Number(document.getElementById('rolle_betrag').value);
    if(!name){ alert('Bitte einen Namen eingeben.'); return; }
    if(!isFinite(betrag) || betrag < 0){ alert('Bitte einen gültigen Betrag eingeben.'); return; }
    try{
      const data = await epCallWithRetry({action:'admin_rollen_set', pass: currentAuthPass, name, betrag, reihenfolge: rollenCache.length});
      rollenCache.push(data.rolle);
      renderRollenVerwaltung();
      renderPersonal();
    }catch(e){
      alert('Rolle konnte nicht gespeichert werden: '+e.message);
    }
  });
}

// baueAllDaysListe: alle Einsatztage-Spalten chronologisch aufbauen. Wird
// sowohl für die Personal-Tabelle als auch für den Einsatztage-Export
// verwendet. Zeigt seit der Umstellung auf freie Einsatztage NICHT MEHR
// alle 15 festen Ferienspiele-Wochentage, sondern nur:
//   a) Wochentage, die TATSÄCHLICH bei mindestens einer Person im
//      Personaleinsatz eingetragen sind (alte, bereits bestehende Daten —
//      bleiben mit ihrer ursprünglichen ID erhalten, damit die serverseitig
//      hinterlegten Rollen pro Tag, personal_gehalt.rollen_pro_tag, die
//      über genau diese ID verknüpft sind, nicht verwaisen)
//   b) alle frei angelegten Einsatztage (state.zusatzTage)
// WICHTIG: Es findet KEINE ID-Umschreibung/Migration mehr statt (frühere
// Version hat genau das versucht und dabei die Rollen-Verknüpfung
// zerstört, siehe Aktionsprotokoll) — bestehende Wochentag-IDs bleiben
// exakt so bestehen, wie sie sind.
function baueAllDaysListe(){
  const genutzeWeekDayIds = new Set();
  (state.personal||[]).forEach(p=>{
    (p.einsatzTage||[]).forEach(id=>genutzeWeekDayIds.add(id));
  });
  const allDays = [];
  (state.weeks||[]).forEach(week=>{
    (week.days||[]).forEach(d=>{
      if(!genutzeWeekDayIds.has(d.id)) return; // ungenutzter Wochentag -> nicht anzeigen
      allDays.push({
        id: d.id,
        date: d.date || null,
        group: week.label,
        head: `${escapeHtml(d.weekday)}${d.date?'<br>'+escapeHtml(fmtDate(d.date)):''}`,
        label: `${d.weekday}${d.date?' '+fmtDate(d.date):''}`,
        title: ''
      });
    });
  });
  zusatzSorted().forEach(z=>{
    allDays.push({
      id: z.id,
      date: z.date,
      group: 'Einsatztage',
      head: `${escapeHtml(isoWeekdayShort(z.date))}<br>${escapeHtml(fmtDate(z.date))}`,
      label: `${isoWeekdayShort(z.date)} ${fmtDate(z.date)}${z.label?' ('+z.label+')':''}`,
      title: z.label||''
    });
  });
  // Chronologisch sortieren (undatierte Einträge — sollte praktisch nicht
  // vorkommen — ans Ende).
  allDays.sort((a,b)=>(a.date||'9999-99-99').localeCompare(b.date||'9999-99-99'));
  return allDays;
}

// buildDayLookup: Nachschlagen von Datum/Label zu einer Einsatztag-ID —
// wiederverwendbar für Personal-Tabelle und die "gewählte Tage"-Chipliste
// beim Neuanlegen einer Person.
function buildDayLookup(){
  const lookup = {};
  baueAllDaysListe().forEach(d=>{ lookup[d.id] = d; });
  return lookup;
}

// findOrCreateTagIdForDate: liefert die ID eines bestehenden Einsatztages
// mit genau diesem Datum — legt bei Bedarf automatisch einen neuen an.
// Ermöglicht das freie, individuelle Eintragen von Einsatztagen im
// Personal-Tab, ohne doppelte Einträge für dasselbe Datum zu erzeugen.
// Prüft bewusst NICHT mehr gegen state.weeks (siehe baueAllDaysListe) —
// ein Datum, das zufällig mit einem Ferienspiele-Wochentag zusammenfällt,
// bekommt trotzdem einen eigenen, unabhängigen Einsatztag-Eintrag.
function findOrCreateTagIdForDate(s, dateIso){
  const bestehender = (s.zusatzTage||[]).find(z=>z.date === dateIso);
  if(bestehender) return bestehender.id;
  if(!Array.isArray(s.zusatzTage)) s.zusatzTage = [];
  const neu = {id: cid(), date: dateIso, label: ''};
  s.zusatzTage.push(neu);
  return neu.id;
}

