async function renderUmfragenAdmin(){
  const status = document.getElementById('ufStatus');
  const liste = document.getElementById('ufListe');
  status.textContent = 'Lädt…';
  document.getElementById('ufAuswertungWrap').style.display = 'none';
  let umfragen = [];
  try{
    const data = await epCallWithRetry({action:'admin_umfrage_list', pass: currentAuthPass});
    umfragen = data.umfragen || [];
    status.textContent = '';
  }catch(e){
    status.textContent = '⚠️ ' + e.message;
    liste.innerHTML = '';
    return;
  }
  if(umfragen.length === 0){
    liste.innerHTML = '<div class="empty">Noch keine Umfragen erstellt.</div>';
    return;
  }
  const wrap = document.createElement('div');
  wrap.className = 'pe-tablewrap';
  const table = document.createElement('table');
  table.className = 'pe-table';
  table.innerHTML = `<thead><tr><th>Frage</th><th>Typ</th><th>Status</th><th></th><th></th><th></th></tr></thead>`;
  const tbody = document.createElement('tbody');
  umfragen.forEach(u=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${escapeHtml(u.frage)}</td>
      <td>${u.typ==='auswahl' ? 'Auswahl ('+(u.optionen||[]).length+' Optionen)' : 'Freitext'}</td>
      <td>${u.aktiv ? '🟢 aktiv' : '⚪ geschlossen'}</td>
      <td><button class="btn ghost uf-toggle" data-id="${u.id}" data-aktiv="${u.aktiv}">${u.aktiv ? 'Schließen' : 'Wieder öffnen'}</button></td>
      <td><button class="btn ghost uf-auswertung" data-id="${u.id}">Auswertung</button></td>
      <td>${isAdmin() ? `<button class="del uf-delete" data-id="${u.id}">Löschen</button>` : ''}</td>
    `;
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  wrap.innerHTML = '';
  wrap.appendChild(table);
  liste.innerHTML = '';
  liste.appendChild(wrap);

  liste.querySelectorAll('.uf-toggle').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const neuerStatus = btn.dataset.aktiv !== 'true';
      try{
        await epCallWithRetry({action:'admin_umfrage_status', pass: currentAuthPass, id: btn.dataset.id, aktiv: neuerStatus});
        renderUmfragenAdmin();
      }catch(e){ status.textContent = '⚠️ ' + e.message; }
    });
  });
  liste.querySelectorAll('.uf-delete').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      if(!(await bestaetigen('Diese Umfrage inkl. aller Antworten wirklich löschen?'))) return;
      try{
        await epCallWithRetry({action:'admin_umfrage_loeschen', pass: currentAuthPass, id: btn.dataset.id});
        renderUmfragenAdmin();
      }catch(e){ status.textContent = '⚠️ ' + e.message; }
    });
  });
  liste.querySelectorAll('.uf-auswertung').forEach(btn=>{
    btn.addEventListener('click', ()=> zeigeUmfrageAuswertung(btn.dataset.id));
  });
}

let aktuelleAuswertung = null;

async function zeigeUmfrageAuswertung(id){
  const wrap = document.getElementById('ufAuswertungWrap');
  const titel = document.getElementById('ufAuswertungTitel');
  const inhalt = document.getElementById('ufAuswertungInhalt');
  wrap.style.display = 'block';
  titel.textContent = 'Lädt…';
  inhalt.innerHTML = '';
  try{
    const data = await epCallWithRetry({action:'admin_umfrage_auswertung', pass: currentAuthPass, id});
    aktuelleAuswertung = data;
    titel.textContent = '📋 ' + data.umfrage.frage;
    renderUmfrageAuswertungInhalt();
  }catch(e){
    titel.textContent = 'Fehler';
    inhalt.innerHTML = '⚠️ ' + e.message;
  }
}

function renderUmfrageAuswertungInhalt(){
  const inhalt = document.getElementById('ufAuswertungInhalt');
  const data = aktuelleAuswertung;
  const beantwortet = data.antworten.filter(a=>a.antwort);
  const unbeantwortet = data.antworten.length - beantwortet.length;
  const query = normName(document.getElementById('uf_auswertung_search') ? document.getElementById('uf_auswertung_search').value : '');
  const gefiltert = query
    ? data.antworten.filter(a => normName(a.vorname+' '+a.nachname).includes(query))
    : data.antworten;

  let html = `<div class="dp-hint" style="margin-top:0;">${beantwortet.length} von ${data.antworten.length} Kindern beantwortet (${unbeantwortet} offen)</div>`;

  if(data.umfrage.typ === 'auswahl'){
    const zaehler = {};
    (data.umfrage.optionen||[]).forEach(opt=>zaehler[opt]=0);
    beantwortet.forEach(a=>{ zaehler[a.antwort] = (zaehler[a.antwort]||0)+1; });
    html += '<div style="margin:12px 0;">' + Object.entries(zaehler).map(([opt,n])=>
      `<div style="margin-bottom:6px;"><strong>${escapeHtml(opt)}:</strong> ${n}</div>`
    ).join('') + '</div>';
  }

  html += `<div class="databar" style="margin:12px 0;"><input type="text" id="uf_auswertung_search" placeholder="🔍 Teilnehmende suchen…" style="flex:1;" value="${escapeHtml(document.getElementById('uf_auswertung_search') ? document.getElementById('uf_auswertung_search').value : '')}"></div>`;

  html += '<div class="pe-tablewrap"><table class="pe-table"><thead><tr><th>Name</th><th>Gruppe</th><th>Antwort</th><th>Weitere Informationen</th></tr></thead><tbody>' +
    (gefiltert.length === 0
      ? '<tr><td colspan="4"><div class="empty">Keine Teilnehmenden gefunden.</div></td></tr>'
      : gefiltert
          .slice()
          .sort((a,b)=> a.nachname.localeCompare(b.nachname))
          .map(a=>`<tr><td class="pe-name">${escapeHtml(a.vorname)} ${escapeHtml(a.nachname)}</td><td>${a.gruppe?escapeHtml(a.gruppe):'–'}</td><td>${a.antwort?escapeHtml(a.antwort):'<em>keine Antwort</em>'}</td><td>${a.notiz?escapeHtml(a.notiz):''}</td></tr>`)
          .join('')) +
    '</tbody></table></div>';

  inhalt.innerHTML = html;
  const searchInput = document.getElementById('uf_auswertung_search');
  searchInput.addEventListener('input', renderUmfrageAuswertungInhalt);
  searchInput.focus();
  searchInput.setSelectionRange(searchInput.value.length, searchInput.value.length);
}

