document.getElementById('kinderBulkAssign').addEventListener('click', async ()=>{
  const status = document.getElementById('kinderStatus');
  if(!kWocheFilterAktiv){
    status.textContent = '⚠️ Bitte zuerst oben eine konkrete Woche auswählen (nicht "Alle Wochen") — Gruppen werden pro Woche zugewiesen.';
    return;
  }
  const gruppe = document.getElementById('kinderBulkGruppe').value;
  const ids = Array.from(kinderSelected);
  if(ids.length === 0) return;
  const btn = document.getElementById('kinderBulkAssign');
  btn.disabled = true;
  let ok = 0, fehler = 0;
  for(const id of ids){
    try{
      const kind = kinderCache.kinder.find(x=>x.id===id);
      const neueZuordnung = {...(kind.gruppen_zuordnung||{})};
      if(gruppe) neueZuordnung[kWocheFilterAktiv] = gruppe; else delete neueZuordnung[kWocheFilterAktiv];
      await epCallWithRetry({action:'admin_patch', pass: currentAuthPass, id, patch:{gruppen_zuordnung: neueZuordnung}});
      if(kind) kind.gruppen_zuordnung = neueZuordnung;
      ok++;
    }catch(e){
      fehler++;
    }
  }
  btn.disabled = false;
  const wocheLabel = (wochenListe().find(w=>w.id===kWocheFilterAktiv)||{}).label || kWocheFilterAktiv;
  status.textContent = `✓ ${ok} Kind(ern) für ${wocheLabel} die Gruppe "${gruppe||'— ohne Gruppe —'}" zugewiesen.` + (fehler>0 ? ` ${fehler} Fehler.` : '');
  kinderSelected.clear();
  renderKinderList();
});

document.getElementById('kinderBulkWochenAssign').addEventListener('click', async ()=>{
  const wochen = Array.from(document.querySelectorAll('.kinder_bulk_woche:checked')).map(cb=>cb.value);
  const ids = Array.from(kinderSelected);
  if(ids.length === 0) return;
  const btn = document.getElementById('kinderBulkWochenAssign');
  btn.disabled = true;
  const status = document.getElementById('kinderStatus');
  let ok = 0, fehler = 0;
  for(const id of ids){
    try{
      await epCallWithRetry({action:'admin_patch', pass: currentAuthPass, id, patch:{wochen}});
      const kind = kinderCache.kinder.find(x=>x.id===id);
      if(kind) kind.wochen = wochen;
      ok++;
    }catch(e){
      fehler++;
    }
  }
  btn.disabled = false;
  const wochenLabels = wochenListe().filter(w=>wochen.includes(w.id)).map(w=>w.label).join(', ') || '— keine —';
  status.textContent = `✓ Bei ${ok} Kind(ern) Wochen gesetzt auf: ${wochenLabels}.` + (fehler>0 ? ` ${fehler} Fehler.` : '');
  kinderSelected.clear();
  renderKinderList();
});

// ---------------- TAGESÜBERSICHT ----------------
let kTagSelectedId = null;

function populateTagSelect(){
  const sel = document.getElementById('k_tag_select');
  const prevValue = kTagSelectedId || sel.value;
  sel.innerHTML = '';
  kinderCache.days.forEach(week=>{
    const optgroup = document.createElement('optgroup');
    optgroup.label = week.weekLabel;
    (week.days||[]).forEach(d=>{
      const opt = document.createElement('option');
      opt.value = d.id;
      opt.dataset.woche = week.weekId;
      opt.textContent = `${d.weekday} ${d.date ? fmtDateDe(d.date) : ''}`;
      optgroup.appendChild(opt);
    });
    sel.appendChild(optgroup);
  });
  // Vorauswahl: heutigen Tag suchen, sonst vorherige Auswahl, sonst ersten Tag
  const todayIsoStr = todayIso();
  let target = prevValue;
  if(!target){
    kinderCache.days.forEach(week => (week.days||[]).forEach(d=>{ if(d.date === todayIsoStr) target = d.id; }));
  }
  if(target) sel.value = target;
  kTagSelectedId = sel.value;
  renderTagesuebersicht();
}

// renderBetreuungsschluesselWarnung: prüft für den gewählten Tag, ob je Gruppe
// genug Personal tatsächlich im Dienst ist — nutzt bewusst dieselbe Kennzahl
// wie die bestehende Personalbedarf-Berechnung im Gruppen-Tab
// (state.kinderProTeamende), damit es nur EINE Stellschraube für das
// Verhältnis gibt.
//
// Die wöchentliche Gruppen-Zuordnung des Personals (state.gruppen[]) wird
// seit 30.08.2026 verpflichtend mit einer stabilen Kartei-personId angelegt
// (analog state.personal[].personId) — der Abgleich läuft daher primär über
// diese ID, nicht mehr über den Namen. Ältere, vor diesem Stichtag angelegte
// Gruppen-Einträge besitzen ggf. noch keine personId; für diese greift als
// Fallback weiterhin der (normalisierte) Namensabgleich, und sie werden in der
// "nicht zuordenbar"-Zeile als Alt-Eintrag markiert, damit klar ist, dass eine
// erneute Zuordnung über die Kartei die Zuverlässigkeit verbessert. Springer/
// Flex-Personal wird bewusst ausgeklammert (weder als vorhanden noch als
// fehlend gezählt), analog zur bestehenden Konfliktprüfung an anderer Stelle
// in der App.
function renderBetreuungsschluesselWarnung(dayId, tagWoche){
  const el = document.getElementById('k_tag_bedarf_warnung');
  if(!el) return;
  if(!isAdmin() || !tagWoche){ el.innerHTML = ''; return; }
  const gnList = state.gruppenNamen || [];
  if(gnList.length === 0){ el.innerHTML = ''; return; }
  const verhaeltnis = state.kinderProTeamende || 8;
  const gnById = {};
  gnList.forEach(gn=>{ gnById[gn.id] = gn.name; });

  // Erwartete Kinder heute pro Gruppe: alle Kinder dieser Woche, die nicht
  // abgemeldet sind (unabhängig vom aktuell gewählten Anzeige-Filter, damit
  // die Warnung immer den vollen Stand zeigt).
  const kinderProGruppe = {};
  kinderCache.kinder.forEach(k=>{
    const wochenDesKindes = k.wochen || [];
    if(wochenDesKindes.length > 0 && !wochenDesKindes.includes(tagWoche)) return;
    const istAb = ((k.anmeldungen||{})[dayId]||{}).status === 'ab';
    if(istAb) return;
    const gruppe = (k.gruppen_zuordnung||{})[tagWoche] || '';
    if(!gruppe) return;
    kinderProGruppe[gruppe] = (kinderProGruppe[gruppe]||0) + 1;
  });

  // Personal heute pro Gruppe: Namensabgleich zwischen state.gruppen
  // (Wochen-Zuordnung) und state.personal (Einsatztage je Tag).
  const personalListe = state.personal || [];
  const nichtZuordenbar = [];
  const personalProGruppe = {};
  (state.gruppen||[]).forEach(g=>{
    if(g.istPlatzhalter) return; // Springer/Flex bewusst ausgeklammert
    const gnId = (g.zuordnung||{})[tagWoche];
    if(!gnId) return;
    const gruppenName = gnById[gnId];
    if(!gruppenName) return;
    const passendesPersonal = g.personId
      ? personalListe.find(p => p.personId === g.personId)
      : personalListe.find(p => normName(p.name) === normName(g.name));
    if(!passendesPersonal){
      nichtZuordenbar.push(g.personId ? g.name : `${g.name} (Alt-Eintrag ohne Kartei-Zuordnung — bitte in „Gruppen" neu über Kartei zuordnen)`);
      return;
    }
    const heuteImDienst = (passendesPersonal.einsatzTage||[]).includes(dayId);
    if(!heuteImDienst) return;
    personalProGruppe[gruppenName] = (personalProGruppe[gruppenName]||0) + 1;
  });

  const gruppenMitKindern = Object.keys(kinderProGruppe).sort((a,b)=>a.localeCompare(b,'de'));
  if(gruppenMitKindern.length === 0){ el.innerHTML = ''; return; }

  const zeilen = gruppenMitKindern.map(gruppe=>{
    const anzahlKinder = kinderProGruppe[gruppe];
    const benoetigt = Math.ceil(anzahlKinder / verhaeltnis);
    const vorhanden = personalProGruppe[gruppe] || 0;
    const fehlt = benoetigt - vorhanden;
    if(fehlt > 0){
      return `<div style="color:var(--awo-red,#E2001A); font-weight:600;">⚠️ ${escapeHtml(gruppe)}: ${anzahlKinder} Kind(er) heute, aber nur ${vorhanden} Teamende im Dienst (Soll: mind. ${benoetigt} bei 1:${verhaeltnis}) — ${fehlt} fehlen.</div>`;
    }
    return `<div>✓ ${escapeHtml(gruppe)}: ${vorhanden} Teamende für ${anzahlKinder} Kind(er) (Soll 1:${verhaeltnis}).</div>`;
  });
  if(nichtZuordenbar.length > 0){
    zeilen.push(`<div class="dp-hint">ℹ️ Namentlich nicht zuordenbar zu den Einsatztagen (Schreibweise in „Gruppen" vs. „Personal" prüfen): ${nichtZuordenbar.map(escapeHtml).join(', ')}</div>`);
  }
  el.innerHTML = zeilen.join('');
}

function renderTagesuebersicht(){
  const dayId = document.getElementById('k_tag_select').value;
  kTagSelectedId = dayId;
  const selectedOption = document.getElementById('k_tag_select').selectedOptions[0];
  const tagWoche = selectedOption ? selectedOption.dataset.woche : '';
  const gruppeFilter = document.getElementById('k_tag_gruppe_filter').value;
  const summaryEl = document.getElementById('k_tag_summary');
  const listEl = document.getElementById('k_tag_list');
  if(!dayId || kinderCache.kinder.length === 0){
    summaryEl.innerHTML = '';
    listEl.innerHTML = '<div class="empty">Keine Kinder angelegt.</div>';
    return;
  }
  const gruppeDesTages = (k) => (k.gruppen_zuordnung||{})[tagWoche] || '';
  const passtZurGruppe = (k) => {
    if(!gruppeFilter) return true;
    if(gruppeFilter === '__ohne__') return !gruppeDesTages(k);
    return gruppeDesTages(k) === gruppeFilter;
  };
  // Nur Kinder zeigen, die entweder noch KEINER Woche zugeordnet sind (z.B. frisch angelegt,
  // noch nicht importiert), oder explizit der Woche des gerade gewählten Tages zugeordnet sind.
  // Kinder, die einer ANDEREN Woche zugeordnet sind, werden ausgeblendet, bis sie per Import
  // auch der aktuellen Woche zugeordnet werden.
  const gehoertZurAktuellenWoche = (k) => {
    const wochenDesKindes = k.wochen || [];
    return wochenDesKindes.length === 0 || wochenDesKindes.includes(tagWoche);
  };
  const query = normName(document.getElementById('k_tag_search').value);
  const passtZurSuche = (k) => {
    if(!query) return true;
    const notizDesTages = ((k.anmeldungen||{})[dayId]||{}).notiz || '';
    return normName(k.vorname+' '+k.nachname).includes(query) || normName(notizDesTages).includes(query);
  };
  const abmeldungFilter = document.getElementById('k_tag_abmeldung_filter').value;
  const passtZurAbmeldung = (k) => {
    if(!abmeldungFilter) return true;
    const istAb = ((k.anmeldungen||{})[dayId]||{}).status === 'ab';
    return abmeldungFilter === 'ab' ? istAb : !istAb;
  };
  const notizFilter = document.getElementById('k_tag_notiz_filter').value;
  const passtZurNotiz = (k) => {
    if(!notizFilter) return true;
    const hatNotiz = !!((k.anmeldungen||{})[dayId]||{}).notiz;
    return notizFilter === 'mit' ? hatNotiz : !hatNotiz;
  };
  const bestaetigtFilter = document.getElementById('k_tag_bestaetigt_filter').value;
  const passtZurBestaetigung = (k) => {
    if(!bestaetigtFilter) return true;
    const istBestaetigt = !!((k.anmeldungen||{})[dayId]||{}).bestaetigt;
    return bestaetigtFilter === 'bestaetigt' ? istBestaetigt : !istBestaetigt;
  };
  const sortFeld = document.getElementById('k_tag_sort').value;
  const sortiert = kinderCache.kinder.filter(k => passtZurGruppe(k) && passtZurSuche(k) && gehoertZurAktuellenWoche(k) && passtZurAbmeldung(k) && passtZurNotiz(k) && passtZurBestaetigung(k)).slice().sort((a,b)=> (a[sortFeld]||'').localeCompare(b[sortFeld]||'', 'de'));
  const abgemeldetCount = sortiert.filter(k => ((k.anmeldungen||{})[dayId]||{}).status === 'ab').length;
  const bestaetigtCount = sortiert.filter(k => ((k.anmeldungen||{})[dayId]||{}).bestaetigt).length;
  // "Noch offen" = weder abgemeldet noch bestätigt anwesend — genau die Kinder,
  // bei denen am Tag selbst noch ein Blick/Haken fehlt (Ankunfts-Check).
  const offenCount = sortiert.filter(k => {
    const e = (k.anmeldungen||{})[dayId] || {};
    return e.status !== 'ab' && !e.bestaetigt;
  }).length;
  summaryEl.innerHTML = `<strong>${bestaetigtCount}</strong> vom Team bestätigt · <strong>${abgemeldetCount}</strong> von Eltern abgemeldet · <strong style="${offenCount>0?'color:var(--awo-red,#E2001A);':''}">${offenCount}</strong> noch offen · von insgesamt ${sortiert.length} Kindern${gruppeFilter?' in dieser Gruppe':''}${abmeldungFilter?(abmeldungFilter==='ab'?' (nur abgemeldete)':' (nur anwesende)'):''}${notizFilter?(notizFilter==='mit'?' (nur mit Notiz)':' (nur ohne Notiz)'):''}${bestaetigtFilter?(bestaetigtFilter==='bestaetigt'?' (nur bestätigt)':' (nur noch offen)'):''}${query?' (gefiltert)':''}`;

  renderBetreuungsschluesselWarnung(dayId, tagWoche);

  if(sortiert.length === 0){
    listEl.innerHTML = '<div class="empty">Keine Kinder gefunden.</div>';
    return;
  }
  const wrap = document.createElement('div');
  wrap.className = 'pe-tablewrap';
  const table = document.createElement('table');
  table.className = 'pe-table';
  table.innerHTML = `<thead><tr><th>Name</th><th>Gruppe</th><th>Abgemeldet</th><th>Abholzeit</th><th>Notiz</th><th>Team bestätigt anwesend</th></tr></thead>`;
  const tbody = document.createElement('tbody');
  sortiert.forEach(k=>{
    const entry = (k.anmeldungen||{})[dayId] || {};
    const istAb = entry.status === 'ab';
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td class="pe-name">${escapeHtml(k.vorname)} ${escapeHtml(k.nachname)}</td>
      <td>${gruppeDesTages(k) ? escapeHtml(gruppeDesTages(k)) : '–'}</td>
      <td><input type="checkbox" class="k-team-abmeldung" data-id="${k.id}" data-day="${dayId}" ${istAb?'checked':''} ${isAdmin()?'':'disabled'}></td>
      <td><input type="time" class="k-team-abholzeit" data-id="${k.id}" data-day="${dayId}" value="${escapeHtml(entry.abholzeit||'')}" ${isAdmin()?'':'disabled'}></td>
      <td><input type="text" class="k-team-notiz" data-id="${k.id}" data-day="${dayId}" value="${escapeHtml(entry.notiz||'')}" placeholder="z.B. per Anruf abgemeldet" style="width:100%;" ${isAdmin()?'':'disabled'}></td>
      <td>
        <label style="display:flex; align-items:center; gap:6px;"><input type="checkbox" class="k-bestaetigt" data-id="${k.id}" data-day="${dayId}" ${entry.bestaetigt?'checked':''}> bestätigt</label>
        ${entry.bestaetigt && (entry.bestaetigtVon || entry.bestaetigtAm) ? `<div class="dp-hint" style="margin:2px 0 0 0; font-size:0.85em;">von ${escapeHtml(entry.bestaetigtVon || '–')}${entry.bestaetigtAm ? ' um '+new Date(entry.bestaetigtAm).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}) : ''}</div>` : ''}
      </td>
    `;
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  wrap.appendChild(table);
  listEl.innerHTML = '';
  listEl.appendChild(wrap);

  async function patchAnmeldungFeld(kindId, dId, felder, revertFn){
    const kind = kinderCache.kinder.find(x=>x.id===kindId);
    if(!kind) return;
    const bisherige = (kind.anmeldungen||{})[dId] || {};
    const neueAnmeldungen = {...(kind.anmeldungen||{}), [dId]: {...bisherige, ...felder}};
    try{
      await epCallWithRetry({action:'admin_patch', pass: currentAuthPass, id: kindId, patch:{anmeldungen: neueAnmeldungen}});
      kind.anmeldungen = neueAnmeldungen;
      renderTagesuebersicht();
    }catch(e){
      if(revertFn) revertFn();
      alert('Konnte nicht gespeichert werden: ' + e.message);
    }
  }

  listEl.querySelectorAll('.k-team-abmeldung').forEach(cb=>{
    cb.addEventListener('change', async ()=>{
      const checked = cb.checked;
      cb.disabled = true;
      await patchAnmeldungFeld(cb.dataset.id, cb.dataset.day, {status: checked?'ab':'', abgemeldetVomTeamAm: new Date().toISOString()}, ()=>{cb.checked = !checked;});
      cb.disabled = false;
    });
  });

  listEl.querySelectorAll('.k-team-notiz').forEach(inp=>{
    inp.addEventListener('change', async ()=>{
      const alterWert = inp.defaultValue;
      inp.disabled = true;
      await patchAnmeldungFeld(inp.dataset.id, inp.dataset.day, {notiz: inp.value.trim()}, ()=>{inp.value = alterWert;});
      inp.disabled = false;
    });
  });

  listEl.querySelectorAll('.k-team-abholzeit').forEach(inp=>{
    inp.addEventListener('change', async ()=>{
      const alterWert = inp.defaultValue;
      inp.disabled = true;
      await patchAnmeldungFeld(inp.dataset.id, inp.dataset.day, {abholzeit: inp.value}, ()=>{inp.value = alterWert;});
      inp.disabled = false;
    });
  });

  listEl.querySelectorAll('.k-bestaetigt').forEach(cb=>{
    cb.addEventListener('change', async ()=>{
      const checked = cb.checked;
      cb.disabled = true;
      // Beim Setzen: wer (myName, "Ich bin"-Identität) und Uhrzeit mitspeichern.
      // Beim Entfernen: beides wieder leeren, damit bei erneutem Bestätigen
      // (ggf. durch eine andere Person) keine veralteten Angaben stehen bleiben.
      await patchAnmeldungFeld(cb.dataset.id, cb.dataset.day, {
        bestaetigt: checked,
        bestaetigtAm: checked ? new Date().toISOString() : null,
        bestaetigtVon: checked ? (myName || '') : null,
      }, ()=>{cb.checked = !checked;});
      cb.disabled = false;
    });
  });
}

