document.getElementById('k_tag_export').addEventListener('click', async ()=>{
  const dayId = document.getElementById('k_tag_select').value;
  if(!dayId){ return; }
  const selectedOption = document.getElementById('k_tag_select').selectedOptions[0];
  const tagWoche = selectedOption ? selectedOption.dataset.woche : '';
  const gruppeDesTages = (k) => (k.gruppen_zuordnung||{})[tagWoche] || '';
  const gruppeFilter = document.getElementById('k_tag_gruppe_filter').value;
  const passtZurGruppe = (k) => {
    if(!gruppeFilter) return true;
    if(gruppeFilter === '__ohne__') return !gruppeDesTages(k);
    return gruppeDesTages(k) === gruppeFilter;
  };
  const gehoertZurAktuellenWoche = (k) => {
    const wochenDesKindes = k.wochen || [];
    return wochenDesKindes.length === 0 || wochenDesKindes.includes(tagWoche);
  };
  const query = normName(document.getElementById('k_tag_search').value);
  const passtZurSuche = (k) => {
    if(!query) return true;
    const notizDesTages = ((k.anmeldungen||{})[dayId]||{}).notiz || '';
    return normName(k.vorname+' '+k.nachname).includes(query) || normName(notizDesTages).includes(query);
  };
  const abmeldungFilter = document.getElementById('k_tag_abmeldung_filter').value;
  const passtZurAbmeldung = (k) => {
    if(!abmeldungFilter) return true;
    const istAb = ((k.anmeldungen||{})[dayId]||{}).status === 'ab';
    return abmeldungFilter === 'ab' ? istAb : !istAb;
  };
  const notizFilter = document.getElementById('k_tag_notiz_filter').value;
  const passtZurNotiz = (k) => {
    if(!notizFilter) return true;
    const hatNotiz = !!((k.anmeldungen||{})[dayId]||{}).notiz;
    return notizFilter === 'mit' ? hatNotiz : !hatNotiz;
  };
  const bestaetigtFilter = document.getElementById('k_tag_bestaetigt_filter').value;
  const passtZurBestaetigung = (k) => {
    if(!bestaetigtFilter) return true;
    const istBestaetigt = !!((k.anmeldungen||{})[dayId]||{}).bestaetigt;
    return bestaetigtFilter === 'bestaetigt' ? istBestaetigt : !istBestaetigt;
  };
  const sortFeld = document.getElementById('k_tag_sort').value;
  let dayLabel = '';
  kinderCache.days.forEach(week => (week.days||[]).forEach(d=>{ if(d.id===dayId) dayLabel = `${week.weekLabel} ${d.weekday} ${d.date?fmtDateDe(d.date):''}`; }));

  const rows = [['Vorname','Nachname','Gruppe','Eltern-Angabe','Abholzeit','Notiz','Team bestätigt','Bestätigt von','Bestätigt um']];
  kinderCache.kinder
    .filter(k => passtZurGruppe(k) && passtZurSuche(k) && gehoertZurAktuellenWoche(k) && passtZurAbmeldung(k) && passtZurNotiz(k) && passtZurBestaetigung(k))
    .slice()
    .sort((a,b)=> (a[sortFeld]||'').localeCompare(b[sortFeld]||'', 'de'))
    .forEach(k=>{
      const entry = (k.anmeldungen||{})[dayId];
      const istAb = entry && entry.status === 'ab';
      rows.push([k.vorname, k.nachname, gruppeDesTages(k), istAb ? 'Abgemeldet' : 'Anwesend', (entry && entry.abholzeit) || '', (entry && entry.notiz) || '', (entry && entry.bestaetigt) ? 'Ja' : 'Nein', (entry && entry.bestaetigtVon) || '', (entry && entry.bestaetigtAm) ? new Date(entry.bestaetigtAm).toLocaleString('de-DE') : '']);
    });

  await ladeBibliothek('xlsx');
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet(rows);
  ws['!cols'] = [{wch:16},{wch:16},{wch:14},{wch:12},{wch:10},{wch:30},{wch:14},{wch:16},{wch:16}];
  XLSX.utils.book_append_sheet(wb, ws, 'Tagesübersicht');
  XLSX.writeFile(wb, `kinder-tagesuebersicht_${dayLabel.replace(/\s+/g,'-')}_${stamp()}.xlsx`);
});

