// ---------------- KONTAKTZETTEL ALS PDF ----------------
// Druckfertige Liste für den Ausflugsrucksack, ohne Internet/Handy nutzbar.
// Enthält bewusst NUR bereits vorhandene Daten (Abholberechtigte, Gruppe,
// Foto-/Video-Erlaubnis, heutiger Anmeldestatus) — KEINE Notfallkontakte,
// Allergien oder Medikamente, da diese Daten in dieser App nicht erfasst
// werden (siehe Entscheidung vom 22.08.2026).
// Übernimmt exakt die gerade aktiven Filter der Tagesübersicht (Gruppe,
// Abmeldung, Notiz, Team-bestätigt, Suche), damit PDF und Bildschirmansicht
// übereinstimmen.
function zeichneKontaktzettelSeite(doc, spalten, kopfY, marginL){
  let y = kopfY;
  doc.setFont('helvetica','bold');
  doc.setFontSize(9);
  let x = marginL;
  spalten.forEach(s=>{ doc.text(s.label, x, y); x += s.width; });
  y += 2;
  doc.setDrawColor(120);
  doc.line(marginL, y, marginL + spalten.reduce((a,s)=>a+s.width,0), y);
  return y + 4.5;
}

// zeichneTabellenZeilen: generische Zeilen-/Seitenumbruch-Logik für einfache
// PDF-Tabellen (genutzt von Kontaktzettel UND Abschluss-Archiv), damit die
// Umbruchlogik nicht doppelt gepflegt werden muss.
function zeichneTabellenZeilen(doc, spalten, zeilen, startY, marginL, marginR, seitenUnten){
  let y = startY;
  doc.setFont('helvetica','normal');
  doc.setFontSize(8.5);
  zeilen.forEach(zeile=>{
    const wrapped = zeile.map((text,i)=>doc.splitTextToSize(String(text||''), spalten[i].width - 2));
    const lineCount = Math.max(...wrapped.map(w=>w.length), 1);
    const hoehe = lineCount * 3.8 + 2.5;
    if(y + hoehe > seitenUnten){
      doc.addPage();
      y = zeichneKontaktzettelSeite(doc, spalten, 18, marginL);
      doc.setFont('helvetica','normal');
      doc.setFontSize(8.5);
    }
    let x = marginL;
    spalten.forEach((s,i)=>{
      doc.text(wrapped[i], x, y);
      x += s.width;
    });
    y += hoehe;
    doc.setDrawColor(230);
    doc.line(marginL, y-1.3, marginR, y-1.3);
  });
  return y;
}

// erstelleUndLadeAbschlussArchiv: lädt Kinder-/Personal-Daten der Aktion
// explizit über die aktionId (unabhängig davon, welche Aktion gerade
// "betreten" ist — epCallOhneAktion + expliziter aktionId-Parameter, siehe
// admin_list/state_get im Backend) und baut daraus ein mehrseitiges PDF:
// Deckblatt, Teilnehmerliste, Gruppenzuordnung pro Woche, Personal-Übersicht.
// Bewusst NUR bereits vorhandene Daten (siehe Kontaktzettel) — keine
// Notfallkontakte/Gesundheitsdaten, da diese nicht erfasst werden.
async function erstelleUndLadeAbschlussArchiv(aktion){
  const [listData, stateData, gehaltData, rollenData] = await Promise.all([
    epCallOhneAktion({action:'admin_list', pass: currentAuthPass, aktionId: aktion.id}),
    epCallOhneAktion({action:'state_get', pass: currentAuthPass, aktionId: aktion.id}),
    epCallOhneAktion({action:'admin_gehalt_list', pass: currentAuthPass, aktionId: aktion.id}),
    epCallOhneAktion({action:'admin_rollen_list', pass: currentAuthPass}),
  ]);
  const kinder = (listData.kinder || []).slice().sort((a,b)=>(a.nachname||'').localeCompare(b.nachname||'', 'de'));
  const days = listData.days || [];
  const state = stateData.data || {};
  const personal = state.personal || [];
  const krankmeldungen = state.krankmeldungen || [];
  const rollenListe = rollenData.rollen || [];
  // Gehalt-Zeilen sind über personId indiziert (personal_gehalt.id === personen.id,
  // siehe Kartei-Umstellung) — NICHT über den globalen gehaltCache, damit diese
  // Funktion unabhängig davon ist, welche Aktion gerade im UI "betreten" ist.
  const gehaltMap = {};
  (gehaltData.gehaelter || []).forEach(g => { gehaltMap[g.id] = g; });
  const dateById = {};
  days.forEach(week => (week.days||[]).forEach(d=>{ if(d.date) dateById[d.id] = d.date; }));

  function tagessatzFuerTagLokal(personId, tagId){
    const gehalt = gehaltMap[personId] || {};
    const rollenProTag = gehalt.rollen_pro_tag || {};
    const rollenId = rollenProTag[tagId];
    if(rollenId){
      const rolle = rollenListe.find(r=>r.id===rollenId);
      if(rolle) return rolle.betrag;
    }
    return gehalt.tagessatz;
  }
  // verdienstUndTageFuerPerson: berücksichtigt sowohl Tagessatz- als auch
  // Stundenlohn-Modell (siehe 47_gehalt_lohnart_stundenlohn.sql), analog zur
  // gleichnamigen Logik im Personal-Tab (gesamtbetragFuerPerson).
  function verdienstUndTageFuerPerson(p){
    const tage = Array.isArray(p.einsatzTage) ? p.einsatzTage : [];
    const gehalt = gehaltMap[p.id] || {};
    const istStundenlohn = (gehalt.lohnart || 'tagessatz') === 'stundenlohn';
    let summe = 0, unvollstaendig = false, gesamtStunden = 0;
    if(istStundenlohn){
      const stundenProTag = gehalt.stunden_pro_tag || {};
      const stundensatz = (gehalt.stundensatz===null || gehalt.stundensatz===undefined) ? null : Number(gehalt.stundensatz);
      tage.forEach(tagId=>{
        const stunden = stundenProTag[tagId];
        if(stunden==null || stundensatz==null){ unvollstaendig = true; return; }
        summe += Number(stunden) * stundensatz;
        gesamtStunden += Number(stunden);
      });
    } else {
      tage.forEach(tagId=>{
        const satz = tagessatzFuerTagLokal(p.id, tagId);
        if(satz==null){ unvollstaendig = true; return; }
        summe += satz;
      });
    }
    const daten = tage.map(id=>dateById[id]).filter(Boolean).sort().map(d=>fmtDateDe(d));
    return { anzahlTage: tage.length, daten, summe, unvollstaendig, istStundenlohn, gesamtStunden };
  }

  await ladeBibliothek('jspdf');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  const marginL = 14, marginR = 196, seitenUnten = 280;
  const zeitraum = aktion.start_datum ? (aktion.end_datum && aktion.end_datum!==aktion.start_datum ? `${fmtDateDe(aktion.start_datum)} – ${fmtDateDe(aktion.end_datum)}` : fmtDateDe(aktion.start_datum)) : 'kein Zeitraum hinterlegt';

  // --- Deckblatt ---
  let y = 40;
  doc.setFont('helvetica','bold');
  doc.setFontSize(20);
  doc.text('Abschluss-Archiv', 105, y, {align:'center'});
  y += 12;
  doc.setFontSize(14);
  doc.text(aktion.name, 105, y, {align:'center'});
  y += 10;
  doc.setFont('helvetica','normal');
  doc.setFontSize(11);
  doc.text(`Zeitraum: ${zeitraum}`, 105, y, {align:'center'});
  y += 7;
  doc.text(`Typ: ${aktion.typ || '–'}`, 105, y, {align:'center'});
  y += 7;
  doc.text(`Kinder: ${kinder.length}  ·  Ehrenamtliche: ${personal.length}`, 105, y, {align:'center'});
  y += 14;
  doc.setFontSize(9);
  doc.setTextColor(120);
  const hinweisZeilen = doc.splitTextToSize('Dieses Archiv enthält Teilnehmerliste, Gruppenzuordnung und eine Personal-Übersicht (inkl. Einsatztage, Verdienst und Krankmeldungen) auf Basis der zum Abschlusszeitpunkt in der App erfassten Daten. Es enthält bewusst KEINE Notfallkontakte, Allergien oder Medikamente der Kinder — diese werden in dieser App nicht erfasst. Die Verdienst-/Gehaltsangaben sind personenbezogene Daten des Personals — entsprechend vertraulich behandeln (siehe auch Löschfristen-Regelung für personal_gehalt).', 150);
  doc.text(hinweisZeilen, 105, y, {align:'center'});
  y += hinweisZeilen.length * 5 + 10;
  doc.setTextColor(0);
  doc.setFontSize(9);
  doc.text(`Erstellt am ${new Date().toLocaleString('de-DE')} beim Abschließen der Aktion.`, 105, y, {align:'center'});

  // --- Teilnehmerliste ---
  doc.addPage();
  doc.setFont('helvetica','bold');
  doc.setFontSize(14);
  doc.text('Teilnehmerliste', marginL, 18);
  const spaltenKinder = [
    {label:'Name', width:36},
    {label:'Geb.', width:20},
    {label:'Wochen', width:26},
    {label:'Abholberechtigte', width:56},
    {label:'Foto/Video', width:44},
  ];
  let yy = zeichneKontaktzettelSeite(doc, spaltenKinder, 26, marginL);
  const kinderZeilen = kinder.map(k=>[
    `${k.vorname} ${k.nachname}`,
    fmtDateDe(k.geburtsdatum),
    (k.wochen||[]).join(', ') || '–',
    (k.abholberechtigte||[]).map(a=>a.name+(a.verhaeltnis?' ('+a.verhaeltnis+')':'')).join(', ') || '–',
    `${fotoZweckeKurz(k)} · V:${k.video_erlaubt===true?'J':(k.video_erlaubt===false?'N':'?')}`,
  ]);
  zeichneTabellenZeilen(doc, spaltenKinder, kinderZeilen, yy, marginL, marginR, seitenUnten);

  // --- Gruppenzuordnung pro Woche ---
  doc.addPage();
  doc.setFont('helvetica','bold');
  doc.setFontSize(14);
  doc.text('Gruppenzuordnung', marginL, 18);
  let gy = 28;
  days.forEach(week=>{
    const proGruppe = {};
    kinder.forEach(k=>{
      const g = (k.gruppen_zuordnung||{})[week.weekId] || '– ohne Gruppe –';
      if(!proGruppe[g]) proGruppe[g] = [];
      proGruppe[g].push(`${k.vorname} ${k.nachname}`);
    });
    const gruppenNamenSortiert = Object.keys(proGruppe).sort((a,b)=>a.localeCompare(b,'de'));
    if(gruppenNamenSortiert.length === 0) return;
    if(gy + 12 > seitenUnten){ doc.addPage(); gy = 18; }
    doc.setFont('helvetica','bold');
    doc.setFontSize(11);
    doc.text(week.weekLabel, marginL, gy);
    gy += 6;
    doc.setFont('helvetica','normal');
    doc.setFontSize(9);
    gruppenNamenSortiert.forEach(g=>{
      const zeile = `${g}: ${proGruppe[g].join(', ')}`;
      const wrapped = doc.splitTextToSize(zeile, marginR - marginL);
      if(gy + wrapped.length*4.2 > seitenUnten){ doc.addPage(); gy = 18; }
      doc.text(wrapped, marginL, gy);
      gy += wrapped.length * 4.2 + 3;
    });
    gy += 5;
  });

  // --- Personal-Übersicht ---
  doc.addPage();
  doc.setFont('helvetica','bold');
  doc.setFontSize(14);
  doc.text('Personal-Übersicht', marginL, 18);
  const spaltenPersonal = [
    {label:'Name', width:30},
    {label:'Position', width:26},
    {label:'Einsatztage', width:46},
    {label:'Verdienst', width:24},
    {label:'Krankmeldungen', width:56},
  ];
  let py = zeichneKontaktzettelSeite(doc, spaltenPersonal, 26, marginL);
  const personalSortiert = personal.slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'','de'));
  if(personalSortiert.length === 0){
    doc.setFont('helvetica','normal');
    doc.setFontSize(9);
    doc.text('Kein Personal für diese Aktion erfasst.', marginL, py);
  } else {
    const personalZeilen = personalSortiert.map(p=>{
      const { anzahlTage, daten, summe, unvollstaendig, istStundenlohn, gesamtStunden } = verdienstUndTageFuerPerson(p);
      const stundenSuffix = istStundenlohn ? `, ${(Math.round(gesamtStunden*100)/100).toString().replace('.',',')} Std. gesamt` : '';
      const einsatzText = anzahlTage === 0 ? '–' : `${anzahlTage} Tag(e)${stundenSuffix}: ${daten.join(', ')}`;
      const verdienstText = anzahlTage === 0 ? '–' : `${summe.toFixed(2).replace('.',',')} €${unvollstaendig ? ' (unvollst.)' : ''}`;
      const kmDesPersonal = krankmeldungen.filter(k=>k.personId===p.id);
      const kmText = kmDesPersonal.length === 0 ? '–' : kmDesPersonal.map(k=>`${fmtDateDe(k.von)}–${fmtDateDe(k.bis)}${k.grund?' ('+k.grund+')':''}`).join('; ');
      return [p.name || '–', p.rolle || '–', einsatzText, verdienstText, kmText];
    });
    zeichneTabellenZeilen(doc, spaltenPersonal, personalZeilen, py, marginL, marginR, seitenUnten);
  }

  doc.save(`abschluss-archiv_${aktion.name.replace(/[^a-zA-Z0-9äöüÄÖÜß]+/g,'-')}_${stamp()}.pdf`);
}

document.getElementById('k_tag_pdf_export').addEventListener('click', async ()=>{
  const dayId = document.getElementById('k_tag_select').value;
  if(!dayId){ return; }
  const selectedOption = document.getElementById('k_tag_select').selectedOptions[0];
  const tagWoche = selectedOption ? selectedOption.dataset.woche : '';
  const gruppeDesTages = (k) => (k.gruppen_zuordnung||{})[tagWoche] || '';
  const gruppeFilter = document.getElementById('k_tag_gruppe_filter').value;
  const passtZurGruppe = (k) => {
    if(!gruppeFilter) return true;
    if(gruppeFilter === '__ohne__') return !gruppeDesTages(k);
    return gruppeDesTages(k) === gruppeFilter;
  };
  const gehoertZurAktuellenWoche = (k) => {
    const wochenDesKindes = k.wochen || [];
    return wochenDesKindes.length === 0 || wochenDesKindes.includes(tagWoche);
  };
  const query = normName(document.getElementById('k_tag_search').value);
  const passtZurSuche = (k) => {
    if(!query) return true;
    const notizDesTages = ((k.anmeldungen||{})[dayId]||{}).notiz || '';
    return normName(k.vorname+' '+k.nachname).includes(query) || normName(notizDesTages).includes(query);
  };
  const abmeldungFilter = document.getElementById('k_tag_abmeldung_filter').value;
  const passtZurAbmeldung = (k) => {
    if(!abmeldungFilter) return true;
    const istAb = ((k.anmeldungen||{})[dayId]||{}).status === 'ab';
    return abmeldungFilter === 'ab' ? istAb : !istAb;
  };
  const notizFilter = document.getElementById('k_tag_notiz_filter').value;
  const passtZurNotiz = (k) => {
    if(!notizFilter) return true;
    const hatNotiz = !!((k.anmeldungen||{})[dayId]||{}).notiz;
    return notizFilter === 'mit' ? hatNotiz : !hatNotiz;
  };
  const bestaetigtFilter = document.getElementById('k_tag_bestaetigt_filter').value;
  const passtZurBestaetigung = (k) => {
    if(!bestaetigtFilter) return true;
    const istBestaetigt = !!((k.anmeldungen||{})[dayId]||{}).bestaetigt;
    return bestaetigtFilter === 'bestaetigt' ? istBestaetigt : !istBestaetigt;
  };
  const sortFeld = document.getElementById('k_tag_sort').value;
  let dayLabel = '';
  kinderCache.days.forEach(week => (week.days||[]).forEach(d=>{ if(d.id===dayId) dayLabel = `${week.weekLabel} ${d.weekday} ${d.date?fmtDateDe(d.date):''}`; }));

  const gefiltert = kinderCache.kinder
    .filter(k => passtZurGruppe(k) && passtZurSuche(k) && gehoertZurAktuellenWoche(k) && passtZurAbmeldung(k) && passtZurNotiz(k) && passtZurBestaetigung(k))
    .slice()
    .sort((a,b)=> (a[sortFeld]||'').localeCompare(b[sortFeld]||'', 'de'));

  if(gefiltert.length === 0){ alert('Keine Kinder in der aktuellen Auswahl.'); return; }

  await ladeBibliothek('jspdf');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  const marginL = 14, marginR = 196;
  const seitenUnten = 280;
  let y = 18;

  doc.setFont('helvetica','bold');
  doc.setFontSize(14);
  doc.text('Kontaktzettel', marginL, y);
  y += 7;
  doc.setFont('helvetica','normal');
  doc.setFontSize(10);
  doc.text(`${dayLabel}${gruppeFilter && gruppeFilter!=='__ohne__' ? ' · Gruppe: '+gruppeFilter : ''}`, marginL, y);
  y += 5;
  doc.setFontSize(8.5);
  doc.setTextColor(120);
  doc.text('Foto: W=Website P=Print S=Social Ö=Öffentlichkeitsarbeit V=Video, J=ja N=nein ?=offen. Ohne ausdrückliches J nicht verwenden. Keine Notfallkontakte/Gesundheitsdaten.', marginL, y);
  doc.setTextColor(0);
  y += 7;

  const spalten = [
    {label:'Name', width:32, key:'name'},
    {label:'Geb.', width:18, key:'geb'},
    {label:'Gruppe', width:20, key:'gruppe'},
    {label:'Abholberechtigte', width:40, key:'abhol'},
    {label:'Foto/Video', width:30, key:'foto'},
    {label:'Status heute', width:42, key:'status'},
  ];
  y = zeichneKontaktzettelSeite(doc, spalten, y, marginL);

  doc.setFont('helvetica','normal');
  doc.setFontSize(8.5);
  const zeilen = gefiltert.map(k=>{
    const entry = (k.anmeldungen||{})[dayId] || {};
    const istAb = entry.status === 'ab';
    const statusText = istAb ? `Abgemeldet${entry.notiz ? ' – '+entry.notiz : ''}` : `Anwesend${entry.bestaetigt ? ' (bestätigt)' : ''}${entry.notiz ? ' – '+entry.notiz : ''}`;
    const abholText = (k.abholberechtigte||[]).map(a=>a.name+(a.verhaeltnis?' ('+a.verhaeltnis+')':'')).join(', ') || '–';
    return [
      `${k.vorname} ${k.nachname}`,
      fmtDateDe(k.geburtsdatum),
      gruppeDesTages(k) || '–',
      abholText,
      `${fotoZweckeKurz(k)}\nV:${k.video_erlaubt===true?'J':(k.video_erlaubt===false?'N':'?')}`,
      statusText,
    ];
  });
  zeichneTabellenZeilen(doc, spalten, zeilen, y, marginL, marginR, seitenUnten);

  doc.setFontSize(7.5);
  doc.setTextColor(150);
  doc.text(`Erstellt am ${new Date().toLocaleString('de-DE')}`, marginL, 291);

  doc.save(`kontaktzettel_${dayLabel.replace(/\s+/g,'-')}_${stamp()}.pdf`);
});

// ---------------- FOTO-ERLAUBNIS PRO ZWECK (Migration 82) ----------------
// Eltern setzen die vier Zwecke im Portal, Admin kann sie in der Kinder-Liste korrigieren.
// Tri-State: true = ja, false = nein, null = keine Angabe. Nur "ja" gilt als erlaubt.
// Der frühere Wert foto_erlaubt (ohne Zweck, Excel-Import) bleibt getrennt bestehen.
const FOTO_ZWECKE = [
  {key:'foto_website', kurz:'W', name:'Website', label:'Veröffentlichung auf der Website (Internet)'},
  {key:'foto_print', kurz:'P', name:'Print', label:'Nutzung in Print-Publikationen (z. B. Broschüren, Veranstaltungsprogramme)'},
  {key:'foto_social', kurz:'S', name:'Social Media', label:'Veröffentlichung in Social-Media-Kanälen (z. B. Facebook, Instagram)'},
  {key:'foto_oeffentlichkeitsarbeit', kurz:'Ö', name:'Öffentlichkeitsarbeit', label:'Nutzung im Rahmen von Öffentlichkeitsarbeit / Marketing'},
];
function fotoZweckeKurz(k){
  return FOTO_ZWECKE.map(z=>z.kurz+':'+(k[z.key]===true ? 'J' : (k[z.key]===false ? 'N' : '?'))).join(' ');
}
function fotoZweckeGeklaert(k){
  return FOTO_ZWECKE.every(z=>k[z.key]===true || k[z.key]===false);
}
function fotoZweckeQuelleText(k){
  if(!k.foto_zwecke_quelle) return 'Noch nicht angegeben';
  const wer = k.foto_zwecke_quelle==='eltern' ? 'Von den Eltern angegeben' : 'Manuell erfasst'+(k.foto_zwecke_von?' von '+k.foto_zwecke_von:'');
  return wer + (k.foto_zwecke_am ? ' am '+fmtDateDe(k.foto_zwecke_am.slice(0,10)) : '');
}

// ---------------- FOTO-/VIDEO-EINWILLIGUNG: Import aus Anmeldeprogramm ----------------
// Eigenständiger, schlanker Import — GLEICHT NUR über Vorname+Nachname+Geburtsdatum
// mit bestehenden Kindern ab (legt KEINE neuen Kinder an) und übernimmt
// ausschließlich Fotoerlaubnis/Videoerlaubnis. Alle anderen Spalten des
// Exports (Allergien, Diät, Bemerkungen, Kontaktdaten, ...) werden bewusst
// nicht gelesen/gespeichert (siehe Entscheidung: keine Gesundheitsdaten in
// dieser App).
function parseJaNeinFoto(val){
  const s = String(val==null?'':val).trim().toLowerCase();
  if(s === '') return {value: null, erkannt: true}; // leer = unklar, kein Fehler
  if(['ja','j','yes','y','1','x','wahr','true'].includes(s)) return {value: true, erkannt: true};
  if(['nein','n','no','0','falsch','false'].includes(s)) return {value: false, erkannt: true};
  return {value: null, erkannt: false}; // nicht erkannter Wert -> manuelle Prüfung nötig
}

document.getElementById('k_fotoImportBtn').addEventListener('click', ()=>{
  document.getElementById('k_fotoImportFile').click();
});

document.getElementById('k_fotoImportFile').addEventListener('change', async (e)=>{
  const file = e.target.files[0];
  if(!file) return;
  const status = document.getElementById('k_fotoImportStatus');
  status.textContent = 'Lese Excel-Datei…';
  try{
    const buf = await file.arrayBuffer();
    await ladeBibliothek('xlsx');
    const wb = XLSX.read(buf, {type:'array', cellDates:false});
    const sheet = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});
    if(rows.length === 0){
      status.textContent = '⚠️ Keine Zeilen in der Excel-Datei gefunden.';
      e.target.value = '';
      return;
    }
    const headerKeys = Object.keys(rows[0]);
    const findKey = (candidates) => headerKeys.find(h => candidates.includes(h.trim().toLowerCase()));
    const vornameKey = findKey(['vorname']);
    const nachnameKey = findKey(['nachname','name']);
    const geburtsdatumKey = findKey(['geburtsdatum','geburtstag','geboren am']);
    const fotoKey = findKey(['fotoerlaubnis','foto-erlaubnis','foto']);
    const videoKey = findKey(['videoerlaubnis','video-erlaubnis','video']);

    if(!vornameKey || !nachnameKey || !geburtsdatumKey){
      status.textContent = '⚠️ Spalten "Vorname", "Nachname"/"Name" und "Geburtsdatum"/"Geburtstag" nicht gefunden.';
      e.target.value = '';
      return;
    }
    if(!fotoKey && !videoKey){
      status.textContent = '⚠️ Weder "Fotoerlaubnis" noch "Videoerlaubnis" als Spalte gefunden.';
      e.target.value = '';
      return;
    }

    status.textContent = 'Gleiche mit bestehender Liste ab…';
    let existingList = [];
    try{
      const listData = await epCall({action:'admin_list', pass: currentAuthPass});
      existingList = listData.kinder || [];
    }catch(err){
      status.textContent = '⚠️ Konnte bestehende Liste nicht laden: ' + err.message;
      e.target.value = '';
      return;
    }
    const existingByKey = new Map();
    existingList.forEach(k => existingByKey.set(normName(k.vorname)+'|'+normName(k.nachname)+'|'+k.geburtsdatum, k));

    let aktualisiert = 0, unveraendert = 0;
    const nichtGefunden = [];
    const unklareWerte = [];

    for(let i=0; i<rows.length; i++){
      const row = rows[i];
      const vorname = String(row[vornameKey]||'').trim();
      const nachname = String(row[nachnameKey]||'').trim();
      const geburtsdatum = parseDateCell(row[geburtsdatumKey]);
      if(!vorname || !nachname || !geburtsdatum) continue; // leere/unvollständige Zeile überspringen
      const key = normName(vorname)+'|'+normName(nachname)+'|'+geburtsdatum;
      const kind = existingByKey.get(key);
      if(!kind){
        nichtGefunden.push(`${vorname} ${nachname}`);
        continue;
      }
      const patch = {};
      if(fotoKey){
        const {value, erkannt} = parseJaNeinFoto(row[fotoKey]);
        if(!erkannt) unklareWerte.push(`${vorname} ${nachname} (Foto: „${row[fotoKey]}")`);
        else if(value !== kind.foto_erlaubt) patch.foto_erlaubt = value;
      }
      if(videoKey){
        const {value, erkannt} = parseJaNeinFoto(row[videoKey]);
        if(!erkannt) unklareWerte.push(`${vorname} ${nachname} (Video: „${row[videoKey]}")`);
        else if(value !== kind.video_erlaubt) patch.video_erlaubt = value;
      }
      if(Object.keys(patch).length === 0){ unveraendert++; continue; }
      patch.foto_quelle = 'import';
      patch.foto_erfasst_am = new Date().toISOString();
      patch.foto_erfasst_von = 'Import' + (myName ? ' ('+myName+')' : '');
      try{
        await epCallWithRetry({action:'admin_patch', pass: currentAuthPass, id: kind.id, patch});
        Object.assign(kind, patch);
        aktualisiert++;
      }catch(err){
        nichtGefunden.push(`${vorname} ${nachname} (Speichern fehlgeschlagen: ${err.message})`);
      }
    }

    let msg = `✓ ${aktualisiert} aktualisiert, ${unveraendert} bereits auf dem Stand.`;
    if(nichtGefunden.length) msg += `<br>⚠️ Nicht gefunden/gespeichert (${nichtGefunden.length}): ${nichtGefunden.map(escapeHtml).join(', ')}`;
    if(unklareWerte.length) msg += `<br>⚠️ Unklarer Wert, bitte manuell prüfen (${unklareWerte.length}): ${unklareWerte.map(escapeHtml).join(', ')}`;
    status.innerHTML = msg;
    renderKinderList();
  }catch(err){
    status.textContent = '⚠️ Fehler beim Import: ' + err.message;
  }
  e.target.value = '';
});

document.getElementById('k_importExcelFile').addEventListener('change', async (e)=>{
  const file = e.target.files[0];
  if(!file) return;
  const status = document.getElementById('kinderStatus');
  const importWoche = document.getElementById('k_import_woche').value;
  if(!importWoche){
    status.textContent = '⚠️ Bitte zuerst auswählen, für welche Woche diese Liste gilt.';
    e.target.value = '';
    return;
  }
  status.textContent = 'Lese Excel-Datei…';
  try{
    const buf = await file.arrayBuffer();
    await ladeBibliothek('xlsx');
    const wb = XLSX.read(buf, {type:'array', cellDates:false});
    const sheet = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});

    if(rows.length === 0){
      status.textContent = '⚠️ Keine Zeilen in der Excel-Datei gefunden.';
      e.target.value = '';
      return;
    }

    // Spalten flexibel erkennen (Groß-/Kleinschreibung, leichte Namensabweichungen egal)
    const headerKeys = Object.keys(rows[0]);
    const findKey = (candidates) => headerKeys.find(h => candidates.includes(h.trim().toLowerCase()));
    const vornameKey = findKey(['vorname','vorname des kindes']);
    const nachnameKey = findKey(['nachname','nachname des kindes']);
    const geburtsdatumKey = findKey(['geburtsdatum','geburtstag','geboren am']);
    const gruppeKey = findKey(['gruppe','gruppenname','team']);

    if(!vornameKey || !nachnameKey || !geburtsdatumKey){
      status.textContent = '⚠️ Spalten "Vorname", "Nachname" und "Geburtsdatum" nicht gefunden. Bitte Spaltenüberschriften prüfen.';
      e.target.value = '';
      return;
    }

    // Bereits vorhandene Kinder laden, um Duplikate beim wöchentlichen Re-Import zu erkennen
    status.textContent = 'Gleiche mit bestehender Liste ab…';
    let existingKeys = new Set();
    let existingList = [];
    try{
      const listData = await epCall({action:'admin_list', pass: currentAuthPass});
      existingList = listData.kinder || [];
      existingKeys = new Set(existingList.map(k =>
        normName(k.vorname) + '|' + normName(k.nachname) + '|' + k.geburtsdatum
      ));
    }catch(err){
      status.textContent = '⚠️ Konnte bestehende Liste nicht laden: ' + err.message;
      e.target.value = '';
      return;
    }

    let imported = 0, skipped = 0, duplicates = 0;
    const skippedRows = [];
    const gruppeFehlerNamen = [];
    const wochenFehlerNamen = [];
    for(let i=0; i<rows.length; i++){
      const row = rows[i];
      const vorname = String(row[vornameKey]||'').trim();
      const nachname = String(row[nachnameKey]||'').trim();
      const geburtsdatum = parseDateCell(row[geburtsdatumKey]);
      if(!vorname || !nachname || !geburtsdatum){
        skipped++;
        skippedRows.push(i+2); // +2: Zeile 1 ist Kopfzeile, Anzeige als Excel-Zeilennummer
        continue;
      }
      const key = normName(vorname) + '|' + normName(nachname) + '|' + geburtsdatum;
      const gruppe = gruppeKey ? String(row[gruppeKey]||'').trim() : '';
      if(existingKeys.has(key)){
        duplicates++;
        const bestehendesKind = existingList.find(x => normName(x.vorname)+'|'+normName(x.nachname)+'|'+x.geburtsdatum === key);
        if(bestehendesKind){
          const patch = {};
          // Bei erneutem Import (z.B. neue Woche) die Gruppe für GENAU DIESE Woche aktualisieren, falls angegeben
          const bisherigeZuordnung = bestehendesKind.gruppen_zuordnung || {};
          if(gruppe && bisherigeZuordnung[importWoche] !== gruppe){
            patch.gruppen_zuordnung = {...bisherigeZuordnung, [importWoche]: gruppe};
          }
          // Die importierte Woche ERGÄNZEN (nicht überschreiben) — ein Kind kann in mehreren Wochen dabei sein
          const bisherigeWochen = bestehendesKind.wochen || [];
          if(!bisherigeWochen.includes(importWoche)) patch.wochen = [...bisherigeWochen, importWoche];
          if(Object.keys(patch).length > 0){
            try{
              await epCallWithRetry({action:'admin_patch', pass: currentAuthPass, id: bestehendesKind.id, patch});
              Object.assign(bestehendesKind, patch);
            }catch(err){
              if('gruppen_zuordnung' in patch) gruppeFehlerNamen.push(`${vorname} ${nachname}`);
              if('wochen' in patch) wochenFehlerNamen.push(`${vorname} ${nachname}`);
            }
          }
        }
        continue;
      }
      try{
        const gruppen_zuordnung = gruppe ? {[importWoche]: gruppe} : {};
        await epCallWithRetry({action:'admin_upsert', pass: currentAuthPass, kind:{vorname, nachname, geburtsdatum, gruppen_zuordnung, wochen:[importWoche]}});
        existingKeys.add(key); // verhindert Doppel-Import, falls dieselbe Zeile mehrfach in der Datei steht
        imported++;
      }catch(err){
        skipped++;
        skippedRows.push(i+2);
      }
      status.textContent = `Importiere… ${imported+skipped+duplicates} / ${rows.length}`;
    }

    const zusammenfassung = `✓ ${imported} Kinder neu importiert.` +
      (duplicates>0 ? ` ${duplicates} bereits vorhanden — übersprungen (Woche/Gruppe bei Bedarf aktualisiert).` : '') +
      (skipped>0 ? ` ${skipped} Zeile(n) übersprungen (fehlende Angaben oder Fehler): Excel-Zeile(n) ${skippedRows.join(', ')}.` : '') +
      (gruppeFehlerNamen.length>0 ? ` ⚠️ Gruppe konnte bei ${gruppeFehlerNamen.length} Kind(ern) NICHT aktualisiert werden — bitte manuell nachtragen: ${gruppeFehlerNamen.join(', ')}.` : '') +
      (wochenFehlerNamen.length>0 ? ` ⚠️ Woche konnte bei ${wochenFehlerNamen.length} Kind(ern) NICHT ergänzt werden — bitte manuell nachtragen: ${wochenFehlerNamen.join(', ')}.` : '');
    e.target.value = '';
    await renderKinderAdmin(); // lädt Liste neu — überschreibt kurzzeitig die Statuszeile, daher DANACH erst die Zusammenfassung setzen
    status.textContent = zusammenfassung;
  }catch(err){
    status.textContent = '⚠️ Fehler beim Lesen der Excel-Datei: ' + err.message;
    e.target.value = '';
  }
});

document.getElementById('k_add').addEventListener('click', async ()=>{
  const vorname = document.getElementById('k_vorname').value.trim();
  const nachname = document.getElementById('k_nachname').value.trim();
  const geburtsdatum = document.getElementById('k_geburtsdatum').value;
  const gruppe = document.getElementById('k_gruppe').value;
  const wochen = Array.from(document.querySelectorAll('.k_add_woche:checked')).map(cb=>cb.value);
  const gruppen_zuordnung = gruppe ? Object.fromEntries(wochen.map(w=>[w, gruppe])) : {};
  if(!vorname || !nachname || !geburtsdatum){
    document.getElementById('kinderStatus').textContent = '⚠️ Bitte Vorname, Nachname und Geburtsdatum ausfüllen.';
    return;
  }
  try{
    await epCall({action:'admin_upsert', pass: currentAuthPass, kind:{vorname, nachname, geburtsdatum, gruppen_zuordnung, wochen}});
    document.getElementById('k_vorname').value = '';
    document.getElementById('k_nachname').value = '';
    document.getElementById('k_geburtsdatum').value = '';
    document.getElementById('k_gruppe').value = '';
    document.querySelectorAll('.k_add_woche').forEach(cb=>cb.checked=false);
    renderKinderAdmin();
  }catch(e){
    document.getElementById('kinderStatus').textContent = '⚠️ ' + e.message;
  }
});

// ---------------- ELTERN-ZUGANG ----------------
let elternCurrentChild = null;
let elternDays = [];
// elternKinderListe: alle in dieser Sitzung gefundenen Kinder ({child, days}),
// nicht nur das gerade aktive — ermöglicht Umschalten zwischen mehreren
// Kindern (z.B. Geschwistern) ohne erneute Nachname+Geburtsdatum-Suche.
// Lebt nur im Browser-Speicher dieser Sitzung, keine neue Server-Funktion.
let elternKinderListe = [];
// elternAktionDatenGeladen: Umfragen/Läusekontroll-Status hängen an der
// AKTION, nicht am einzelnen Kind — beim Wechsel zwischen bereits
// gefundenen Kindern muss nur neu GERENDERT (nicht neu geladen) werden.
let elternAktionDatenGeladen = false;
let elternLaeuseAktiv = false;

function unlockElternApp(){
  document.getElementById('lockscreen').style.display = 'none';
  document.getElementById('elternShell').style.display = 'flex';
  ladeElternHinweise();
  datenschutzPruefen();
}

async function ladeElternHinweise(){
  const wrap = document.getElementById('ec_hinweise_wrap');
  try{
    const data = await epCall({action:'hinweise_public_list'});
    const hinweise = data.hinweise || [];
    if(hinweise.length === 0){ wrap.innerHTML = ''; return; }
    wrap.innerHTML = hinweise.map(h => `
      <div class="card" style="border-color:var(--amber); background:#FFF9EE;">
        <div class="dp-hint" style="margin:0;">📢 ${escapeHtml(h.text)}</div>
      </div>`).join('');
  }catch(e){
    wrap.innerHTML = '';
  }
}

document.getElementById('elternLogoutBtn').addEventListener('click', ()=>{
  localStorage.removeItem('unlocked');
  localStorage.removeItem('appRole');
  location.reload();
});

document.getElementById('ec_datenschutz_toggle').addEventListener('click', ()=>{
  const box = document.getElementById('ec_datenschutz_text');
  const btn = document.getElementById('ec_datenschutz_toggle');
  const sichtbar = box.style.display !== 'none';
  box.style.display = sichtbar ? 'none' : 'block';
  btn.textContent = sichtbar ? '📄 Datenschutzhinweis anzeigen ▼' : '📄 Datenschutzhinweis ausblenden ▲';
});

// "+ weiteres Kind": öffnet die Suche erneut, OHNE die bereits gefundenen
// Kinder zu vergessen (anders als früher, als das die komplette Sitzung
// zurückgesetzt hat). "← Zurück zu meinen Kindern" auf der Suchseite bricht
// die Suche ab und zeigt wieder das zuletzt aktive Kind.
document.getElementById('ec_change').addEventListener('click', ()=>{
  document.getElementById('elternChildStage').style.display = 'none';
  document.getElementById('elternSearchStage').style.display = 'block';
  document.getElementById('es_error').textContent = '';
  document.getElementById('es_nachname').value = '';
  document.getElementById('es_geburtsdatum').value = '';
  document.getElementById('es_zurueck_btn').style.display = elternKinderListe.length > 0 ? 'block' : 'none';
});
document.getElementById('es_zurueck_btn').addEventListener('click', ()=>{
  if(elternKinderListe.length === 0) return;
  document.getElementById('elternSearchStage').style.display = 'none';
  document.getElementById('elternChildStage').style.display = 'block';
});

document.getElementById('es_submit').addEventListener('click', ()=>elternSuchen());

// elternAktiviereKind: macht ein (neu gefundenes oder bereits bekanntes)
// Kind zum aktiven Kind und rendert alles Kind-bezogene neu — OHNE
// Netzwerk-Aufruf, wenn das Kind schon in elternKinderListe steht.
// elternSyncKindImCache: hält elternKinderListe nach einem Speichervorgang
// aktuell — sonst würde ein "Zurück"-Wechsel zu einem anderen Kind und
// wieder zurück den gerade gespeicherten Stand aus dem Sitzungs-Cache
// überschreiben (der Server-Stand bliebe zwar korrekt, die Anzeige aber
// kurzzeitig veraltet).
function elternSyncKindImCache(){
  const idx = elternKinderListe.findIndex(e=>e.child.id === elternCurrentChild.id);
  if(idx >= 0) elternKinderListe[idx] = {child: elternCurrentChild, days: elternKinderListe[idx].days};
}

function elternAktiviereKind(child, days){
  elternCurrentChild = child;
  elternDays = days;
  renderElternKinderTabs();
  renderElternChild();
  if(elternUmfragen.length) renderElternUmfragen();
  if(elternLaeuseAktiv) renderLaeuseElternKarte();
  document.getElementById('elternSearchStage').style.display = 'none';
  document.getElementById('elternChildStage').style.display = 'block';
}

function renderElternKinderTabs(){
  const wrap = document.getElementById('ec_kinder_tabs');
  if(elternKinderListe.length <= 1){
    wrap.style.display = 'none';
    wrap.innerHTML = '';
    return;
  }
  wrap.style.display = 'flex';
  wrap.innerHTML = elternKinderListe.map(eintrag=>{
    const aktiv = eintrag.child.id === elternCurrentChild.id;
    return `<button class="btn ${aktiv ? '' : 'ghost'} ecKindTabBtn" data-id="${escapeHtml(eintrag.child.id)}" style="padding:4px 12px; font-size:0.85rem;">${escapeHtml(eintrag.child.vorname)}</button>`;
  }).join('');
  wrap.querySelectorAll('.ecKindTabBtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const eintrag = elternKinderListe.find(e=>e.child.id === btn.dataset.id);
      if(eintrag) elternAktiviereKind(eintrag.child, eintrag.days);
    });
  });
}

async function elternSuchen(vornameAuswahl){
  const nachname = document.getElementById('es_nachname').value.trim();
  const geburtsdatum = document.getElementById('es_geburtsdatum').value;
  const errEl = document.getElementById('es_error');
  const mehrdeutigWrap = document.getElementById('es_mehrdeutig');
  errEl.textContent = '';
  if(!nachname || !geburtsdatum){
    errEl.textContent = 'Bitte Nachname und Geburtsdatum eingeben.';
    return;
  }
  try{
    const payload = {action:'lookup', nachname, geburtsdatum};
    if(vornameAuswahl) payload.vorname = vornameAuswahl;
    const data = await epCall(payload);
    if(data.mehrdeutig){
      mehrdeutigWrap.style.display = 'block';
      const liste = document.getElementById('es_mehrdeutig_liste');
      liste.innerHTML = '';
      data.vornamen.forEach(vn=>{
        const btn = document.createElement('button');
        btn.className = 'btn ghost';
        btn.textContent = vn;
        btn.addEventListener('click', ()=>elternSuchen(vn));
        liste.appendChild(btn);
      });
      return;
    }
    mehrdeutigWrap.style.display = 'none';
    // Schon in dieser Sitzung gefunden (z.B. versehentlich erneut gesucht)?
    // Dann nicht doppelt in die Liste aufnehmen, nur aktivieren.
    const bestehenderIndex = elternKinderListe.findIndex(e=>e.child.id === data.child.id);
    if(bestehenderIndex >= 0){
      elternKinderListe[bestehenderIndex] = {child: data.child, days: data.days || []};
    } else {
      elternKinderListe.push({child: data.child, days: data.days || []});
    }
    elternAktiviereKind(data.child, data.days || []);
    if(!elternAktionDatenGeladen){
      elternAktionDatenGeladen = true;
      ladeElternUmfragen();
      ladeLaeuseStatus();
    }
  }catch(e){
    mehrdeutigWrap.style.display = 'none';
    errEl.textContent = e.message;
  }
}

let elternUmfragen = [];

async function ladeElternUmfragen(){
  const wrap = document.getElementById('ec_umfragen_wrap');
  try{
    const data = await epCall({action:'umfrage_public_list'});
    elternUmfragen = data.umfragen || [];
  }catch(e){
    wrap.innerHTML = '';
    return;
  }
  renderElternUmfragen();
}

async function ladeLaeuseStatus(){
  const wrap = document.getElementById('ec_laeuse_wrap');
  try{
    const data = await epCall({action:'laeuse_status_public'});
    elternLaeuseAktiv = !!data.aktiv;
    if(!elternLaeuseAktiv){ wrap.innerHTML = ''; return; }
  }catch(e){
    elternLaeuseAktiv = false;
    wrap.innerHTML = '';
    return;
  }
  renderLaeuseElternKarte();
}

function renderLaeuseElternKarte(){
  const wrap = document.getElementById('ec_laeuse_wrap');
  const c = elternCurrentChild;
  wrap.innerHTML = `
    <div class="card" style="border-color:var(--awo-red);">
      <div class="dp-hint" style="margin-top:0;">🦟 Läusekontrolle — aktuell gemeldet</div>
      <p style="font-size:0.85rem; margin:6px 0 12px 0;">Aktuell wurde bei den Ferienspielen ein Läusebefall gemeldet. Bitte kontrolliert/behandelt euer Kind und bestätigt dies hier. Details dazu stehen im Datenschutzhinweis oben.</p>
      <label style="display:block; margin:8px 0;"><input type="checkbox" id="ec_laeuse_kontrolle" ${c.laeuse_kontrolle_bestaetigt?'checked':''}> Ich bestätige, dass mein Kind auf Kopfläuse kontrolliert bzw. behandelt wurde.</label>
      <label style="display:block; margin:8px 0;"><input type="checkbox" id="ec_laeuse_einwilligung" ${c.laeuse_einwilligung_vor_ort?'checked':''}> Ich bin außerdem (freiwillig) mit einer zusätzlichen Kontrolle meines Kindes vor Ort durch das Team einverstanden.</label>
      <button class="btn" id="ec_laeuse_speichern" style="margin-top:8px;">Speichern</button>
      <div class="dp-hint" id="ec_laeuse_status" style="margin-top:8px;">${c.laeuse_kontrolle_datum ? 'Zuletzt bestätigt am '+fmtDateDe(c.laeuse_kontrolle_datum.slice(0,10)) : ''}</div>
    </div>`;
  document.getElementById('ec_laeuse_speichern').addEventListener('click', async ()=>{
    const statusEl = document.getElementById('ec_laeuse_status');
    const kontrolle = document.getElementById('ec_laeuse_kontrolle').checked;
    const einwilligung = document.getElementById('ec_laeuse_einwilligung').checked;
    statusEl.textContent = 'Speichert…';
    const patch = {
      laeuse_kontrolle_bestaetigt: kontrolle,
      laeuse_kontrolle_datum: kontrolle ? new Date().toISOString() : null,
      laeuse_einwilligung_vor_ort: einwilligung,
      laeuse_einwilligung_datum: einwilligung ? new Date().toISOString() : null,
    };
    try{
      const data = await epCall({action:'update', id: elternCurrentChild.id, nachname: elternCurrentChild.nachname, geburtsdatum: elternCurrentChild.geburtsdatum, patch});
      elternCurrentChild = data.child;
      elternSyncKindImCache();
      statusEl.textContent = '✓ Gespeichert' + (kontrolle ? ', am '+fmtDateDe(new Date().toISOString().slice(0,10)) : '') + '.';
    }catch(e){
      statusEl.textContent = '⚠️ ' + e.message;
    }
  });
}

function renderElternUmfragen(){
  const wrap = document.getElementById('ec_umfragen_wrap');
  if(elternUmfragen.length === 0){ wrap.innerHTML = ''; return; }
  wrap.innerHTML = '';
  elternUmfragen.forEach(u=>{
    const bisherige = (elternCurrentChild.umfrage_antworten||{})[u.id] || {};
    const card = document.createElement('div');
    card.className = 'card';
    card.style.marginTop = '16px';
    let feldHtml = '';
    if(u.typ === 'auswahl'){
      feldHtml = (u.optionen||[]).map(opt => `
        <label style="display:block; margin:6px 0;">
          <input type="radio" name="uq_${u.id}" value="${escapeHtml(opt)}" ${bisherige.antwort===opt?'checked':''}> ${escapeHtml(opt)}
        </label>`).join('');
    } else {
      feldHtml = `<textarea class="uq_text" data-id="${u.id}" rows="3" style="width:100%;" placeholder="Deine Antwort…">${escapeHtml(bisherige.antwort||'')}</textarea>`;
    }
    card.innerHTML = `
      <div class="dp-hint" style="margin-top:0;">📋 ${escapeHtml(u.frage)}</div>
      <div class="uq_feld" data-id="${u.id}" data-typ="${u.typ}" style="margin:10px 0;">${feldHtml}</div>
      <textarea class="uq_notiz" data-id="${u.id}" rows="2" style="width:100%; margin-top:8px;" placeholder="Weitere Informationen (optional)">${escapeHtml(bisherige.notiz||'')}</textarea>
      <button class="btn uq_save" data-id="${u.id}" style="margin-top:8px;">Antwort speichern</button>
      <span class="dp-hint uq_status" data-id="${u.id}" style="margin-left:10px;">${bisherige.antwort ? 'Zuletzt beantwortet' + (bisherige.beantwortetAm ? ' am '+fmtDateDe(bisherige.beantwortetAm.slice(0,10)) : '') : ''}</span>
    `;
    wrap.appendChild(card);
  });

  wrap.querySelectorAll('.uq_save').forEach(btn=>{
    btn.addEventListener('click', async ()=>{
      const uId = btn.dataset.id;
      const feldEl = wrap.querySelector(`.uq_feld[data-id="${uId}"]`);
      const statusEl = wrap.querySelector(`.uq_status[data-id="${uId}"]`);
      const notiz = wrap.querySelector(`.uq_notiz[data-id="${uId}"]`).value.trim();
      let antwort = '';
      if(feldEl.dataset.typ === 'auswahl'){
        const checked = feldEl.querySelector(`input[name="uq_${uId}"]:checked`);
        antwort = checked ? checked.value : '';
      } else {
        antwort = feldEl.querySelector('.uq_text').value.trim();
      }
      if(!antwort && !notiz){ statusEl.textContent = '⚠️ Bitte eine Antwort oder Notiz eintragen.'; return; }
      btn.disabled = true;
      statusEl.textContent = 'Speichert…';
      const neueAntworten = {...(elternCurrentChild.umfrage_antworten||{}), [uId]: {antwort, notiz, beantwortetAm: new Date().toISOString()}};
      try{
        const res = await epCall({action:'update', id: elternCurrentChild.id, nachname: elternCurrentChild.nachname, geburtsdatum: elternCurrentChild.geburtsdatum, patch:{umfrage_antworten: neueAntworten}});
        elternCurrentChild = res.child;
        elternSyncKindImCache();
        statusEl.textContent = '✓ Gespeichert.';
      }catch(e){
        statusEl.textContent = '⚠️ ' + e.message;
      }finally{
        btn.disabled = false;
      }
    });
  });
}

function renderElternChild(){
  const c = elternCurrentChild;
  document.getElementById('ec_name').textContent = `${c.vorname} ${c.nachname}`;

  // Dokumente (Migration 67): einmal pro Aktion laden, nicht bei jedem
  // renderElternChild()-Aufruf (z.B. nach dem Speichern) erneut.
  if(currentAktionId && ecDokumenteAktionId !== currentAktionId){
    ecDokumenteAktionId = currentAktionId;
    dokListeRenderFuerRolle('ec_dokumente_wrap', 'eltern', currentAktionId);
  }

  // Tage
  const daysEl = document.getElementById('ec_days');
  daysEl.innerHTML = '';
  const heute = todayIso();
  elternDays.forEach(week=>{
    const kommendeTage = (week.days||[]).filter(d => !d.date || d.date >= heute);
    if(kommendeTage.length === 0) return; // Woche komplett in der Vergangenheit — Eltern nicht mehr anzeigen
    const box = document.createElement('div');
    box.style.marginBottom = '10px';
    box.innerHTML = `<div class="dp-hint" style="margin:8px 0 4px 0;"><strong>${escapeHtml(week.weekLabel)}</strong></div>`;
    kommendeTage.forEach(d=>{
      const entry = (c.anmeldungen||{})[d.id] || {status:'', notiz:''};
      const isAbgemeldet = entry.status === 'ab';
      const row = document.createElement('div');
      row.style.cssText = 'display:grid; grid-template-columns:110px 170px 1fr; gap:8px; align-items:center; margin-bottom:6px;';
      row.innerHTML = `
        <span>${escapeHtml(d.weekday)} ${d.date?fmtDateDe(d.date):''}</span>
        <label style="display:flex; align-items:center; gap:6px; white-space:nowrap;">
          <input type="checkbox" data-day="${d.id}" class="ec-status" ${isAbgemeldet?'checked':''}> abgemeldet
        </label>
        <input type="text" data-day="${d.id}" class="ec-notiz" placeholder="Notiz (optional)" value="${escapeHtml(entry.notiz||'')}">
      `;
      box.appendChild(row);
    });
    daysEl.appendChild(box);
  });

  // Abholberechtigte
  renderAbholliste();

  // Schminken
  document.getElementById('ec_schminken').value = c.schminken===true ? 'ja' : (c.schminken===false ? 'nein' : '');

  // Fotos je Zweck
  const fotoBox = document.getElementById('ec_foto_zeilen');
  fotoBox.innerHTML = FOTO_ZWECKE.map(z=>`
    <div style="display:grid; grid-template-columns:1fr auto; gap:8px; align-items:center; margin-bottom:8px;">
      <label for="ec_${z.key}" style="font-weight:normal; font-size:0.9rem;"><strong>${escapeHtml(z.name)}</strong><br><span class="dp-hint" style="margin:0;">${escapeHtml(z.label)}</span></label>
      <select id="ec_${z.key}" style="width:auto;">
        <option value="" ${c[z.key]==null?'selected':''}>Keine Angabe</option>
        <option value="ja" ${c[z.key]===true?'selected':''}>Ja</option>
        <option value="nein" ${c[z.key]===false?'selected':''}>Nein</option>
      </select>
    </div>`).join('');

  // Einwilligung
  document.getElementById('ec_consent1').checked = !!c.einwilligung_bestaetigt;
  document.getElementById('ec_consent2').checked = !!c.einwilligung_bestaetigt;
  document.getElementById('ec_consent3').checked = !!c.einwilligung_bestaetigt;

  document.getElementById('ec_status').textContent = c.einwilligung_datum
    ? `Zuletzt bestätigt am ${fmtDateDe(c.einwilligung_datum.slice(0,10))}`
    : '';
}

function renderAbholliste(){
  const el = document.getElementById('ec_abholliste');
  const liste = elternCurrentChild.abholberechtigte || [];
  el.style.cssText = 'display:flex; flex-wrap:wrap; gap:8px;';
  if(liste.length === 0){
    el.innerHTML = '<div class="dp-hint" style="margin-top:0;">Noch niemand eingetragen.</div>';
    return;
  }
  el.innerHTML = '';
  liste.forEach((a, idx)=>{
    const chip = document.createElement('span');
    chip.className = 'dp-chip sel';
    chip.innerHTML = `${escapeHtml(a.name)}${a.verhaeltnis?' ('+escapeHtml(a.verhaeltnis)+')':''} <span style="cursor:pointer;" title="Entfernen">✕</span>`;
    chip.querySelector('span').addEventListener('click', ()=>{
      elternCurrentChild.abholberechtigte.splice(idx,1);
      renderAbholliste();
    });
    el.appendChild(chip);
  });
}

document.getElementById('ec_abhol_add').addEventListener('click', ()=>{
  const name = document.getElementById('ec_abhol_name').value.trim();
  const verhaeltnis = document.getElementById('ec_abhol_verhaeltnis').value.trim();
  if(!name) return;
  if(!Array.isArray(elternCurrentChild.abholberechtigte)) elternCurrentChild.abholberechtigte = [];
  elternCurrentChild.abholberechtigte.push({name, verhaeltnis});
  document.getElementById('ec_abhol_name').value = '';
  document.getElementById('ec_abhol_verhaeltnis').value = '';
  renderAbholliste();
});

document.getElementById('ec_save').addEventListener('click', async ()=>{
  const statusEl = document.getElementById('ec_status');
  const c1 = document.getElementById('ec_consent1').checked;
  const c2 = document.getElementById('ec_consent2').checked;
  const c3 = document.getElementById('ec_consent3').checked;

  // Anmeldungen aus den Feldern einsammeln — Eltern melden nur AB, kein separates "an"
  const anmeldungen = {...(elternCurrentChild.anmeldungen||{})};
  document.querySelectorAll('.ec-status').forEach(cb=>{
    const dayId = cb.dataset.day;
    const notizEl = document.querySelector(`.ec-notiz[data-day="${dayId}"]`);
    const istAbgemeldet = cb.checked;
    const notizVal = notizEl ? notizEl.value.trim() : '';
    if(!istAbgemeldet && !notizVal){ delete anmeldungen[dayId]; return; }
    anmeldungen[dayId] = { status: istAbgemeldet ? 'ab' : '', notiz: notizVal, updatedAt: new Date().toISOString() };
  });

  const schminkenVal = document.getElementById('ec_schminken').value;
  const patch = {
    anmeldungen,
    abholberechtigte: elternCurrentChild.abholberechtigte || [],
    schminken: schminkenVal==='ja' ? true : (schminkenVal==='nein' ? false : null),
    einwilligung_bestaetigt: !!(c1 && c2 && c3),
  };
  FOTO_ZWECKE.forEach(z=>{
    const v = document.getElementById('ec_'+z.key).value;
    patch[z.key] = v==='ja' ? true : (v==='nein' ? false : null);
  });

  if(!(c1 && c2 && c3)){
    statusEl.textContent = '⚠️ Bitte alle drei Bestätigungen ankreuzen, damit wir die Angaben speichern dürfen.';
    return;
  }

  statusEl.textContent = 'Speichert…';
  try{
    const data = await epCall({
      action: 'update',
      id: elternCurrentChild.id,
      nachname: elternCurrentChild.nachname,
      geburtsdatum: elternCurrentChild.geburtsdatum,
      patch
    });
    elternCurrentChild = data.child;
    elternSyncKindImCache();
    renderElternChild();
    statusEl.textContent = '✓ Gespeichert. Vielen Dank!';
  }catch(e){
    statusEl.textContent = '⚠️ ' + e.message;
  }
});

// ================================================================
// ANLEITUNG (In-App-Hilfe) — ein Reiter + "?"-Knöpfe an einzelnen Stellen.
// Ein einziges Datenobjekt speist beides, damit nichts doppelt gepflegt
// werden muss. adminOnly:true blendet den Abschnitt für Team aus.
// ================================================================
