const ANLEITUNG_REIHENFOLGE = [
  'start','programm','gruppen','gruppen_personalbedarf','personal',
  'kinder_uebersicht','kinder_anlegen','kinder_wochen_gruppen','kinder_tagesuebersicht','kinder_foto_import','kinder_team_hinweise','kinder_export','kinder_aktionsprotokoll',
  'umfragen','feedback','aufgaben','verfuegbarkeit','hinweise','laeusekontrolle','material','einkauf','verlauf','dienste','todo','wuensche',
  'startmenu_aktionen','startmenu_allgemein','startmenu_verwaltung','team_startseite',
  'allgemein_info','allgemein_rueckmeldung','allgemein_termine','allgemein_email','allgemein_zugriff',
  'verwaltung_kalender','verwaltung_fristen','verwaltung_versionen','nachweise','verwaltung_email','loeschfristen','statistik','jahresbericht','newsletter','verleih','sitzungen','sicherung',
  'verwaltung_personen','verwaltung_oberaktionen','verwaltung_konten','verwaltung_protokoll','verwaltung_infothek','infothek_team','verwaltung_meldungen','meldung_team','verwaltung_massnahmen','verwaltung_risikoanalyse',
  'anmelden','datenschutzhinweis','eltern_zugang','rollen'
];

// renderAnleitung: rendert die Anleitung-Liste wahlweise in den Reiter
// innerhalb einer Aktion (Standard-IDs, mit Modul-Filterung nach der
// aktuell geöffneten Aktion) oder — mit global=true — in die neue,
// aktionsübergreifende Anleitung-Kachel im Startmenü (KEINE Modul-
// Filterung, da dort keine einzelne Aktion im Kontext ist und die
// komplette Anleitung gezeigt werden soll).
function renderAnleitung(listId, searchId, global){
  listId = listId || 'anleitungInhalt';
  searchId = searchId || 'anleitung_search';
  const el = document.getElementById(listId);
  if(!el) return;
  const searchEl = document.getElementById(searchId);
  const query = normName(searchEl ? searchEl.value : '');
  el.innerHTML = '';
  ANLEITUNG_REIHENFOLGE.forEach(key=>{
    const eintrag = ANLEITUNG_DATEN[key];
    if(!eintrag) return;
    if(eintrag.adminOnly && !isAdmin()) return;
    // Abschnitte, die zu einem deaktivierten Modul dieser Aktion gehören,
    // werden ausgeblendet — sonst würde z.B. bei einer Weihnachtsfeier ohne
    // "Kinder"-Modul trotzdem ausführlich über Kinder-Import berichtet.
    // modul:null = immer sichtbar (aktionsübergreifende/grundsätzliche Themen).
    // In der globalen Ansicht (kein Aktion im Kontext) entfällt dieser
    // Filter bewusst — dort soll wirklich alles auffindbar sein.
    if(!global && eintrag.modul && !modulAktiv(eintrag.modul)) return;
    if(query && !(eintrag.titel.toLowerCase().includes(query) || eintrag.html.toLowerCase().includes(query))) return;
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `<h3 style="margin-top:0;">${escapeHtml(eintrag.titel)}</h3>${eintrag.html}`;
    el.appendChild(card);
  });
  if(el.children.length === 0){
    el.innerHTML = '<div class="empty">Keine Treffer.</div>';
  }
}
document.getElementById('anleitung_search').addEventListener('input', ()=>renderAnleitung());

// pruefeAnleitungAufDrift: reiner Entwicklungs-Check (nur Konsole, keine
// UI) — meldet, wenn ein "?"-Knopf im HTML auf einen Schlüssel zeigt, der
// in ANLEITUNG_DATEN gar nicht existiert (kaputter Knopf, passiert z.B.
// wenn ein neuer Reiter gebaut wird, aber der Anleitung-Eintrag vergessen
// wird — siehe Vorfall "Verfügbarkeit" 08/2026), oder umgekehrt Einträge,
// auf die kein einziger Knopf verweist (toter Anleitung-Abschnitt). Damit
// so etwas nicht erst auffällt, wenn ein Teammitglied auf ein totes "?"
// klickt.
function pruefeAnleitungAufDrift(){
  const referenzierteKeys = new Set(
    [...document.querySelectorAll('.hilfe-knopf[data-hilfe]')].map(el=>el.dataset.hilfe)
  );
  const fehlend = [...referenzierteKeys].filter(k=>!ANLEITUNG_DATEN[k]);
  const unreferenziert = Object.keys(ANLEITUNG_DATEN).filter(k=>!referenzierteKeys.has(k) && !ANLEITUNG_REIHENFOLGE.includes(k));
  if(fehlend.length > 0){
    console.warn('[Anleitung] "?"-Knöpfe ohne passenden Anleitung-Eintrag (kaputt):', fehlend);
  }
  if(unreferenziert.length > 0){
    console.warn('[Anleitung] Einträge ohne "?"-Knopf und ohne Aufnahme in ANLEITUNG_REIHENFOLGE (unerreichbar):', unreferenziert);
  }
}
document.addEventListener('DOMContentLoaded', pruefeAnleitungAufDrift);

// hilfeKnopf: kleiner "?"-Knopf zum Einbetten in beliebige HTML-Strings,
// öffnet ein schwebendes Fenster mit genau dem passenden Anleitung-Abschnitt.
function hilfeKnopf(key){
  return `<span class="hilfe-knopf" data-hilfe="${key}" title="Hilfe zu diesem Bereich">?</span>`;
}
function zeigeHilfePopup(key){
  const eintrag = ANLEITUNG_DATEN[key];
  if(!eintrag) return;
  let overlay = document.getElementById('hilfePopupOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'hilfePopupOverlay';
    // z-index MUSS über dem von .lockscreen (999) liegen — sonst öffnet
    // sich das Popup unsichtbar dahinter, sobald der "?"-Knopf aus einem
    // .lockscreen-Bereich heraus geklickt wird (Startmenü/Verwaltung/
    // Allgemein, seit deren "?"-Knöpfe hinzukamen). Gleicher Bug-Typ wie
    // beim Verleih-Unterschrift-Dialog, dort war die Ursache identisch.
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.35); z-index:1000; display:flex; align-items:center; justify-content:center; padding:20px;';
    document.body.appendChild(overlay);
    overlay.addEventListener('click', (e)=>{ if(e.target===overlay) overlay.style.display='none'; });
  }
  overlay.innerHTML = `
    <div class="card" style="max-width:520px; width:100%; max-height:80vh; overflow-y:auto; position:relative;">
      <button class="btn ghost" id="hilfePopupSchliessen" style="position:absolute; top:14px; right:14px;">✕</button>
      <h3 style="margin-top:0;">${escapeHtml(eintrag.titel)}</h3>
      ${eintrag.html}
    </div>`;
  overlay.style.display = 'flex';
  document.getElementById('hilfePopupSchliessen').addEventListener('click', ()=>{ overlay.style.display='none'; });
}
document.addEventListener('click', (e)=>{
  const btn = e.target.closest('.hilfe-knopf');
  if(btn) zeigeHilfePopup(btn.dataset.hilfe);
});

// ===== KLICK AUF EINE HANDY-BENACHRICHTIGUNG (Version 8zf) =====
// Der Service Worker schickt nur ein Kürzel (frist, sitzung, einladung, aktion, meldung, antwort, glocke):
// entweder per Nachricht an die offene App oder als ?ziel=... beim Start. Die App merkt es sich, bis die Person
// angemeldet ist, und öffnet dann je nach Rolle die passende Seite. Unbekannte Kürzel werden ignoriert.
var PUSH_ZIEL_ERLAUBT = ['frist','sitzung','einladung','aktion','meldung','antwort','glocke'];
function pushZielMerken(z){
  z = String(z || '');
  if(PUSH_ZIEL_ERLAUBT.indexOf(z) < 0) return;
  pushZielOffen = z;
  if(appEntsperrt) setTimeout(pushZielAnwenden, 0);
}
function pushZielAnwenden(){
  var z = pushZielOffen;
  if(!z || !appEntsperrt) return;
  var klick = function(id){ var el = document.getElementById(id); if(el) el.click(); };
  try{
    if(userRole === 'admin'){
      var kachel = { frist:'vwKachelFristen', sitzung:'vwKachelSitzungen', einladung:'vwKachelSitzungen', aktion:'vwKachelKalender', meldung:'vwKachelMeldungen' }[z];
      if(!kachel) { pushZielOffen = ''; return; }
      pushZielOffen = '';
      zeigeVerwaltung();
      klick(kachel);
    }else if(userRole === 'team'){
      if(!teamPersonId) return; // erst identifizieren; danach wird erneut versucht
      pushZielOffen = '';
      if(z === 'sitzung' || z === 'einladung'){ zeigeSitzungenBereich('team'); }
      else if(z === 'aktion' || z === 'frist'){ teamAnsichtWechseln(z === 'aktion' ? 'aktionen' : 'menue'); }
      else if(z === 'antwort' || z === 'meldung'){ klick('teamMeldungBtn'); if(z === 'antwort') klick('meldungTabMeine'); }
    }else{
      pushZielOffen = '';
    }
  }catch(e){ pushZielOffen = ''; console.warn('Push-Ziel konnte nicht geöffnet werden:', e); }
}
(function(){
  try{
    var u = new URL(location.href);
    var z = u.searchParams.get('ziel');
    if(z){
      u.searchParams.delete('ziel');
      history.replaceState(null, '', u.pathname + (u.search || '') + u.hash);
      pushZielMerken(z);
    }
  }catch(e){}
  try{
    if('serviceWorker' in navigator){
      navigator.serviceWorker.addEventListener('message', function(ev){
        if(ev && ev.data && ev.data.typ === 'push-ziel') pushZielMerken(ev.data.ziel);
      });
    }
  }catch(e){}
})();

// Versionsabgleich: passen index.html, app-basis.js und app.js nicht zusammen (z.B. nur eine Datei hochgeladen)?
(function(){
  try{
    var m=document.querySelector('meta[name="app-version"]'); var soll=m?m.content:'';
    var v=window.APP_VERSIONEN||{};
    if(soll && (v.app!==soll || v.basis!==soll)){
      console.warn('Versionen passen nicht zusammen:', soll, v);
      setTimeout(function(){ alert('Die Programmdateien haben unterschiedliche Versionen. Bitte die Seite neu laden (Strg+Umschalt+R). Besteht das Problem weiter, fehlt beim Hochladen eine Datei.'); }, 1500);
    }
  }catch(e){}
})();
